/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode(int x) : val(x), next(NULL) {}
 * };
 */
class Solution {
public:
    ListNode* reverseBetween(ListNode* head, int m, int n) {
        ListNode dummy{0};
        dummy.next = head;

        auto *prev = &dummy;

        for (int i = 0; i < m - 1; ++i) {
            prev = prev->next;
        }

        auto *head2 = prev;

        prev = prev->next;
        auto *cur = prev->next;

        for (int i = m; i < n; ++i) {
            prev->next = cur->next;  // Remove cur from the list.
            cur->next = head2->next; // Add cur to the head.
            head2->next = cur;       // Add cur to the head.
            cur = prev->next;        // Get next cur.
        }

        return dummy.next;
    }
};

// Time Complexity: O(n^m), where n is max length of number, m is count of segment
// Space Complexity: O(nm)

class Solution {
    public:
        vector<string> restoreIpAddresses(string s) {
            vector<string> ans;
            dfs(s, 0, 4, "", ans);
            return ans;
        }

    private:
        void dfs(const string &s, int start, int step, string ip, vector<string> &ans) {
            if(start == s.size() && step == 0) {
                ip.pop_back();
                ans.push_back(ip);
                return;
            }

            if(s.size() - start < step || s.size() - start > step * 3) // pruing
                return;

            int num = 0;
            for(int i = start; i < start + 3; ++i) {
                num = num * 10 + s[i] - '0';
                if(num > 255) break;
                ip += s[i];
                dfs(s, i + 1, step - 1, ip + '.', ans);
                if(num == 0) break; // only one 0
            }
        }
};

