// Time:  O(n)
// Space: O(n)
// Manacher's Algorithm
class Solution3 {
public:
    string shortestPalindrome(string s) {
            string T = preProcess(s);
            int n = T.length();
            vector<int> P(n);
            int C = 0, R = 0;
            for (int i = 1; i < n - 1; ++i) {
                int i_mirror = 2 * C - i; // equals to i' = C - (i-C)

                P[i] = (R > i) ? min(R - i, P[i_mirror]) : 0;

                // Attempt to expand palindrome centered at i
                while (T[i + 1 + P[i]] == T[i - 1 - P[i]]) {
                    ++P[i];
                }

                // If palindrome centered at i expand past R,
                // adjust center based on expanded palindrome.
                if (i + P[i] > R) {
                    C = i;
                    R = i + P[i];
                }
            }

            // Find the max len of palindrome which starts with the first char of s.
            int max_len = 0;
            for (int i = 1; i < n - 1; ++i) {
                if (i - P[i] == 1) {
                    max_len = P[i];
                }
            }

            // Assume s is (Palindrome)abc.
            string ans = s.substr(max_len); // abc.
            reverse(ans.begin(), ans.end()); // cba.
            ans.append(s); // cba(Palindrome)abc.
            return ans;
        }
private:
    string preProcess(string s) {
        int n = s.length();
        if (n == 0) {
            return "^$";
        }
        string ret = "^";
        for (int i = 0; i < n; ++i) {
            ret += "#" + s.substr(i, 1);
        }
        ret += "#$";
        return ret;
    }
};

// Time:  O(n) on average, using Median of Medians could achieve O(n) (Intro Select)
// Space: O(1)

// optimized for duplicated nums
class Solution {
public:
    int findKthLargest(vector<int>& nums, int k) {
        nth_element(nums, k - 1);
        return nums[k - 1];
    }

private:
    void nth_element(vector<int>& nums, int n) {
        int left = 0, right = size(nums) - 1;
        default_random_engine gen((random_device())());
        while (left <= right) {
            // Generates a random int in [left, right].
            uniform_int_distribution<int> dis(left, right);
            int pivot_idx = dis(gen);
            const auto& [pivot_left, pivot_right] = TriPartition(left, right, nums[pivot_idx], &nums);
            if (pivot_left <= n && n <= pivot_right) {
                return;
            } else if (pivot_left > n) {
                right = pivot_left - 1;
            } else {  // pivot_right < n.
                left = pivot_right + 1;
            }
        }
    }

    pair<int, int> TriPartition(int left, int right, int target, vector<int> *nums) {
        for (int mid = left; mid <= right;) {
            if ((*nums)[mid] == target) {
                ++mid;
            } else if ((*nums)[mid] > target) {
                swap((*nums)[left++], (*nums)[mid]);
                ++mid;
            } else {
                swap((*nums)[mid], (*nums)[right--]);
            }
        }
        return {left, right};
    }
};

