// Time:  O(m * n)
// Space: O(1)

class Solution {
public:
    void gameOfLife(vector<vector<int>>& board) {
        const int m = board.size(), n = m ? board[0].size() : 0;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                int count = 0;
                // Count live cells in 3x3 block.
                for (int I = max(i - 1, 0); I < min(i + 2, m); ++I) {
                    for (int J = max(j - 1, 0); J < min(j + 2, n); ++J) {
                        count += board[I][J] & 1;
                    }
                }
                // if (count == 4 && board[i][j]) means:
                //     Any live cell with three live neighbors lives.
                // if (count == 3) means:
                //     Any live cell with two live neighbors.
                //     Any dead cell with exactly three live neighbors lives.
                if ((count == 4 && board[i][j]) || count == 3) {
                    board[i][j] |= 2;  // Mark as live. 
                }
            }
        }
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                board[i][j] >>= 1;  // Update to the next state.
            }
        }
    }
};

// Time:  O(n)
// Space: O(c), c is unique count of pattern

class Solution {
public:
    bool wordPattern(string pattern, string str) {
        // Count the words.
        int cnt = str.empty() ? 0 : 1;
        for (const auto& c : str) {
            if (c == ' ') {
                ++cnt;
            }
        }
        if (pattern.size() != cnt) {
            return false;
        }

        unordered_map<string, char> w2p;
        unordered_map<char, string> p2w;
        int i = 0, j = 0;
        for (const auto& p : pattern) {
            // Get a word at a time without saving all the words.
            j = str.find(" ", i);
            if (j == string::npos) {
                j = str.length();
            }
            const string w = str.substr(i, j - i);

            if (!w2p.count(w) && !p2w.count(p)) { 
                // Build mapping. Space: O(c)
                w2p[w] = p; 
                p2w[p] = w; 
            } else if (!w2p.count(w) || w2p[w] != p) {
                // Contradict mapping.
                return false;
            }
            i = j + 1;
        }
        return true;
    }
};

// Time:  O(n * C(n - 1, c - 1)), n is length of str, c is unique count of pattern,
//                                there are H(n - c, c - 1) = C(n - 1, c - 1) possible splits of string,
//                                and each one costs O(n) to check if it matches the word pattern.
// Space: O(n + c) 

class Solution {
public:
    bool wordPatternMatch(string pattern, string str) {
        unordered_map<string, char> w2p;
        unordered_map<char, string> p2w;
        return match(pattern, str, 0, 0, &w2p, &p2w);
    }

    bool match(const string &pattern, const string &str,
               const int i, const int j,
               unordered_map<string, char>* w2p,
               unordered_map<char, string>* p2w) {

        bool is_match = false;
        if (i == pattern.length() && j == str.length()) {
            is_match = true;
        } else if (i < pattern.length() && j < str.length()) {
            const char p = pattern[i];
            if (p2w->count(p)) {
                const auto& w = (*p2w)[p];
                if (w == str.substr(j, w.length())) {  // Match pattern.
                    is_match = match(pattern, str, i + 1, j + w.length(), w2p, p2w);
                }  // Else return false.
            } else {
                for (int k = j; k < str.length() && !is_match; ++k) {
                    const string w = str.substr(j, k - j + 1);
                    if (!w2p->count(w)) {
                        // Build mapping. Space: O(n + c)
                        (*w2p)[w] = p, (*p2w)[p] = w;
                        is_match = match(pattern, str, i + 1, k + 1, w2p, p2w);
                        w2p->erase(w), p2w->erase(p);
                    }  // Else try longer word.
                }
            }
        }
        return is_match;
    }
};

