// Space: O(h)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    int longestConsecutive(TreeNode* root) {
        int max_len = 0;
        longestConsecutiveHelper(root, &max_len);
        return max_len;
    }

    int longestConsecutiveHelper(TreeNode *root, int *max_len) {
        if (!root) {
            return 0;
        }

        const int left_len = longestConsecutiveHelper(root->left, max_len);
        const int right_len = longestConsecutiveHelper(root->right, max_len);

        int cur_len = 1;
        if (root->left && root->left->val == root->val + 1) {
            cur_len = max(cur_len, left_len + 1);
        }
        if (root->right && root->right->val == root->val + 1) {
            cur_len = max(cur_len, right_len + 1);
        }
        *max_len = max(*max_len, max(cur_len, max(left_len, right_len)));
        return cur_len;
    }
};

// Time:  O(n)
// Space: O(10) = O(1)

// One pass solution.
class Solution {
public:
    string getHint(string secret, string guess) {
        unordered_map<char, int> lookup;
        int A = 0, B = 0;
        for (int i = 0; i < size(secret); ++i) {
            const char s = secret[i];
            const char g = guess[i];
            if (s == g) {
                ++A;
            } else {
                B += int(lookup[s]++ < 0) + int(lookup[g]-- > 0);
             }
        }
        return to_string(A).append("A").append(to_string(B)).append("B");
    }
};

// Two pass solution.
class Solution2 {
public:
    string getHint(string secret, string guess) {
        unordered_map<char, int> lookup;
        int A = 0, B = 0;
        for (const auto& s : secret) {
            ++lookup[s];
        }
        for (const auto& g : guess) {
            if (lookup[g]) {
                --lookup[g];
                ++B;
            }
        }
        for (int i = 0; i < size(secret); ++i) {
            if (secret[i] == guess[i]) {
                ++A, --B;
            }
        }
        return to_string(A).append("A").append(to_string(B)).append("B");
    }
};

