// Time:  O(n)
// Space: O(1)

class Solution {
public:
    bool isValidSerialization(string preorder) {
        if (preorder.empty()) {
            return false;
        }
        Tokenizer tokens(preorder);
        int depth = 0; 
        int i = 0;
        for (; i < tokens.size() && depth >= 0; ++i) {
            if (tokens.get_next() == "#") {
                --depth;
            } else {
                ++depth;
            }
        }
        return i == tokens.size() && depth < 0;  
    }

    class Tokenizer {
    public:
        Tokenizer(const string& str) : str_(str), i_(0), cnt_(0) {
            size_ = count(str_.cbegin(), str_.cend(), ',') + 1;
        }

        string get_next() {
            string next;
            if (cnt_ < size_) {
                size_t j =  str_.find(",", i_);
                next = str_.substr(i_, j - i_);
                i_ = j + 1;
                ++cnt_;
            }
            return next;
        }

        size_t size() {
            return size_;
        }

    private:
        const string& str_;
        size_t size_;
        size_t cnt_;
        size_t i_;
    };

};

// Time:  O(|V| + |E|log|V|)
// Space: O(|V| + |E|)

// Hierholzer Algorithm
class Solution {
public:
    vector<string> findItinerary(vector<vector<string>>& tickets) {
        static const string origin{"JFK"};

        unordered_map<string, vector<string>> adj;
        for (const auto& ticket : tickets) {
            adj[ticket[0]].emplace_back(ticket[1]);
        }
        for (auto& [k, v] : adj) {
            sort(rbegin(v), rend(v));
        }

        vector<string> result;
        vector<string> stk = {origin};
        while (!empty(stk)) {
            while (!empty(adj[stk.back()])) { 
                auto x = adj[stk.back()].back();
                adj[stk.back()].pop_back();
                stk.emplace_back(x);

            }
            result.emplace_back(stk.back());
            stk.pop_back();
        }
        reverse(begin(result), end(result));
        return result;
    }
};

// Time:  O(t! / (n1! * n2! * ... nk!)), t is the total number of tickets, 
//                                       ni is the number of the ticket which from is city i,
//                                       k is the total number of cities.
// Space: O(t)
class Solution2 {
public:
   vector<string> findItinerary(vector<vector<string>>& tickets) {
        unordered_map<string, map<string, int>> graph;
        for (const auto& ticket : tickets) {
            ++graph[ticket[0]][ticket[1]];
        }
        const string from{"JFK"};
        vector<string> ans{from};
        routeHelper(from, tickets.size(), &graph, &ans);
        return ans;
    }

private:
    bool routeHelper(const string& from, const int ticket_cnt,
                     unordered_map<string, map<string, int>> *graph, vector<string> *ans) {

        if (ticket_cnt == 0) {
            return true;
        }

        for (auto& to : (*graph)[from]) {
            if (to.second) {
                --to.second;
                ans->emplace_back(to.first);
                if (routeHelper(to.first, ticket_cnt - 1, graph, ans)) {
                    return true;
                }
                ans->pop_back();
                ++to.second;
            }
        }
        return false;
    }
};

// Time:  O(n)
// Space: O(h)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    int largestBSTSubtree(TreeNode* root) {
        if (!root) {
            return 0;
        }

        int max_size = 1;
        largestBSTSubtreeHelper(root, &max_size);
        return max_size;
    }

private:
    tuple<int, int, int> largestBSTSubtreeHelper(TreeNode* root, int *max_size) {
        if (!root->left && !root->right) {
            return make_tuple(1, root->val, root->val);
        }

        int left_size = 0, left_min = root->val, left_max = root->val;
        if (root->left) {
            tie(left_size, left_min, left_max) = largestBSTSubtreeHelper(root->left, max_size);
        }

        int right_size = 0, right_min = root->val, right_max = root->val;
        if (root->right) {
            tie(right_size, right_min, right_max) = largestBSTSubtreeHelper(root->right, max_size);
        }

        int size = 0;
        if ((!root->left || left_size > 0) && 
            (!root->right || right_size > 0) &&
            left_max <= root->val && root->val <= right_min) {
            size = 1 + left_size + right_size;
            *max_size = max(*max_size, size);
        }

        return make_tuple(size, left_min, right_max);
    }
};

