    MovingAverage(int size) : size_(size), sum_(0) {
    }

    double next(int val) {
        if (q_.size() == size_) {
            sum_ -= q_.front();
            q_.pop();
        }
        q_.emplace(val);
        sum_ += val;
        return 1.0 * sum_ / q_.size();
    }

