     : food_(food)
     , f_{0}
     , width_{width}
     , height_{height}
     , score_{0}
     , snake_{{0, 0}}
     , lookup_{{0}} {
    }

    /** Moves the snake.
        @param direction - 'U' = Up, 'L' = Left, 'R' = Right, 'D' = Down 
        @return The game's score after the move. Return -1 if game over. 
        Game over when snake crosses the screen boundary or bites its body. */
    int move(string direction) {
        const auto x = snake_.back()[0] + direction_[direction].first;
        const auto y = snake_.back()[1] + direction_[direction].second;
        const auto tail = snake_.front();
        lookup_.erase(hash(tail[0], tail[1]));
        snake_.pop_front();
        if (!valid(x, y)) {
            return -1;
        } else if (f_ != size(food_) && food_[f_][0] == x && food_[f_][1] == y) {
            ++score_;
            ++f_;
            snake_.push_front(tail);
            lookup_.emplace(hash(tail[0], tail[1]));
        }
        snake_.push_back({x, y});
        lookup_.emplace(hash(x, y));
        return score_;
    }

private:
    bool valid(int x, int y) {
        if (x < 0 || x >= height_ || y < 0 || y >= width_) {
            return false;
        }
        return !lookup_.count(hash(x, y));
    }

    int hash(int x, int y) {
        return x * width_ + y;
    }

    const vector<vector<int>>& food_;
    int f_, width_, height_, score_;
    deque<vector<int>> snake_;
    unordered_set<int> lookup_;
    unordered_map<string, pair<int, int>> direction_ = {{"U", {-1, 0}}, {"L", {0, -1}},
                                                        {"R", {0, 1}}, {"D", {1, 0}}};
};

// Time:  O(nlogn + nlogk) = O(nlogn), k is the length of the result.
// Space: O(1)

class Solution {
public:
    int maxEnvelopes(vector<pair<int, int>>& envelopes) {
        vector<int> result;

        sort(envelopes.begin(), envelopes.end(),  // O(nlogn)
            [](const pair<int, int>& a, const pair<int, int>& b) {
                if (a.first == b.first) {
                    return a.second > b.second;
                }
                return a.first < b.first;
            });
        for (const auto& envelope : envelopes) {
            const auto target = envelope.second;
            auto it = lower_bound(result.begin(), result.end(), target);  // O(logk)
            if (it == result.end()) {
                result.emplace_back(target);
            } else {
                *it = target;
            }
        }

        return result.size();
    }
};

// Time:  O(u + klogk), k is most recently number of tweets,
//                      u is the number of the user's following.
// Space: O(t + f), t is the total number of tweets,
//                  f is the total number of followings.

class Twitter {
public:
    /** Initialize your data structure here. */
    Twitter() : time_(0) {

    }

    /** Compose a new tweet. */
    void postTweet(int userId, int tweetId) {
        messages_[userId].emplace_back(make_pair(++time_, tweetId));
    }

    /** Retrieve the 10 most recent tweet ids in the user's news feed. Each item in the news feed must be posted by users who the user followed or by the user herself. Tweets must be ordered from most recent to least recent. */
    vector<int> getNewsFeed(int userId) {
        using RIT = deque<pair<size_t, int>>::reverse_iterator;

        vector<tuple<size_t, RIT, RIT>> candidates;
        if (messages_[userId].size()) {
            candidates.emplace_back(messages_[userId].rbegin()->first,
                                    messages_[userId].rbegin(),
                                    messages_[userId].rend());
        }
        for (const auto& id : followings_[userId]) {
            if (messages_[id].size()) {
                candidates.emplace_back(messages_[id].rbegin()->first,
                                        messages_[id].rbegin(),
                                        messages_[id].rend());
            }
        }
        if (size(candidates) > number_of_most_recent_tweets_) {
            nth_element(begin(candidates), begin(candidates) + number_of_most_recent_tweets_ - 1, end(candidates));
        }
        priority_queue<tuple<size_t, RIT, RIT>> heap(cbegin(candidates), cbegin(candidates) + min(size(candidates), number_of_most_recent_tweets_));
        vector<int> res;
        while (!heap.empty() && res.size() < number_of_most_recent_tweets_) {
            const auto& top = heap.top();
            size_t t;
            RIT begin, end;
            tie(t, begin, end) = top;
            heap.pop();

            auto next = begin + 1;
            if (next != end) {
                heap.emplace(make_tuple(next->first, next, end));
            }

            res.emplace_back(begin->second);
        }
        return res;
    }

    /** Follower follows a followee. If the operation is invalid, it should be a no-op. */
    void follow(int followerId, int followeeId) {
        if (followerId != followeeId && !followings_[followerId].count(followeeId)) {
            followings_[followerId].emplace(followeeId);
        }
    }

    /** Follower unfollows a followee. If the operation is invalid, it should be a no-op. */
    void unfollow(int followerId, int followeeId) {
        if (followings_[followerId].count(followeeId)) {
            followings_[followerId].erase(followeeId);
        }
    }

private:
    const size_t number_of_most_recent_tweets_ = 10;
    unordered_map<int, unordered_set<int>> followings_;
    unordered_map<int, deque<pair<size_t, int>>> messages_;
    size_t time_;
};

// Time:  O(n)
// Space: O(n)

// Hash solution.
class Solution {
public:
    bool isReflected(vector<pair<int, int>>& points) {
        if (points.empty()) {
            return true;
        }
        unordered_map<int, unordered_set<int>> groups_by_y;
        int left = numeric_limits<int>::max();
        int right = numeric_limits<int>::min();
        for (const auto& p : points) {
            groups_by_y[p.second].emplace(p.first);
            left = min(left, p.first);
            right = max(right, p.first);
        }
        const auto mid = left + right;
        for (const auto& kvp : groups_by_y) {
            for (const auto& x : kvp.second) {
                if (kvp.second.count(mid - x) == 0) {
                    return false;
                }
            }
        }
        return true;
    }
};

// Time:  O(nlogn)
// Space: O(1)
// Two pointers solution.
class Solution2 {
public:
    bool isReflected(vector<pair<int, int>>& points) {
        if (points.empty()) {
            return true;
        }
        sort(points.begin(), points.end());
        sort(points.begin(), points.begin() + distance(points.begin(), points.end()) / 2,
            [](const pair<int, int>& a, const pair<int, int>& b) {
                if (a.first == b.first) {
                    return a.second > b.second;
                }
                return a.first < b.first;
            });

        const auto mid = points.front().first + points.back().first;
        for (int left = 0, right = points.size() - 1; left <= right; ++left, --right) {
            if ((mid != points[left].first + points[right].first) || 
                (points[left].first != points[right].first &&
                 points[left].second != points[right].second)) {
                return false;
            }
        }
        return true;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int countNumbersWithUniqueDigits(int n) {
        if (n == 0) {
            return 1;
        }
        int result = 1;
        for (int i = 0, cnt = 1; i < n - 1; ++i) {
            cnt *= 9 - i;
            result += cnt;
        }
        return 1 + 9 * result;
    }
};

// Time:  O(n)
// Space: O(n)
class Solution2 {
public:
    int countNumbersWithUniqueDigits(int n) {
        vector<int> fact(2, 1);
        const auto& nPr = [&](int n, int k) {
            while (size(fact) <= n) {  // lazy initialization
                fact.emplace_back(fact.back() * size(fact));
            }
            return fact[n] / fact[n - k];
        };

        int result = 0;
        for (int i = 0; i < n; ++i) {
            result += nPr(9, i);
        }
        result *= 9;
        return ++result;
    }
};

// Time:  O(n)
// Space: O(c)

class Solution {
public:
    string rearrangeString(string s, int k) {
        if (!k) {
            return s;
        }
        unordered_map<char, int> cnts;
        for (const auto& c : s) {
            ++cnts[c];
        }
        const int bucket_cnt = max_element(cbegin(cnts), cend(cnts), [](const auto& a, const auto& b) {
            return a.second < b.second;
        })->second;
        if (!((bucket_cnt - 1) * k + count_if(cbegin(cnts), cend(cnts), [&](const auto& x) { return x.second == bucket_cnt; }) <= size(s))) {
            return "";
        }
        vector<char> partial_sorted_cnts;
        for (const auto& [c, v] : cnts) {
            if (v == bucket_cnt) {
                partial_sorted_cnts.emplace_back(c);
            }
        }
        for (const auto& [c, v] : cnts) {
            if (v != bucket_cnt) {
                partial_sorted_cnts.emplace_back(c);
            }
        }
        string result(size(s), 0);
        int i = (size(s) - 1) % k;
        for (const auto& c : partial_sorted_cnts) {
            for (int _ = 0; _ < cnts[c]; ++_) {
                result[i] = c;
                i += k;
                if (i >= size(result)) {
                    i = (i - 1) % k;
                }
            }
        }
        return result;
    }
};

