class Solution {
public:
    int compress(vector<char>& chars) {
        int write = 0, anchor = 0;
        for (int read = 0; read < chars.size(); ++read) {
            if (read + 1 == chars.size() || chars[read + 1] != chars[read]) {
                chars[write++] = chars[read];
                if (read - anchor > 0) {
                    auto n = read - anchor + 1, cnt = 0;
                    while (n > 0) {
                        chars[write++] = n % 10 + '0';
                        n /= 10;
                        ++cnt;
                    }
                    reverse(chars.begin() + write - cnt, chars.begin() + write);
                }
                anchor = read + 1;
            }
        }
        return write;
    }
};

// Time:  O(n * s), n is the size of org, s is the size of seqs
// Space: O(n)

class Solution {
public:
    bool sequenceReconstruction(vector<int>& org, vector<vector<int>>& seqs) {
        if (seqs.empty()) {
            return false;
        }
        vector<int> pos(org.size() + 1);
        for (int i = 0; i < org.size(); ++i) {
            pos[org[i]] = i;
        }

        vector<bool> is_matched(org.size() + 1);
        int cnt_to_match = org.size() - 1;
        for (const auto& seq : seqs) {
            for (int i = 0; i < seq.size(); ++i) {
                if (seq[i] <= 0 || seq[i] > org.size()) {
                    return false;
                }
                if (i == 0) {
                    continue;
                }
                if (pos[seq[i - 1]] >= pos[seq[i]]) {
                    return false;
                }
                if (is_matched[seq[i - 1]] == false && pos[seq[i - 1]] + 1 == pos[seq[i]]) {
                    is_matched[seq[i - 1]] = true;
                    --cnt_to_match;
                }
            }
        }
        return cnt_to_match == 0;
    }
};

