// Time:  O(n!)
// Space: O(n)

class Solution {
public:
    bool canIWin(int maxChoosableInteger, int desiredTotal) {
        if ((1 + maxChoosableInteger) * (maxChoosableInteger / 2) < desiredTotal) {
            return false;
        }
        unordered_map<int, int> lookup;
        return canIWinHelper(maxChoosableInteger, desiredTotal, 0, &lookup);
    }

private:
    int canIWinHelper(int maxChoosableInteger, int desiredTotal,
                      int visited, unordered_map<int, int> *lookup) {

        if  (lookup->find(visited) != lookup->end()) {
            return (*lookup)[visited];
        }
        int mask = 1;
        for (int i = 0; i < maxChoosableInteger; ++i) {
            if (!(visited & mask)) {
                if (i + 1 >= desiredTotal ||
                    !canIWinHelper(maxChoosableInteger, desiredTotal - (i + 1), visited | mask, lookup)) {
                    (*lookup)[visited] = true;
                    return true;
                }
            }
            mask <<= 1;
        }
        (*lookup)[visited] = false;
        return false;
    }
};

// Time:  O(n * 2^n), n is the size of debts.
// Space: O(2^n)

class Solution {
public:
    int minTransfers(vector<vector<int>>& transactions) {
        unordered_map<int, int> account;
        for (const auto& transaction : transactions) {
            account[transaction[0]] += transaction[2];
            account[transaction[1]] -= transaction[2];
        }
        vector<int> debts;
        for (const auto& [_, debt] : account) {
            if (debt) {
                debts.emplace_back(debt);
            }
        }

        vector<int> dp(1 << debts.size());
        vector<int> sums(1 << debts.size());
        for (int i = 0; i < dp.size(); ++i) {
            for (int j = 0, bit = 1; j < debts.size(); ++j, bit <<= 1) {
                if ((i & bit) == 0) {
                    auto nxt = i | bit;
                    sums[nxt] = sums[i] + debts[j];
                    if (sums[nxt] == 0) {
                        dp[nxt] = max(dp[nxt], dp[i] + 1);
                    } else {
                        dp[nxt] = max(dp[nxt], dp[i]);
                    }
                }
            }
        }
        return debts.size() - dp.back();
    }
};

// Time:  O(s1 * min(s2, n1))
// Space: O(s2)

class Solution {
public:
    int getMaxRepetitions(string s1, int n1, string s2, int n2) {
        vector<int> repeatCount(s2.size() + 1, 0);
        unordered_map<int, int> lookup;
        int j = 0, count = 0;
        for (int k = 1; k <= n1; ++k) {
            for (int i = 0; i < s1.size(); ++i) {
                if (s1[i] == s2[j]) {
                    j = (j + 1) % s2.size();
                    count += (j == 0);
                }
            }

            if (lookup.find(j) != lookup.end()) {  // cyclic
                int i = lookup[j];
                int prefixCount = repeatCount[i];
                int patternCount = (count - repeatCount[i]) * ((n1 - i) / (k - i));
                int suffixCount = repeatCount[i + (n1 - i) % (k - i)] - repeatCount[i];
                return (prefixCount + patternCount + suffixCount) / n2;
            }
            lookup[j] = k;
            repeatCount[k] = count;
        }
        return repeatCount[n1] / n2;  // not cyclic iff n1 <= s2
    }
};

