class Solution {
public:
    bool isConvex(vector<vector<int>>& points) {
        const auto det = [](const vector<vector<int>>& A) {
            return A[0][0]*A[1][1] - A[0][1]*A[1][0];
        };
        long n = points.size(), prev = 0, curr;
        for (int i = 0; i < n; ++i) {
            vector<vector<int>> A;
            for (int j = 1; j < 3; ++j) {
                A.push_back({points[(i + j) % n][0] - points[i][0], points[(i + j) % n][1] - points[i][1]});
            }
            if (curr = det(A)) {
                if (curr * prev < 0) {
                    return false;
                }
                prev = curr;
            }
        }
        return true;
    }
};

// Time:  O(1.199), counted by statistics, limit would be O(log10/log7) = O(1.183)
// Space: O(1)

// The rand7() API is already defined for you.
// int rand7();
// @return a random integer in the range 1 to 7

// Reference: https://leetcode.com/problems/implement-rand10-using-rand7/discuss/151567/C++JavaPython-Average-1.199-Call-rand7-Per-rand10
class Solution {
public:
    int rand10() {
        while (cache_.empty()) {
            generate();
        }
        auto result = cache_.back(); cache_.pop_back();
        return result;
    }

private:
    void generate() {
        static const int n = 19;
        uint64_t curr = 0, range = static_cast<uint64_t>(pow(7, n));
        for (int i = 0; i < n; ++i) {
            curr += static_cast<uint64_t>(pow(7, i)) * (rand7() - 1);
        }
        while (curr < range / 10 * 10) {
            cache_.emplace_back(curr % 10 + 1);
            curr /= 10;
            range /= 10;
        }
    }
    vector<int> cache_;
};

