};

// Time:  O(n * s * 2^n), s is the number of subset of which sum equals to side length.
// Space: O(n * (2^n + s))

class Solution {
public:
    bool makesquare(vector<int>& nums) {
        int sum = accumulate(nums.begin(), nums.end(), 0);
        if (sum % 4) {
            return false;
        }

        const auto side_len = sum / 4;
        const auto all = (1 << nums.size()) - 1;

        vector<int> used_subsets;
        vector<bool> valid_half_subsets(1 << nums.size());

        for (int subset = 0; subset <= all; ++subset) {
            int subset_sum = 0;
            for (int i = 0; i < nums.size(); ++i) {
                if (subset & (1 << i)) {
                    subset_sum += nums[i];
                }
            }
            if (subset_sum == side_len) {
                for (const auto& used_subset : used_subsets) {
                    if ((used_subset & subset) == 0) {
                        int valid_half_subset = used_subset | subset;
                        valid_half_subsets[valid_half_subset] = true;
                        if (valid_half_subsets[all ^ valid_half_subset]) {
                            return true;
                        }
                    }
                }
                used_subsets.emplace_back(subset);
            }
        }
        return false;
    }
};

// Time:  O(s * m * n), s is the size of the array.
// Space: O(m * n)

class Solution {
public:
    int findMaxForm(vector<string>& strs, int m, int n) {
        vector<vector<int>> dp(m + 1, vector<int>(n + 1));
        for (const auto &str : strs) {
            int zero_count = 0, one_count = 0;
            for (const auto& c : str) {
                if (c == '0') {
                    ++zero_count;
                } else if (c == '1') {
                    ++one_count;
                }
            }

            for (int i = m; i - zero_count >= 0; --i) {
            	for (int j = n; j - one_count >= 0; --j) {
                    dp[i][j] = max(dp[i][j], dp[i - zero_count][j - one_count] + 1);
            	}
            }
        }
        return dp[m][n];
    }
};

// Time:  O((m + n) * logn), m is the number of the houses, n is the number of the heaters.
// Space: O(1)

class Solution {
public:
    int findRadius(vector<int>& houses, vector<int>& heaters) {
        sort(heaters.begin(), heaters.end());
        int min_radius = 0;
        for (const auto& house : houses) {
        	auto equal_or_larger = lower_bound(heaters.cbegin(), heaters.cend(), house);
        	auto curr_radius = numeric_limits<int>::max();
        	if (equal_or_larger != heaters.cend()) {
        	    curr_radius = *equal_or_larger - house;
        	}
        	if (equal_or_larger != heaters.cbegin()) {
        	    auto smaller = prev(equal_or_larger);
        	    curr_radius = min(curr_radius, house - *smaller);
        	}
        	min_radius = max(min_radius, curr_radius);
        }
        return min_radius;
    }
};

