        while (changed) {
            changed = false;
            for (int start = 0, i = 0; start < size(s); ++start) {
                while(i < size(s) && s[start] == s[i]) {
                    ++i;
                }
                if (i - start >= 3) {
                    s = s.substr(0, start) + s.substr(i); 
                    changed = true;
                    break;
                } 
            }
        }
        return s;
    }

    static const int MAX_STEP = 6;
};

