/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    vector<int> boundaryOfBinaryTree(TreeNode* root) {
        if (!root) {
            return {};
        }

        vector<int> nodes;
        nodes.emplace_back(root->val);
        leftBoundary(root->left, &nodes);
        leaves(root->left, &nodes);
        leaves(root->right, &nodes);
        rightBoundary(root->right, &nodes);
        return nodes;
    }

private:
    void leftBoundary(TreeNode *root, vector<int> *nodes) {
        if (!root || (!root->left && !root->right)) {
            return;
        }
        nodes->emplace_back(root->val);
        if (!root->left) {
            leftBoundary(root->right, nodes);
        } else {
            leftBoundary(root->left, nodes);
        }
    }

    void rightBoundary(TreeNode *root, vector<int> *nodes) {
        if (!root || (!root->right && !root->left)) {
            return;
        }
        if (!root->right) {
            rightBoundary(root->left, nodes);
        } else {
            rightBoundary(root->right, nodes);
        }
        nodes->emplace_back(root->val);
    }

    void leaves(TreeNode *root, vector<int> *nodes) {
        if (!root) {
            return;
        }
        if (!root->left && !root->right) {
            nodes->emplace_back(root->val);
            return;
        }
        leaves(root->left, nodes);
        leaves(root->right, nodes);
    }
};

// Time:  O(n^3) ~ O(n^4)
// Space: O(n^3)

class Solution {
public:
    int removeBoxes(vector<int>& boxes) {
        int lookup[100][100][100] = {0};
        return removeBoxesHelper(boxes, 0, boxes.size() - 1, 0, lookup);
    }

private:
    int removeBoxesHelper(const vector<int>& boxes, int l, int r, int k, int lookup[100][100][100]) {
        if (l > r) {
            return 0;
        }
        if (lookup[l][r][k]) {
            return lookup[l][r][k];
        }

        auto& result = lookup[l][r][k];
        while (l < r && boxes[l + 1] == boxes[l]) {
            ++l, ++k;
        }
        result = removeBoxesHelper(boxes, l + 1, r, 0, lookup) + (k + 1) * (k + 1);
        for (int i = l + 1; i <= r; ++i) {
            if (boxes[i] == boxes[l]) {
                result = max(result,
                             removeBoxesHelper(boxes, l + 1,  i - 1, 0, lookup) +
                             removeBoxesHelper(boxes, i, r, k + 1, lookup));
            }
        }
        return result;
    }
};

// Time:  O(n^2)
// Space: O(n)

class Solution {
public:
    int findCircleNum(vector<vector<int>>& M) {
        UnionFind circles(M.size());
        for (int i = 0; i < M.size(); ++i) {
            for (int j = 0; j < M[i].size(); ++j) {
                if (M[i][j] && i != j) {
                    circles.union_set(i, j);
                }
            }
        }
        return circles.size();
    }

private:
    class UnionFind {
        public:
            UnionFind(const int n) : set_(n), count_(n) {
                iota(set_.begin(), set_.end(), 0);
            }

            int find_set(const int x) {
               if (set_[x] != x) {
                   set_[x] = find_set(set_[x]);  // Path compression.
               }
               return set_[x];
            }

            void union_set(const int x, const int y) {
                int x_root = find_set(x), y_root = find_set(y);
                if (x_root != y_root) {
                    set_[min(x_root, y_root)] = max(x_root, y_root);
                    --count_;
                }
            }

            int size() const {
                return count_;
            }

        private:
            vector<int> set_;
            int count_;
    };
};

