// Space: O(k)

class Solution {
public:
    int maxVacationDays(vector<vector<int>>& flights, vector<vector<int>>& days) {
        if (days.empty() || flights.empty()) {
            return 0;
        }
        vector<vector<int>> dp(2, vector<int>(days.size()));
        for (int week = days[0].size() - 1; week >= 0; --week) {
            for (int cur_city = 0; cur_city < days.size(); ++cur_city) {
                dp[week % 2][cur_city] = days[cur_city][week] + dp[(week + 1) % 2][cur_city];
                for (int dest_city = 0; dest_city < days.size(); ++dest_city) {
                    if (flights[cur_city][dest_city] == 1) {
                        dp[week % 2][cur_city] = max(dp[week % 2][cur_city],
                                                     days[dest_city][week] + dp[(week + 1) % 2][dest_city]);
                    }
                }
            }
        }
        return dp[0][0];
    }
};

// Time:  O(m * n), m is the number of nodes of s, n is the number of nodes of t
// Space: O(h), h is the height of s

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    bool isSubtree(TreeNode* s, TreeNode* t) {
        return preOrderTraverse(s, t);
    }

private:
    bool preOrderTraverse(TreeNode *s, TreeNode *t) {
        return s && (isSame(s, t) ||
                     preOrderTraverse(s->left, t) ||
                     preOrderTraverse(s->right, t));
    }

    bool isSame(TreeNode *x,TreeNode *y) {
        if (!x && !y) {
            return true;
        }
        if (!x || !y) {
            return false;
        }
        return x->val == y->val &&
               isSame(x->left, y->left) &&
               isSame(x->right, y->right);
    }
};

