private:
    int shoppingOffersHelper(const vector<int>& price, const vector<vector<int>>& special, vector<int>& needs, int i) {
        if (i == special.size()) {
            return inner_product(price.begin(), price.end(), needs.begin(), 0);
        }

        int result = shoppingOffersHelper(price, special, needs, i + 1);

        for (int j = 0; j < needs.size(); ++j) {
            needs[j] -= special[i][j];
        }
        if (all_of(needs.begin(), needs.end(), [](int i) { return i >= 0; })) {
            result = min(result, special[i].back() + shoppingOffersHelper(price, special, needs, i));
        }
        for (int j = 0; j < needs.size(); ++j) {
            needs[j] += special[i][j];
        }

        return result;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int numDecodings(string s) {
        static const int M = 1000000007;
        static const int W = 3;
        vector<long long> dp(W);
        dp[0] = 1;
        dp[1] = s[0] == '*' ? 9 : (s[0] != '0' ? dp[0] : 0);
        for (int i = 1; i < s.length(); ++i) {
            if (s[i] == '*') {
                dp[(i + 1) % W] = 9 * dp[i % W];
                if (s[i - 1] == '1') {
                    dp[(i + 1) % W] = (dp[(i + 1) % W] + 9 * dp[(i - 1) % W]) % M;
                } else if (s[i - 1] == '2') {
                    dp[(i + 1) % W] = (dp[(i + 1) % W] + 6 * dp[(i - 1) % W]) % M;
                } else if (s[i - 1] == '*') {
                    dp[(i + 1) % W] = (dp[(i + 1) % W] + 15 * dp[(i - 1) % W]) % M;
                }
            } else {
                dp[(i + 1) % W] = s[i] != '0' ? dp[i % W] : 0;
                if (s[i - 1] == '1') {
                    dp[(i + 1) % W] = (dp[(i + 1) % W] + dp[(i - 1) % W]) % M;
                } else if (s[i - 1] == '2' && s[i] <= '6') {
                    dp[(i + 1) % W] = (dp[(i + 1) % W] + dp[(i - 1) % W]) % M;
                } else if (s[i - 1] == '*') {
                    dp[(i + 1) % W] = (dp[(i + 1) % W] + (s[i] <= '6' ? 2 : 1) * dp[(i - 1) % W]) % M;
                }
            }
        }
        return static_cast<int>(dp[s.length() % W]);
    }
};

// Time:  O(n)
// Space: O(n)

class Solution {
public:
    string solveEquation(string equation) {
        auto a = 0, b = 0;
        auto side = 1;
        int submatches[] = { 1, 2, 3, 4 };
        auto e = regex("(=)|([-+]?)(\\d*)(x?)");
        for (regex_token_iterator<string::iterator> it(equation.begin(), equation.end(), e, submatches), end;
             it != end;) {
            auto eq = (it++)->str();
            auto sign = (it++)->str();
            auto num = (it++)->str();
            auto isx = (it++)->str();
            if (!eq.empty()) {
                side = -1;
            } else if (!isx.empty()) {
                a += side * stoi(sign + "1") * stoi(num.empty() ? "1" : num);
            } else if (!num.empty()) {
                b -= side * stoi(sign + num);
            }
        }
        return a != 0 ? "x=" + to_string(b / a) : b != 0 ? "No solution" : "Infinite solutions";
    }
};

// Time:  O(n)
// Space: O(n)
class Solution2 {
public:
    string solveEquation(string equation) {
        equation = regex_replace(equation, regex("(^|[+=-])x"), "$011x");

        auto pos = equation.find('=');
        auto l = coef(equation.substr(0, pos));
        auto r = coef(equation.substr(pos + 1));

        auto a = l.first - r.first;
        auto b = r.second - l.second;

        return a != 0 ? "x=" + to_string(b / a) : b != 0 ? "No solution" : "Infinite solutions";
    }

private:
    pair<int, int> coef(string s) {
        auto a = 0, b = 0;
        auto e = regex("(^|[+-])\\d+x?");
        for (regex_token_iterator<string::iterator> it(s.begin(), s.end(), e), end;
             it != end; ++it) {
            (it->str().back() == 'x' ? a : b) += stoi(*it);
        }
        return {a, b};
    } 
};

