/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    vector<vector<string>> printTree(TreeNode* root) {
        auto h = getHeight(root), w = getWidth(root);
        vector<vector<string>> result(h, vector<string>(w, ""));
        preorderTraversal(root, 0, 0, w - 1, &result);
        return result;
    }

private:
    int getHeight(TreeNode* root) {
        if (!root) {
            return 0;
        }
        return max(getHeight(root->left), getHeight(root->right)) + 1;
    }

    int getWidth(TreeNode* root) {
        if (!root) {
            return 0;
        }
        return 2 * max(getWidth(root->left), getWidth(root->right)) + 1;
    }

    void preorderTraversal(TreeNode *root, int level, int left, int right, vector<vector<string>> *result) {
        if (!root) {
            return;
        }
        auto mid = left + (right - left) / 2;
        (*result)[level][mid] = to_string(root->val);
        preorderTraversal(root->left, level + 1, left, mid - 1, result);
        preorderTraversal(root->right, level + 1, mid + 1, right, result);
    }
};

// Time:  O(n * B)
// Space: O(n)

class Solution {
public:
    vector<int> cheapestJump(vector<int>& A, int B) {
        vector<int> result;
        if (A.empty() || A.back() == -1) {
            return result;
        }
        const int n = A.size();
        vector<int> dp(n, numeric_limits<int>::max()), next(n, -1);
        dp[n - 1] = A[n - 1];
        for (int i = n - 2; i >= 0; --i) {
            if (A[i] == -1) {
                continue;
            }
            for (int j = i + 1; j <= min(i + B, n - 1); ++j) {
                if (dp[j] == numeric_limits<int>::max()) {
                    continue;
                }
                if (A[i] + dp[j] < dp[i]) {
                    dp[i] = A[i] + dp[j];
                    next[i] = j;
                }
            }
        }
        if (dp[0] == numeric_limits<int>::max()) {
            return result;
        }
        int k = 0;
        while (k != -1) {
            result.emplace_back(k + 1);
            k = next[k];
        }
        return result;
    }
};

