// Space: O(min(m, n))
// Binary search + rolling hash solution (36 ms)
class Solution2 {
public:
    int findLength(vector<int>& A, vector<int>& B) {
        if (A.size() > B.size()) {
            return findLength(B, A);
        }
        int left = 0, right = min(A.size(), B.size()) + 1;
        while (left < right) {
            const auto mid = left + (right-left) / 2;
            if (!check(mid, A, B)) {  // find the min idx such that check(idx) == false
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left - 1;
    }

private:
    bool check(const int guess, const vector<int>& A, const vector<int>& B) {
        unordered_map<uint64_t, vector<int>> hashes;
        int i = 0;
        for (const auto& hash_a : rolling_hashes(A, guess)) {
            hashes[hash_a].emplace_back(i++);
        }
        int j = 0;
        for (const auto& hash_b : rolling_hashes(B, guess)) {
            for (const auto& i : hashes[hash_b]) {
                if (equal(A.begin() + i, A.begin() + i + guess, B.begin() + j)) {
                    return true;
                }
            }
            ++j;
        }
        return false;
    }

    vector<uint64_t> rolling_hashes(const vector<int>& source, const int length) {
        static const uint64_t M = 1000000007;
        static const uint64_t p = 113; 
        static const uint64_t p_inv = pow(p, M - 2, M);
        vector<uint64_t> result(source.size() - length + 1);
        uint64_t hash = 0, power = 1;
        if (length == 0) {
            return result;
        }
        for (int i = 0; i < source.size(); ++i) {
            hash = (hash + source[i] * power) % M;
            if (i < length - 1) {
                power = (power * p) % M;
            } else {
                result[i - (length - 1)] = hash;
                hash = (hash - source[i - (length - 1)]) * p_inv % M;
            }
        }
        return result;
    }

    uint64_t pow(uint64_t a,uint64_t b, uint64_t m) {
        a %= m;
        uint64_t result = 1;
        while (b) {
            if (b & 1) {
                result = (result * a) % m;
            }
            a = (a * a) % m;
            b >>= 1;
        }
        return result;
    }
};

// Time:  O(nlogn + nlogw), n = len(nums), w = max(nums) - min(nums)
// Space: O(1)

// Binary search with sliding window solution
class Solution {
public:
    int smallestDistancePair(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());
        int left = 0, right = nums.back() - nums.front() + 1;
        while (left < right) {
            const auto mid = left + (right - left) / 2;
            if (possible(mid, nums, k)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }

private:
    bool possible(const int guess, const vector<int>& nums, const int k) {
        int count = 0, left = 0;
        for (int right = 0; right < nums.size(); ++right) {
            while ((nums[right] - nums[left]) > guess) {
                ++left;
            }
            count += right - left;
        }
        return count >= k;
    }
};

// Time:  O(n), n is the total sum of the lengths of words
// Space: O(t), t is the number of nodes in trie

class Solution {
public:
    string longestWord(vector<string>& words) {
        TrieNode trie;
        for (int i = 0; i < words.size(); ++i) {
            trie.Insert(words[i], i);
        }

        // DFS
        stack<TrieNode *> stk;
        for (const auto& node : trie.leaves) {
            if (node) {
                stk.emplace(node);
            }
        }

        string result;
        while (!stk.empty()) {
            const auto curr = stk.top(); stk.pop();
            if (curr->isString) {
                const auto& word = words[curr->val];
                if (word.size() > result.size() || (word.size() == result.size() && word < result)) {
                    result = word;
                }
                for (const auto& node : curr->leaves) {
                    if (node) {
                        stk.emplace(node);
                    }
                }
            }
        }
        return result;
    }

private:
    struct TrieNode {
        bool isString;
        int  val;
        vector<TrieNode *> leaves;

        TrieNode() : isString{false}, val{0}, leaves(26) {}

        void Insert(const string& s, const int i) {
            auto* p = this;
            for (const auto& c : s) {
                if (!p->leaves[c - 'a']) {
                    p->leaves[c - 'a'] = new TrieNode;
                }
                p = p->leaves[c - 'a'];
            }
            p->isString = true;
            p->val = i;
        }

        ~TrieNode() {
            for (auto& node : leaves) {
                if (node) {
                    delete node;
                }
            }
        }
    };
};

// Time:  O(nlogn), n is the number of total emails, and the max length of email is 320, p.s. {64}@{255}
// Space: O(n)

class Solution {
public:
    vector<vector<string>> accountsMerge(vector<vector<string>>& accounts) {
        UnionFind union_find;
        unordered_map<string, string> email_to_name;
        unordered_map<string, int> email_to_id;
        for (const auto& account : accounts) {
            const auto& name = account[0];
            for (int i = 1; i < account.size(); ++i) {
                if (!email_to_id.count(account[i])) {
                    email_to_name[account[i]] = name;
                    email_to_id[account[i]] = union_find.get_id();
                }
                union_find.union_set(email_to_id[account[1]], email_to_id[account[i]]);
            }
        }

        unordered_map<int, set<string>> lookup; 
        for (const auto& kvp : email_to_name) {
            const auto& email = kvp.first;
            lookup[union_find.find_set(email_to_id[email])].emplace(email);
        }
        vector<vector<string>> result;
        for (const auto& kvp : lookup) {
            const auto& emails = kvp.second;
            vector<string> tmp{email_to_name[*emails.begin()]};
            for (const auto& email : emails) {
                tmp.emplace_back(email);
            }
            result.emplace_back(move(tmp));
        }
        return result;
    }

private:
    class UnionFind {
        public:
            int get_id() {
                set_.emplace_back(set_.size());
                return set_.size() - 1;
            }

            int find_set(const int x) {
               if (set_[x] != x) {
                   set_[x] = find_set(set_[x]);  // Path compression.
               }
               return set_[x];
            }

            void union_set(const int x, const int y) {
                int x_root = find_set(x), y_root = find_set(y);
                if (x_root != y_root) {
                    set_[min(x_root, y_root)] = max(x_root, y_root);
                }
            }

        private:
            vector<int> set_;
    };
};

// Time:  O(n), n is the length of the source
// Space: O(k), k is the max length of a line

class Solution {
public:
    vector<string> removeComments(vector<string>& source) {
        bool in_block = false;
        vector<string> result;
        string newline;
        for (const auto& line : source) {
            for (int i = 0; i < line.length(); ++i) {
                if (!in_block && i + 1 < line.length() && line.substr(i, 2) == "/*") {
                    in_block = true;
                    ++i;
                } else if (in_block && i + 1 < line.length() && line.substr(i, 2) == "*/") {
                    in_block = false;
                    ++i;
                } else if (!in_block && i + 1 < line.length() && line.substr(i, 2) == "//") {
                    break;
                } else if (!in_block) {
                    newline.push_back(line[i]);
                }
            }
            if (!in_block && !newline.empty()) {
                result.emplace_back(move(newline));
            }
        }
        return result;
    }
};

// Time:  O((R * C)^2)
// Space: O(1)

class Solution {
public:
    vector<vector<int>> candyCrush(vector<vector<int>>& board) {
        const auto R = board.size(), C = board[0].size();
        bool changed = true;

        while (changed) {
            changed = false;

            for (int r = 0; r < R; ++r) {
                for (int c = 0; c + 2 < C; ++c) {
                    auto v = abs(board[r][c]);
                    if (v != 0 && v == abs(board[r][c + 1]) && v == abs(board[r][c + 2])) {
                        board[r][c] = board[r][c + 1] = board[r][c + 2] = -v;
                        changed = true;
                    }
                }
            }

            for (int r = 0; r + 2 < R; ++r) {
                for (int c = 0; c < C; ++c) {
                    auto v = abs(board[r][c]);
                    if (v != 0 && v == abs(board[r + 1][c]) && v == abs(board[r + 2][c])) {
                        board[r][c] = board[r + 1][c] = board[r + 2][c] = -v;
                        changed = true;
                    }
                }
            }

            for (int c = 0; c < C; ++c) {
                int empty_r = R - 1;
                for (int r = R - 1; r >= 0; --r) {
                    if (board[r][c] > 0) {
                        board[empty_r--][c] = board[r][c];
                    }
                }
                for (int r = empty_r; r >= 0; --r) {
                    board[r][c] = 0;
                }
            }
        }

        return board;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int pivotIndex(vector<int>& nums) {
        const auto total = accumulate(nums.begin(), nums.end(), 0);
        auto left_sum = 0;
        for (int i = 0; i < nums.size(); ++i) {
            if (left_sum == (total - left_sum - nums[i])) {
                return i;
            }
            left_sum += nums[i];
        }
        return -1;
    }
};

// Time:  O(n + k)
// Space: O(1)

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode(int x) : val(x), next(NULL) {}
 * };
 */
class Solution {
public:
    vector<ListNode*> splitListToParts(ListNode* root, int k) {
        auto n = 0;
        auto curr = root;
        while (curr) {
            curr = curr->next;
            n += 1;
        }
        auto width = n / k;
        auto remainder = n % k;

        vector<ListNode *> result;
        curr = root;
        for (int i = 0; i < k; ++i) {
            auto head = curr;
            for (int j = 0; curr &&
                 j < width - 1 + static_cast<int>(i < remainder); ++j) {
                curr = curr->next;
            }
            if (curr) {
                auto tail = curr;
                curr = curr->next;
                tail->next = nullptr;
            }
            result.emplace_back(head);
        }
        return result;
    }
};

