class Solution {
public:
    int countCornerRectangles(vector<vector<int>>& grid) {
        vector<vector<int>> rows;
        for (int i = 0; i < grid.size(); ++i) {
            vector<int> row;
            for (int j = 0; j < grid[i].size(); ++j) {
                if (grid[i][j]) {
                    row.emplace_back(j);
                }
            }
            if (!row.empty()) {
                rows.emplace_back(move(row));
            }
        }
        int result = 0;
        for (int i = 0; i < rows.size(); ++i) {
            unordered_set<int> lookup(rows[i].begin(), rows[i].end());
            for (int j = 0; j < i; ++j) {
                int count = 0;
                for (const auto& c : rows[j]) {
                    count += lookup.count(c);
                }
                result += count * (count - 1) / 2;
            }
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    vector<string> ipToCIDR(string ip, int range) {
        auto start = ipToInt(ip);
        vector<string> result;
        while (range > 0) {
            auto mask = max(33 - bitLength(start & ~(start - 1)),
                            33 - bitLength(range));
            result.emplace_back(intToIP(start) + "/" + to_string(mask));
            start += 1 << (32 - mask);
            range -= 1 << (32 - mask);
        }
        return result;
    }

private:
    uint32_t ipToInt(const string& ip) {
        uint32_t result = 0;
        for (const auto& n : split(ip, '.')) {
            result = 256 * result + stoi(n);
        }
        return result;
    }

    string intToIP(uint32_t n) {
        string ip;
        for (const auto& i : {24, 16, 8, 0}) {
            ip += to_string((n >> i) % 256);
            ip += ".";
        }
        ip.pop_back();
        return ip;
    }

    vector<string> split(const string& s, const char delim) {
        vector<string> tokens;
        stringstream ss(s);
        string token;
        while (getline(ss, token, delim)) {
            tokens.emplace_back(token);
        }
        return tokens;
    }

    uint32_t bitLength(uint32_t n) {
        uint32_t left = 1, right = 32;
        while (left <= right) {
            auto mid = left + (right - left) / 2;
            if ((1 << mid) > n) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }
};

// Time:  O(k * n^k + d), n is the number of alphabets,
//                        k is the length of target,
//                        d is the size of deadends
// Space: O(k * n^k + d)

class Solution {
public:
    int openLock(vector<string>& deadends, string target) {
        unordered_set<string> dead(deadends.begin(), deadends.end());
        vector<string> q{"0000"};
        unordered_set<string> lookup{"0000"};
        int depth = 0;
        while (!q.empty()) {
            vector<string> next_q;
            for (const auto& node : q) {
                if (node == target) {
                    return depth;
                }
                if (dead.count(node)) {
                    continue;
                }
                for (int i = 0; i < 4; ++i) {
                    auto n = node[i] - '0';
                    for (const auto& d : {-1, 1}) {
                        auto nn = (n + d + 10) % 10;
                        auto neighbor = node;
                        neighbor[i] = '0' + nn;
                        if (!lookup.count(neighbor)) {
                            lookup.emplace(neighbor);
                            next_q.emplace_back(neighbor);
                        }
                    }
                }
            }
            swap(q, next_q);
            ++depth;
        }
        return -1;
    }
};

// Time:  O(k^n)
// Space: O(k^n)

// https://en.wikipedia.org/wiki/De_Bruijn_sequence
// https://en.wikipedia.org/wiki/Lyndon_word
class Solution {
public:
    string crackSafe(int n, int k) {
        const int M = pow(k, n - 1);
        vector<int> P;
        for (int i = 0; i < k; ++i) {
            for (int q = 0; q < M; ++q) {
                P.emplace_back(q * k + i);  // rotate: i*k^(n-1) + q => q*k + i
            }
        }
        const int total = pow(k, n);
        string result(n - 1, '0' + k - 1);
        for (int i = 0; i < total; ++i) {
            int j = i;
            // concatenation in lexicographic order of Lyndon words
            while (P[j] >= 0) {
                result.push_back('0' + j / M);
                auto Pj = P[j];
                P[j] = -1;
                j = Pj;
            }
        }
        return result;
    }
};

// Time:  O(k^n)
// Space: O(k^n)
class Solution2 {
public:
    string crackSafe(int n, int k) {
        const int M = pow(k, n - 1);
        int unique_rolling_hash = 0;
        string result(n - 1, '0');
        unordered_set<int> lookup;
        const int total = pow(k, n);
        while (lookup.size() < total) {
            for (int i = k - 1; i >= 0; --i) {  // preorder like traversal relative to initial result to avoid getting stuck, i.e. don't use 0 until there is no other choice
                const auto& new_unique_rolling_hash = unique_rolling_hash * k + i;
                if (!lookup.count(new_unique_rolling_hash)) {
                    lookup.emplace(new_unique_rolling_hash);
                    result.push_back('0' + i);
                    unique_rolling_hash = new_unique_rolling_hash % M;
                    break;
                }
            }
        }
        return result;
    }
};

