                    break;
                }
            }
            ++heights[best];
        }
        return heights;
    }
};

// Time:  O((a^(b+1)-a)/(a-1)) = O(a^b) , a is the size of allowed, 
//                                        b is the length of bottom
// Space: O((a^(b+1)-a)/(a-1)) = O(a^b) 

// dfs solution
class Solution {
public:
    bool pyramidTransition(string bottom, vector<string>& allowed) {
        vector<vector<vector<int>>> edges(7, vector<vector<int>>(7));
        unordered_set<string> lookup;
        for (const auto& s: allowed) {
            edges[s[0] - 'A'][s[1] - 'A'].emplace_back(s[2] - 'A');
        }
        return pyramidTransitionHelper(bottom, edges, &lookup);
    }

private:
    bool pyramidTransitionHelper(const string& bottom, const vector<vector<vector<int>>>& edges,
                                 unordered_set<string> *lookup) {
        if (bottom.size() == 1) {
            return true;
        }
        for (int i = 0; i < bottom.size() - 1; ++i) {
            if (edges[bottom[i] - 'A'][bottom[i + 1] - 'A'].empty()) {
                return false;
            }
        }
        if (lookup->count(bottom)) {
            return false;
        }
        lookup->emplace(bottom);
        string new_bottom(bottom.size() - 1, 'A');
        return dfs(bottom, edges, &new_bottom, 0, lookup);
    }

    bool dfs(const string& bottom, const vector<vector<vector<int>>>& edges, string *new_bottom, int idx,
             unordered_set<string> *lookup) {
        if (idx == bottom.size() - 1) {
            return pyramidTransitionHelper(*new_bottom, edges, lookup);
        }
        for (const auto& i : edges[bottom[idx] - 'A'][bottom[idx + 1] - 'A']) {
            (*new_bottom)[idx] = i + 'A';
            if (dfs(bottom, edges, new_bottom, idx + 1, lookup)) {
                return true;
            }
        }
        return false;
    }
};

// Time:  O(nlogn)
// Space: O(n)

// greedy solution
class Solution {
public:
    int intersectionSizeTwo(vector<vector<int>>& intervals) {
        sort(intervals.begin(), intervals.end(),
             [](const vector<int>& a, const vector<int>& b) {
                 return (a[0] != b[0]) ? (a[0] < b[0]) : (b[1] < a[1]);
             });
        vector<int> cnts(intervals.size(), 2);
        int result = 0;
        while (!intervals.empty()) {
            auto start = intervals.back()[0]; intervals.pop_back();
            auto cnt = cnts.back(); cnts.pop_back();
            for (int s = start; s < start + cnt; ++s) {
                for (int i = 0; i < intervals.size(); ++i) {
                    if (cnts[i] && s <= intervals[i][1]) {
                        --cnts[i];
                    }
                }
            }
            result += cnt;
        }
        return result;
    }
};

// Time:  O(n * l), n is the length of S, l is the average length of words
// Space: O(t)    , t is the size of trie

class Solution {
public:
    string boldWords(vector<string>& words, string S) {
        TrieNode trie;
        for (const auto& word : words) {
            trie.Insert(word);
        }

        vector<bool> lookup(S.length());
        for (int i = 0; i < S.length(); ++i) {
            auto curr = &trie;
            int k = i - 1;
            for (int j = i; j < S.length(); ++j) {
                if (!curr->leaves[S[j] - 'a']) {
                    break;
                }
                curr = curr->leaves[S[j] - 'a'];
                if (curr->isString) {
                    k = j;
                }
            }
            fill(lookup.begin() + i, lookup.begin() + k + 1, true);
        }

        string result;
        for (int i = 0; i < S.length(); ++i) {
            if (lookup[i] && (i == 0 || !lookup[i - 1])) {
                result += "<b>";
            }
            result.push_back(S[i]);
            if (lookup[i] && (i == (S.length() - 1) || !lookup[i + 1])) {
                result += "</b>";
            }
        }
        return result;
    }

private:
    struct TrieNode {
        bool isString;
        vector<TrieNode *> leaves;

        TrieNode() : isString{false}, leaves(26) {}

        void Insert(const string& s) {
            auto* p = this;
            for (const auto& c : s) {
                if (!p->leaves[c - 'a']) {
                    p->leaves[c - 'a'] = new TrieNode;
                }
                p = p->leaves[c - 'a'];
            }
            p->isString = true;
        }

        ~TrieNode() {
            for (auto& node : leaves) {
                if (node) {
                    delete node;
                }
            }
        }
    };
};


