/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    vector<TreeNode*> splitBST(TreeNode* root, int V) {
        if (!root) {
            return {nullptr, nullptr};
        } else if (root->val <= V) {
            const auto& result = splitBST(root->right, V);
            root->right = result[0];
            return {root, result[1]};
        } else {
            const auto& result = splitBST(root->left, V);
            root->left = result[1];
            return {result[0], root};
        }
    }
};

// Time:  O(n)
// Space: O(1)

// the followings are invariant if the number of 'X' in both strings are the same
// 1. the ordering of 'L', 'R' in both strings are the same
// 2. for each position (i, j) of paired 'L' character in both strings, i >= j
// 3. for each position (i, j) of paired 'R' character in both strings, i <= j
class Solution {
public:
    bool canTransform(string start, string end) {
        int count = 0;
        for (int i = 0; i < size(start); ++i) {
            if (start[i] == 'X') {
                ++count;
            }
            if (end[i] == 'X') {
                --count;
            }
        }
        if (count) {
            return false;
        }
        for (int i = 0, j = 0; i < size(start) && j < size(end); ++i, ++j) {
            while (i < size(start) && start[i] == 'X') {
                ++i;
            }
            while (j < size(end) && end[j] == 'X') {
                ++j;
            }
            if ((i < size(start)) != (j < size(end))) {
                return false;
            }
            if (i < size(start) && j < size(end)) {
                if (start[i] != end[j] ||
                    (start[i] == 'L' && i < j) ||
                    (start[i] == 'R' && i > j)) {
                    return false;
                }
            }
        }
        return true;
    }
};

// Time:  O(n^2)
// Space: O(n^2)

class Solution {
public:
    int swimInWater(vector<vector<int>>& grid) {
        const int n = grid.size();
        vector<pair<int, int>> positions(n * n);
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                positions[grid[i][j]] = {i, j};
            }
        }
        static const vector<pair<int, int>> directions{{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        UnionFind union_find(n * n);
        for (int elevation = 0; elevation < positions.size(); ++elevation) {
            int i, j;
            tie(i, j) = positions[elevation];
            for (const auto& dir : directions) {
                int x = i + dir.first;
                int y = j + dir.second;
                if (0 <= x && x < n &&
                    0 <= y && y < n &&
                    grid[x][y] <= elevation) {
                    union_find.union_set(i * n + j, x * n + y);
                    if (union_find.find_set(0) == union_find.find_set(n * n - 1)) {
                        return elevation;
                    }
                }
            }
        }
        return n * n - 1;
    }

private:
    class UnionFind {
    public:
        UnionFind(const int n) : set_(n) {
            iota(set_.begin(), set_.end(), 0);
        }

        int find_set(const int x) {
           if (set_[x] != x) {
               set_[x] = find_set(set_[x]);  // Path compression.
           }
           return set_[x];
        }

        void union_set(const int x, const int y) {
            int x_root = find_set(x), y_root = find_set(y);
            if (x_root != y_root) {
                set_[min(x_root, y_root)] = max(x_root, y_root);
            }
        }

    private:
        vector<int> set_;
    };
};

