// Space: O(k), k is the number of words

class Solution {
public:
    int numMatchingSubseq(string S, vector<string>& words) {
        unordered_map<char, vector<pair<int, int>>> waiting;
        for (int i = 0; i < words.size(); ++i) {
            waiting[words[i][0]].emplace_back(i, 1);
        }
        for (const auto& c : S) {
            auto advance = move(waiting[c]);
            waiting.erase(c);
            for (const auto& kvp : advance) {
                int i = kvp.first, j = kvp.second;
                int next = (j != words[i].length()) ? words[i][j] : 0;
                waiting[next].emplace_back(i, j + 1);
            }
        }
        return waiting[0].size();
    }
};

// Time:  O((logn)^2)
// Space: O(1)

class Solution {
public:
    int preimageSizeFZF(int K) {
        const int p = 5;
        int left = 0, right = p * K;
        while (left <= right) {
            const int mid = left + (right - left) / 2;
            if (countOfFactorialPrimes(mid, p) >= K) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return countOfFactorialPrimes(left, p) == K ? p : 0;
    }

private:
    int countOfFactorialPrimes(int n, int p) {
        int cnt = 0;
        for (; n > 0; n /= p) {
            cnt += n / p;
        }
        return cnt;
    }
};

