        vector<Color> lookup(size(graph), WHITE);

        const function<bool(int)> dfs = [&](int node) {
            if (lookup[node] != WHITE) {
                return lookup[node] == BLACK;
            }
            lookup[node] = GRAY;
            if (any_of(cbegin(graph[node]), cend(graph[node]), [&](const auto& child) { return !dfs(child); })) {
