// Time:  O(1)
// Space: O(1)

class Solution {
private:
    template <typename T>
    struct PairHash {
        size_t operator()(const pair<T, T>& p) const {
            size_t seed = 0;
            seed ^= std::hash<T>{}(p.first)  + 0x9e3779b9 + (seed<<6) + (seed>>2);
            seed ^= std::hash<T>{}(p.second) + 0x9e3779b9 + (seed<<6) + (seed>>2);
            return seed;
        }
    };

public:
    double soupServings(int N) {
        if (N > 4800) {
            return 1.0;
        }
        unordered_map<pair<int, int>, double, PairHash<int>> lookup;
        N = (N + 24) / 25;
        return dp(N, N, &lookup);
    }

private:
    double dp(int a, int b, unordered_map<pair<int, int>, double, PairHash<int>> *lookup) {
        if (lookup->count(make_pair(a, b))) {
            return (*lookup)[make_pair(a, b)];
        }
        if (a <= 0 && b <= 0) {
            return 0.5;
        }
        if (a <= 0) {
            return 1.0;
        }
        if (b <= 0) {
            return 0.0;
        }
        (*lookup)[make_pair(a, b)] = 0.25 * (dp(a - 4, b, lookup) +
                                             dp(a - 3, b - 1, lookup) +
                                             dp(a - 2, b - 2, lookup) +
                                             dp(a - 1, b - 3, lookup));
        return (*lookup)[make_pair(a, b)];
    }
};

// Time:  O(n + s), n is the sum of all word lengths, s is the length of S
// Space: O(l + s)

class Solution {
public:
    int expressiveWords(string S, vector<string>& words) {
        int result = 0;
        const auto& R = RLE(S);
        for (const auto& word : words) {
            const auto& R2 = RLE(word);
            if (R.key != R2.key) {
                continue;
            }
            int i;
            for (i = 0; i < R.counts.size(); ++i) {
               const auto& c1 = R.counts[i];
               const auto& c2 = R2.counts[i];
               if (c1 < max(c2, 3) && c1 != c2) {
                   break;
               }
            }
            if (i == R.counts.size()) {
                ++result;
            }
        }
        return result;
    }

private:
    struct RLE {
        string key;
        vector<int> counts;
        RLE(const string& s) {
            int prev = -1;
            for (int i = 0; i < s.length(); ++i) {
                if (i == s.length() - 1 || s[i] != s[i + 1]) {
                    key.push_back(s[i]);
                    counts.emplace_back(i - prev);
                    prev = i;
                }
            }
        }
    };
};

