// Time:  O(n), is the length of cpdomains (assuming the length of cpdomains[i] is fixed)
// Space: O(n)

class Solution {
public:
    vector<string> subdomainVisits(vector<string>& cpdomains) {
        unordered_map<string, int> counts;
        for (const auto& cpdomain : cpdomains) {
            int i = cpdomain.find(" ");
            const int count = stoi(cpdomain.substr(0, i));
            const auto& domain = cpdomain.substr(i + 1);
            for (int i = -1; i < static_cast<int>(domain.length()); ++i) {
                if (i != -1 && domain[i] != '.') {
                    continue;
                }
                counts[domain.substr(i + 1)] += count;
            }
        }

        vector<string> result;
        for (const auto& count : counts) {
            result.emplace_back(to_string(count.second));
            result.back() += " ";
            result.back() += count.first;
        }
        return result;
    }
};

// Time:  O(n^3)
// Space: O(1)

class Solution {
public:
    double largestTriangleArea(vector<vector<int>>& points) {
        double result = 0.0;
        for (int i = 0; i < points.size() - 2; ++i) {
            for (int j = i + 1; j < points.size() - 1; ++j) {
                for (int k = j + 1; k < points.size(); ++k) {
                    result = max(result,
                                 0.5 * abs(points[i][0] * points[j][1] +
                                           points[j][0] * points[k][1] +
                                           points[k][0] * points[i][1] -
                                           points[j][0] * points[i][1] -
                                           points[k][0] * points[j][1] -
                                           points[i][0] * points[k][1]));
                }
            }
        }
        return result;
    }
};

// Time:  O(k * n^2)
// Space: O(n)

class Solution {
public:
    double largestSumOfAverages(vector<int>& A, int K) {
        vector<int> accum_sum;
        accum_sum.emplace_back(A[0]);
        for (int i = 1; i < A.size(); ++i) {
            accum_sum.emplace_back(A[i] + accum_sum.back());
        }

        vector<vector<double>> dp(2, vector<double>(A.size()));
        for (int k = 1; k <= K; ++k) {
            for (int i = k - 1; i < A.size(); ++i) {
                if (k == 1) {
                    dp[k % 2][i] = static_cast<double>(accum_sum[i]) / (i + 1);
                } else {
                    for (int j = k - 2 ; j < i; ++j) {
                        dp[k % 2][i] = max(dp[k % 2][i],
                                           dp[(k - 1) % 2][j] +
                                           static_cast<double>(accum_sum[i] - accum_sum[j]) / (i - j));
                    }
                }
            }
        }
        return dp[K % 2].back();
    }
};

// Time:  O(n)
// Space: O(h)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    TreeNode* pruneTree(TreeNode* root) {
        if (!root) {
            return nullptr;
        }
        root->left = pruneTree(root->left);
        root->right = pruneTree(root->right);
        if (!root->left && !root->right && root->val == 0) {
            return nullptr;
        }
        return root;  
    }
};

// Time:  O(|V| + |E|)
// Space: O(|V| + |E|)

class Solution {
public:
    int numBusesToDestination(vector<vector<int>>& routes, int S, int T) {
        if (S == T) {
            return 0;
        }
        unordered_map<int, unordered_set<int>> to_route;
        for (int i = 0; i < routes.size(); ++i) {
            for (const auto& stop : routes[i]) {
                to_route[stop].emplace(i);
            }
        }

        int result = 1;
        vector<int> q{S};
        unordered_set<int> lookup{S};
        while (!q.empty()) {
            vector<int> next_q;
            for (const auto& stop : q) {
                for (const auto& i : to_route[stop]) {
                    for (const auto& next_stop : routes[i]) {
                        if (lookup.count(next_stop)) {
                            continue;
                        }
                        if (next_stop == T) {
                            return result;
                        }
                        next_q.emplace_back(next_stop);
                        to_route[next_stop].erase(i);
                        lookup.emplace(next_stop);
                    }
                }
            }
            swap(q, next_q);
            ++result;
        }
        return -1;
    }
};

// Time:  O(n^4)
// Space: O(n^2)

class Solution {
public:
    vector<string> ambiguousCoordinates(string S) {
        vector<string> result;
        for (int i = 1; i < S.length() - 2; ++i) {
            const auto& lefts = make(S, 1, i);
            const auto& rights = make(S, i + 1, S.length() - 2 - i);
            for (const auto& left : lefts) {
                for (const auto& right : rights) {
                    string s;
                    s += "(";
                    s += left;
                    s += ", ";
                    s += right;
                    s += ")";
                    result.emplace_back(move(s));
                }
            }
        }
        return result;
    }

private:
    // Time:  O(n^2)
    // Space: O(n^2)
    vector<string> make(const string& S, int i, int n) {
        vector<string> result;
        for (int d = 1; d <= n; ++d) {
            const auto& left = S.substr(i, d);
            const auto& right = S.substr(i + d, n - d);
            if ((left.front() != '0' || left == "0") &&
                 right.back() != '0') {
                string s;
                s += left;
                s += (!right.empty() ? "." : "");
                s += right;
                result.emplace_back(move(s));
            }
        }
        return result;
    }
};

// Time:  O(m + n), m is the number of G, n is the number of nodes
// Space: O(m)

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode(int x) : val(x), next(NULL) {}
 * };
 */
class Solution {
public:
    int numComponents(ListNode* head, vector<int>& G) {
        unordered_set<int> lookup(G.cbegin(), G.cend());
        ListNode dummy(-1);
        dummy.next = head;
        auto curr = &dummy;
        int result = 0;
        while (curr && curr->next) {
            if (!lookup.count(curr->val) && lookup.count(curr->next->val)) {
                ++result;
            }
            curr = curr->next;
        }
        return result;
    }
};

// Time : O(nlogn), n is the value of the target
// Space: O(n)

class Solution {
public:
    int racecar(int target) {
        vector<int> dp(target + 1);
        for (int i = 1; i <= target; ++i) {
            int k = bitLength(i);
            if (i == (1 << k) - 1) {
                dp[i] = k;
                continue;
            }
            dp[i] = dp[(1 << k) - 1 - i] + k + 1;
            for (int j = 0; j < k; ++j) {
                dp[i] = min(dp[i], dp[i - (1 << (k - 1)) + (1 << j)] + k + j + 1);
            }
        }
        return dp.back();
    }

private:
    uint32_t bitLength(uint32_t n) {
        uint32_t left = 1, right = 32;
        while (left <= right) {
            auto mid = left + (right - left) / 2;
            if ((1 << mid) > n) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }
};

// Time:  O(m + n), m is the size of banned, n is the size of paragraph
// Space: O(m + n)

class Solution {
public:
    string mostCommonWord(string paragraph, vector<string>& banned) {
        unordered_set<string> lookup(banned.cbegin(), banned.cend());
        unordered_map<string, int> counts;
        string word;
        for (const auto& c : paragraph) {
            if (isalpha(c)) {
                word.push_back(tolower(c));
            } else if (!word.empty()) {
                ++counts[word];
                word.clear();
            }
        }
        if (!word.empty()) {
            ++counts[word];
        }
        string result;
        for (const auto& kvp : counts) {
            if ((result.empty() || kvp.second > counts[result]) &&
                !lookup.count(kvp.first)) {
                result = kvp.first;
            }
        }
        return result;
    }
};

// Time:  O(n), n is the total sum of the lengths of words
// Space: O(t), t is the number of nodes in trie

class Solution {
public:
    int minimumLengthEncoding(vector<string>& words) {
        unordered_set<string> unique_words(words.cbegin(), words.cend());
        vector<TrieNode *> leaves;
        TrieNode trie;
        for (auto word : unique_words) {
            reverse(word.begin(), word.end());
            leaves.emplace_back(trie.Insert(word));
        }
        int result = 0;
        int i = 0;
        for (const auto& word: unique_words) {
            if (leaves[i++]->leaves.empty()) {
                result += word.length() + 1;
            }
        }
        return result;
    }

private:
    struct TrieNode {
        unordered_map<int, TrieNode *> leaves;

        TrieNode *Insert(const string& s) {
            auto* p = this;
            for (const auto& c : s) {
                if (!p->leaves[c - 'a']) {
                    p->leaves[c - 'a'] = new TrieNode;
                }
                p = p->leaves[c - 'a'];
            }
            return p;
        }

        ~TrieNode() {
            for (auto& node : leaves) {
                delete node.second;
            }
        }
    };
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    vector<int> shortestToChar(string S, char C) {
        vector<int> result(S.length(), S.length());
        int prev = -S.length();
        for (int i = 0; i < S.length(); ++i) {
            if (S[i] == C) {
                prev = i;
            }
            result[i] = min(result[i], abs(i - prev));
        }
        for (int i = S.length() - 1; i >= 0; --i) {
            if (S[i] == C) {
                prev = i;
            }
            result[i] = min(result[i], abs(i - prev));
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(n)

class Solution {
public:
    int flipgame(vector<int>& fronts, vector<int>& backs) {
        unordered_set<int> same;
        for (int i = 0; i < fronts.size(); ++i) {
            if (fronts[i] == backs[i]) {
                same.emplace(fronts[i]);
            }
        }
        int result = numeric_limits<int>::max();
        for (const auto& n : fronts) {
            if (!same.count(n)) {
                result = min(result, n);
            }
        }
        for (const auto& n : backs) {
            if (!same.count(n)) {
                result = min(result, n);
            }
        }
        return result != numeric_limits<int>::max() ? result : 0;
    }
};

// Time:  O(n^2)
// Space: O(n)

class Solution {
public:
    int numFactoredBinaryTrees(vector<int>& A) {
        static const int M = 1e9 + 7;
        sort(A.begin(), A.end());
        unordered_map<int, int64_t> dp;
        for (int i = 0; i < A.size(); ++i) {
            dp[A[i]] = 1;
            for (int j = 0; j < i; ++j) {
                if (A[i] % A[j] == 0 && dp.count(A[i] / A[j])) {
                   dp[A[i]] = (dp[A[i]] + dp[A[j]] * dp[A[i] / A[j]]) % M;
                }
            }
        }
        return accumulate(dp.cbegin(), dp.cend(), 0L,
                          [](int64_t x, const pair<int, int>& p) {
                              return x + p.second;
                          }) % M;
    }
};

// Time:  O(n + w^2), n = w * l,
//                    n is the length of S,
//                    w is the number of words,
//                    l is the average of word lengths
// Space: O(l)

class Solution {
public:
    string toGoatLatin(string S) {
        unordered_set<char> vowel{'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'};
        string result, word;
        int count = 0;
        for (int i = 0; i < S.length(); ++i) {
            if (S[i] != ' ') {
                word.push_back(S[i]);
                if (i != S.length() - 1) {
                    continue;
                }
            }
            if (!vowel.count(word.front())) {
                word.push_back(word.front());
                word = word.substr(1);
            }
            word += "ma";
            word += string(++count, 'a');
            result += word;
            result += " ";
            word.clear();
        }
        result.pop_back();
        return result;
    }
};

// Time:  O(a^2 + n), a is the number of ages,
//                    n is the number of people
// Space: O(a)

class Solution {
public:
    int numFriendRequests(vector<int>& ages) {
        unordered_map<int, int> count;
        for (const auto &age : ages) {
            ++count[age];
        }
        int result = 0;
        for (const auto &a: count) {
            for (const auto &b: count) {
                if (request(a.first, b.first)) {
                    result += a.second * (b.second - (a.first == b.first ? 1 : 0));
                }
            }
        }
        return result;
    }

private:
    bool request(int a, int b) {
        return 0.5 * a + 7 < b && b <= a;
    }
};

// Time:  O(mlogm + nlogn), m is the number of workers,
//                        , n is the number of jobs
// Space: O(n)

class Solution {
public:
    int maxProfitAssignment(vector<int>& difficulty, vector<int>& profit, vector<int>& worker) {
        vector<pair<int,int>> jobs;
        for (int i = 0; i < profit.size(); ++i) {
            jobs.emplace_back(difficulty[i], profit[i]);
        }
        sort(jobs.begin(), jobs.end());
        sort(worker.begin(), worker.end());

        int result = 0, i = 0, max_profit = 0;
        for (const auto& ability: worker) {
            while (i < profit.size() && jobs[i].first <= ability) {
                max_profit = max(max_profit, jobs[i++].second);
            }
            result += max_profit;
        }
        return result;
    }
};

// Time:  O(n^2)
// Space: O(n^2)

class Solution {
public:
    int largestIsland(vector<vector<int>>& grid) {
        int result = 0;
        unordered_map<int, int> area;
        int index = 2;
        for (int r = 0; r < grid.size(); ++r) {
            for (int c = 0; c < grid[r].size(); ++c) {
                if (grid[r][c] != 1) {
                    continue;
                }
                area[index] = dfs(r, c, index, &grid);
                result = max(result, area[index++]);
            }
        }

        for (int r = 0; r < grid.size(); ++r) {
            for (int c = 0; c < grid[r].size(); ++c) {
                if (grid[r][c] != 0) {
                    continue;
                }
                unordered_set<int> seen;
                for (const auto& d :directions) {
                    int nr = r + d.first, nc = c + d.second;
                    if (0 <= nr && nr < grid.size() &&
                        0 <= nc && nc < grid[0].size() &&
                        grid[nr][nc] > 1) {
                        seen.emplace(grid[nr][nc]);
                    }
                }
                int sum = 0;
                for (const auto& i : seen) {
                    sum += area[i];
                }
                result = max(result, 1 + sum);
            }
        }
        return result;
    }

private:
    const vector<pair<int, int>> directions{{0, -1}, {0, 1}, {-1, 0}, {1, 0}};

    int dfs(int r, int c, int index, vector<vector<int>> *grid) {
        if (!(0 <= r && r < grid->size() &&
              0 <= c && c < (*grid)[0].size() &&
              (*grid)[r][c] == 1)) {
            return 0;
        }
        int result = 1;
        (*grid)[r][c] = index;
        for (const auto& d :directions) {
            result += dfs(r + d.first, c + d.second, index, grid);
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int uniqueLetterString(string S) {
        static const int M = 1e9 + 7;
        int result = 0;
        vector<vector<int>> index(26, vector<int>(2, -1));
        for (int i = 0; i < S.length(); ++i) {
            int c = S[i] - 'A';
            result = (result + (i - index[c][1]) *
                               (index[c][1] - index[c][0])) % M;
            index[c][0] = index[c][1];
            index[c][1] = i;
        }
        for (int c = 0; c < 26; ++c) {
            result = (result + (S.length() - index[c][1]) *
                               (index[c][1] - index[c][0])) % M;
        }
        return result;
    }
};

// Time:  O(sqrt(n))
// Space: O(1)

class Solution {
public:
    int consecutiveNumbersSum(int N) {
        int result = 1;
        while (N % 2 == 0) {
            N /= 2;
        }
        for (int i = 3; i * i <= N; i += 2) {
            int count = 0;
            while (N % i == 0) {
                N /= i;
                ++count;
            }
            result *= count + 1;
        }
        if (N != 1) {
            result *= 1 + 1;
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
