    vector<vector<int>> largeGroupPositions(string S) {
        vector<vector<int>> result;
        for (int i = 0, j = 0; j < S.length(); ++j) {
            if (j == S.length() - 1 || S[j] != S[j + 1]) {
                if (j - i + 1 >= 3) {
                    result.emplace_back(vector<int>{i, j});
                }
                i = j + 1;
            }
        }
        return result;
    }
};

// Time:  O(1)
// Space: O(1)

class Solution {
public:
    string maskPII(string S) {
        auto at = S.find("@");
        if (at != string::npos) {
            transform(S.begin(), S.end(), S.begin(), ::tolower);
            return S.substr(0, 1) + "*****" + S.substr(at - 1);
        }
        string digits;
        for (const auto& c : S) {
            if (::isdigit(c)) {
                digits.push_back(c);
            }
        }
        string local{"***-***-"};
        local += digits.substr(digits.length() - 4);
        if (digits.length() == 10) {
            return local;
        }
        return "+" + string(digits.length() - 10, '*') + "-" + local;
    }
};

// Time:  O(n^2)
// Space: O(1)

class Solution {
public:
    vector<vector<int>> flipAndInvertImage(vector<vector<int>>& A) {
        for (auto& row : A) {
            for (int i = 0; i < (row.size() + 1) / 2; ++i) {
                row[i] ^= 1;
                if (i != row.size() + ~i) {
                    row[row.size() + ~i] ^= 1;
                    swap(row[i], row[row.size() + ~i]);
                }
            }
        }
        return A;
    }
};

// Time:  O(n + m), m is the number of targets
// Space: O(n)

class Solution {
public:
    string findReplaceString(string S, vector<int>& indexes, vector<string>& sources, vector<string>& targets) {
        vector<pair<int, string>> bucket(S.length());
        for (int i = 0; i < indexes.size(); ++i)  {
            if (S.compare(indexes[i], sources[i].length(), sources[i]) == 0) {
                bucket[indexes[i]] = {sources[i].length(), targets[i]};
            }
        }
        string result;
        for (int i = 0; i < S.length();) {
            if (bucket[i].first) {
                result += bucket[i].second;
                i += bucket[i].first;
            } else {
                result.push_back(S[i++]);
            }
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(n)

class Solution {
public:
    vector<int> sumOfDistancesInTree(int N, vector<vector<int>>& edges) {
        unordered_map<int, vector<int>> graph;
        for (const auto& edge : edges) {
            graph[edge[0]].emplace_back(edge[1]);
            graph[edge[1]].emplace_back(edge[0]);
        }

        vector<int> count(N, 1);
        vector<int> result(N, 0);

        dfs(graph, 0, -1, &count, &result);
        dfs2(graph, 0, -1, &count, &result);
        return result;
    }

private:
    void dfs(const unordered_map<int, vector<int>>& graph,
             int node, int parent,
             vector<int> *count, vector<int> *result) {
        if (!graph.count(node)) {
            return;
        }
        for (const auto& nei : graph.at(node)) {
            if (nei != parent) {
                dfs(graph, nei, node, count, result);
                (*count)[node] += (*count)[nei];
                (*result)[node] += (*result)[nei] + (*count)[nei];
            }
        }
    }

    void dfs2(const unordered_map<int, vector<int>>& graph,
             int node, int parent,
             vector<int> *count, vector<int> *result) {
        if (!graph.count(node)) {
            return;
        }
        for (const auto& nei : graph.at(node)) {
            if (nei != parent) {
                (*result)[nei] = (*result)[node] - (*count)[nei] +
                                 count->size() - (*count)[nei];
                dfs2(graph, nei, node, count, result);
            }
        }
    }
};

// Time:  O(n^4)
// Space: O(n^2)

class Solution {
public:
    int largestOverlap(vector<vector<int>>& A, vector<vector<int>>& B) {
        vector<int> count(pow(2 * A.size() - 1, 2));
        for (int i = 0; i < A.size(); ++i) {
            for (int j = 0; j < A[i].size(); ++j) {
                if  (!A[i][j]) {
                    continue;
                }
                for (int m = 0; m < B.size(); ++m) {
                   for (int n = 0; n < B[m].size(); ++n) {
                        if (!B[m][n]) {
                            continue;
                        }
                        ++count[(A.size() - 1 + i - m) * (2 * A.size() - 1) +
                                 A.size() - 1 + j - n];
                   }
                }
            }
        }
        return *max_element(count.cbegin(), count.cend());
    }
};

