// Time:  O(n)
// Space: O(n)

class Solution {
public:
    double new21Game(int N, int K, int W) {
        if (K == 0 || N >= K + W) {
            return 1.0f;
        }
        vector<double> dp(N + 1);
        dp[0] = 1.0f;
        double W_sum = 1.0f, result = 0.0f;
        for (int i = 1; i <= N; ++i) {
            dp[i] = W_sum / W;
            if (i < K) {
                W_sum += dp[i];
            } else {
                result += dp[i];
            }
            if (i - W >= 0) {
                W_sum -= dp[i - W];
            }
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(n)

class Solution {
public:
    string pushDominoes(string dominoes) {
        vector<int> force(dominoes.length());

        int f = 0;
        for (int i = 0; i < dominoes.length(); ++i) {
            if (dominoes[i] == 'R') {
                f = dominoes.length();
            } else if (dominoes[i] == 'L') {
                f = 0;
            } else {
                f = max(f - 1, 0);
            }
            force[i] += f;
        }

        f = 0;
        for (int i = dominoes.length() - 1; i >= 0; --i) {
            if (dominoes[i] == 'L') {
                f = dominoes.length();
            } else if (dominoes[i] == 'R') {
                f = 0;
            } else {
                f = max(f - 1, 0);
            }
            force[i] -= f;
        }
        string result;
        for (const auto& f : force) {
            result.push_back((f == 0) ? '.' : ((f > 0) ? 'R' : 'L'));
        }
        return result;
    }
};

// Time:  O(n^2 * l), l is the average length of words
// Space: O(n)

class Solution {
public:
    int numSimilarGroups(vector<string>& A) {
        UnionFind union_find(A.size());
        for (int i = 0; i < A.size(); ++i) {
            for (int j = 0; j < i; ++j) {
                if (isSimilar(A[i], A[j])) {
                    union_find.union_set(i, j);
                }
            }
        }
        return union_find.size();
    }

private:
    bool isSimilar(const string& a, const string& b) {
        int diff = 0;
        for (int i = 0; i < a.length(); ++i) {
            if (a[i] != b[i]) {
                if (++diff > 2) {
                    return false;
                }
            }
        }
        return diff == 2;
    }

    class UnionFind {
        public:
            UnionFind(const int n) : set_(n), size_(n) {
                iota(set_.begin(), set_.end(), 0);
            }

            int find_set(const int x) {
               if (set_[x] != x) {
                   set_[x] = find_set(set_[x]);  // Path compression.
               }
               return set_[x];
            }

            bool union_set(const int x, const int y) {
                int x_root = find_set(x), y_root = find_set(y);
                if (x_root == y_root) {
                    return false;
                }
                set_[min(x_root, y_root)] = max(x_root, y_root);
                --size_;
                return true;
            }

            int size() const {
                return size_;
            }

        private:
            vector<int> set_;
            int size_;
    };
};

