// Space: O(n) ~ O(n * l^3)
class Solution_MLE {
public:
    int numSimilarGroups(vector<string>& A) {
        const int N = A.size(), L = A[0].length();
        UnionFind union_find(A.size());
        if (N < L*L) {
            for (int i = 0; i < N; ++i) {
                for (int j = 0; j < i; ++j) {
                    if (isSimilar(A[i], A[j])) {
                        union_find.union_set(i, j);
                    }
                }
            }
        } else {
            unordered_map<string, vector<int>> buckets;
            unordered_set<string> lookup;
            for (int i = 0; i < A.size(); ++i) {
                auto word = A[i];
                if (!lookup.count(word)) {
                    buckets[word].emplace_back(i);
                    lookup.emplace(word);
                }
                for (int j1 = 0; j1 < L; ++j1) {
                    for (int j2 = 0; j2 < j1; ++j2) {
                        swap(word[j1], word[j2]);
                        buckets[word].emplace_back(i);
                        swap(word[j1], word[j2]);
                    }
                }
            }
            for (const auto& word : A) {
                for (int i = 0; i < buckets[word].size(); ++i) {
                    for (int j = 0; j < i; ++j) {
                        union_find.union_set(buckets[word][i], buckets[word][j]);
                    }
                }
            }
        }
        return union_find.size();
    }

private:
    bool isSimilar(const string& a, const string& b) {
        int diff = 0;
        for (int i = 0; i < a.length(); ++i) {
            if (a[i] != b[i]) {
                if (++diff > 2) {
                    return false;
                }
            }
        }
        return diff == 2;
    }

    class UnionFind {
        public:
            UnionFind(const int n) : set_(n), size_(n) {
                iota(set_.begin(), set_.end(), 0);
            }

            int find_set(const int x) {
               if (set_[x] != x) {
                   set_[x] = find_set(set_[x]);  // Path compression.
               }
               return set_[x];
            }

            bool union_set(const int x, const int y) {
                int x_root = find_set(x), y_root = find_set(y);
                if (x_root == y_root) {
                    return false;
                }
                set_[min(x_root, y_root)] = max(x_root, y_root);
                --size_;
                return true;
            }

            int size() const {
                return size_;
            }

        private:
            vector<int> set_;
            int size_;
    };
};

// Time:  O(m * n)
// Space: O(1)

class Solution {
public:
    int numMagicSquaresInside(vector<vector<int>>& grid) {
        int result = 0;
        for (int i = 0; i + k - 1 < grid.size(); ++i) {
            for (int j = 0; j + k - 1 < grid[j].size(); ++j) {
                if (magic(grid, i, j)) {
                    ++result;
                }
            }
        }
        return result;
    }

private:
    static const int k = 3;

    bool magic(const vector<vector<int>>& grid, int r, int c) {
        const int expect = k * (k * k + 1) / 2; 
        unordered_set<int> nums;
        int min_num = numeric_limits<int>::max();
        int sum_diag = 0, sum_anti = 0;
        for (int i = 0; i < k; ++i) {
            sum_diag += grid[r + i][c + i];
            sum_anti += grid[r + i][c + k - 1 - i];
            int sum_r = 0, sum_c = 0;
            for (int j = 0; j < k; ++j) {
                min_num = min(min_num, grid[r + i][c + j]);
                nums.emplace(grid[r + i][c + j]);
                sum_r += grid[r + i][c + j];
                sum_c += grid[r + j][c + i];
            }
            if (!(sum_r == sum_c &&
                  sum_c == expect)) {
                return false;
            }
        }
        return sum_diag == sum_anti &&
               sum_anti == expect &&
               nums.size() == k * k &&
               min_num == 1;
    }
};

// Time:  O(n!)
// Space: O(n)

class Solution {
public:
    bool canVisitAllRooms(vector<vector<int>>& rooms) {
        unordered_set<int> lookup = {0};
        vector<int> stack = {0};
        while (!stack.empty()) {
            auto node = stack.back(); stack.pop_back();
            for (const auto& nei : rooms[node]) {
                if (!lookup.count(nei)) {
                    lookup.emplace(nei);
                    if (lookup.size() == rooms.size()) {
                        return true;
                    }
                    stack.emplace_back(nei);
                }
            }
        }
        return lookup.size() == rooms.size();
    }
};

