        vector<pair<int, double>> cars;
        for (int i = 0; i < position.size(); ++i) {
            cars.emplace_back(position[i],
                              static_cast<double>(target - position[i]) / speed[i]);
        }
        sort(cars.begin(), cars.end());
        int result = 0;
        double curr = 0;
        for (int i = position.size() - 1; i >= 0 ; --i) {
