        while (i_ < A_.size()) {
            if (n > A_[i_] - cnt_) {
                n -= A_[i_] - cnt_;
                cnt_ = 0;
                i_ += 2;
            } else {
                cnt_ += n;
                return A_[i_ + 1];
            }
        }
        return -1;
    }

