        vector<TreeNode *> stk1 = {root1}, stk2 = {root2};
        while (!stk1.empty() && !stk2.empty()) {
            auto node1 = stk1.back(); stk1.pop_back();
            auto node2 = stk2.back(); stk2.pop_back();
            if (!node1 && !node2) {
                continue;
            }
            if (!node1 || !node2 || node1->val != node2->val) {
                return false;
            }
            if ((!node1->left && !node2->right) ||
                (node1->left && node2->right && node1->left->val == node2->right->val)) {
                stk1.emplace_back(node1->right);
                stk1.emplace_back(node1->left);
            } else {
                stk1.emplace_back(node1->left);
                stk1.emplace_back(node1->right);
            }
            stk2.emplace_back(node2->left);
            stk2.emplace_back(node2->right);
        }
        return stk1.empty() && stk2.empty();
    }
};

// Time:  O(n)
// Space: O(h)
// recursive dfs solution
class Solution3 {
public:
    bool flipEquiv(TreeNode* root1, TreeNode* root2) {
        if (!root1 && !root2) {
            return true;
        }
        if (!root1 || !root2 || root1->val != root2->val) {
            return false;
        }

        return (flipEquiv(root1->left, root2->left) &&
                flipEquiv(root1->right, root2->right) ||
                flipEquiv(root1->left, root2->right) &&
                flipEquiv(root1->right, root2->left));
    }
};

// Time:  O(f * n), f is the max number of unique prime factors
// Soace: O(p + n), p is the total number of unique primes

class Solution {
public:
    int largestComponentSize(vector<int>& A) {
        UnionFind union_find(A.size());
        unordered_map<int, int> nodesWithCommonFactor;
        for (int i = 0; i < A.size(); ++i) {
            for (const auto& factor : primeFactors(A[i])) {
                if (!nodesWithCommonFactor.count(factor)) {
                    nodesWithCommonFactor[factor] = i;
                }
                union_find.union_set(nodesWithCommonFactor[factor], i);
            }
         }
        return union_find.max_size();
    }

private:
    vector<int> primeFactors(int i) const {
        vector<int> result;
        int d = 2;
        if (i % d == 0) {
            while (i % d == 0) {
                i /= d;
            }
            result.emplace_back(d);
        }
        d = 3;
        for (d = 3; d * d <= i; d += 2) {
            if (i % d == 0) {
                while (i % d == 0) {
                    i /= d;
                }
                result.emplace_back(d);
            }
        }
        if (i != 1) {
            result.emplace_back(i);
        }
        return result;
    }

    class UnionFind {
        public:
            UnionFind(const int n) : set_(n), size_(n, 1) {
                iota(set_.begin(), set_.end(), 0);
            }

            int find_set(const int x) {
               if (set_[x] != x) {
                   set_[x] = find_set(set_[x]);  // Path compression.
               }
               return set_[x];
            }

            bool union_set(const int x, const int y) {
                int x_root = find_set(x), y_root = find_set(y);
                if (x_root == y_root) {
                    return false;
                }
                set_[min(x_root, y_root)] = max(x_root, y_root);
                size_[max(x_root, y_root)] += size_[min(x_root, y_root)];
                return true;
            }

            int max_size() const {
                return *max_element(size_.cbegin(), size_.cend());
            }

        private:
            vector<int> set_;
            vector<int> size_;
    };
};

// Time:  O(n * l), l is the average length of words
// Space: O(1)

class Solution {
public:
    bool isAlienSorted(vector<string>& words, string order) {
        vector<int> lookup(order.size());
        for (int i = 0; i < order.size(); ++i) {
            lookup[order[i] - 'a'] = i;
        }
        for (int i = 0; i < words.size() - 1; ++i) {
            const auto& word1 = words[i];
            const auto& word2 = words[i + 1];
            int j = 0;
            for (; j < min(word1.length(), word2.length()); ++j) {
                if (word1[j] != word2[j]) {
                    if (lookup[word1[j] - 'a'] > lookup[word2[j] - 'a']) {
                        return false;
                    }
                    break;
                }
            }
            if (j == min(word1.length(), word2.length()) &&
                word1.length() > word2.length()) {
                return false;
            }
        }
        return true;
    }
};

// Time:  O(n + klogk)
// Space: O(k)

class Solution {
public:
    bool canReorderDoubled(vector<int>& A) {
        unordered_map<int, int> count;
        for (const auto& x : A) {
            ++count[x];
        }
        vector<int> keys;
        for (const auto& kvp : count) {
            keys.emplace_back(kvp.first);
        }
        sort(keys.begin(), keys.end(),
             [](int i, int j) {
                 return abs(i) < abs(j);
             });
        for (const auto& x : keys) {
            if (count[x] > count[2 * x]) {
                return false;
            }
            count[2 * x] -= count[x];
        }
        return true;
    }
};

// Time:  O(n * l)
// Space: O(n)

class Solution {
public:
    int minDeletionSize(vector<string>& A) {
        int result = 0;
        unordered_set<int> unsorted;
        for (int i = 0; i < A.size() - 1; ++i) {
            unsorted.emplace(i);
        }
        for (int j = 0; j < A[0].size(); ++j) {
            if (any_of(unsorted.begin(), unsorted.end(),
                       [&](int i) {
                           return A[i][j] > A[i + 1][j];
                       })
               ) {
                ++result;
            } else {
                unordered_set<int> tmp(unsorted);
                for (const auto& i : tmp) {
                    if (A[i][j] < A[i + 1][j]) {
                        unsorted.erase(i);
                    }
                }
            }
        }
        return result;
    }
};

