class Solution {
public:
    int shipWithinDays(vector<int>& weights, int D) {    
        int left = *max_element(weights.cbegin(), weights.cend());
        int right = accumulate(weights.cbegin(), weights.cend(), 0);
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (possible(weights, D, mid)) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }

private:
    int possible(const vector<int>& weights, int D, int mid) const {
        int result = 1, curr = 0;
        for (const auto& w : weights) {
            if (curr + w > mid) {
                ++result;
                curr = 0;
            }
            curr += w;
        }
        return result <= D;
    }
};

// Time:  O(logn)
// Space: O(logn)

class Solution {
public:
    int numDupDigitsAtMostN(int N) {
        const auto& digits = to_string(N + 1);
        int result = 0;

        // Given 321
        //
        // 1. count numbers without repeated digits:
        // - X
        // - XX
        for (int i = 1; i < digits.length(); ++i) {
            result += P(9, 1) * P(9, i - 1);
        }

        // 2. count numbers without repeated digits:
        // - 1XX ~ 3XX
        // - 30X ~ 32X
        // - 320 ~ 321
        unordered_set<int> prefix_set;
        for (int i = 0; i < digits.length(); ++i) {
            for (int d = (i == 0) ? 1 : 0; d < digits[i] - '0'; ++d) {
                if (prefix_set.count(d)) {
                    continue;
                }
                result += P(9 - i, digits.length() - i - 1);
            }
            if (prefix_set.count(digits[i] - '0')) {
                break;
            }
            prefix_set.emplace(digits[i] - '0');
        }
        return N - result;
    }

private:
    int P(int m, int n) const {
        int result = 1;
        while (n--) {
            result *= m--;
        }
        return result;
    }
};

