        int result = 2;
        for (int i = 0; i < A.size(); ++i) {
            for (int j = i + 1; j < A.size(); ++j)  {
                int v = A[j] - A[i];
                dp[v][j] = max(dp[v][j], dp[v][i] + 1);
                result = max(result, dp[v][j] + 1);
