class Solution {
public:
    int validSubarrays(vector<int>& nums) {
        int result = 0;
        vector<int> s;
        for (const auto& num : nums) {
            while (!s.empty() && s.back() > num) {
                s.pop_back();
            }
            s.emplace_back(num);
            result += s.size();
        }
        return result;
    }
};

// Time:  O(logn)
// Space: O(1)

class Solution {
public:
    int fixedPoint(vector<int>& A) {
        int left = 0, right = A.size() - 1;
        while (left <= right) {
            const auto& mid = left + (right - left) / 2;
            if (A[mid] >= mid) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return A[left] == left ? left : -1;
    }
};

// Time:  O(n + m + z), n is the total size of patterns
//                    , m is the total size of query string
//                    , z is the number of all matched strings
// Space: O(t), t is the total size of ac automata trie

struct AhoNode {
    vector<AhoNode *> children;
    vector<int> indices;
    AhoNode *suffix;
    AhoNode *output;
    AhoNode() :
        children(26, nullptr),
        suffix(nullptr),
        output(nullptr) {}
};

class AhoTrie {
public:
    AhoTrie(const vector<string>& patterns) : root_(createACTrie(patterns)) {
        node_ = createACSuffixAndOutputLinks(root_);
    }

    vector<int> step(char letter) {
        while (node_ && !node_->children[letter - 'a']) {
            node_ = node_->suffix;
        }
        node_ = node_ ? node_->children[letter - 'a'] : root_;
        return getACNodeOutputs(node_);
    }

private:
    AhoNode *createACTrie(const vector<string>& patterns) {  // Time:  O(n), Space: O(t)
        auto root = new AhoNode();
        for (int i = 0; i < patterns.size(); ++i) {
            auto node = root;
            for (const auto& c : patterns[i]) {
                if (!node->children[c - 'a']) {
                    node->children[c - 'a'] = new AhoNode();
                }
                node = node->children[c - 'a'];
            }
            node->indices.emplace_back(i);
        }
        return root;
    }

    AhoNode *createACSuffixAndOutputLinks(AhoNode *root) {  // Time:  O(n), Space: O(t)
        queue<AhoNode *> q;
        for (auto node : root->children) {
            if (!node) {
                continue;
            }
            q.emplace(node);
            node->suffix = root;
        }

        while (!q.empty()) {
            auto node = q.front(); q.pop();
            for (int c = 0; c < node->children.size(); ++c) {
                if (!node->children[c]) {
                    continue;
                }
                auto child = node->children[c];
                q.emplace(child);
                auto suffix = node->suffix;
                while (suffix && !suffix->children[c]) {
                    suffix = suffix->suffix;
                }
                child->suffix = suffix ? suffix->children[c] : root;
                child->output = !child->suffix->indices.empty() ?
                    child->suffix : child->suffix->output;
            }
        }

        return root;
    }

    vector<int> getACNodeOutputs(AhoNode *node) {  // Time:  O(z)
        vector<int> result;
        for (const auto& i : node_->indices) {
            result.emplace_back(i);
            // return result;
        }
        auto output = node_->output;
        while (output) {
            for (const auto& i : output->indices) {
                result.emplace_back(i);
                // return result;
            }
            output = output->output;
        }
        return result;
    }

    AhoNode * const root_;
    AhoNode *node_;
};

class Solution {
public:
    vector<vector<int>> indexPairs(string text, vector<string>& words) {
        for (auto& word : words) {
            reverse(word.begin(), word.end());
        }
        AhoTrie trie(words);
        vector<vector<int>> result;
        for (int i = text.length() - 1; i >= 0; --i) {
            for (const auto& j : trie.step(text[i])) {
                result.push_back({i, i + words[j].length() - 1});
            }
        }
        reverse(result.begin(), result.end());
        return result;
    }
};

// Time:  O(w * b * 2^b)
// Space: O(w * b * 2^b)

// if w = b, we can even apply Hungarian algorithm (see https://en.wikipedia.org/wiki/Hungarian_algorithm),
// it can be improved to O(w^3), see https://github.com/t3nsor/codebook/blob/master/bipartite-mincost.cpp
class Solution {
public:
    int assignBikes(vector<vector<int>>& workers, vector<vector<int>>& bikes) {
        vector<vector<double>> dp(2,
                                  vector<double>(1 << bikes.size(),
                                                 numeric_limits<double>::infinity()));
        dp[0][0] = 0;
        for (int i = 0; i < workers.size(); ++i) {
            dp[(i + 1) % 2] = vector<double>(1 << bikes.size(),
                                             numeric_limits<double>::infinity());
            for (int j = 0; j < bikes.size(); ++j) {
                for (int taken = 0; taken < (1 << bikes.size()); ++taken) {
                    if (taken & (1 << j)) {
                        continue;
                    }
                    dp[(i + 1) % 2][taken | (1 << j)] =
                        min(dp[(i + 1) % 2][taken | (1 << j)],
                            dp[i % 2][taken] + manhattan(workers[i], bikes[j]));
                }
            }
        }
        return *min_element(dp[workers.size() % 2].cbegin(), dp[workers.size() % 2].cend());
    }

private:
    int manhattan(const vector<int>& p1, const vector<int>& p2) {
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1]);
    }
};

// Time:  O((w * b * 2^b) * log(w * b * 2^b))
// Space: O(w * b * 2^b)
class Solution2 {
public:
    template <typename T>
    struct PairHash {
        size_t operator()(const pair<T, T>& p) const {
            size_t seed = 0;
            seed ^= std::hash<T>{}(p.first)  + 0x9e3779b9 + (seed<<6) + (seed>>2);
            seed ^= std::hash<T>{}(p.second) + 0x9e3779b9 + (seed<<6) + (seed>>2);
            return seed;
        }
    };

    int assignBikes(vector<vector<int>>& workers, vector<vector<int>>& bikes) {
        using P = vector<int>;
        priority_queue<P, vector<P>, greater<P>> min_heap;
        min_heap.push({0, 0, 0});
        unordered_set<pair<int, int>, PairHash<int>> lookup;
        while (!min_heap.empty()) {
            const auto cost = min_heap.top()[0];
            const auto i = min_heap.top()[1];
            const auto taken = min_heap.top()[2];
            min_heap.pop();
            if (lookup.count(make_pair(i, taken))) {
                continue;
            }
            lookup.emplace(i, taken);
            if (i == workers.size()) {
                return cost;
            }
            for (int j = 0; j < bikes.size(); ++j) {
                if (taken & (1 << j)) {
                    continue;
                }
                min_heap.push({cost + +manhattan(workers[i], bikes[j]),  // O(b)
                               i + 1,  // O(w)
                               taken | (1 << j)});  // O(2^b)
            }
        }
        return -1;
    }

private:
    int manhattan(const vector<int>& p1, const vector<int>& p2) {
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1]);
    }
};

// Time:  O(logn)
// Space: O(1)

class Solution {
public:
    int digitsCount(int d, int low, int high) {
        return digitsCount(high, d) - digitsCount(low - 1, d);
    }

private:
    int digitsCount(int n, int k) {
        int result = 0;
        int64_t pivot = 1;
        while (n >= pivot) {
            result += n / (10 * pivot) * pivot +
                      min(pivot, max(n % (10 * pivot) - k * pivot + 1, 0l));
            if (k == 0) {
                 result -= pivot;
            }
            pivot *= 10;
        }
        return result;
    }
};

// Time:  O(m + n)
// Space: O(1)

class Solution {
public:
    string gcdOfStrings(string str1, string str2) {
        if (str1.empty() || str2.empty()) {
            return "";
        }
        int c = gcd(str1.length(), str2.length());
        const auto& result = str1.substr(0, c);
        return check(str1, result) && check(str2, result) ? result : "";
    }

private:
    bool check(const string& s, const string& common) {
        int i = 0;
        for (const auto& c : s) {
            if (c != common[i]) {
                return false;
            }
            i = (i + 1) % common.length();
        }
        return true;
    }

    int gcd(int a, int b) {
        while (b != 0) {
            int tmp = b;
            b = a % b;
            a = tmp;
        }
        return a;
    }
};

// Time:  O(m * n)
// Space: O(m * n)

class Solution {
public:
    int maxEqualRowsAfterFlips(vector<vector<int>>& matrix) {
        unordered_map<string,int> count;
        for (const auto& row : matrix){
            ++count[encode(row)]; 
        }

        using pair_type = decltype(count)::value_type;
        return max_element(count.cbegin(), count.cend(),
                           [] (const pair_type& a,
                               const pair_type& b) {
                               return a.second < b.second;
                           })->second;
    }

private:
    string encode(const vector<int>& s) {
        string result;
        for (const auto& c : s) {
            result.push_back(c ^ s[0]);
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(n)

class Solution {
public:
    vector<int> addNegabinary(vector<int>& arr1, vector<int>& arr2) {
        vector<int> result;
        int carry = 0, i = arr1.size() - 1, j = arr2.size() - 1;
        while (i >= 0 || j >= 0 || carry) {
            if (i >= 0) {
                carry += arr1[i--];
            }
            if (j >= 0) {
                carry += arr2[j--];
            }
            result.emplace_back(carry & 1);
            carry = -(carry >> 1);
        }
        while (result.size() > 1 && result.back() == 0) {
            result.pop_back();
        }
        reverse(result.begin(), result.end());
        return result;
    }
};

// Time:  O(m^2*n), m is min(r, c), n is max(r, c)
// Space: O(n), which doesn't include transposed space

class Solution {
public:
    int numSubmatrixSumTarget(vector<vector<int>>& matrix, int target) {
        if (matrix.size() > matrix[0].size()) {
            const auto& transposed = transpose(matrix);
            return numSubmatrixSumTarget(const_cast<vector<vector<int>>&>(transposed),
                                         target);
        }

        for (int i = 0; i < matrix.size(); ++i) {
            for (int j = 0; j < matrix[i].size() - 1; ++j) {
                matrix[i][j + 1] += matrix[i][j];
            }
        }

        int result = 0;
        for (int i = 0; i < matrix.size(); ++i) {
            vector<int> prefix_sum(matrix[i].size());
            for (int j = i; j < matrix.size(); ++j) {
                unordered_map<int, int> lookup;
                ++lookup[0];
                for (int k = 0; k < matrix[i].size(); ++k) {
                    prefix_sum[k] += matrix[j][k];
                    if (lookup.count(prefix_sum[k] - target)) {
                        result += lookup[prefix_sum[k] - target];
                    }
                    ++lookup[prefix_sum[k]];
                }
            }
        }
        return result;
    }

private:
    vector<vector<int>> transpose(const vector<vector<int>>& matrix) {
        vector<vector<int>> result(matrix[0].size(),
                                   vector<int>(matrix.size()));
        for (int i = 0; i < matrix.size(); ++i) {
            for (int j = 0; j < matrix[i].size(); ++j) {
                result[j][i] = matrix[i][j];
            }
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    vector<string> findOcurrences(string text, string first, string second) {
        vector<string> result;
        first.push_back(' ');
        second.push_back(' ');
        string third;
        int i = 0, j = 0, k = 0;
        while (k < text.length()) {
            auto c = text[k++];
            if (i != first.length()) {
                if (c == first[i]) {
                    ++i;
                } else {
                    i = 0;
                }
                continue;
            }
            if (j != second.length()) {
                if (c == second[j]) {
                    ++j;
                } else {
                    k -= j + 1;
                    i = 0, j = 0;
                }
                continue;
            }
            if (c != ' ') {
                third.push_back(c);
                continue;
            }
            k -= second.length() + third.length() + 1;
            i = 0, j = 0;
            result.emplace_back(move(third));
        }
        if (!third.empty()) {
            result.emplace_back(move(third));
        }
        return result;
    }
};

// Time:  O(n^2)
// Space: O(n)

class Solution {
public:
    int numTilePossibilities(string tiles) {
        vector<double> fact(tiles.size() + 1);
        fact[0] = 1.0;
        for (int i = 1; i < fact.size(); ++i) {
            fact[i] = fact[i - 1] * i;
        }
        vector<int> count(26);
        for (const auto& c : tiles) {
            ++count[c - 'A'];
        }

        // 1. we can represent each alphabet 1..26 as generating functions:
        //    G1(x) = 1 + x^1/1! + x^2/2! + x^3/3! + ... + x^count1/count1!
        //    G2(x) = 1 + x^1/1! + x^2/2! + x^3/3! + ... + x^count2/count2!
        //    ...
        //    G26(x) = 1 + x^1/1! + x^2/2! + x^3/3! + ... + x^count26/count26!
        //
        // 2. let G1(x)*G2(x)*...*G26(x) = c0 + c1*x1 + ... + ck*x^k, k is the max number s.t. ck != 0
        //    => ci (1 <= i <= k) is the number we need to divide when permuting i letters
        //    => the answer will be : c1*1! + c2*2! + ... + ck*k!

        vector<double> coeff(tiles.size() + 1);
        coeff[0] = 1.0;
        for (int i = 0; i < 26; ++i) {
            vector<double> new_coeff(coeff.size());
            for (int j = 0; j < coeff.size(); ++j) {
                for (int k = 0; k <= count[i]; ++k) {
                    if (k + j >= new_coeff.size()) {
                        break;
                    }
                    new_coeff[j + k] += coeff[j] * 1.0 / fact[k]; 
                }
            }
            coeff = move(new_coeff);
        }

        int result = 0;
        for (int i = 1; i < coeff.size(); ++i) {
            result += int(round(coeff[i] * fact[i]));
        }
        return result;
    }
};

// Time:  O(r), r is the value of result
// Space: O(n)
class Solution2 {
public:
    int numTilePossibilities(string tiles) {
        unordered_map<char,int> count;
        for (const auto& c : tiles) {
            ++count[c];
        }
        return backtracking(&count);
    }

private:
    int backtracking(unordered_map<char,int> *count) {
        int total = 0;
        for (auto& c : *count) {
            if (c.second) {
                --c.second;
                total += 1 + backtracking(count);
                ++c.second;
            }
        }
        return total;
    }
};

// Time:  O(n)
// Space: O(h)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    TreeNode* sufficientSubset(TreeNode* root, int limit) {
        if (!root) {
            return nullptr;
        }
        if (!root->left && !root->right) {
            return root->val < limit ? nullptr : root;
        }
        root->left = sufficientSubset(root->left, limit - root->val);
        root->right = sufficientSubset(root->right, limit - root->val);
        if (!root->left && !root->right) {
            return nullptr;
        }
        return root;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    string smallestSubsequence(string text) {
        const int k = 26;
        vector<int> count(k);
        for (const auto& c : text) {
            ++count[c - 'a'];
        }

        vector<bool> lookup(k);
        string stk;
        for (const auto& c : text) {
            if (!lookup[c - 'a']) {
                while (!stk.empty() && stk.back() > c &&
                       count[stk.back() - 'a']) {
                    lookup[stk.back() - 'a'] = false;
                    stk.pop_back();
                }
                stk.push_back(c);
                lookup[c - 'a'] = true;
            }
            --count[c - 'a'];
        }
        return stk; 
    }
};

// Time:  O(n * l), l is the max length of numbers
// Space: O(l)

class Solution {
public:
    int sumOfDigits(vector<int>& A) {
        int min_num = *min_element(A.begin(),A.end());
        int total = 0;
        while (min_num) {
            total += min_num % 10;
            min_num /= 10;
        }
        return total % 2 == 0;
    }
};

// Time:  O(nlogn)
// Space: O(n)

class Solution {
public:
    vector<vector<int>> highFive(vector<vector<int>>& items) {
        map<int, priority_queue<int, vector<int>, greater<int>>> min_heaps;
        for (const auto& item: items) {
            min_heaps[item[0]].emplace(item[1]);
            if (min_heaps[item[0]].size() > 5) {
                min_heaps[item[0]].pop();
            }
        }

        vector<vector<int>> result;
        for (auto& [i, min_heap] : min_heaps) {
            int total = 0, count = min_heap.size();
            while (!min_heap.empty()) {
                total += min_heap.top(); min_heap.pop();
            }
            result.push_back({i, total / count});
        }
        return result;
    }
};

// Time:  O(nlogn)
// Space: O(n)
class Solution2 {
public:
    vector<vector<int>> highFive(vector<vector<int>>& items) {
        vector<vector<int>> result;
        map<int, vector<int>> students;
        for (const auto& item : items) {
            students[item[0]].push_back(item[1]);
        }
        for (auto& [i, scores] : students) {
          partial_sort(scores.begin(), scores.begin() + 5, scores.end(), greater<int>());
          result.push_back({i, accumulate(scores.cbegin(), scores.cbegin() + 5, 0) / 5});
       }
       return result;
    }
};

// Time:  O(p*l * log(p*l)), p is the production of all number of options
//                         , l is the length of a word
// Space: O(p*l)

class Solution {
public:
    vector<string> expand(string S) {  // nested is fine
        int i = 0;
        return generateWords(S, &i);
    }

private:
    vector<string> generateWords(const string& expr, int *i) {
        vector<vector<string>> options;
        while (*i != expr.length() &&
               string(",}").find(expr[*i]) == string::npos) {
            vector<string> tmp;
            if (string("{,}").find(expr[*i]) == string::npos) {
                tmp.emplace_back(string(1, expr[*i]));
                ++(*i);  // a-z
            } else if (expr[*i] == '{') {
                tmp = generateOption(expr, i);
            }
            options.emplace_back(move(tmp));
        }
        return formWords(options);
    }

    vector<string> generateOption(const string& expr, int *i) {
        set<string> option_set;
        while (*i != expr.length() && expr[*i] != '}') {
            ++(*i);  // { or ,
            for (const auto& option : generateWords(expr, i)) {
                option_set.emplace(option);
            }
        }
        ++(*i);  // }
        return vector<string>(option_set.cbegin(), option_set.cend());
    }

    vector<string> formWords(const vector<vector<string>>& options) {
        set<string> words_set;
        int total = 1;
        for (const auto& opt : options) {
            total *= opt.size();
        }
        for (int i = 0; i < total; ++i) {
            vector<string> tmp;
            int curr = i;
            for (int j = options.size() - 1; j >= 0; --j) {
                tmp.emplace_back(options[j][curr % options[j].size()]);
                curr /= options[j].size();
            }
            reverse(tmp.begin(), tmp.end());
            words_set.emplace(accumulate(tmp.cbegin(), tmp.cend(), string()));
        }
        return vector<string>(words_set.cbegin(), words_set.cend());
    }
};

// Time:  O(logn)
// Space: O(logn)

class Solution {
public:
    int confusingNumberII(int n) {
        return totalCount(n) - validCountInLessLength(n) - validCountInFullLength(n);
    }

private:
    int totalCount(int n) {  // count all numbers in the pattern of [01689]{1,len(n)} in the range of [1, n]
        const auto& s = to_string(n);
        int total = 0;
        int p = pow(lookup.size(), s.length() - 1);
        for (int i = 0; i <= s.length(); ++i, p /= lookup.size()) {
            if (i == s.length()) {
                ++total;
                break;
            }
            int smaller = 0;
            for (const auto& kvp : lookup) {
                smaller += int(kvp.first < s[i]);
            }
            total += smaller * p;
            if (!lookup.count(s[i])) {
                break;
            }
        }
        return total - 1;  // exclude 0
    }

    int validCountInLessLength(int n) {  // count unconfusing numbers in the pattern of [01689]{1,len(n)-1} in the range of [1, n]
        const auto& s = to_string(n);
        int valid = 0;
        int total = centers.size();
        for (int i = 1; i < s.length(); i += 2) {  // count unconfusing numbers for each odd length less than s
            if (i == 1) {
                valid += accumulate(cbegin(centers), cend(centers), 0,
                                    [](const auto& total, const auto& kvp) {
                                        return total + (kvp.first != '0');
                                    });
            } else {
                valid += total * (lookup.size() - 1);
                total *= lookup.size();
            }
        }
        total = 1;
        for (int i = 2; i < s.length(); i += 2) {  // count unconfusing numbers for each even length less than s
            valid += total * (lookup.size() - 1);
            total *= lookup.size();
        }
        return valid;
    }

    int validCountInFullLength(int n) {  // count unconfusing numbers in the pattern of [01689]{len(n)} in the range of [1, n]
        const auto& s = to_string(n);
        const auto& half_s = s.substr(0, (s.length() + 1) / 2);
        int total = 0;
        const auto& choices = (s.length() % 2) ? centers : lookup;
        int p = pow(lookup.size(), int(half_s.length()) - 2) * choices.size();
        for (int i = 0; i < half_s.length(); ++i, p /= lookup.size()) {
            if (i == half_s.length() - 1) {
                for (const auto& kvp : choices) {
                    if (kvp.first == '0' && i == 0) {
                        continue;
                    }
                    total += int(kvp.first < half_s[i]);
                }
                if (!choices.count(half_s[i])) {
                    break;
                }
                string tmp(half_s);
                for (int i = half_s.length() - 1 - (s.length() % 2); i >= 0; --i) {
                    tmp.push_back(lookup.at(half_s[i]));
                }
                if (stoull(tmp) <= n && n != 0) {
                    ++total;
                }
                break;
            }
            int smaller = 0;
            for (const auto& kvp : lookup) {
                if (kvp.first == '0' && i == 0) {
                    continue;
                }
                smaller += int(kvp.first < half_s[i]);
            }
            total += smaller * p;
            if (!lookup.count(half_s[i])) {
                break;
            }
        }
        return total;
    }

    const unordered_map<char, char> lookup = {{'0', '0'}, {'1', '1'}, {'6', '9'},
                                              {'8', '8'}, {'9', '6'}};
    const unordered_map<char, char> centers = {{'0', '0'}, {'1', '1'}, {'8', '8'}};
};


