// Space: O(n)

class Solution {
public:
    int earliestAcq(vector<vector<int>>& logs, int N) {
        sort(logs.begin(), logs.end());
        UnionFind union_find(N);
        for (const auto& log : logs) {
            union_find.union_set(log[1], log[2]);
            if (union_find.count() == 1) {
                return log[0];
            }
        }
        return -1;
    }

private:
    class UnionFind {
    public:
        UnionFind(const int n) : set_(n), count_(n) {
            iota(set_.begin(), set_.end(), 0);
        }

        int find_set(const int x) {
           if (set_[x] != x) {
               set_[x] = find_set(set_[x]);  // Path compression.
           }
           return set_[x];
        }

        bool union_set(const int x, const int y) {
            int x_root = find_set(x), y_root = find_set(y);
            if (x_root == y_root) {
                return false;
            }
            set_[min(x_root, y_root)] = max(x_root, y_root);
            --count_;
            return true;
        }

        int count() const {
            return count_;
        }

    private:
        vector<int> set_;
        int count_;
    };
};

// Time:  O(m * n * log(m * n))
// Space: O(m * n)

// binary search + dfs solution
class Solution {
private:
    template <typename T>
    struct PairHash {
        size_t operator()(const pair<T, T>& p) const {
            size_t seed = 0;
            seed ^= std::hash<T>{}(p.first)  + 0x9e3779b9 + (seed<<6) + (seed>>2);
            seed ^= std::hash<T>{}(p.second) + 0x9e3779b9 + (seed<<6) + (seed>>2);
            return seed;
        }
    };

public:
    int maximumMinimumPath(vector<vector<int>>& A) {
        vector<int> vals;
        const auto ceil = min(A[0][0], A.back().back());
        for (int i = 0; i < A.size(); ++i) {
            for (int j = 0; j < A[0].size(); ++j) {
                if (A[i][j] <= ceil) {
                    vals.emplace_back(A[i][j]);
                }
            }
        }
        sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());
        int left = 0, right = vals.size() - 1;
        while (left <= right) {
            const auto& mid = left + (right - left) / 2;
            unordered_set<pair<int, int>, PairHash<int>> lookup;
            if (!check(A, vals[mid], 0, 0, &lookup)) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
       }
        return vals[right];
    }

private:
    bool check(const vector<vector<int>>& A,
               int val, int r, int c,
               unordered_set<pair<int, int>, PairHash<int>> *lookup) {

        static const vector<pair<int, int>> directions = {{0, 1}, {1, 0},
                                                          {0, -1}, {-1, 0}};        
        if (r == A.size() - 1 && c == A[0].size() - 1) {
            return true;
        }
        lookup->emplace(r, c);
        for (const auto& d : directions) {
            const auto nr = r + d.first;
            const auto nc = c + d.second;
            if (0 <= nr && nr < A.size() &&
                0 <= nc && nc < A[0].size() &&
                !lookup->count({nr, nc}) &&
                A[nr][nc] >= val &&
                check(A, val, nr, nc, lookup)) {
                return true;
            }
        }
        return false;
    }
};

// Time:  O(m * n * log(m * n))
// Space: O(m * n)
// Dijkstra algorithm solution
class Solution2 {
private:
    template <typename T>
    struct PairHash {
        size_t operator()(const pair<T, T>& p) const {
            size_t seed = 0;
            seed ^= std::hash<T>{}(p.first)  + 0x9e3779b9 + (seed<<6) + (seed>>2);
            seed ^= std::hash<T>{}(p.second) + 0x9e3779b9 + (seed<<6) + (seed>>2);
            return seed;
        }
    };

public:
    int maximumMinimumPath(vector<vector<int>>& A) {
        static const vector<pair<int, int>> directions = {{0, 1}, {1, 0},
                                                          {0, -1}, {-1, 0}};
        using P = tuple<int, int, int>;
        priority_queue<P> max_heap;
        max_heap.emplace(A[0][0], 0, 0);
        unordered_set<pair<int, int>, PairHash<int>> lookup = {{0, 0}};
        while (!max_heap.empty()) {
            int i, r, c;
            tie(i, r, c) = max_heap.top(); max_heap.pop();
            if (r == A.size() - 1 && c == A[0].size() - 1) {
                return i;
            }
            for (const auto& d : directions) {
                const auto nr = r + d.first;
                const auto nc = c + d.second;
                if (0 <= nr && nr < A.size() &&
                    0 <= nc && nc < A[0].size() &&
                    !lookup.count({nr, nc})) {
                    max_heap.emplace(min(i, A[nr][nc]), nr, nc);
                    lookup.emplace(nr, nc);
                }
            }
        }
        return -1;
    }
};

// Time:  O(n + logc), c is the number of candies
// Space: O(1)

class Solution {
public:
    vector<int> distributeCandies(int candies, int num_people) {
        // find max integer p s.t. sum(1 + 2 + ... + p) <= C
        // => remaining : 0 <= C-(1+p)*p/2 < p+1
        // => -2p-2 < p^2+p-2C <= 0
        // => 2C+1/4 < (p+3/2)^2 and (p+1/2)^2 <= 2C+1/4
        // => sqrt(2C+1/4)-3/2 < p <= sqrt(2C+1/4)-1/2
        // => p = floor(sqrt(2C+1/4)-1/2)
        int p = int(sqrt(2 * candies + 0.25) - 0.5);
        int remaining = candies - (p + 1) * p / 2;
        int rows = p / num_people, cols = p % num_people;

        vector<int> result(num_people);
        for (int i = 0; i < num_people; ++i) {
            result[i] = (i < cols) ? (i + 1) * (rows + 1) + (rows * (rows + 1) / 2) * num_people
                                   : (i + 1) * rows + ((rows - 1) * rows / 2) * num_people;
        }
        result[cols] += remaining;
        return result;
    }
};

// Time:  O(n + logc), c is the number of candies
// Space: O(1)
class Solution2 {
public:
    vector<int> distributeCandies(int candies, int num_people) {
        // find max integer p s.t. sum(1 + 2 + ... + p) <= C
        int left = 1, right = candies;
        while (left <= right) {
            const auto& mid = left + (right - left) / 2;
            if (!(mid <= candies * 2 / (mid + 1))) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        int p = right;
        int remaining = candies - (p + 1) * p / 2;
        int rows = p / num_people, cols = p % num_people;

        vector<int> result(num_people);
        for (int i = 0; i < num_people; ++i) {
            result[i] = (i < cols) ? (i + 1) * (rows + 1) + (rows * (rows + 1) / 2) * num_people
                                   : (i + 1) * rows + ((rows - 1) * rows / 2) * num_people;
        }
        result[cols] += remaining;
        return result;
    }
};

