class Solution {
public:
    vector<int> pathInZigZagTree(int label) {
        int count = 1;
        while (count <= label) {
          count *= 2;
        }
        vector<int> result;
        for (; label >= 1; label /= 2, count /= 2) {
            result.emplace_back(label);
            label = (count / 2) + ((count - 1) - label);
        }
        reverse(result.begin(), result.end());
        return result;
    }
};

// Time:  O(n^2)
// Space: O(n)

class Solution {
public:
    int minHeightShelves(vector<vector<int>>& books, int shelf_width) {
        vector<int> dp(books.size() + 1, numeric_limits<int>::max());
        dp[0] = 0;
        for (int i = 1; i <= books.size(); ++i) {
            int max_width = shelf_width;
            int max_height = 0;
            for (int j = i - 1; j >= 0; --j) {
                if (max_width - books[j][0] < 0) {
                    break;
                }
                max_width -= books[j][0];
                max_height = max(max_height, books[j][1]);
                dp[i] = min(dp[i], dp[j] + max_height);
            }
        }
        return dp[books.size()];
    }
};

// Time:  O(n)
// Space: O(n)

class Solution {
public:
    bool parseBoolExpr(string expression) {
        int i = 0;
        return parse(expression, &i);
    }

private:
    bool parse(const string& expression, int *i) {
        static const string ops = "&|!";
        if (ops.find(expression[*i]) == string::npos) {
            bool result = expression[*i] == 't';
            ++(*i);
            return result;
        }
        const auto& op = expression[*i];
        *i += 2;
        vector<bool> stk;
        while (expression[*i] != ')') {
            if (expression[*i] == ',') {
                ++(*i);
                continue;
            }
            stk.emplace_back(parse(expression, i));
        }
        ++(*i);
        if (op == '&') {
            return all_of(stk.cbegin(), stk.cend(),
                          [](bool val) { return val; });
        }
        if (op == '|') {
            return any_of(stk.cbegin(), stk.cend(),
                          [](bool val) { return val; });
        }
        return !stk[0];
    }
};

