class Solution2 {
public:
    vector<int> maxDepthAfterSplit(string seq) {
        int A = 0, B = 0;
        vector<int> result(seq.length());
        for (int i = 0; i < seq.length(); ++i) {
            int point = seq[i] == '(' ? 1 : -1;
            if ((point == 1 && A <= B) ||
                (point == -1 && A >= B)) {
                A += point;
            } else {
                B += point;
                result[i] = 1;
            }
        }
        return result;
    }
};

