// Space: O(n)

class Solution {
public:
    int minimumCost(int N, vector<vector<int>>& connections) {
        sort(connections.begin(), connections.end(),
             [](const auto& a, const auto& b) {
                return a[2] < b[2]; 
             });
        UnionFind union_find(N);
        int result = 0;
        for (const auto& c : connections) {
            if (union_find.union_set(c[0] - 1, c[1] - 1)) {
                result += c[2];
            }
        }
        return union_find.size() == 1 ? result : -1;
    }

private:
    class UnionFind {
    public:
        UnionFind(const int n) : set_(n), count_(n) {
            iota(set_.begin(), set_.end(), 0);
        }

        int find_set(const int x) {
           if (set_[x] != x) {
               set_[x] = find_set(set_[x]);  // Path compression.
           }
           return set_[x];
        }

        bool union_set(const int x, const int y) {
            int x_root = find_set(x), y_root = find_set(y);
            if (x_root == y_root) {
                return false;
            }
            set_[min(x_root, y_root)] = max(x_root, y_root);
            --count_;
            return true;
        }

        int size() const {
            return count_;
        }

    private:
        vector<int> set_;
        int count_;
    };
};

// Time:  O(|V| + |E|)
// Space: O(|E|)

class Solution {
public:
    int minimumSemesters(int N, vector<vector<int>>& relations) {
        unordered_map<int, vector<int>> g;
        vector<int> in_degree(N);
        for (const auto& r : relations) {
            g[r[0] - 1].emplace_back(r[1] - 1);          
            ++in_degree[r[1] - 1];
        }
        queue<pair<int, int>> q;
        for (int i = 0; i < N; ++i) {
            if (!in_degree[i]) {
                q.emplace(1, i);
            }
        }

        int result = 0;
        int count = N;
        while (!q.empty()) {
            int level, u;
            tie(level, u) = q.front(); q.pop();
            --count;
            result = level;
            for (const auto& v : g[u]) {
                --in_degree[v];
                if (!in_degree[v]) {
                    q.emplace(level+1, v);
                }
            }
        }
        return count == 0 ? result : -1;
    }
};

// Time:  O(logn)
// Space: O(1)

class Solution {
public:
    int tribonacci(int n) {
        vector<vector<int>> T = {{1, 1, 0},
                                 {1, 0, 1},
                                 {1, 0, 0}};
        return matrixMult({{1, 0, 0}}, matrixExpo(T, n))[0][1];  // [a1, a0, a(-1)] * T^n
    }

private:
    vector<vector<int>> matrixExpo(const vector<vector<int>>& A, int pow) {
        vector<vector<int>> result(A.size(), vector<int>(A.size()));
        vector<vector<int>> A_exp(A);
        for (int i = 0; i < A.size(); ++i) {
            result[i][i] = 1;
        }
        while (pow) {
            if (pow % 2 == 1) {
                result = matrixMult(result, A_exp);
            }
            A_exp = matrixMult(A_exp, A_exp);
            pow /= 2;
        }
        return result;
    }

    vector<vector<int>> matrixMult(const vector<vector<int>>& A, const vector<vector<int>>& B) {
        vector<vector<int>> result(A.size(), vector<int>(B[0].size()));
        for (int i = 0; i < A.size(); ++i) {
            for (int j = 0; j < B[0].size(); ++j) {
                int64_t entry = 0;
                for (int k = 0; k < B.size(); ++k) {
                    entry = (static_cast<int64_t>(A[i][k]) * B[k][j] + entry);
                }
                result[i][j] = static_cast<int>(entry);
            }
        }
        return result;
    }
};

