// Time:  O(n)
// Space: O(1)

// Rabin-Karp Algorithm
class Solution {
public:
    int longestDecomposition(string text) {  
        static const uint64_t MOD = 1e9 + 7;
        static const uint64_t D = 26;
        int result = 0;
        int left = 0, right = 0, l = 0;
        uint64_t pow_D = 1;
        for (int i = 0; i < text.length(); ++i) {
            left = (D * left + (text[i] - 'a')) % MOD;
            right = (pow_D * (text[text.length() - 1 - i] - 'a') + right) % MOD;
            ++l;
            pow_D = (pow_D * D) % MOD;
            if (left == right &&
                compare(text, l, i - l + 1, text.length() - 1 - i)) {
                ++result;
                left = 0, right = 0, l = 0, pow_D = 1;
            }
        }
        return result;
    }

private:
    bool compare(const string& text, size_t l, int s1, int s2) {
        for (int i = 0; i < l; ++i) {
            if (text[s1 + i] != text[s2 + i]) {
                return false;
            }
        }
        return true;
    }
};

// Time:  O(logn)
// Space: O(1)

class Solution {
public:
    bool isMajorityElement(vector<int>& nums, int target) {
        if (nums.size() % 2) {
            if (nums[nums.size() / 2] != target) {
                return false;
            }
        } else {
            if (nums[nums.size() / 2 - 1] != nums[nums.size() / 2] ||
                nums[nums.size() / 2] != target) {
                return false;
            }
        }
        const auto& l = lower_bound(nums.cbegin(), nums.cend(), target);
        const auto& r = upper_bound(nums.cbegin(), nums.cend(), target);
        return (r - l) * 2 > nums.size();
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int minSwaps(vector<int>& data) {
        const auto& total_count = accumulate(data.cbegin(), data.cend(), 0);
        int result = 0, count = 0, left = 0;
        for (int i = 0; i < data.size(); ++i) {
            count += data[i];
            if (i - left + 1 > total_count) {
                count -= data[left];
                ++left;
            }
            result = max(result, count);
        }
        return total_count - result;
    }
};

// Time:  O(n^3)
// Space: O(n^3)

class Solution {
public:
    vector<string> mostVisitedPattern(vector<string>& username, vector<int>& timestamp, vector<string>& website) {
        vector<tuple<int, string, string>> A;
        for (int i = 0; i < username.size(); ++i) {
            A.emplace_back(timestamp[i], username[i], website[i]);
        }
        sort(A.begin(), A.end());
        unordered_map<string, vector<string>> users;
        for (const auto& [t, u, w] : A) {
            users[u].emplace_back(w);
        }

        vector<string> result;
        unordered_map<vector<string>, int, VectorHash<string>> count;
        for (const auto& [u, webs] : users) {
            unordered_set<vector<string>, VectorHash<string>> lookup;
            for (int i = 0; i + 2 < webs.size(); ++i) {
                for (int j = i + 1; j + 1 < webs.size(); ++j) {
                    for (int k = j + 1; k < webs.size(); ++k) {
                        vector<string> pattern = {webs[i], webs[j], webs[k]};
                        if (lookup.count(pattern)) {
                            continue;
                        }
                        lookup.emplace(pattern);
                        ++count[pattern];
                        if (result.empty() ||
                            count[pattern] > count[result] ||
                            (count[pattern] == count[result] && pattern < result)) {
                            result = pattern;
                        }
                    }
                }
            }
        }
        return result;
    }

private:
    template<typename T>
    struct VectorHash {
        size_t operator()(const std::vector<T>& v) const {
            size_t seed = 0;
            for (const auto& i : v) {
                seed ^= std::hash<T>{}(i)  + 0x9e3779b9 + (seed<<6) + (seed>>2);
            }
            return seed;
        }
    };
};

