// Time:  O(1)
// Space: O(1)

class Solution {
public:
    Solution() : lookup_(12) {
        for (int M = 1; M < lookup_.size(); ++M) {
            lookup_[M] = lookup_[M - 1] + dayOfMonth(M);
        }
    }

    int dayOfYear(string date) {   
        const auto& result = split(date, '-');
        const auto& Y = stoi(result[0]), &M = stoi(result[1]), &D = stoi(result[2]);
        const auto& leap = (M > 2 && (((Y % 4 == 0) && (Y % 100 != 0)) || (Y % 400 == 0))) ? 1 : 0;
        return lookup_[M - 1] + D + leap;
    }

private:
    int dayOfMonth(int M) {
        return (M == 2) ? 28 : 31 - (M - 1) % 7 % 2;
    }

    vector<string> split(const string& s, const char delim) {
        vector<string> result;
        auto end = string::npos;
        do {
            const auto& start = end + 1;
            end = s.find(delim, start);
            result.emplace_back(s.substr(start, end - start));
        } while (end != string::npos); 
        return result;
    }

    vector<int> lookup_;
};

// Time:  O(d * f * t)
// Space: O(t)

class Solution {
public:
    int numRollsToTarget(int d, int f, int target) {
        static const int MOD = 1e9 + 7;
        vector<vector<int>> dp(2, vector<int>(target + 1));
        dp[0][0] = 1;
        for (int i = 1; i <= d; ++i) {
            dp[i % 2] = vector<int>(target + 1);
            for (int k = 1; k <= f; ++k) {
                for (int j = k; j <= target; ++j) {
                    dp[i % 2][j] = (dp[i % 2][j] + dp[(i - 1) % 2][j - k]) % MOD;
                }
            }
        }
        return dp[d % 2][target] % MOD;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int maxRepOpt1(string text) {
        static const int K = 1;
        int result = 0, max_count = 0;
        unordered_map<char, int> total_count, count;
        int left = 0;
        for (int i = 0; i < text.length(); ++i) {
            ++total_count[text[i]];
            ++count[text[i]];
            max_count = max(max_count, count[text[i]]);
            if (i - left + 1 - max_count > K) {
                --count[text[left++]];
            }
            result = max(result, min(i - left + 1, total_count[text[i]]));
        }
        return result;
    }
};

// Time:  ctor:  O(n)
//        query: O(klogn), k = log2(Q/ERROR_RATE)
// Space: O(n)

class MajorityChecker {
public:
    MajorityChecker(vector<int>& arr)
      : arr_(arr)
      , gen_((random_device())())
    {
        for (int i = 0; i < arr_.size(); ++i) {
            inv_idx_[arr_[i]].emplace_back(i);
        }
    }

    int query(int left, int right, int threshold) {
        for (int i = 0; i < K; ++i) {
            const auto& m = arr_[uniform_int_distribution<int>{left, right}(gen_)];
            if (count(inv_idx_, m, left, right) >= threshold) {
                return m;
            }
        }
        return -1;
    }

private:
    int count(const unordered_map<int, vector<int>>& inv_idx, int m, int left, int right) {
        const auto& l = lower_bound(inv_idx_[m].cbegin(), inv_idx_[m].cend(), left);
        const auto& r = upper_bound(inv_idx_[m].cbegin(), inv_idx_[m].cend(), right);
        return r - l;
    }

    static constexpr int Q = 10000;
    static constexpr double ERROR_RATE = 0.001;
    static constexpr int K = log(Q / ERROR_RATE) / log(2) + 1;
    const vector<int>& arr_;
    unordered_map<int, vector<int>> inv_idx_;
    default_random_engine gen_;
};

// Time:  ctor:  O(n)
//        query: O(sqrt(n) * logn)
// Space: O(n)
class MajorityChecker2 {
public:
    MajorityChecker2(vector<int>& arr)
      : arr_(arr)
      , bound_(round(sqrt(arr_.size())))
    {
        for (int i = 0; i < arr_.size(); ++i) {
            inv_idx_[arr_[i]].emplace_back(i);
        }
        for (const auto& [i, group] : inv_idx_) {
            if (group.size() >= bound_) {
                majorities_.emplace_back(i);
            }
        }
    }

    int query(int left, int right, int threshold) {
        if (right - left + 1 < bound_) {
            const auto& m = boyer_moore_majority_vote(arr_, left, right);
            if (count(inv_idx_, m, left, right) >= threshold) {
                return m;
            }
        } else {
            for (const auto& m : majorities_) {
                if (count(inv_idx_, m, left, right) >= threshold) {
                    return m;
                }
            }
        }
        return -1;
    }

private:
    int count(const unordered_map<int, vector<int>>& inv_idx, int m, int left, int right) {
        const auto& l = lower_bound(inv_idx_[m].cbegin(), inv_idx_[m].cend(), left);
        const auto& r = upper_bound(inv_idx_[m].cbegin(), inv_idx_[m].cend(), right);
        return r - l;
    }

    int boyer_moore_majority_vote(const vector<int>& nums, int left, int right) {
        int m = nums[left], cnt = 1;
        for (int i = left; i <= right; ++i) {
            if (m == nums[i]) {
                ++cnt;
            } else {
                --cnt;
                if (cnt == 0) {
                    m = nums[i];
                    cnt = 1;
                }
            }
        }
        return m;
    }

    const vector<int>& arr_;
    const int bound_;
    unordered_map<int, vector<int>> inv_idx_;
    vector<int> majorities_;
};

// Time:  ctor:  O(nlogn)
//        query: O((logn)^2)
// Space: O(n)
class MajorityChecker3 {
private:
    struct SegmentTreeRecu {
    public:
        SegmentTreeRecu(const vector<int>& nums,
                    const function<int(int, int, int)>& count)
          : original_length_(nums.size())
          , count_(count)
        {
            int size = 1;
            while (size <= original_length_) {
                size *= 2;
            }
            if (original_length_ & (original_length_ - 1)) {
                size *= 2;
            }
            tree_ = vector<int>(size - 1, -1);
            constructTree(nums, 0, original_length_ - 1, 0);
        }

        pair<int, int> query(int i, int j) const {
            return queryRange(i, j, 0, original_length_- 1, 0);
        }

    private:
        void constructTree(const vector<int>& nums, int left, int right, int idx) {
            if (left > right) {
                 return;
            }
            if (left == right) {
                tree_[idx] = nums[left];
                return;
            }
            const auto& mid = left + (right - left) / 2;
            constructTree(nums, left, mid, idx * 2 + 1);
            constructTree(nums, mid+1, right, idx * 2 + 2);
            if (tree_[idx * 2 + 1] != -1 &&
                count_(tree_[idx * 2 + 1], left, right) * 2 > right - left + 1) {
                tree_[idx] = tree_[idx * 2 + 1];
            } else if (tree_[idx * 2 + 2] != -1 &&
                       count_(tree_[idx * 2 + 2], left, right) * 2 > right - left + 1) {
                tree_[idx] = tree_[idx * 2 + 2];
            }
        }

        pair<int, int> queryRange(int range_left, int range_right,
                                  int left, int right, int idx) const {
            if (left > right) {
                return {-1, -1};
            }
            if (right < range_left || left > range_right) {
                return {-1, -1};
            }
            if (range_left <= left && right <= range_right) {
                if (tree_[idx] != -1) {
                    const auto& c = count_(tree_[idx], range_left, range_right);
                    if (c * 2 > range_right - range_left + 1) {
                        return {tree_[idx], c};
                    }
                }
            } else {
                const auto& mid = left + (right - left) / 2;
                auto result = queryRange(range_left, range_right, left, mid, idx * 2 + 1);
                if (result.first != -1) {
                    return result;
                }
                result = queryRange(range_left, range_right, mid + 1, right, idx * 2 + 2);
                if (result.first != -1) {
                    return result;
                }
            }
            return {-1, -1};
        }

    private:
        const int original_length_;
        const function<int(int, int, int)> count_;
        vector<int> tree_;
    };

    int count(const unordered_map<int, vector<int>>& inv_idx, int m, int left, int right) {
        const auto& l = lower_bound(inv_idx_[m].cbegin(), inv_idx_[m].cend(), left);
        const auto& r = upper_bound(inv_idx_[m].cbegin(), inv_idx_[m].cend(), right);
        return r - l;
    }

public:
    MajorityChecker3(vector<int>& arr)
      : arr_(arr)
    {
        for (int i = 0; i < arr_.size(); ++i) {
            inv_idx_[arr_[i]].push_back(i);
        }
        segment_tree_ = make_unique<SegmentTreeRecu>(arr,
                            bind(&MajorityChecker3::count, this, cref(inv_idx_),
                                 placeholders::_1,
                                 placeholders::_2,
                                 placeholders::_3));
    }

    int query(int left, int right, int threshold) {
        const auto& result = segment_tree_->query(left, right);
        if (result.second >= threshold) {
            return result.first;
        }
        return -1;
    }

private:
    const vector<int>& arr_;
    unordered_map<int, vector<int>> inv_idx_;
    unique_ptr<SegmentTreeRecu> segment_tree_;
};

// Time:  ctor:  O(n)
//        query: O(sqrt(n) * logn)
// Space: O(n)
class MajorityChecker4 {
public:
    MajorityChecker4(vector<int>& arr)
      : arr_(arr)
      , bucket_size_(round(sqrt(arr_.size())))
    {
        for (int i = 0; i < arr_.size(); ++i) {
            inv_idx_[arr_[i]].emplace_back(i);
        }
        for (int left = 0; left < arr_.size(); left += bucket_size_) {
            const auto right = min(left + bucket_size_ - 1, int(arr_.size()) - 1);
            bucket_majorities_.emplace_back(boyer_moore_majority_vote(arr_, left, right));
        }
    }

    int query(int left, int right, int threshold) {
        int l = left / bucket_size_;
        int r = right / bucket_size_;
        if (l == r) {
            const auto& m = boyer_moore_majority_vote(arr_, left, right);
            if (count(inv_idx_, m, left, right) >= threshold) {
                return m;
            }
            return -1;
        }
        else {
            int m = boyer_moore_majority_vote(arr_, left, (l + 1) * bucket_size_ - 1);
            if (count(inv_idx_, m, left, right) >= threshold) {
                return m;
            }
            m = boyer_moore_majority_vote(arr_, r * bucket_size_, right);
            if (count(inv_idx_, m, left, right) >= threshold) {
                return m;
            }
            for (int i = l + 1; i < r; ++i) {
                if (count(inv_idx_, bucket_majorities_[i], left, right) >= threshold) {
                    return bucket_majorities_[i];
                }
            }
            return -1;
        }
    }

private:
    int count(const unordered_map<int, vector<int>>& inv_idx, int m, int left, int right) {
        const auto& l = lower_bound(inv_idx_[m].cbegin(), inv_idx_[m].cend(), left);
        const auto& r = upper_bound(inv_idx_[m].cbegin(), inv_idx_[m].cend(), right);
        return r - l;
    }

    int boyer_moore_majority_vote(const vector<int>& nums, int left, int right) {
        int m = nums[left], cnt = 1;
        for (int i = left; i <= right; ++i) {
            if (m == nums[i]) {
                ++cnt;
            } else {
                --cnt;
                if (cnt == 0) {
                    m = nums[i];
                    cnt = 1;
                }
            }
        }
        return m;
    }

    const vector<int>& arr_;
    const int bucket_size_;
    unordered_map<int, vector<int>> inv_idx_;
    vector<int> bucket_majorities_;
};

// Time:  O(m * n), m is the length of chars, n is the number of words
// Space: O(1)

class Solution {
public:
    int countCharacters(vector<string>& words, string chars) {
        const auto& count = counter(chars);
        int result = 0;
        for (const auto& word : words) {
            if (check(word, chars, count)) {
                result += word.length();
            }
        }
        return result;
    }

private:
    unordered_map<char, int> counter(const string& s) {
        unordered_map<char, int> result;
        for (const auto& c : s) {
            ++result[c];
        }
        return result;
    }

    bool check(const string& word, const string& chars,
               const unordered_map<char, int>& count) {
        if (word.length() > chars.length()) {
            return false;
        }
        unordered_map<char, int> curr_count;
        for (const auto& c : word) {
            ++curr_count[c];
            if (!count.count(c) || count.at(c) < curr_count[c]) {
                return false;
            }
        }
        return true;
    }
};

// Time:  O(n)
// Space: O(h)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */

// dfs solution
class Solution {
public:
    int maxLevelSum(TreeNode* root) {
        vector<int> level_sums;
        dfs(root, 0, &level_sums);
        return distance(level_sums.cbegin(),
                        max_element(level_sums.cbegin(), level_sums.cend())) + 1;
    }

private:
    void dfs(TreeNode *node, int i, vector<int> *level_sums) {
        if (!node) {
            return;
        }
        if (i == level_sums->size()) {
            level_sums->emplace_back();
        }
        (*level_sums)[i] += node->val;
        dfs(node->left, i + 1, level_sums);
        dfs(node->right, i + 1, level_sums);
    }
};

// Time:  O(n)
// Space: O(w)
// bfs solution
class Solution2 {
public:
    int maxLevelSum(TreeNode* root) {
        int result = 0, level = 1, max_total = numeric_limits<int>::min();
        queue<TreeNode*> q({root});
        while (!q.empty()) {
            queue<TreeNode*> next_q;
            int total = 0;
            while (!q.empty()) {
                const auto node = q.front(); q.pop();
                total += node->val;
                if (node->left) {
                    next_q.emplace(node->left);
                }
                if (node->right) {
                    next_q.emplace(node->right);
                }
            }
            if (total > max_total) {
                max_total = total;
                result = level;
            }
            q = move(next_q);
            ++level;
        }
        return result;
    }
};

// Time:  O(m * n)
// Space: O(m * n)

class Solution {
public:
    int maxDistance(vector<vector<int>>& grid) {
        static const vector<pair<int, int>> directions{{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        queue<pair<int, int>> q;
        for (int i = 0; i < grid.size(); ++i) {
            for (int j = 0; j < grid[i].size(); ++j) {
                if (grid[i][j]) {
                    q.emplace(i, j);
                }
            }
        }
        if (q.size() == grid.size() * grid[0].size()) {
            return -1;
        }
        int level = -1;
        while (!q.empty()) {
            queue<pair<int, int>> next_q;
            while (!q.empty()) {
                const auto [x, y] = q.front(); q.pop();
                for (const auto& [dx, dy] : directions) {
                    const auto& nx = x + dx;
                    const auto& ny = y + dy;
                    if (!(0 <= nx && nx < grid.size() && 
                          0 <= ny && ny < grid[0].size() && 
                          grid[nx][ny] == 0)) {
                        continue;
                    }
                    next_q.emplace(nx, ny);
                    grid[nx][ny] = 1;
                }
            }
            q = move(next_q);
            ++level;
        }
        return level;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    string lastSubstring(string s) {
        int left = 0, right = 1, l = 0;
        while (right + l < size(s)) {
            if (s[left + l] == s[right + l]) {
                ++l;
                continue;
            }
            if (s[left + l] > s[right + l]) {
                right += l + 1;
            } else {
                left = max(right, left + l + 1);
                right = left + 1;
            }
            l = 0;
        }
        return s.substr(left);
    }
};

// Time:  O(n)
// Space: O(n)
class Solution2 {
public:
    string lastSubstring(string s) {
        unordered_map<char, vector<size_t>> count;
        for (size_t i = 0; i < s.length(); ++i) {
            count[s[i]].emplace_back(i);
        }

        const auto& max_c = max_element(count.cbegin(), count.cend(),
                                        [](const auto& a, const auto& b) {
                                            return a.first < b.first;
                                        })->first;
        unordered_map<int, int> starts;
        for (const auto& i : count[max_c]) {
            starts[i] = i + 1;
        }
        while (starts.size() > 1) {
            unordered_set<int> lookup;
            unordered_map<char, vector<int>> next_count;
            for (const auto& [start, end] : starts) {
                if (end == s.length())  {  // finished
                    lookup.emplace(start);
                    continue;
                }
                next_count[s[end]].emplace_back(start);			
                if (starts.count(end)) {  // overlapped
                    lookup.emplace(end);
                }
            }
            unordered_map<int, int> next_starts;
            const auto& max_c = max_element(next_count.cbegin(), next_count.cend(),
                                            [](const auto& a, const auto& b) {
                                                return a.first < b.first;
                                            })->first;
            for (const auto& start : next_count[max_c]) {
                if (!lookup.count(start)) {
                    next_starts[start] = starts[start] + 1;
                }
            }
            starts = move(next_starts);
        }
        return s.substr(starts.cbegin()->first);
    }
};

