// Time:  O(nlogn)
// Space: O(n)

class Solution {
public:
    int minCostToSupplyWater(int n, vector<int>& wells, vector<vector<int>>& pipes) {
        vector<tuple<int, int, int>> nodes;
        for (int i = 0; i < wells.size(); ++i) {
            nodes.emplace_back(wells[i], 0, i + 1);
        }
        for (int i = 0; i < pipes.size(); ++i) {
            nodes.emplace_back(pipes[i][2], pipes[i][0], pipes[i][1]);
        }
        sort(nodes.begin(), nodes.end());
        int result = 0;
        UnionFind union_find(n + 1);
        for (const auto& [c, x, y] : nodes) {
            if (!union_find.union_set(x, y)) {
                continue;
            }
            result += c;
            if (union_find.count() == 1) {
                break;
            }
        }
        return result;
    }

private:
    class UnionFind {
    public:
        UnionFind(const int n) : set_(n), count_(n) {
            iota(set_.begin(), set_.end(), 0);
        }

        int find_set(const int x) {
           if (set_[x] != x) {
               set_[x] = find_set(set_[x]);  // Path compression.
           }
           return set_[x];
        }

        bool union_set(const int x, const int y) {
            int x_root = find_set(x), y_root = find_set(y);
            if (x_root == y_root) {
                return false;
            }
            set_[min(x_root, y_root)] = max(x_root, y_root);
            --count_;
            return true;
        }

        int count() const {
            return count_;
        }

    private:
        vector<int> set_;
        int count_;
    };
};

// Time:  O(nlogn)
// Space: O(n)

class Solution {
public:
    vector<string> invalidTransactions(vector<string>& transactions) {
        static const int AMOUNT = 1000;
        static const int MINUTES = 60;
        vector<tuple<string, int, int, string>> trans;
        for (const auto& transaction : transactions) {
            const auto& t = split(transaction, ',');
            trans.emplace_back(t[0], stoi(t[1]), stoi(t[2]), t[3]);
        }
        sort(trans.begin(), trans.end(),
             [](const auto& a, const auto& b) {
                 return get<1>(a) < get<1>(b);
             });
        unordered_map<string, vector<int>> trans_indexes;
        for (int i = 0; i < trans.size(); ++i) {
            trans_indexes[get<0>(trans[i])].emplace_back(i);
        }
        vector<string> result;
        for (const auto& [name, indexes] : trans_indexes) {
            int left = 0, right = 0;
            for (int i = 0; i < indexes.size(); ++i) {
                const auto& t = trans[indexes[i]];
                if (get<2>(t) > AMOUNT) {
                    result.emplace_back(to_str(t));
                    continue;
                }
                while (left + 1 < indexes.size() &&
                       get<1>(trans[indexes[left]]) < get<1>(t) - MINUTES) {
                    ++left;
                }
                while (right + 1 < indexes.size() &&
                       get<1>(trans[indexes[right + 1]]) <= get<1>(t) + MINUTES) {
                    ++right;
                }
                for (int i = left; i <= right; ++i) {
                    if (get<3>(trans[indexes[i]]) != get<3>(t)) {
                        result.emplace_back(to_str(t));
                        break;
                    }
                }
            }
        }
        return result;
    }

private:
    vector<string> split(const string& s, const char delim) {
        vector<string> result;
        auto end = string::npos;
        do {
            const auto& start = end + 1;
            end = s.find(delim, start);
            result.emplace_back(s.substr(start, end - start));
        } while (end != string::npos); 
        return result;
    }

    template<typename T>
    string to_str(const T& t) {
        stringstream ss;
        ss << get<0>(t) << "," << get<1>(t) << ","
           << get<2>(t) << "," << get<3>(t);
        return ss.str();
    }
};

// Time:  O((m + n)logn), m is the number of queries, n is the number of words
// Space: O(n)

class Solution {
public:
    vector<int> numSmallerByFrequency(vector<string>& queries, vector<string>& words) {
        vector<int> words_freq;
        for (const auto& word : words) {
            words_freq.emplace_back(f(word));
        }
        sort(words_freq.begin(), words_freq.end());
        vector<int> result;
        for (const auto& query : queries) {
            const auto& it = upper_bound(words_freq.cbegin(), words_freq.cend(), f(query));
            result.emplace_back(distance(it, words_freq.cend()));
        }
        return result;
    }

private:
    int f(const string& word) {
        const auto& smallest = *min_element(word.cbegin(), word.cend());
        return count(word.cbegin(), word.cend(), smallest);
    }
};

// Time:  O(n)
// Space: O(n)

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode(int x) : val(x), next(NULL) {}
 * };
 */
class Solution {
public:
    ListNode* removeZeroSumSublists(ListNode* head) {
        ListNode dummy(0);
        auto curr = &dummy;
        dummy.next = head;
        int prefix = 0;
        OrderedDict<int, ListNode*> lookup;
        while (curr) {
            prefix += curr->val;
            auto node = curr;
            if (lookup.count(prefix)) {
                node = lookup[prefix];
            }
            while (lookup.count(prefix)) {
                lookup.popitem();
            }
            lookup[prefix] = node;
            node->next = curr->next;
            curr = curr->next;
        }
        return dummy.next;
    }

private:
    template<typename K, typename V>
    class OrderedDict {
    public:
        bool count(const K& key) const {
            return map_.count(key);
        }

        V& operator[](const K& key) {
            if (!map_.count(key)) {
                list_.emplace_front();
                list_.begin()->first = key;
                map_[key] = list_.begin();
            }
            return map_[key]->second;
        }

        void popitem() {
            auto del = list_.front(); list_.pop_front();
            map_.erase(del.first);
        }

    private:
        list<pair<K, V>> list_;
        unordered_map<K, typename list<pair<K, V>>::iterator> map_;
    };
};

// Time:  push: O(logn)
//        pop:  O(1), amortized
//        popAtStack: O(logn)
// Space: O(n * c)

class DinnerPlates {
public:
    DinnerPlates(int capacity) : c_(capacity) {
    }

    void push(int val) {
        if (!min_heap_.empty()) {
            const auto l = min_heap_.top(); min_heap_.pop();
            if (l < stks_.size()) {
                stks_[l].emplace_back(val);
                return;
            }
            min_heap_ = {};  // nothing is valid in min heap
        }
        if (stks_.empty() || stks_.back().size() == c_) {
            stks_.emplace_back();
        }
        stks_.back().emplace_back(val);
    }

    int pop() {
        while (!stks_.empty() && stks_.back().empty()) {
            stks_.pop_back();
        }
        if (stks_.empty()) {
            return -1;
        }
        auto result = stks_.back().back(); stks_.back().pop_back();
        return result;
    }

    int popAtStack(int index) {
        if (index >= stks_.size() || stks_[index].empty()) {
            return -1;
        }
        min_heap_.emplace(index);
        auto result = stks_[index].back(); stks_[index].pop_back();
        return result;
    }

private:
    vector<vector<int>> stks_;
    int c_;
    priority_queue<int, vector<int>, greater<int>> min_heap_;
};

// Time:  O(n/2 + n/3 + ... + n/p) = O(nlog(logn)), see https://mathoverflow.net/questions/4596/on-the-series-1-2-1-3-1-5-1-7-1-11
// Space: O(n)

class Solution {
public:    
    int numPrimeArrangements(int n) {
        int cnt = count_primes(n);
        return static_cast<uint64_t>(factorial(cnt)) * factorial(n - cnt) % MOD;
    }

private:
    int count_primes(int n) {
        if (n <= 1) {
            return 0;
        }
        vector<bool> is_primes((n + 1) / 2, true);
        int cnt = is_primes.size();
        for (int i = 3; i * i <= n; i += 2) {
            if (!is_primes[i / 2]) {
                continue;
            }
            for (int j = i * i; j <= n; j += 2 * i) {
                if (!is_primes[j / 2]) {
                    continue;
                }
                --cnt;
                is_primes[j / 2] = false;
            }
        }
        return cnt;
    }

    int factorial(int n) {
        int result = 1ull;
        for (int i = 2; i <= n; ++i) {
            result = (static_cast<uint64_t>(result) * i) % MOD;
        }
        return result;
    }

    static const int MOD = 1e9 + 7;
};

