// Time:  O(l * rlogr)  , l is the max length of phrases
//                      , r is the number of result, could be up to O(n^2)
// Space: O(l * (n + r)), n is the number of phrases

class Solution {
public:
    vector<string> beforeAndAfterPuzzles(vector<string>& phrases) {
        unordered_map<string, vector<size_t>> lookup;
        for (int i = 0; i < phrases.size(); ++i) {
            const auto& phrase = phrases[i];
            const auto& right = phrase.rfind(' ');
            const auto& word = (right == string::npos) ? phrase : phrase.substr(right + 1);
            lookup[word].emplace_back(i);
        }
        unordered_set<string> result_set;
        for (int i = 0; i < phrases.size(); ++i) {
            const auto& phrase = phrases[i];
            const auto& left = phrase.find(' ');
            const auto& word = (left == string::npos) ? phrase : phrase.substr(0, left);
            if (!lookup.count(word)) {
                continue;
            }
            for (const auto& j : lookup[word]) {
                if (j == i) {
                    continue;
                }
                result_set.emplace(phrases[j] + phrase.substr(word.length()));
            }
        }
        vector<string> result(result_set.cbegin(), result_set.cend());
        sort(result.begin(), result.end());
        return result;
    }
};

// Time:  O(n)
// Space: O(n)

class Solution {
public:
    vector<int> shortestDistanceColor(vector<int>& colors, vector<vector<int>>& queries) {   
        vector<vector<int>> dp(3, vector<int>(colors.size(), -1));
        dp[colors[0] - 1][0] = 0;
        for (int i = 1; i < colors.size(); ++i) {
            for (int color = 0; color < 3; ++color) {
                dp[color][i] = dp[color][i - 1];
            }
            dp[colors[i] - 1][i] = i;
        }

        dp[colors[colors.size() - 1] - 1][colors.size() - 1] = colors.size() - 1;
        for (int i = colors.size() - 2; i >= 0; --i) {
            for (int color = 0; color < 3; ++color) {
                if (dp[color][i + 1] != -1) {
                    continue;
                }
                if (dp[color][i] == -1 ||
                    abs(dp[color][i + 1] - i) < abs(dp[color][i] - i)) {
                    dp[color][i] = dp[color][i + 1];
                }
            }
            dp[colors[i] - 1][i] = i;
        }

        vector<int> result;
        for (const auto& query : queries) {
            const auto d = abs(dp[query[1] - 1][query[0]]);
            result.emplace_back(dp[query[1] - 1][query[0]] != -1 ? abs(dp[query[1] - 1][query[0]] - query[0]) : -1);
        }
        return result;
    }
};

// Time:  O(1)
// Space: O(1)

class Solution {
public:
    int maximumNumberOfOnes(int width, int height, int sideLength, int maxOnes) {
        if (width < height) {
            swap(width, height);
        }

        const auto& R = height / sideLength, &r = height % sideLength;
        const auto& C = width / sideLength, &c = width % sideLength;
        assert(R <= C);
        vector<pair<int, int>> area_counts = {{r * c, (R + 1) * (C + 1)},
                                              {r * (sideLength - c), (R + 1) * C},
                                              {(sideLength - r) * c, R * (C + 1)},
                                              {(sideLength - r) * (sideLength - c), R * C}};
        int result = 0;
        for (const auto& [area, count] : area_counts) {
            result += count * min(maxOnes, area);
            maxOnes -= min(maxOnes, area);
            if (!maxOnes) {
                break;
            }
        }
        return result;
    }
};

