// Space: O(1)

class Solution {
public:
    int distanceBetweenBusStops(vector<int>& distance, int start, int destination) {
        if (start > destination) {
            swap(start, destination);
        }
        const auto& s_to_d = accumulate(distance.cbegin() + start,
                                        distance.cbegin() + destination, 0);
        const auto& d_to_s = accumulate(distance.cbegin(),
                                        distance.cbegin() + start, 0) +
                             accumulate(distance.cbegin() + destination,
                                        distance.cend(), 0);
        return min(s_to_d, d_to_s);
    }
};

// Time:  O(1)
// Space: O(1)

class Solution {
public:
    string dayOfTheWeek(int day, int month, int year) {
        static const vector<string> DAYS = {"Sunday", "Monday", "Tuesday", "Wednesday",
                                            "Thursday", "Friday", "Saturday"};

        // Zeller Formula
        if (month < 3) {
            month += 12;
            --year;
        }
        int c = year / 100, y = year % 100;
        const auto& w = ((c / 4 - 2 * c + y + y / 4 + 13 * (month + 1) / 5 + day - 1) % 7 + 7) % 7;
        return DAYS[w];
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int maximumSum(vector<int>& arr) {
        int result = numeric_limits<int>::min();
        int prev = numeric_limits<int>::min();
        int curr = numeric_limits<int>::min();
        for (const auto &x : arr) {
            curr = max(prev, (curr == numeric_limits<int>::min()) ? x : max(curr + x, x));
            result = max(result, curr);
            prev = (prev == numeric_limits<int>::min()) ? x : max(prev + x, x);
        }
        return result;
    }
};

// Time:  O(n^2 * logn)
// Space: O(n)

class Solution {
public:
    int makeArrayIncreasing(vector<int>& arr1, vector<int>& arr2) {
        std::sort(arr2.begin(), arr2.end());
        arr2.erase(unique(arr2.begin(), arr2.end()), arr2.end());
        unordered_map<int, int> dp = {{0, -1}};  // dp[min_cost] = end_with_val
        for (const auto& val1 : arr1) {
            unordered_map<int, int> next_dp;
            for (const auto& [cost, val] : dp) {
                if (val < val1) {
                    if (!next_dp.count(cost)) {
                        next_dp[cost] = val1;
                    } else {
                        next_dp[cost] = min(next_dp[cost], val1);
                    }
                }
                const auto& it = upper_bound(arr2.cbegin(), arr2.cend(), val);
                if (it != arr2.cend()) {
                    if (!next_dp.count(cost + 1)) {
                        next_dp[cost + 1] = *it;
                    } else {
                        next_dp[cost + 1] = min(next_dp[cost + 1], *it);
                    }
                }
            }
            dp = move(next_dp);
            if (dp.empty()) {
                return -1;
            }
        }
        return min_element(dp.cbegin(), dp.cend())->first;
    }
};

// Time:  O(n)
// Space: O(1)

class BoundedBlockingQueue {
public:    
    BoundedBlockingQueue(int capacity)
      : cap_(capacity) {

    }

    void enqueue(int element) {
        {
            unique_lock<mutex> l(m_);
            cv_.wait(l, [this]() { return q_.size() != cap_; }) ;
            q_.emplace(element);
        }
        cv_.notify_all();
    }

    int dequeue() {
        int element;
        {
            unique_lock<mutex> l(m_);
            cv_.wait(l, [this]() { return !q_.empty(); }) ;
            element = q_.front(); q_.pop();
        }
        cv_.notify_all();
        return element;
    }

    int size() {
        unique_lock<mutex> l(m_);
        return q_.size();
    }

private:
    mutex m_;
    condition_variable cv_;
    queue<int> q_;
    int cap_;
};

