// Space: O(n)
class Solution2 {
public:
    string smallestStringWithSwaps(string s, vector<vector<int>>& pairs) { 
        unordered_map<int, vector<int>> adj;
        for (const auto& pair : pairs) {
            adj[pair[0]].emplace_back(pair[1]);
            adj[pair[1]].emplace_back(pair[0]);
        }
        unordered_set<int> lookup;
        string result = s;
        for (int i = 0; i < s.length(); ++i) {
            if (lookup.count(i)) {
                continue;
            }
            vector<int> component;
            dfs(i, adj, &lookup, &component);
            sort(component.begin(), component.end());
            vector<char> chars;
            for (const auto& k : component) {
                chars.emplace_back(result[k]);
            }
            sort(chars.begin(), chars.end());
            for (int j = 0; j < component.size(); ++j) {
                result[component[j]] = chars[j];
            }
        }
        return result;
    }

private:
    void dfs(int i, const unordered_map<int, vector<int>>& adj,
             unordered_set<int> *lookup, vector<int> *component) {
        lookup->emplace(i);
        component->emplace_back(i);
        if (!adj.count(i)) {
            return;
        }
        for (const auto& j : adj.at(i)) {
            if (lookup->count(j)) {
                continue;
            }
            dfs(j, adj, lookup, component);
        }
    }
};

// Time:  O(n + e)
// Space: O(n + e)

class Solution {    
public:
    vector<int> sortItems(int n, int m, vector<int>& group_id, vector<vector<int>>& beforeItems) {
        for (int i = 0; i < n; ++i) {
            if (group_id[i] == -1) {
                group_id[i] = m++;
            }
        }
        Topo global_group;
        for (int i = 0; i < m; ++i) {
            global_group.addNode(i);
        }
        unordered_map<int, Topo> local_groups;
        for (int i = 0; i < n; ++i) {
            local_groups[group_id[i]].addNode(i);
        }
        for (int i = 0; i < n; ++i) {
            for (const auto& j : beforeItems[i]) {
                if (group_id[i] == group_id[j]) {
                    local_groups[group_id[i]].addEdge(j, i);
                } else {
                    global_group.addEdge(group_id[j], group_id[i]);
                }
            }
        }
        vector<int> result;
        const auto& global_order = global_group.sort();
        if (!global_order) {
            return {};
        }        
        for (const auto& i : *global_order) {
            const auto& local_order = local_groups[i].sort();
            if (!local_order) {
                return {};
            }
            for (const auto& x : *local_order) {
                result.emplace_back(x);
            }
        }
        return result;
    }

private:
    class Topo {
    public:
        void addNode(int node) {
            nodes_.emplace(node);
        }

        void addEdge(int from, int to) {
            addNode(from), addNode(to);
            in_degree_[to].emplace(from);
            out_degree_[from].emplace(to);
        }

        unique_ptr<vector<int>> sort() {
            queue<int> q;
            auto result = make_unique<vector<int>>();
            for (const auto& node : nodes_) {
                if (!in_degree_.count(node)) {
                    q.emplace(node);
                }
            }
            while (!q.empty()) {
                auto node = q.front(); q.pop();
                result->emplace_back(node);
                for (const auto& nei : out_degree_[node]) {
                    in_degree_[nei].erase(node);
                    if (in_degree_[nei].empty()) {
                        in_degree_.erase(nei);
                        q.emplace(nei);
                    }
                }
            }            
            if (result->size() < nodes_.size()) {
                return nullptr;
            }
            return result;
        }

    private:
        unordered_set<int> nodes_;
        unordered_map<int, unordered_set<int>> in_degree_;
        unordered_map<int, unordered_set<int>> out_degree_;
    };
};

// Time:  O(logn) on average for each operation
// Space: O(n)

// see proof in references:
// 1. https://kunigami.blog/2012/09/25/skip-lists-in-python/
// 2. https://opendatastructures.org/ods-cpp/4_4_Analysis_Skiplists.html
// 3. https://brilliant.org/wiki/skip-lists/
class Skiplist {
private:
    class SkipNode {
    public:
        SkipNode() : SkipNode(0, -1) {

        }

        SkipNode(int level, int num)
          : num(num)
          , nexts(level) {

        }

        int num;
        vector<SkipNode *> nexts;
    };

public:
    Skiplist()
      : gen_((random_device())())
      , len_(0)
      , head_(new SkipNode()) {

    }

    ~Skiplist() {
        if (head_->nexts.empty()) {
            return;
        }
        auto curr = head_->nexts[0];
        while (curr) {
            auto next = curr->nexts[0];
            delete curr;
            curr = next;
        }
    }

    bool search(int target) const {
        return find(target, find_prev_nodes(target)) != nullptr;
    }

    void add(int num) {
        auto node = new SkipNode(random_level(), num);
        if (head_->nexts.size() < node->nexts.size()) {
            head_->nexts.resize(node->nexts.size());
        }
        auto prevs = find_prev_nodes(num);
        for (int i = 0; i < node->nexts.size(); ++i) {
            node->nexts[i] = prevs[i]->nexts[i];
            prevs[i]->nexts[i] = node;
        }
        ++len_;
    }

    bool erase(int num) {
        auto prevs = find_prev_nodes(num);
        auto curr = find(num, prevs);
        if (!curr) {
            return false;
        }
        --len_;
        for (int i = curr->nexts.size() - 1; i >= 0; --i) {
            prevs[i]->nexts[i] = curr->nexts[i];
            if (!head_->nexts[i]) {
                head_->nexts.pop_back();
            }
        }
        delete curr;
        return true;
    }

    int size() const {
        return len_;
    }

private:
    SkipNode *find(int num, const vector<SkipNode *>& prevs) const {
        if (!prevs.empty()) {
            auto candidate = prevs[0]->nexts[0];
            if (candidate && candidate->num == num) {
                return candidate;
            }
        }
        return nullptr;
    }

    vector<SkipNode *> find_prev_nodes(int num) const {
        vector<SkipNode *> prevs(head_->nexts.size());
        auto curr = head_;
        for (int i = head_->nexts.size() - 1; i >= 0; --i) {
            while (curr->nexts[i] && curr->nexts[i]->num < num) {
                curr = curr->nexts[i];
            }
            prevs[i] = curr;
        }
        return prevs;
    }

    int random_level() {
        static const int P_NUMERATOR = 1;
        static const int P_DENOMINATOR = 2;  // P = 1/4 in redis implementation
        static const int MAX_LEVEL = 32;  // enough for 2^32 elements
        int level = 1;
        while (uniform_int_distribution<int>{1, P_DENOMINATOR}(gen_) <= P_NUMERATOR &&
               level < MAX_LEVEL) {
            ++level;
        }
        return level;
    }

    void print_list() const {
        for (int i = head_->nexts.size() - 1; i >= 0; --i) {
            auto curr = head_->nexts[i];
            cout << curr->num;
            curr = curr->nexts[i];
            while (curr) {
                cout << "->" << curr->num;
                curr = curr->nexts[i];
            }
            cout << endl;
        }
    }

    default_random_engine gen_;
    int len_;
    SkipNode *head_;
};

// Time:  O(logn) on average for each operation
// Space: O(n)
// smart pointer version (a little bit slower)
class Skiplist2 {
private:
    class SkipNode {
    public:
        SkipNode() : SkipNode(0, -1) {

        }

        SkipNode(int level, int num)
          : num(num)
          , nexts(level) {

        }

        int num;
        vector<shared_ptr<SkipNode>> nexts;
    };

public:
    Skiplist2()
      : gen_((random_device())())
      , len_(0)
      , head_(make_shared<SkipNode>()) {

    }

    bool search(int target) const {
        return find(target, find_prev_nodes(target)) != nullptr;
    }

    void add(int num) {
        auto node = make_shared<SkipNode>(random_level(), num);
        if (head_->nexts.size() < node->nexts.size()) {
            head_->nexts.resize(node->nexts.size());
        }
        auto prevs = find_prev_nodes(num);
        for (int i = 0; i < node->nexts.size(); ++i) {
            node->nexts[i] = prevs[i]->nexts[i];
            prevs[i]->nexts[i] = node;
        }
        ++len_;
    }

    bool erase(int num) {
        auto prevs = find_prev_nodes(num);
        auto curr = find(num, prevs);
        if (!curr) {
            return false;
        }
        --len_;
        for (int i = curr->nexts.size() - 1; i >= 0; --i) {
            prevs[i]->nexts[i] = curr->nexts[i];
            if (!head_->nexts[i]) {
                head_->nexts.pop_back();
            }
        }
        return true;
    }

    int size() const {
        return len_;
    }

private:
    shared_ptr<SkipNode> find(int num, const vector<shared_ptr<SkipNode>>& prevs) const {
        if (!prevs.empty()) {
            auto candidate = prevs[0]->nexts[0];
            if (candidate && candidate->num == num) {
                return candidate;
            }
        }
        return nullptr;
    }

    vector<shared_ptr<SkipNode>> find_prev_nodes(int num) const {
        vector<shared_ptr<SkipNode>> prevs(head_->nexts.size());
        auto curr = head_;
        for (int i = head_->nexts.size() - 1; i >= 0; --i) {
            while (curr->nexts[i] && curr->nexts[i]->num < num) {
                curr = curr->nexts[i];
            }
            prevs[i] = curr;
        }
        return prevs;
    }

    int random_level() {
        static const int P_NUMERATOR = 1;
        static const int P_DENOMINATOR = 2;  // P = 1/4 in redis implementation
        static const int MAX_LEVEL = 32;  // enough for 2^32 elements
        int level = 1;
        while (uniform_int_distribution<int>{1, P_DENOMINATOR}(gen_) <= P_NUMERATOR &&
               level < MAX_LEVEL) {
            ++level;
        }
        return level;
    }

    void print_list() const {
        for (int i = head_->nexts.size() - 1; i >= 0; --i) {
            auto curr = head_->nexts[i];
            cout << curr->num;
            curr = curr->nexts[i];
            while (curr) {
                cout << "->" << curr->num;
                curr = curr->nexts[i];
            }
            cout << endl;
        }
    }

    default_random_engine gen_;
    int len_;
    shared_ptr<SkipNode> head_;
};

