            tie(a, e, i, o, u) = make_tuple(((e + i) % MOD + u) % MOD,
                                            (a + i) % MOD,
                                            (e + o) % MOD,
                                            i,
                                            (i + o) % MOD);
        }
        return (((a + e) % MOD + (i + o) % MOD) % MOD + u) % MOD;
    }

private:
