class Solution {
public:
    int minimumSwap(string s1, string s2) {
        int x1 = 0, y1 = 0;
        for (int i = 0; i < s1.length(); ++i) {
            if (s1[i] == s2[i]) {
                continue;
            }
            x1 += int(s1[i] == 'x');
            y1 += int(s1[i] == 'y');
        }
        if (x1 % 2 !=  y1 % 2) {  // impossible
            return -1;
        }
        // case1: per xx or yy needs one swap, (x1 / 2 + y1 / 2) 
        // case2: per xy or yx needs two swaps, (x1 % 2 + y1 % 2)
        return x1 / 2 + y1 / 2 + x1 % 2 + y1 % 2;
    }
};

// Time:  O(n)
// Space: O(k)

class Solution {
public:
    int numberOfSubarrays(vector<int>& nums, int k) {
        return atMostK(nums, k) - atMostK(nums, k - 1);
    }

private:
    int atMostK(const vector<int>& nums, int k) {
        int result = 0, left = 0, count = 0;
        for (int right = 0; right < nums.size(); ++right) {
            count += nums[right] % 2;
            while (count > k) {
                count -= nums[left] % 2;
                ++left;
            }
            result += right - left + 1;
        }
        return result;
    }
};

