        int result = 0;
        for (int i = 0; i < 31; ++i) {
            int a_i = a & 1, b_i = b & 1, c_i = c & 1;
            if ((a_i | b_i) != c_i) {
                result += (a_i == b_i && b_i == 1) ? 2 : 1;
            }
            a = a >> 1, b = b >> 1, c = c >> 1;
        }
        return result;
    }
};

// Time:  O(|E| + |V|)
// Space: O(|V|)

class Solution {
public:
    int makeConnected(int n, vector<vector<int>>& connections) {
        if (connections.size() < n - 1) {
            return -1;
        }
        UnionFind union_find(n);
        for (const auto& c : connections) {
            union_find.union_set(c[0], c[1]);
        }
        return union_find.size() - 1;
    }

private:
    class UnionFind {
    public:
        UnionFind(const int n) : set_(n), size_(n) {
            iota(set_.begin(), set_.end(), 0);
        }

        int find_set(const int x) {
           if (set_[x] != x) {
               set_[x] = find_set(set_[x]);  // Path compression.
           }
           return set_[x];
        }

        bool union_set(const int x, const int y) {
            int x_root = find_set(x), y_root = find_set(y);
            if (x_root == y_root) {
                return false;
            }
            set_[min(x_root, y_root)] = max(x_root, y_root);
            --size_;
            return true;
        }

        int size() const {
            return size_;
        }

    private:
        vector<int> set_;
        int size_;
    };
};

// Time:  O(|E| + |V|)
// Space: O(|V|)
class Solution2 {
public:
    int makeConnected(int n, vector<vector<int>>& connections) {
        if (connections.size() < n - 1) {
            return -1;
        }
        unordered_map<int, vector<int>> G;
        for (const auto& c : connections) {
            G[c[0]].emplace_back(c[1]);
            G[c[1]].emplace_back(c[0]);
        }
        int result = 0;
        unordered_set<int> lookup;
        for (int i = 0; i < n; ++i) {
            result += dfs(G, i, &lookup);
        }
        return result - 1;
    }

private:
    int dfs(const unordered_map<int, vector<int>>& G,
            int i, unordered_set<int> *lookup) {
        if (lookup->count(i)) {
            return 0;
        }
        lookup->emplace(i);
        if (G.count(i)) {
            for (const auto& j : G.at(i)) {
                dfs(G, j, lookup);
            }
        }
        return 1;
    }
};

// Time:  O(26n)
// Space: O(26)

class Solution {
public:
    int minimumDistance(string word) {
        vector<int> dp(26);
        for (int i = 0; i < word.length() - 1; ++i) {
            int b = word[i] - 'A', c = word[i + 1] - 'A';
            for (int a = 0; a < 26; ++a) {
                dp[b] = max(dp[b], dp[a] - distance(a, c) + distance(b, c));
            }
        }
        int result = 0;
        for (int i = 0; i < word.length() - 1; ++i) {
            result += distance(word[i] - 'A', word[i + 1] - 'A');
        }
        return result - *max_element(dp.cbegin(), dp.cend());
    }

private:
    int distance(int a, int b) {
        return abs(a / 6 - b / 6) + abs(a % 6 - b % 6);
    }
};

// Time:  O(52n)
// Space: O(52)
class Solution2 {
private:
    template <typename T>
    struct PairHash {
        size_t operator()(const pair<T, T>& p) const {
            size_t seed = 0;
            seed ^= std::hash<T>{}(p.first)  + 0x9e3779b9 + (seed<<6) + (seed>>2);
            seed ^= std::hash<T>{}(p.second) + 0x9e3779b9 + (seed<<6) + (seed>>2);
            return seed;
        }
    };

public:
    int minimumDistance(string word) {
        unordered_map<pair<int, int>, int, PairHash<int>> dp = {{{-1, -1}, 0}};
        for (const auto& w : word) {
            int c = w - 'A';
            unordered_map<pair<int, int>, int, PairHash<int>> new_dp;
            for (const auto& [p, v] : dp) {
                const auto& [a, b] = p;
                if (!new_dp.count(make_pair(c, b)) || 
                    v + distance(a, c) < new_dp[make_pair(c, b)]) {
                    new_dp[make_pair(c, b)] = v + distance(a, c);
                }
                if (!new_dp.count(make_pair(a, c)) || 
                    v + distance(b, c) < new_dp[make_pair(a, c)]) {
                    new_dp[make_pair(a, c)] = v + distance(b, c);
                };
            }
            dp = move(new_dp);
        }
        return min_element(dp.cbegin(), dp.cend(),
                           [](const auto&a, const auto& b) {
                                return a.second < b.second;
                           })->second;
    }

private:
    int distance(int a, int b) {
        if (a == -1 || b == -1) {
            return 0;
        }
        return abs(a / 6 - b / 6) + abs(a % 6 - b % 6);
    }
};

