// Time:  O(n^3)
// Space: O(n^2)

class Solution {
public:
    int findTheCity(int n, vector<vector<int>>& edges, int distanceThreshold) {
        vector<vector<int>> dist(n, vector<int>(n, numeric_limits<int>::max()));
        for (const auto& e : edges) {
            dist[e[0]][e[1]] = dist[e[1]][e[0]] = e[2];
        }
        for (int i = 0; i < n; ++i) {
            dist[i][i] = 0;
        }
        for (int k = 0; k < n; ++k) {
             for (int i = 0; i < n; ++i) {
                 for (int j = 0; j < n; ++j) {
                     if (dist[i][k] != numeric_limits<int>::max() &&
                         dist[k][j] != numeric_limits<int>::max()) {
                        dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
                     }
                 }
             }
        }
        int result = -1, min_num = numeric_limits<int>::max();
        for (int i = n - 1; i >= 0; --i) {
            int num = accumulate(dist[i].cbegin(), dist[i].cend(), 0,
                                 [&distanceThreshold](const auto& a, const auto& b) {
                                     return a + (b <= distanceThreshold);
                                 });
            if (num < min_num) {
                min_num = num;
                result = i;
            }
        }
        return result;
    }
};

// Time:  O(d * n^2)
// Space: O(d * n)

class Solution {
public:
    int minDifficulty(vector<int>& jobDifficulty, int d) {
        if (jobDifficulty.size() < d) {
            return -1;
        }

        vector<vector<int>> dp(d,
                               vector<int>(jobDifficulty.size(),
                                           numeric_limits<int>::max()));
        dp[0][0] = jobDifficulty[0];
        for (int i = 1; i < jobDifficulty.size(); ++i) {
            dp[0][i] = max(dp[0][i - 1], jobDifficulty[i]);
        }
        for (int i = 1; i < d; ++i) {
            for (int j = i; j < jobDifficulty.size(); ++j) {
                int curr_max = jobDifficulty[j];
                for (int k = j; k >= i; --k) {
                    curr_max = max(curr_max, jobDifficulty[k]);
                    if (dp[i - 1][k - 1] != numeric_limits<int>::max()) {
                        dp[i][j] = min(dp[i][j], dp[i - 1][k - 1] + curr_max);
                    }
                }
            }
        }
        return dp[d - 1][jobDifficulty.size() - 1];
    }
};

