class Solution {
public:
    int minSetSize(vector<int>& arr) {
        vector<int> counting_sort(arr.size());
        unordered_map<int, int> count;
        for (const auto& x : arr) {
            ++count[x];
        }
        for (const auto& [_, c] : count) {
            ++counting_sort[c - 1];
        }
        int result = 0, total = 0;
        for (int c = arr.size() - 1; c >= 0; --c) {
            if (!counting_sort[c]) {
                continue;
            }
            int count = min(counting_sort[c],
                            ((int(arr.size()) + 1) / 2 - total - 1) / (c + 1) + 1);
            result += count;
            total += count * (c + 1);
            if (total >= (arr.size() + 1) / 2) {
                break;
            }
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(h)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    int maxProduct(TreeNode* root) {
        static const int MOD = 1e9 + 7;
        int64_t result = 0;
        dfs(root, dfs(root, 0, &result), &result);
        return result % MOD;
    }

private:
    int64_t dfs(TreeNode *root, int64_t total, int64_t *result) {
        if (!root) {
            return 0;
        }
        int64_t subtotal = dfs(root->left, total, result) +
                           dfs(root->right, total, result) +
                           root->val;
        *result = max(*result, subtotal * (total - subtotal));
        return subtotal;
    }
};

