};

// Time:  O(r + nlogn), r is the max end day of events
// Space: O(n)

class Solution {
public:
    int maxEvents(vector<vector<int>>& events) {
        sort(events.begin(), events.end(), greater<vector<int>>());
        const auto max_day = (*max_element(events.cbegin(), events.cend(),
                                           [](const auto& a, const auto& b) {
                                               return a[1] < b[1];
                                           }))[1];
        priority_queue<int, vector<int>, greater<int>> min_heap;
        int result = 0;
        for (int d = 1; d <= max_day; ++d) {
            while (!events.empty() && events.back()[0] == d) {
                min_heap.emplace(events.back()[1]);
                events.pop_back();
            }
            while (!min_heap.empty() && min_heap.top() == d - 1) {
                min_heap.pop();
            }
            if (min_heap.empty()) {
                continue;
            }
            min_heap.pop();
            ++result;
        }
        return result;
    }
};

// Time:  O(log(max(t)) * logn)
// Space: O(n)

class Solution {
public:
    bool isPossible(vector<int>& target) {
        // (1) x + remain = y
        // (2) y + remain = total
        // (1) - (2) => x - y = y - total
        //           => x = 2*y - total
        auto total = accumulate(cbegin(target), cend(target), 0ll);
        priority_queue<int> max_heap(cbegin(target), cend(target));
        while (total != target.size()) {
            const auto y = max_heap.top(); max_heap.pop();
            const auto& remain = total - y;
            auto x = y - remain;
            if (x <= 0) {
                return false;
            }
            if (x > remain) {  // for case [1, 1000000000]
                x = x % remain + remain;
            }
            max_heap.emplace(x);
            total = x + remain;
        }
        return true;
    }
};

