// Time:  O(1)
// Space: O(1)

class Solution {
public:
    Solution() : lookup_(12) {
        for (int M = 1; M < lookup_.size(); ++M) {
            lookup_[M] = lookup_[M - 1] + dayOfMonth(M);
        }
    }

    int daysBetweenDates(string date1, string date2) {
        return abs(dayOfYear(date1) - dayOfYear(date2));
    }

private:    
    int dayOfYear(string date) {   
        const auto& result = split(date, '-');
        const auto& Y = stoi(result[0]), &M = stoi(result[1]), &D = stoi(result[2]);
        const auto& leap = (M > 2 && (((Y % 4 == 0) && (Y % 100 != 0)) || (Y % 400 == 0))) ? 1 : 0;
        return (Y - 1) * 365 + ((Y - 1) / 4 - (Y - 1) / 100 + (Y - 1) / 400) + lookup_[M - 1] + D + leap;
    }

    int dayOfMonth(int M) {
        return (M == 2) ? 28 : 31 - (M - 1) % 7 % 2;
    }

    vector<string> split(const string& s, const char delim) {
        vector<string> result;
        auto end = string::npos;
        do {
            const auto& start = end + 1;
            end = s.find(delim, start);
            result.emplace_back(s.substr(start, end - start));
        } while (end != string::npos); 
        return result;
    }

    vector<int> lookup_;
};

// Time:  O(n)
// Space: O(n)

class Solution {
public:
    bool validateBinaryTreeNodes(int n, vector<int>& leftChild, vector<int>& rightChild) {
        unordered_set<int> roots;
        for (int i = 0; i < n; ++i) {
            roots.emplace(i);
        }
        for (const auto& i : leftChild) {
            roots.erase(i);
        }
        for (const auto& i : rightChild) {
            roots.erase(i);
        }
        if (size(roots) != 1) {
            return false;
        }
        const auto& root = *cbegin(roots);
        vector<int> stk({root});
        unordered_set<int> lookup({root});
        while (!empty(stk)) {
            const auto node = stk.back(); stk.pop_back();
            for (const auto& i : {leftChild[node], rightChild[node]}) {
                if (i < 0) {
                    continue;
                }
                if (lookup.count(i)) {
                    return false;
                }
                lookup.emplace(i);
                stk.emplace_back(i);
            }
        }
        return size(lookup) == n;
    }
};

// Time:  O(sqrt(n))
// Space: O(1)

class Solution {
public:
    vector<int> closestDivisors(int num) {
        vector<vector<int>> results = {divisors(num + 1), divisors(num + 2)};
        return *min_element(cbegin(results), cend(results),
                            [](const auto& a, const auto& b) {
                                return a[1] - a[0] < b[1] - b[0];
                            });
    }

private:
    vector<int> divisors(int n) {
        for (int d = sqrt(n); d >= 1; --d) {
            if (n % d == 0) {
                return {d, n / d};
            }
        }
        return {1, n};
    }
};

// Time:  O(sqrt(n))
// Space: O(1)
class Solution2 {
public:
    vector<int> closestDivisors(int num) {
        vector<int> result = {1, num};
        for (int d = 1; d * d <= num + 2; ++d) {
            if ((num + 2) % d == 0) {
                result = {d, (num + 2) / d};
            }
            if ((num + 1) % d == 0) {
                result = {d, (num + 1) / d};
            }
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    string largestMultipleOfThree(vector<int>& digits) {
        static const unordered_map<int, vector<vector<int>>> lookup = {
            {0, {}},
            {1, {{1}, {4}, {7}, {2, 2}, {5, 2}, {5, 5}, {8, 2}, {8, 5}, {8, 8}}},
            {2, {{2}, {5}, {8}, {1, 1}, {4, 1}, {4, 4}, {7, 1}, {7, 4}, {7, 7}}}
        };
        unordered_map<int, int> count = counter(digits);
        const auto& r = accumulate(cbegin(digits), cend(digits), 0) % 3;
        for (const auto& deletes : lookup.at(r)) {
            if (remove(deletes, &count)) {
                break;
            }
        }
        string result;
        for (int d = 9; d >= 0; --d) {
            result += string(count[d], '0' + d);
        }
        return !result.empty() && result[0] == '0' ? "0" : result;
    }

private:
    bool remove(const vector<int>& deletes, unordered_map<int, int> *count) {
        const auto& delete_count = counter(deletes);
        if (all_of(cbegin(delete_count), cend(delete_count),
                   [&count](const auto& kvp) {
                       return (*count)[kvp.first] >= kvp.second;
                   })) {
            for (const auto& [k, v] : delete_count) {
                (*count)[k] -= v;
            }
            return true;
        }
        return false;
    }

    unordered_map<int, int> counter(const vector<int> & digits) {
        unordered_map<int, int> result;
        for (const auto& i : digits) {
            ++result[i];
        }
        return result;
    }
};

