// Space: O(h + l)

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode(int x) : val(x), next(NULL) {}
 * };
 */
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */

// kmp solution
class Solution {
public:
    bool isSubPath(ListNode* head, TreeNode* root) {
        if (!head) {
            return true;
        }
        const auto& [pattern, prefix] = getPrefix(head);
        return dfs(pattern, prefix, root, -1);
    }

private:
    bool dfs(const vector<int>& pattern,
             const vector<int>& prefix,
             TreeNode *root, int j) {
        if (!root) {
            return false;
        }
        while (j + 1 && pattern[j + 1] != root->val) {
            j = prefix[j];
        }
        if (pattern[j + 1] == root->val) {
            ++j;
        }
        if (j + 1 == pattern.size()) {
            return true;
        }
        return dfs(pattern, prefix, root->left, j) ||
               dfs(pattern, prefix, root->right, j);
    }

    pair<vector<int>, vector<int>> getPrefix(ListNode *head) {
        vector<int> pattern = {head->val};
        vector<int> prefix = {-1};
        int j = -1;
        auto node = head->next;
        while (node) {
            while (j + 1 && pattern[j + 1] != node->val) {
                j = prefix[j];
            }
            if (pattern[j + 1] == node->val) {
                ++j;
            }
            pattern.emplace_back(node->val);
            prefix.emplace_back(j);
            node = node->next;
        }
        return {pattern, prefix};
    }
};

// Time:  O(n * min(h, l))
// Space: O(h)
// dfs solution
class Solution2 {
public:
    bool isSubPath(ListNode* head, TreeNode* root) {
        if (!head) {
            return true;
        }
        if (!root) {
            return false;
        }
        return dfs(head, root) ||
               isSubPath(head, root->left) ||
               isSubPath(head, root->right);
    }

private:
    bool dfs(ListNode *head, TreeNode *root) {
        if (!head) {
            return true;
        }
        if (!root) {
            return false;
        }
        return root->val == head->val &&
               (dfs(head->next, root->left) ||
                dfs(head->next, root->right));
    }
};

// Time:  O(m * n)
// Space: O(m * n)

// A* Search Algorithm without heap
class Solution {
public:
    int minCost(vector<vector<int>>& grid) {
        const pair<int, int> b = {0, 0}, t = {grid.size() - 1, grid[0].size() - 1}; 
        return a_star(grid, b, t);
    }

private:
    int a_star(const vector<vector<int>>& grid,
               const pair<int, int>& b,
               const pair<int, int>& t) {

        static const vector<tuple<int, int, int>> directions = {{1, 0, 1}, {2, 0, -1},
                                                                {3, 1, 0}, {4, -1, 0}};
        int f = 0, dh = 1;
        vector<pair<int, int>> closer = {b}, detour;
        unordered_set<int> lookup;
        while (!closer.empty() || !detour.empty()) {
            if (closer.empty()) {
                f += dh;
                swap(closer, detour);
            }
            const auto b = closer.back(); closer.pop_back();
            if (lookup.count(b.first * size(grid[0]) + b.second)) {
                continue;
            }
            lookup.emplace(b.first * size(grid[0]) + b.second);
            if (b == t) {
                return f;
            }
            for (const auto& [nd, dr, dc] : directions) {
                const pair<int, int>& nb = {b.first + dr, b.second + dc};
                if (!(0 <= nb.first && nb.first < grid.size() &&
                      0 <= nb.second && nb.second < grid[0].size() &&
                      !lookup.count(nb.first * size(grid[0]) + nb.second))) {
                    continue;
                }
                if (nd == grid[b.first][b.second]) {
                    closer.emplace_back(nb);
                } else {
                    detour.emplace_back(nb);
                }
            }
        }
        return -1;
    }
};

// Time:  O(m * n)
// Space: O(m * n)
// 0-1 bfs solution
class Solution2 {
public:
    int minCost(vector<vector<int>>& grid) {
        static const vector<tuple<int, int, int>> directions = {{1, 0, 1}, {2, 0, -1},
                                                                {3, 1, 0}, {4, -1, 0}};
        const pair<int, int> b = {0, 0}, t = {grid.size() - 1, grid[0].size() - 1}; 
        deque<pair<pair<int, int>, int>> dq = {{b, 0}};
        unordered_set<int> lookup;
        while (!dq.empty()) {
            const auto [b, d] = dq.front(); dq.pop_front();
            if (lookup.count(b.first * size(grid[0]) + b.second)) {
                continue;
            }
            lookup.emplace(b.first * size(grid[0]) + b.second);
            if (b == t) {
                return d;
            }
            for (const auto& [nd, dr, dc] : directions) {
                const auto& nb = make_pair(b.first + dr, b.second + dc);
                const auto& cost = nd != grid[b.first][b.second] ? 1 : 0;
                if (!(0 <= nb.first && nb.first < grid.size() &&
                      0 <= nb.second && nb.second < grid[0].size() &&
                      !lookup.count(nb.first * size(grid[0]) + nb.second))) {
                    continue;
                }
                if (!cost) {
                    dq.emplace_front(nb, d);
                } else {
                    dq.emplace_back(nb, d + cost);
                }
            }
        }
        return -1;  // never reach here
    }
};

