// Time:  O(n)
// Space: O(h)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */

class Solution {
public:
    TreeNode* getTargetCopy(TreeNode* original, TreeNode* cloned, TreeNode* target) {
        for (PreorderIterator<TreeNode*> left(original), right(cloned);
             *left && *right;
             ++left, ++right) {
            if ((*left) == target) {
                return (*right);
            }
        }
        return nullptr;
    }

private:
    template<typename T>
    class PreorderIterator {
    public:
        PreorderIterator(T root)
         : stack_{{root}}
         , curr_{} {
             ++(*this);
        }

        PreorderIterator& operator++() {
            while (!stack_.empty()) {
                const auto root = stack_.back(); stack_.pop_back();
                if (!root) {
                    continue;
                }
                stack_.emplace_back(root->right);
                stack_.emplace_back(root->left);
                curr_ = root;
                return *this;
            }
            curr_ = T{};
            return *this;
        }

        const T& operator*() const {
            return curr_;
        }

    private:
        vector<T> stack_;
        T curr_;
    };
};

// Time:  O(m * n)
// Space: O(m + n)

class Solution {
public:
    vector<int> luckyNumbers (vector<vector<int>>& matrix) {
        vector<int> rows;
        for (const auto& row : matrix) {
            rows.emplace_back(*min_element(row.cbegin(), row.cend()));
        }
        vector<int> cols;
        for (int c = 0; c < matrix[0].size(); ++c) {
            int max_cell = 0;
            for (int r = 0; r < matrix.size(); ++r) {
                max_cell = max(max_cell, matrix[r][c]);
            }
            cols.emplace_back(max_cell);
        }
        vector<int> result;
        for (int r = 0; r < matrix.size(); ++r) {
            for (int c = 0; c < matrix[0].size(); ++c) {
                if (rows[r] == cols[c]) {
                    result.emplace_back(matrix[r][c]);
                }
            }
        }
        return result;
    }
};

// Time:  O(m * n)
// Space: O(m + n)
class Solution2 {
public:
    vector<int> luckyNumbers (vector<vector<int>>& matrix) {
        unordered_set<int> rows;
        for (const auto& row : matrix) {
            rows.emplace(*min_element(row.cbegin(), row.cend()));
        }
        unordered_set<int> cols;
        for (int c = 0; c < matrix[0].size(); ++c) {
            int max_cell = 0;
            for (int r = 0; r < matrix.size(); ++r) {
                max_cell = max(max_cell, matrix[r][c]);
            }
            cols.emplace(max_cell);
        }
        unordered_set<int> intersection = set_intersection(rows, cols);
        return vector<int>(intersection.cbegin(), intersection.cend());
    }

private:
    template<typename T>
    unordered_set<T> set_intersection(const unordered_set<T>& a,
                                      const unordered_set<T>& b) {
        if (a.size() > b.size()) {
            return set_intersection(b, a);
        }
        unordered_set<T> result;
        for (const auto& x : a) {
            if (b.count(x)) {
                result.emplace(x);
            }
        }
        return result;
    }
};

