// Time:  O(n^2 * logn)
// Space: O(n^2)

class Solution {
public:
    vector<string> simplifiedFractions(int n) {
        unordered_set<pair<int, int>, PairHash<int>> lookup;
        for (int b = 1; b <= n; ++b) {
            for (int a = 1; a < b; ++a) {
                const auto& g = gcd(a, b);
                lookup.emplace(a / g, b / g);
            }
        }
        vector<string> result;
        transform(cbegin(lookup), cend(lookup), back_inserter(result),
                  [](const auto& kvp) {
                      return to_string(kvp.first) + "/" + to_string(kvp.second);
                  });
        return result;
    }

private:    
    template <typename T>
    struct PairHash {
        size_t operator()(const pair<T, T>& p) const {
            size_t seed = 0;
            seed ^= std::hash<T>{}(p.first)  + 0x9e3779b9 + (seed<<6) + (seed>>2);
            seed ^= std::hash<T>{}(p.second) + 0x9e3779b9 + (seed<<6) + (seed>>2);
            return seed;
        }
    };
};

// Time:  O(n)
// Space: O(h)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    int goodNodes(TreeNode* root) {
        int result = 0;
        vector<pair<TreeNode *, int>> stk = {{root, root->val}};
        while (!stk.empty()) {
            auto [node, curr_max] = stk.back(); stk.pop_back();
            if (!node) {
                continue;
            }
            curr_max = max(curr_max, node->val);
            result += (curr_max <= node->val);
            stk.emplace_back(node->right, curr_max);
            stk.emplace_back(node->left, curr_max);
        }
        return result;
    }
};

// Time:  O(n)
