        return result;
    }
};

// Time:  O(n * m * l + n^2 * m), n is favoriteCompanies.length
//                              , m is the max of favoriteCompanies[i].length
//                              , l is the max of favoriteCompanies[i][j].length
// Space: O(n * m * l)

class Solution {
public:
    vector<int> peopleIndexes(vector<vector<string>>& favoriteCompanies) {
        unordered_map<string, int> lookup;
        vector<unordered_set<int>> comps;
        for (const auto& cs : favoriteCompanies) {
            comps.emplace_back();
            for (const auto& c : cs) {
                if (!lookup.count(c)) {
                    const auto id = lookup.size();
                    lookup[c] = id;
                }
                comps.back().emplace(lookup[c]);
            }
        }
        vector<int> result;
        for (int i = 0; i < comps.size(); ++i) {
            bool is_not_subset = true;
            for (int j = 0; j < comps.size(); ++j) {
                if (i == j) {
                    continue;
                }
                if (all_of(cbegin(comps[i]), cend(comps[i]),
                           [&](const auto& a) {
                               return comps[j].count(a);
                           })) {
                    is_not_subset = false;
                    break;
                }
            }
            if (is_not_subset) {
                result.emplace_back(i);
            }
        }
        return result;
    }
};

// Time:  O(n^2 * logn)
// Space: O(n)

// angle sweep solution
// great explanation:
// https://leetcode.com/problems/maximum-number-of-darts-inside-of-a-circular-dartboard/discuss/636345/Python-O(n3)-and-O(n2logn)-solution-explained-in-detail-with-pictures
class Solution {
public:
    int numPoints(vector<vector<int>>& points, int r) {
        int result = 0;
        for (int i = 0; i < points.size(); ++i) {
            result = max(result, countPoints(points, r, i));
        }
        return result;
    }

private:
    int countPoints(const vector<vector<int>>& points, int r, int i) {
        vector<pair<double, bool>> angles;
        for (int j = 0; j < points.size(); ++j) {
            if (j == i) {
                continue;
            }
            int dx = points[i][0] - points[j][0];
            int dy = points[i][1] - points[j][1];
            const auto d = sqrt(dx * dx + dy * dy);
            if (d > 2 * r) {
                continue;
            }
            const auto delta = acos(d / (2 * r));
            const auto angle = atan2(dy, dx);
            angles.emplace_back(angle - delta, false);
            angles.emplace_back(angle + delta, true);
        }
        sort(begin(angles), end(angles));
        int result = 1, count = 1;
        for (const auto& [_, is_closed] : angles) {  // angle sweep
            if (!is_closed) {
                ++count;
            } else {
                --count;
            }
            result = max(result, count);
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(n)

class Solution {
public:
    int isPrefixOfWord(string sentence, string searchWord) {
        if (sentence.compare(0, searchWord.size(), searchWord) == 0) {
            return 1;
        }
        searchWord = " " + searchWord;
        auto p = KMP(sentence, searchWord);
        if (p == -1) {
            return -1;
        }
        return 1 + accumulate(cbegin(sentence), cbegin(sentence) + p + 1, 0,
                              [](const auto& a, const auto& b) {
                                  return a + (b == ' ');
                              });
    }

private:
    int KMP(const string& text, const string& pattern) {
        const vector<int> prefix = getPrefix(pattern);
        int j = -1;
        for (int i = 0; i < text.length(); ++i) {
            while (j > -1 && pattern[j + 1] != text[i]) {
                j = prefix[j];
            }
            if (pattern[j + 1] == text[i]) {
                ++j;
            }
            if (j == pattern.length() - 1) {
                return i - j;
            }
        }
        return -1;
    }

    vector<int> getPrefix(const string& pattern) {
        vector<int> prefix(pattern.length(), -1);
        int j = -1;
        for (int i = 1; i < pattern.length(); ++i) {
            while (j > -1 && pattern[j + 1] != pattern[i]) {
                j = prefix[j];
            }
            if (pattern[j + 1] == pattern[i]) {
                ++j;
            }
            prefix[i] = j;
        }
        return prefix;
    }
};

