// Time:  O(n)
// Space: O(h)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */

class Solution {
public:
    int pseudoPalindromicPaths (TreeNode* root) {
        int result = 0;
        vector<pair<TreeNode *, int>> stk = {{root, 0}};
        while (!stk.empty()) {
            auto [node, count] = stk.back(); stk.pop_back();
            if (!node) {
                continue;
            }
            count ^= 1 << node->val;
            result += int(!node->left && !node->right && (count & (count - 1)) == 0);
            stk.emplace_back(node->right, count);
            stk.emplace_back(node->left, count);
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(h)
class Solution2 {
public:
    int pseudoPalindromicPaths (TreeNode* root) {
        return dfs(root, 0);
    }

private:
    int dfs(TreeNode *node, int count) {
        if (!node) {
            return 0;
        }
        count ^= 1 << node->val;
        return int(!node->left && !node->right && (count & (count - 1)) == 0) +
               dfs(node->left, count) + dfs(node->right, count);
    }
};

// Time:  O(m * n)
// Space: O(min(m, n))

class Solution {
public:
    int maxDotProduct(vector<int>& nums1, vector<int>& nums2) {
        if (nums1.size() < nums2.size()) {
            return maxDotProduct(nums2, nums1);
        }
        vector<vector<int64_t>> dp(2, vector<int64_t>(nums2.size()));
        for (int i = 0; i < nums1.size(); ++i) {
            for (int j = 0; j < nums2.size(); ++j) {
                dp[i % 2][j] = int64_t(nums1[i]) * nums2[j];
                if (i && j) {
                    dp[i % 2][j] += max(dp[(i - 1) % 2][j - 1], int64_t(0));
                }
                if (i) {
                    dp[i % 2][j] = max(dp[i % 2][j], dp[(i - 1) % 2][j]);
                }
                if (j) {
                    dp[i % 2][j] = max(dp[i % 2][j], dp[i % 2][j - 1]);
                }
            }
        }
        return dp[(nums1.size() - 1) % 2].back();
    }
};

