// Time:  O(n * k)
// Space: O(2^k)

class Solution {
public:
    bool hasAllCodes(string s, int k) {
        unordered_set<int> lookup;
        const int base = 1 << k;
        if (base > s.length()) {
            return false;
        }
        int num = 0;
        for (int i = 0; i < s.length(); ++i) {
            num = (num << 1) + (s[i] - '0');
            if (i >= k - 1) {
                lookup.emplace(num);
                num -= (s[i - k + 1] - '0') * (base >> 1);
            }
        }
        return lookup.size() == base;
    }
};

// Time:  O(n * k)
// Space: O(k * 2^k)
class Solution2 {
public:
    bool hasAllCodes(string s, int k) {
        unordered_set<string> lookup;
        const int base = 1 << k;
        if (base > s.length()) {
            return false;
        }
        for (int i = 0; i + k - 1 < s.length(); ++i) {
            lookup.emplace(s.substr(i, k));
        }
        return lookup.size() == base;
    }
};

// Time:  O(n^3)
// Space: O(n^2)

class Solution {
public:
    vector<bool> checkIfPrerequisite(int n, vector<vector<int>>& prerequisites, vector<vector<int>>& queries) {
        const auto& reachable = floydWarshall(n, prerequisites);
        vector<bool> result;
        for (const auto& q : queries) {
            result.emplace_back(reachable.count(q[0] * n + q[1]));
        }
        return result;
    }

private:
    unordered_set<int> floydWarshall(int n, const vector<vector<int>>& graph) {
        unordered_set<int> reachable;
        for (const auto& connected : graph) {
            reachable.emplace(connected[0] * n + connected[1]);
        }
        for (int k = 0; k < n; ++k) {
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < n; ++j) {
                    if (!reachable.count(i * n + j) &&
                        (reachable.count(i * n + k) && reachable.count(k * n + j))) {
                        reachable.emplace(i * n + j);
                    }
                }
            }
        }
        return reachable;
    }
};

// Time:  O(n * q)
// Space: O(p + n)
class Solution_TLE {
public:
    vector<bool> checkIfPrerequisite(int n, vector<vector<int>>& prerequisites, vector<vector<int>>& queries) {
        unordered_map<int, vector<int>> graph;
        for (const auto& connected : prerequisites) {
            graph[connected[0]].emplace_back(connected[1]);
        }
        vector<bool> result;
        for (const auto& q : queries) {
            vector<int> stk = {q[0]};
            unordered_set<int> lookup = {q[0]};
            while (!stk.empty()) {
                const auto node = stk.back(); stk.pop_back();
                for (const auto& nei : graph[node]) {
                    if (lookup.count(nei)) {
                        continue;
                    }
                    stk.emplace_back(nei);
                    lookup.emplace(nei);
                }
            }
            result.emplace_back(lookup.count(q[1]));
        }
        return result;
    }
};

// Time:  O(m * n^2)
// Space: O(n^2)

class Solution {
public:
    int cherryPickup(vector<vector<int>>& grid) {
        vector<vector<vector<int>>> dp(2,
            vector<vector<int>>(grid[0].size() + 2,
              vector<int>(grid[0].size() + 2, numeric_limits<int>::min())));

        dp[0][1][grid[0].size()] = grid[0][0] + grid[0][grid[0].size() - 1];
        int result = 0;
        for (int i = 1; i < grid.size(); ++i) {
            for (int j = 1; j <= grid[0].size(); ++j) {
                for (int k = 1; k <= grid[0].size(); ++k) {
                    int max_prev_dp = numeric_limits<int>::min();
                    for (int d1 = -1; d1 <= 1; ++d1) {
                        for (int d2 = -1; d2 <= 1; ++d2) {
                            max_prev_dp = max(max_prev_dp, dp[(i - 1) % 2][j + d1][k + d2]);
                        }
                    }
                    dp[i % 2][j][k] = (max_prev_dp == numeric_limits<int>::min()) ? numeric_limits<int>::min() :
                                      max_prev_dp + ((j != k) ? (grid[i][j - 1] + grid[i][k - 1]) : grid[i][j - 1]);
                    result = max(result, dp[i % 2][j][k]);
                }
            }
        }
        return result;
    }
};

