class Solution {
public:
    int maxProduct(vector<int>& nums) {
        int m1 = 0, m2 = 0;
        for (const auto& num : nums) {
            if (num > m1) {
                m2 = m1;
                m1 = num;
            } else if (num > m2) {
                m2 = num;
            }
        }
        return (m1 - 1) * (m2 - 1);
    }
};

// Time:  O(hlogh + wlogw)
// Space: O(1)

class Solution {
public:
    int maxArea(int h, int w, vector<int>& horizontalCuts, vector<int>& verticalCuts) {
        static const int MOD = 1e9 + 7;
        return max_len(h, &horizontalCuts) * max_len(w, &verticalCuts) % MOD;
    }

private:
    uint64_t max_len(int l, vector<int> *cuts) {
        sort(begin(*cuts), end(*cuts));
        l = max((*cuts)[0] - 0, l - cuts->back());
        for (int i = 1; i < cuts->size(); ++i) {
            l = max(l, (*cuts)[i] - (*cuts)[i - 1]);
        }
        return l;
    }
};

// Time:  O(n)
// Space: O(n)

class Solution {
public:
    int minReorder(int n, vector<vector<int>>& connections) {
        unordered_set<uint64_t> lookup;
        unordered_map<int, vector<int>> graph;
        for (const auto& connection : connections) {
            lookup.emplace(uint64_t(connection[0]) * n + connection[1]);
            graph[connection[0]].emplace_back(connection[1]);
            graph[connection[1]].emplace_back(connection[0]);
        }
        int result = 0;
        vector<pair<int, int>> stk = {{-1, 0}};
        while (!stk.empty()) {
            const auto [parent, u] = stk.back(); stk.pop_back();
            for (const auto& v : graph[u]) {
                if (v == parent) {
                    continue;
                }
                stk.emplace_back(u, v);
            }
            result += lookup.count(uint64_t(parent) * n + u);
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(n)
class Solution2 {
public:
    int minReorder(int n, vector<vector<int>>& connections) {
        unordered_set<uint64_t> lookup;
        unordered_map<int, vector<int>> graph;
        for (const auto& connection : connections) {
            lookup.emplace(uint64_t(connection[0]) * n + connection[1]);
            graph[connection[0]].emplace_back(connection[1]);
            graph[connection[1]].emplace_back(connection[0]);
        }
        return dfs(n, lookup, graph, -1, 0);
    }

private:
    int dfs(int n, const unordered_set<uint64_t>& lookup, const unordered_map<int, vector<int>>& graph, int parent, int u) {
        int result = lookup.count(uint64_t(parent) * n + u);
        for (const auto& v : graph.at(u)) {
            if (v == parent) {
                continue;
            }
            result += dfs(n, lookup, graph, u, v);
        }
        return result;
    }
};

// Time:  O(k^3 * n^2)
// Space: O(k^2 * n)

class Solution {
public:
    double getProbability(vector<int>& balls) {
        unordered_map<pair<int, int>, uint64_t, PairHash<int>> dp;
        dp[pair(0, 0)] = 1;  // dp[i, j] is the ways of number difference i and color difference j
        for (const auto& n : balls) {  // O(k) times
            unordered_map<pair<int, int>, uint64_t, PairHash<int>> new_dp;
            for (const auto& kvp : dp) {  // O(k^2 * n) times
                const auto& [ndiff, cdiff] = kvp.first;
                for (int k = 0, new_count = 1; k <= n; ++k, new_count *= n - k + 1, new_count /= k) {  // O(n) times
                    const auto& new_ndiff = ndiff + (k - (n - k));
                    const auto& new_cdiff = (k == 0) ? cdiff - 1 : ((k == n) ? cdiff + 1 : cdiff);
                    new_dp[pair(new_ndiff, new_cdiff)] += kvp.second * new_count;
                }
            }
            dp = move(new_dp);
        }
        const auto& total = accumulate(cbegin(balls), cend(balls), 0);
        return double(dp[pair(0, 0)]) / nCr(total, total / 2);
    }

private:
    uint64_t nCr(int n, int r) {  // Time: O(n), Space: O(1)
        if (n - r < r) {
            return nCr(n, n - r);
        }
        uint64_t c = 1;
        for (int k = 1; k <= r; ++k) {
            c *= n - k + 1;
            c /= k;
        }
        return c;
    }

    template <typename T>
    struct PairHash {
        size_t operator()(const pair<T, T>& p) const {
            size_t seed = 0;
            seed ^= std::hash<T>{}(p.first)  + 0x9e3779b9 + (seed<<6) + (seed>>2);
            seed ^= std::hash<T>{}(p.second) + 0x9e3779b9 + (seed<<6) + (seed>>2);
            return seed;
        }
    };
};

