        vector<int> result;
        for (int i = 1; i * i <= n; ++i) {
            if (n % i) {
                continue;
            }
            if (i * i != n) {
                result.emplace_back(i);
            }
            if (!--k) {
                return i;
            }
        }
        return (k > result.size()) ? -1 : n / result[result.size() - k];
    }
};

