        int result = 0, count = 0, left = 0;
        for (int right = 0; right < nums.size(); ++right) {
            count += (nums[right] == 0);
            while (count >= 2) {
                count -= (nums[left++] == 0);
            }
            result = max(result, right - left + 1);
        }
