// Time:  O((n * C(c, min(c, k))) * 2^n)
// Space: O(2^n)

// concise dp solution
class Solution {
public:
    int minNumberOfSemesters(int n, vector<vector<int>>& dependencies, int k) {
        vector<int> reqs(n);
        for (const auto& d : dependencies) {
            reqs[d[1] - 1] |= 1 << (d[0] - 1);
        }
        vector<int> dp(1 << n, n);
        dp[0] = 0;
        for (int mask = 0; mask < dp.size(); ++mask) {
            vector<int> candidates;
            for (int v = 0; v < n; ++v) {
                if ((mask & (1 << v)) == 0 && (mask & reqs[v]) == reqs[v]) {
                    candidates.emplace_back(v);
                }
            }
            const auto r = min(int(candidates.size()), k);
            combinations(candidates.size(), min(int(candidates.size()), k), 
                         [&dp, &mask, &candidates](const vector<int>& idxs) {
                             auto new_mask = mask;
                             new_mask |= accumulate(cbegin(idxs), cend(idxs), 0,
                                                    [&candidates](const auto& a, const auto& b) {
                                                        return a | (1 << candidates[b]);
                                                    });
                             dp[new_mask] = min(dp[new_mask], dp[mask] + 1);
                         });
        }
        return dp.back();
    }

private:
    void combinations(int n, int k, const function<void (const vector<int>&)>& callback) {
        static const auto& next_pos =
            [](const auto& n, const auto& k, const auto& idxs) {
                int i = k - 1;
                for (; i >= 0; --i) {
                    if (idxs[i] != i + n - k) {
                        break;
                    }
                }
                return i;
            };

        vector<int> idxs(k);
        iota(begin(idxs), end(idxs), 0);
        callback(idxs);
        for (int i; (i = next_pos(n, k, idxs)) >= 0;) {
            ++idxs[i];
            for (int j = i + 1; j < k; ++j) {
                idxs[j] = idxs[j - 1] + 1;
            }
            callback(idxs);
        }
    }
};

// Time:  O((n * C(c, min(c, k))) * 2^n)
// Space: O(2^n)
// embedded combination dp solution
class Solution2 {
public:
    int minNumberOfSemesters(int n, vector<vector<int>>& dependencies, int k) {
        static const auto& choice_mask =
            [](const auto& nums, const auto& idxs) {
                return accumulate(cbegin(idxs), cend(idxs), 0,
                                  [&nums](const auto& a, const auto& b) {
                                      return a | (1 << nums[b]);
                                  });
            };
        static const auto& next_pos =
            [](const auto& n, const auto& r, const auto& idxs) {
                int i = r - 1;
                for (; i >= 0; --i) {
                    if (idxs[i] != i + n - r) {
                        break;
                    }
                }
                return i;
            };

        vector<int> reqs(n);
        for (const auto& d : dependencies) {
            reqs[d[1] - 1] |= 1 << (d[0] - 1);
        }
        vector<int> dp(1 << n, n);
        dp[0] = 0;
        for (int mask = 0; mask < dp.size(); ++mask) {
            vector<int> candidates;
            for (int v = 0; v < n; ++v) {
                if ((mask & (1 << v)) == 0 && (mask & reqs[v]) == reqs[v]) {
                    candidates.emplace_back(v);
                }
            }
            const auto r = min(int(candidates.size()), k);
            vector<int> idxs(r);
            iota(begin(idxs), end(idxs), 0);
            const auto& new_mask = (mask | choice_mask(candidates, idxs));
            dp[new_mask] = min(dp[new_mask], dp[mask] + 1);
            for (int i; (i = next_pos(candidates.size(), r, idxs)) >= 0;) {
                ++idxs[i];
                for (int j = i + 1; j < k; ++j) {
                    idxs[j] = idxs[j - 1] + 1;
                }
                const auto& new_mask = (mask | choice_mask(candidates, idxs));
                dp[new_mask] = min(dp[new_mask], dp[mask] + 1);
            }
        }
        return dp.back();
    }
};

// Time:  O(nlogn + e), e is the number of edges in graph
// Space: O(n + e)
// wrong greedy solution
// since the priority of courses are hard to decide especially for those courses with zero indegrees are of the same outdegrees and depths
// e.x.
// 9
// [[1,4],[1,5],[3,5],[3,6],[2,6],[2,7],[8,4],[8,5],[9,6],[9,7]]
// 3
class Solution_WA {
public:
    int minNumberOfSemesters(int n, vector<vector<int>>& dependencies, int k) {
        unordered_map<int, vector<int>> graph;
        vector<int> degrees(n);
        for (const auto &d: dependencies) {
            graph[d[0] - 1].emplace_back(d[1] - 1);
            ++degrees[d[1] - 1];
        }
        vector<int> depths(n, -1);
        for (int i = 0; i < n; ++i) {
            dfs(graph, i, &depths);
        }
        priority_queue<pair<int, int>> max_heap;
        for (int i = 0; i < n; ++i) {
            if (!degrees[i]) {
                max_heap.emplace(depths[i], i);
            }
        }
        int result = 0;
        while (!max_heap.empty()) {
            vector<int> new_q;
            for (int i = 0; !max_heap.empty() && i < k; ++i) {
                const auto [depth, node] = max_heap.top(); max_heap.pop();
                for (const auto& child : graph[node]) {
                    if (!--degrees[child]) {
                        new_q.emplace_back(child);
                    }
                }
            }
            ++result;
            for (const auto& node : new_q) {
                max_heap.emplace(depths[node], node);
            }
        }
        return result;
    }

private:
    int dfs(const unordered_map<int, vector<int>> &graph,
            int i, vector<int> *depths) {
        if ((*depths)[i] == -1) {
            int depth = 0;
            if (graph.count(i)) {
                for (const auto& child : graph.at(i)) {
                    depth = max(depth, dfs(graph, child, depths));
                }
            }
            (*depths)[i] = depth + 1;
        }
        return (*depths)[i];
    }
};

// Time:  O(n)
// Space: O(n)

class Solution {
public:
    bool isPathCrossing(string path) {
        unordered_set<pair<int, int>, PairHash<int>> lookup = {{0, 0}};
        int x = 0, y = 0;
        for (const auto& c : path) {
            switch(c) {
                case 'E':
                    ++x;
                    break;
                case 'W':
                    --x;
                    break;
                case 'N':
                    ++y;
                    break;
                case 'S':
                    --y;
                    break;
            }
            if (!lookup.emplace(x, y).second) {
                return true;
            }
        }
        return false;
    }

private:
    template <typename T>
    struct PairHash {
        size_t operator()(const pair<T, T>& p) const {
            size_t seed = 0;
            seed ^= std::hash<T>{}(p.first)  + 0x9e3779b9 + (seed<<6) + (seed>>2);
            seed ^= std::hash<T>{}(p.second) + 0x9e3779b9 + (seed<<6) + (seed>>2);
            return seed;
        }
    };
};

// Time:  O(n)
// Space: O(k)

class Solution {
public:
    bool canArrange(vector<int>& arr, int k) {
        unordered_map<int, int> count;
        for (const auto& i : arr) {
            ++count[(i % k + k) % k];
        }
        if (count.count(0) && count[0] % 2) {
            return false;
        }
        for (int i = 1; i < k; ++i) {
            if (!count.count(i)) {
                continue;
            }
            if (!(count.count(k - i) && count[i] == count[k - i])) {
                return false;
            }
        }
        return true;
    }
};

// Time:  O(nlogn)
// Space: O(n)

class Solution {
public:
    int numSubseq(vector<int>& nums, int target) {
        static const int MOD = 1e9 + 7;
        sort(begin(nums), end(nums));
        int result = 0;
        int left = 0, right = nums.size() - 1;
        while (left <= right) {
            if (nums[left] + nums[right] > target) {
                --right;
            } else {
                result = (result + pow(2, right - left, MOD)) % MOD;
                ++left;
            }
        }
        return result;
    }

private:
    uint64_t pow(uint64_t a,uint64_t b, uint64_t m) {
        a %= m;
        uint64_t result = 1;
        while (b) {
            if (b & 1) {
                result = (result * a) % m;
            }
            a = (a * a) % m;
            b >>= 1;
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(n)

class Solution {
public:
    int findMaxValueOfEquation(vector<vector<int>>& points, int k) {
        int result = numeric_limits<int>::min();
        deque<int> dq;
        for (int i = 0; i < points.size(); ++i) {
            const auto& x = points[i][0], &y = points[i][1];
            while(!dq.empty() && points[dq.front()][0] < x - k) {
                dq.pop_front();
            }
            if (!dq.empty()) {
                result = max(result, points[dq.front()][1] - points[dq.front()][0] + y + x);
            }
            while(!dq.empty() && points[dq.back()][1] - points[dq.back()][0] <= y - x) {
                dq.pop_back();
            }
            dq.emplace_back(i);
        }
        return result;
    }
};

// Time:  ctor:    O(1)
//        join:    O(logu + c), u is the number of total joined users
//        leave:   O(logu + c), c is the number of chunks
//        request: O(u)
// Space: O(u * c)

// "u ~= n" solution, n is the average number of users who own the chunk
class FileSharing {
public:
    FileSharing(int m) {

    }

    int join(vector<int> ownedChunks) {
        int userID = users_.size() + 1;
        if (!min_heap_.empty()) {
            userID = min_heap_.top();
            min_heap_.pop();
        } else {
            users_.emplace_back();
        }
        for (const auto& chunk : ownedChunks) {
            users_[userID - 1].emplace(chunk);
        }
        lookup_.emplace(userID);
        return userID;
    }

    void leave(int userID) {
        if (!lookup_.count(userID)) {
            return;
        }
        lookup_.erase(userID);
        users_[userID - 1].clear();
        min_heap_.emplace(userID);
    }

    vector<int> request(int userID, int chunkID) {
        vector<int> result;
        for (int i = 0; i < users_.size(); ++i) {
            if (users_[i].count(chunkID)) {
                result.emplace_back(i + 1);
            }
        }
        if (!result.empty()) {
            users_[userID - 1].emplace(chunkID);
        }
        return result;
    }

private:
    vector<unordered_set<int>> users_;
    unordered_set<int> lookup_;
    priority_queue<int, vector<int>, greater<int>> min_heap_;
};

// Time:  ctor:    O(1)
//        join:    O(logu + c), u is the number of total joined users
//        leave:   O(logu + c), c is the number of chunks
//        request: O(nlogn)   , n is the average number of users who own the chunk
// Space: O(u * c + m)
// "u >> n" solution
class FileSharing2 {
public:
    FileSharing2(int m) {

    }

    int join(vector<int> ownedChunks) {
        int userID = users_.size() + 1;
        if (!min_heap_.empty()) {
            userID = min_heap_.top();
            min_heap_.pop();
        } else {
            users_.emplace_back();
        }
        for (const auto& chunk : ownedChunks) {
            users_[userID - 1].emplace(chunk);
            chunks_[chunk].emplace(userID);
        }
        lookup_.emplace(userID);
        return userID;
    }

    void leave(int userID) {
        if (!lookup_.count(userID)) {
            return;
        }
        lookup_.erase(userID);
        for (const auto& chunk : users_[userID - 1]) {
            chunks_[chunk].erase(userID);
        }
        users_[userID - 1].clear();
        min_heap_.emplace(userID);
    }

    vector<int> request(int userID, int chunkID) {
        vector<int> result(cbegin(chunks_[chunkID]), cend(chunks_[chunkID]));
        sort(begin(result), end(result));
        if (!result.empty()) {
            users_[userID - 1].emplace(chunkID);
            chunks_[chunkID].emplace(userID);
        }
        return result;
    }

private:
    vector<unordered_set<int>> users_;
    unordered_set<int> lookup_;
    unordered_map<int, unordered_set<int>> chunks_;
    priority_queue<int, vector<int>, greater<int>> min_heap_;
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    bool canMakeArithmeticProgression(vector<int>& arr) {
        const auto m = *min_element(cbegin(arr), cend(arr));
        const auto& d = (*max_element(cbegin(arr), cend(arr)) - m) / (arr.size() - 1);
        if (!d) {
            return true;
        }
        for (int i = 0; i < arr.size();) {
            if (arr[i] == m + i * d) {
                ++i;
            } else {
                const auto& diff = arr[i] - m;
                if (diff % d || diff / d >= arr.size() || arr[i] == arr[diff / d]) {
                    return false;
                }
                swap(arr[i], arr[diff / d]);
            }
        }
        return true;
    }
};

