// one pass solution without recursion
class Solution {
public:
    Node* moveSubTree(Node* root, Node* p, Node* q) {
        unordered_map<Node *, Node *> lookup;
        const auto& is_ancestor = iter_find_parents(root, nullptr, p, q, false, &lookup);
        if (lookup.count(p) && lookup[p] == q) {
            return root;
        }
        q->children.emplace_back(p);
        if (!is_ancestor) {
            lookup[p]->children.erase(find(begin(lookup[p]->children), end(lookup[p]->children), p));
        } else {
            lookup[q]->children.erase(find(begin(lookup[q]->children), end(lookup[q]->children), q));
            if (p == root) {
                root = q;
            } else {
                *find(begin(lookup[p]->children), end(lookup[p]->children), p) = q;
            }
        }
        return root;
    }

private:
    bool iter_find_parents(Node *node, Node *parent, Node *p, Node *q,
                           bool is_ancestor,
                           unordered_map<Node *, Node *> *lookup) {
        vector<tuple<int, Node *, Node *, bool, int>> stk = {tuple(1, node, parent, is_ancestor, -1)};
        while (!stk.empty()) {
            const auto [step, node, parent, is_ancestor, i] = stk.back(); stk.pop_back();
            if (step == 1) {
                if (node == p || node == q) {
                    (*lookup)[node] = parent;
                    if (lookup->size() == 2) {
                        return is_ancestor;
                    }
                }
                stk.emplace_back(2, node, parent, is_ancestor, node->children.size() - 1);
            } else {
                if (i < 0) {
                    continue;
                }
                stk.emplace_back(2, node, parent, is_ancestor, i - 1);
                stk.emplace_back(1, node->children[i], node, is_ancestor || node == p, -1);
            }
        }
        assert(false);
        return false;
    }
};

// Time:  O(n)
// Space: O(h)
// one pass solution with recursion
class Solution_Recu {
public:
    Node* moveSubTree(Node* root, Node* p, Node* q) {
        unordered_map<Node *, Node *> lookup;
        const auto& [_, is_ancestor] = find_parents(root, nullptr, p, q, false, &lookup);
        if (lookup.count(p) && lookup[p] == q) {
            return root;
        }
        q->children.emplace_back(p);
        if (!is_ancestor) {
            lookup[p]->children.erase(find(begin(lookup[p]->children), end(lookup[p]->children), p));
        } else {
            lookup[q]->children.erase(find(begin(lookup[q]->children), end(lookup[q]->children), q));
            if (p == root) {
                root = q;
            } else {
                *find(begin(lookup[p]->children), end(lookup[p]->children), p) = q;
            }
        }
        return root;
    }

private:
    pair<bool, bool> find_parents(Node *node, Node *parent, Node *p, Node *q,
                                  bool is_ancestor,
                                  unordered_map<Node *, Node *> *lookup) {
        if (node == p || node == q) {
            (*lookup)[node] = parent;
            if (lookup->size() == 2) {
                return {true, is_ancestor};
            }
        }
        for (const auto& child : node->children) {
            const auto& [found, result] = find_parents(child, node, p, q, is_ancestor || node == p, lookup);
            if (found) {
                return {true, result};
            }
        }
        return {false, false};
    }
};

// Time:  O(n)
// Space: O(h)
// two pass solution without recursion
class Solution2 {
public:
    Node* moveSubTree(Node* root, Node* p, Node* q) {
        unordered_map<Node *, Node *> lookup;
        iter_find_parents(root, nullptr, p, q, &lookup);
        if (lookup.count(p) && lookup[p] == q) {
            return root;
        }
        q->children.emplace_back(p);
        if (!iter_is_ancestor(p, q)) {
            lookup[p]->children.erase(find(begin(lookup[p]->children), end(lookup[p]->children), p));
        } else {
            lookup[q]->children.erase(find(begin(lookup[q]->children), end(lookup[q]->children), q));
            if (p == root) {
                root = q;
            } else {
                *find(begin(lookup[p]->children), end(lookup[p]->children), p) = q;
            }
        }
        return root;
    }

private:
    void iter_find_parents(Node *node, Node *parent, Node *p, Node *q,
                           unordered_map<Node *, Node *> *lookup) {
        vector<tuple<int, Node *, Node *, int>> stk = {tuple(1, node, parent, -1)};
        while (!stk.empty()) {
            const auto [step, node, parent, i] = stk.back(); stk.pop_back();
            if (step == 1) {
                if (node == p || node == q) {
                    (*lookup)[node] = parent;
                    if (lookup->size() == 2) {
                        return;
                    }
                }
                stk.emplace_back(2, node, parent, node->children.size() - 1);
            } else {
                if (i < 0) {
                    continue;
                }
                stk.emplace_back(2, node, parent, i - 1);
                stk.emplace_back(1, node->children[i], node, -1);
            }
        }
    }

    bool iter_is_ancestor(Node *node, Node *q) {
        vector<tuple<int, Node *, int>> stk = {tuple(1, node, -1)};
        while (!stk.empty()) {
            const auto [step, node, i] = stk.back(); stk.pop_back();
            if (step == 1) {
                stk.emplace_back(2, node, node->children.size() - 1);
            } else {
                if (i < 0) {
                    continue;
                }
                if (node->children[i] == q) {
                    return true;
                }
                stk.emplace_back(2, node, i - 1);
                stk.emplace_back(1, node->children[i], -1);
            }
        }
        return false;
    }
};

// Time:  O(n)
// Space: O(h)
// two pass solution with recursion
class Solution2_Recu {
public:
    Node* moveSubTree(Node* root, Node* p, Node* q) {
        unordered_map<Node *, Node *> lookup;
        find_parents(root, nullptr, p, q, &lookup);
        if (lookup.count(p) && lookup[p] == q) {
            return root;
        }
        q->children.emplace_back(p);
        if (!is_ancestor(p, q)) {
            lookup[p]->children.erase(find(begin(lookup[p]->children), end(lookup[p]->children), p));
        } else {
            lookup[q]->children.erase(find(begin(lookup[q]->children), end(lookup[q]->children), q));
            if (p == root) {
                root = q;
            } else {
                *find(begin(lookup[p]->children), end(lookup[p]->children), p) = q;
            }
        }
        return root;
    }

private:
    bool find_parents(Node *node, Node *parent, Node *p, Node *q, unordered_map<Node *, Node *> *lookup) {
        if (node == p || node == q) {
            (*lookup)[node] = parent;
            if (lookup->size() == 2) {
                return true;
            }
        }
        for (const auto& child : node->children) {
            if (find_parents(child, node, p, q, lookup)) {
                return true;
            }
        }
        return false;
    }

    bool is_ancestor(Node *node, Node *q) {
        for (const auto& child : node->children) {
            if (child == q || is_ancestor(child, q)) {
                return true;
            }
        }
        return false;
    }
};

// Time:  O(logn/logm), n is numBottles, m is numExchange
// Space: O(1)

class Solution {
public:
    int numWaterBottles(int numBottles, int numExchange) {
        int result = numBottles;
        while (numBottles >= numExchange) {
            result += numBottles / numExchange;
            numBottles = numBottles / numExchange + numBottles % numExchange;
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(h)

class Solution {
public:
    vector<int> countSubTrees(int n, vector<vector<int>>& edges, string labels) {
        vector<vector<int>> adj(n);
        for (const auto& edge : edges) {
            adj[edge[0]].emplace_back(edge[1]);
            adj[edge[1]].emplace_back(edge[0]);
        }
        vector<int> result(n);
        iter_dfs(labels, adj, 0, -1, &result);
        return result;
    }

private:
    void iter_dfs(
        const string& labels,
        const vector<vector<int>>& adj,
        int node, int parent, vector<int> *result) {
        using RET = vector<int>;
        RET ret(26);
        vector<tuple<int, int, int, int, shared_ptr<RET>, RET *>> stk = {{1, node, -1, -1, nullptr, &ret}};
        while (!stk.empty()) {
            const auto [step, node, parent, i, ret2, ret] = stk.back(); stk.pop_back();
            if (step == 1) {
                stk.emplace_back(4, node, -1, -1, nullptr, ret);
                stk.emplace_back(2, node, parent, adj[node].size() - 1, nullptr, ret);
            } else if (step == 2) {
                if (i < 0 || adj[node][i] == parent) {
                    continue;
                }
                const auto& ret2 = make_shared<vector<int>>(26);
                stk.emplace_back(2, node, parent, i - 1, nullptr, ret);
                stk.emplace_back(3, -1, -1, -1, ret2, ret);
                stk.emplace_back(1, adj[node][i], node, -1, nullptr, ret2.get());
            } else if (step == 3) {
                for (int k = 0; k < ret2->size(); ++k) {
                    (*ret)[k] += (*ret2)[k];
                }
            } else {
                (*result)[node] = ++(*ret)[labels[node] - 'a'];
            }
        }
    }
};

// Time:  O(n)
// Space: O(h)
class Solution_Recu {
public:
    vector<int> countSubTrees(int n, vector<vector<int>>& edges, string labels) {
        vector<vector<int>> adj(n);
        for (const auto& edge : edges) {
            adj[edge[0]].emplace_back(edge[1]);
            adj[edge[1]].emplace_back(edge[0]);
        }
        vector<int> result(n);
        dfs(labels, adj, 0, -1, &result);
        return result;
    }

private:
    vector<int> dfs(
        const string& labels,
        const vector<vector<int>>& adj,
        int node, int parent, vector<int> *result) {
        vector<int> count(26);
        for (const auto& child : adj[node]) {
            if (child == parent) {
                continue;
            }
            const auto& new_count = dfs(labels, adj, child, node, result);
            for (int k = 0; k < new_count.size(); ++k) {
                count[k] += new_count[k];
            }
        }
        (*result)[node] = ++count[labels[node] - 'a'];
        return count;
    }
};

// Time:  O(n)
// space: O(1)

class Solution {
public:
    vector<string> maxNumOfSubstrings(string s) {
        vector<int> first(26, numeric_limits<int>::max());
        vector<int> last(26, numeric_limits<int>::min());
        for (int i = 0; i < s.length(); ++i) {
            first[s[i] - 'a'] = min(first[s[i] - 'a'], i);
            last[s[i] - 'a'] = max(last[s[i] - 'a'], i);
        }
        vector<string> result(1);
        int right = numeric_limits<int>::max();
        for (int left = 0; left < s.length(); ++left) {
            if (left != first[s[left] - 'a']) {
                continue;
            }
            int new_right = findRightFromLeft(s, first, last, left);
            if (new_right == -1) {
                continue;
            }
            if (left > right) {
                result.emplace_back();     
            }
            right = new_right;
            result.back() = s.substr(left, right - left + 1);
        }
        return result;
    }

private:
    int findRightFromLeft(const string &s,
                          const vector<int>& first,
                          const vector<int>& last,
                          int left) {
        int right = last[s[left] - 'a'];
        for (auto i = left; i <= right; ++i) {
            if (first[s[i] - 'a'] < left) {
                return -1;
            }
            right = max(right, last[s[i] - 'a']);
        }
        return right;
    }
};

// Time:  O(n)
// Space: O(1)
class Solution2 {
public:
    vector<string> maxNumOfSubstrings(string s) {
        vector<int> first(26, numeric_limits<int>::max());
        vector<int> last(26, numeric_limits<int>::min());
        for (int i = 0; i < s.length(); ++i) {
            first[s[i] - 'a'] = min(first[s[i] - 'a'], i);
            last[s[i] - 'a'] = max(last[s[i] - 'a'], i);
        }
        vector<pair<int, int>> intervals;
        for (int c = 0; c < first.size(); ++c) {
            if (first[c] == numeric_limits<int>::max()) {
                continue;
            }
            int left = first[c], right = findRightFromLeft(s, first, last, first[c]);
            if (right != -1) {
                intervals.emplace_back(right, left);
            }
        }
        sort(begin(intervals), end(intervals));  // Time: O(26log26)
        vector<string> result;
        int prev = -1;
        for (const auto& [right, left] : intervals) {
            if (left <= prev) {
                continue;
            }
            result.emplace_back(s.substr(left, right - left + 1));
            prev = right;
        }
        return result;
    }

private:
    int findRightFromLeft(const string &s,
                          const vector<int>& first,
                          const vector<int>& last,
                          int left) {
        int right = last[s[left] - 'a'];
        for (auto i = left; i <= right; ++i) {
            if (first[s[i] - 'a'] < left) {
                return -1;
            }
            right = max(right, last[s[i] - 'a']);
        }
        return right;
    }
};

// Time:  O(nlogm), m is the max value of arr
// Space: O(logm)

class Solution {
public:
    int closestToTarget(std::vector<int>& arr, int target) {
        static const int LOGM = 20;
        BitCount count(LOGM);
        int result = numeric_limits<int>::max();
        for (int left = 0, right = 0; right < arr.size(); ++right) {
            count += arr[right];
            while (left <= right) {
                const auto& f = count.bitAnd();
                result = min(result, abs(f - target));
                if (f >= target) {
                    break;
                }
                count -= arr[left++];
            }
        }
        return result;
    }

private:
    class BitCount {
    public:
        BitCount(int n)
          : l_(0)
          , n_(n)
          , count_(n) {

        }

        int bitAnd() const {
            int num = 0;
            for (int i = 0; i < n_; ++i) {
                if (count_[i] == l_) {
                    num |= 1 << i;
                }
            }
            return num;
        }

        void operator+=(int num) {
            ++l_;
            for (int i = 0; i < n_; ++i) {
                if (num & (1 << i)) {
                    ++count_[i];
                }
            }
        }

        void operator-=(int num) {
            --l_;
            for (int i = 0; i < n_; ++i) {
                if (num & (1 << i)) {
                    --count_[i];
                }
            }
        }

    private:
        int l_;
        int n_;
        vector<int> count_;
    };
};

// Time:  O(nlogm), m is the max value of arr
// Space: O(logm)
class Solution2 {
public:
    int closestToTarget(vector<int>& arr, int target) {
        int result = numeric_limits<int>::max();
        unordered_set<int> dp;  // at most O(logm) dp states
        for (const auto& x : arr) {
            unordered_set<int> new_dp = {x};
            for (const auto& f: dp) {
                new_dp.emplace(f & x);
            }
            for (const auto& f : new_dp) {
                result = min(result, abs(f - target));
            }
            dp = move(new_dp);
        }
        return result;
    }
};

