// Space: O(1)

class Solution {
public:
    int maxSum(vector<int>& nums1, vector<int>& nums2) {
        static const int MOD = 1e9 + 7;
        uint64_t result = 0, sum1 = 0, sum2 = 0;
        for (int i = 0, j = 0; i != nums1.size() || j != nums2.size();) {
            if (i != nums1.size() && (j == nums2.size() || nums1[i] < nums2[j])) {
                sum1 += nums1[i];
                ++i;
            } else if (j != nums2.size() && (i == nums1.size() || nums1[i] > nums2[j])) {
                sum2 += nums2[j];
                ++j;
            } else {
                result = (result + (max(sum1, sum2) + nums1[i])) % MOD;
                sum1 = sum2 = 0;
                ++i, ++j;
            }
        }
        return (result + max(sum1, sum2)) % MOD;
    }
};

// Time:  O(n), n queries
// Space: O(1)

class Solution {
public:
    int guessMajority(ArrayReader &reader) {
        int count_a = 1, count_b = 0, idx_b = -1;
        const auto& value_0_1_2_3 = reader.query(0, 1, 2, 3);
        int value_0_1_2_i = -1;
        for (int i = reader.length() - 1; i >= 4; --i) {
            value_0_1_2_i = reader.query(0, 1, 2, i);
            if (value_0_1_2_i == value_0_1_2_3) {  // nums[i] == nums[3]
                ++count_a;
            } else {
                ++count_b;
                idx_b = i;
            }
        }
        const auto& value_0_1_2_4 = value_0_1_2_i;
        for (int i = 0; i < 3; ++i) {
            vector<int> a_b;
            for (int j = 0; j < 3; ++j) {
                if (j == i) {
                    continue;
                }
                a_b.emplace_back(j);
            }
            const auto& value_a_b_3_4 = reader.query(a_b[0], a_b[1], 3, 4);
            if (value_a_b_3_4 == value_0_1_2_4) {  // nums[i] == nums[3]
                ++count_a;
            } else {
                ++count_b;
                idx_b = i;
            }
        }
        if (count_a == count_b) {
            return -1;
        }
        return count_a > count_b ? 3 : idx_b;
    }
};

// Time:  O(logn)
// Space: O(1)

class Solution {
public:
    int findKthPositive(vector<int>& arr, int k) {
        int left = 0, right = arr.size() - 1;
        while (left <= right) {
            const auto& mid = left + (right - left) / 2;
            if (!check(arr, k, mid)) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return right + 1 + k;  // right >= 0 ? arr[right] + (k - (arr[right] - (right + 1))) : k;
    }

private:
    bool check(const vector<int>& arr, int k, int x) {
        return arr[x] - (x + 1) < k;
    }
};

