// Time:  O(n^2)
// Space: O(n^2)

static vector<vector<int>> dp;

class Solution {
public:
    int numOfWays(vector<int>& nums) {
        static const int MAX_N = 1000;
        if (dp.empty()) {
            dp = vector<vector<int>>(MAX_N, vector<int>(MAX_N));
            for (int i = 0; i < dp.size(); ++i) {
                dp[i][0] = 1;
                for (int j = 1; j <= i; ++j) {
                    dp[i][j] = (dp[i - 1][j - 1] + dp[i - 1][j]) % MOD;
                }
            }
        }

        return ((iter_dfs(nums) - 1) % MOD + MOD) % MOD;
    }

private:
    int iter_dfs(const vector<int>& nums) {
        using RET = int;
        RET result = 0;
        vector<tuple<int, shared_ptr<vector<int>>, shared_ptr<RET>, shared_ptr<RET>, RET *>> stk;
        stk.emplace_back(1, make_shared<vector<int>>(cbegin(nums), cend(nums)), nullptr, nullptr, &result);
        while (!stk.empty()) {
            auto [step, nums, ret1, ret2, ret] = stk.back(); stk.pop_back();
            if (step == 1) {
                if (nums->size() <= 2) {
                    *ret = 1;
                    continue;
                }
                auto left = make_shared<vector<int>>(), right = make_shared<vector<int>>();
                for (int i = 1; i < nums->size(); ++i) {
                    if ((*nums)[i] < (*nums)[0]) {
                        left->emplace_back((*nums)[i]);
                    } else {
                        right->emplace_back((*nums)[i]);
                    }
                }
                auto ret1 = make_shared<RET>(), ret2 = make_shared<RET>();
                *ret = dp[left->size() + right->size()][left->size()];
                stk.emplace_back(2, nullptr, ret1, ret2, ret);
                stk.emplace_back(1, right, nullptr, nullptr, ret2.get());
                stk.emplace_back(1, left, nullptr, nullptr, ret1.get());
            } else if (step == 2) {
                *ret = int64_t(*ret) * (*ret1) % MOD;
                *ret = int64_t(*ret) * (*ret2) % MOD;
            }
        }
        return result;
    }

    static const int MOD = 1e9 + 7;
};


// Time:  O(n^2)
// Space: O(n^2)
class Solution2 {
public:
    int numOfWays(vector<int>& nums) {
        static const int MAX_N = 1000;
        if (dp.empty()) {
            dp = vector<vector<int>>(MAX_N, vector<int>(MAX_N));
            for (int i = 0; i < dp.size(); ++i) {
                dp[i][0] = 1;
                for (int j = 1; j <= i; ++j) {
                    dp[i][j] = (dp[i - 1][j - 1] + dp[i - 1][j]) % MOD;
                }
            }
        }

        return ((dfs(nums) - 1) % MOD + MOD) % MOD;
    }

private:
    int dfs(const vector<int>& nums) {
        if (nums.size() <= 2) {
            return 1;
        }

        vector<int> left, right;
        for (int i = 1; i < nums.size(); ++i) {
            if (nums[i] < nums[0]) {
                left.emplace_back(nums[i]);
            } else {
                right.emplace_back(nums[i]);
            }
        }
        int64_t result = dp[left.size() + right.size()][left.size()];
        result = result * dfs(left) % MOD;
        result = result * dfs(right) % MOD;
        return result;
    }

    static const int MOD = 1e9 + 7;
};

// Time:  ctor: O(n)
//        dot_product: O(min(n, m))
// Space: O(n)

class SparseVector {
public:
    SparseVector(vector<int> &nums) {
        for (int i = 0; i < nums.size(); ++i) {
            if (nums[i]) {
                lookup_[i] = nums[i];
            }
        }
    }

    int dotProduct(SparseVector& vec) {
        auto a = this, b = &vec;
        if (a->lookup_.size() > b->lookup_.size()) {
            swap(a, b);
        }
        int result = 0;
        for (const auto& [i, v] : a->lookup_) {
            if (b->lookup_.count(i)) {
                result += v * b->lookup_[i];
            }
        }
        return result;
    }

private:
    unordered_map<int, int> lookup_;
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int diagonalSum(vector<vector<int>>& mat) {
        const int n = mat.size();
        int result = 0;
        for (int i = 0; i < n; ++i) {
            result += mat[i][i] + mat[n - 1 - i][i];
        }
        if (n % 2) {
            result -= mat[n / 2][n / 2];
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int numWays(string s) {
        static const int MOD = 1e9 + 7;
        int ones = count_if(cbegin(s), cend(s),
                            [](const auto& x) {
                                return x == '1';
                            });
        if (ones % 3) {
            return 0;
        }
        ones /= 3;
        if (ones == 0) {
            return static_cast<int64_t>(s.length() - 1) * (s.length() - 2) / 2 % MOD;
        }
        int count = 0, left = 0, right = 0;
        for (const auto& c : s) {
            if (c == '1') {
                ++count;
            }
            if (count == ones) {
                ++left;
            } else if (count == 2 * ones) {
                ++right;
            }
        }
        return static_cast<int64_t>(left) * right % MOD;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int findLengthOfShortestSubarray(vector<int>& arr) {
        int j;
        for (j = arr.size() - 1; j >= 1; --j) {
            if (arr[j - 1] > arr[j]) {
                break;
            }
        }
        if (j == 0) {
            return 0;
        }
        int result = j;
        for (int i = 0; i < arr.size(); ++i) {
            if (i && arr[i - 1] > arr[i]) {
                break;
            }
            while (j < arr.size() && arr[i] > arr[j]) {
                ++j;
            }
            result = min(result, (j - i + 1) - 2);
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(1)
class Solution2 {
public:
    int findLengthOfShortestSubarray(vector<int>& arr) {
        int result = 0;
        for (int i = 1; i < arr.size(); ++i) {
            if (arr[i - 1] <= arr[i]) {
                continue;
            }
            int j = arr.size() - 1;
            while (j > i && (j == arr.size() - 1 || arr[j] <= arr[j + 1]) && arr[i - 1] <= arr[j]) {
                --j;
            }
            result = j - i + 1;
            break;
        }
        for (int j = arr.size() - 2; j >= 0; --j) {
            if (arr[j] <= arr[j + 1]) {
                continue;
            }
            int i = 0;
            while (i < j && (i == 0 || arr[i - 1] <= arr[i]) && arr[i] <= arr[j + 1]) {
                ++i;
            }
            result = min(result, j - i + 1);
            break;
        }
        return result;
    }
};

// Time:  O(nlogn + n * f)
// Space: O(n * f)

class Solution {
public:
    int countRoutes(vector<int>& locations, int start, int finish, int fuel) {
        static const int MOD = 1e9 + 7;

        int s = locations[start];
        int f = locations[finish];
        sort(begin(locations), end(locations));
        start = distance(cbegin(locations), lower_bound(cbegin(locations), cend(locations), s));
        finish = distance(cbegin(locations), lower_bound(cbegin(locations), cend(locations), f));

        vector<vector<int>> left(locations.size(), vector<int>(fuel + 1));  // left[i][f], last move is toward left to location i by f fuel
        vector<vector<int>> right(locations.size(), vector<int>(fuel + 1));  // right[i][f], last move is toward right to location i by f fuel
        for (int f = 1; f <= fuel; ++f) {
            for (int j = 0; j < locations.size() - 1; ++j) {
                int d = locations[j + 1] - locations[j];
                if (f > d) {
                    // left[j][f] = right[j+1][f-d(j, j+1)] + 2*right[j+2][f-d(j, j+2)] + ... + 2^(k-1)*right[j+k][f-d(j, j+k)]
                    // => left[j+1][f] = (ight[j+2][f-d(j+1, j+2)] + 2*right[j+3][f-d(j+1, j+3)] + ... + 2^(k-2)*right[j+1+k-1][f-d(j+1, j+1+k-1)]
                    // => left[j+1][f-d(j, j+1)] = right[j+2][f-d(j, j+2)] + 2*right[j+3][f-d(j, j+3)] + ... + 2^(k-2)*right[j+k][f-d(j, j+k)]
                    // => left[j][f] = right[j+1][f-d(j, j+1)] + 2*left[j+1][f-d(j, j+1)]
                    left[j][f] = (right[j + 1][f - d] + 2 * left[j + 1][f - d] % MOD) % MOD;
                } else if (f == d) {
                    left[j][f] = int(j + 1 == start);
                }
            }
            for (int j = 1; j < locations.size(); ++j) {
                int d = locations[j] - locations[j - 1];
                if (f > d) {
                    // right[j][f] = left[j-1][f-d(j, j-1)] + 2*left[j-2][f-d(j, j-2)] + ... + 2^(k-1)*left[j-k][f-d(j, j-k)]
                    // => right[j-1][f] = left[j-2][f-d(j-1, j-2)] + 2*left[j-3][f-d(j-1, j-3)] + ... + 2^(k-2)*left[j-1-k+1][f-d(j-1, j-1-k+1)]
                    // => right[j-1][f-d(j, j-1)] = left[j-2][f-d(j, j-2)] + 2*left[j-3][f-d(j, j-3)] + ... + 2^(k-2)*left[j-k][f-d(j, j-k)]
                    // => right[j][f] = left[j-1][f-d(j, j-1)] + 2*right[j-1][f-d(j, j-1)]
                    right[j][f] = (left[j - 1][f - d] + 2 * right[j - 1][f - d] % MOD) % MOD;
                } else if (f == d) {
                    right[j][f] = int(j - 1 == start);
                }
            }
        }
        int result = int(start == finish);
        for (int f = 1; f <= fuel; ++f) {
            result = ((result + left[finish][f]) % MOD + right[finish][f]) % MOD;
        }
        return result;
    }
};

// Time:  O(n^2 * f)
// Space: O(n * f)
class Solution2 {
public:
    int countRoutes(vector<int>& locations, int start, int finish, int fuel) {
        static const int MOD = 1e9 + 7;

        vector<vector<int>> dp(locations.size(), vector<int>(fuel + 1));
        dp[start][0] = 1;
        for (int f = 1; f <= fuel; ++f) {
            for (int i = 0; i < locations.size(); ++i) {
                for (int j = 0; j < locations.size(); ++j) {
                    if (i == j) {
                        continue;
                    }
                    int d = abs(locations[i] - locations[j]);
                    if (f - d < 0) {
                        continue;
                    }
                    dp[i][f] = (static_cast<int64_t>(dp[i][f]) + dp[j][f - d]) % MOD;
                }
            }
        }
        return accumulate(cbegin(dp[finish]), cend(dp[finish]), 0LL,
                          [&](const int64_t a, const int b) {
                              return (a + b) % MOD;
                          });
    }
};

