// Time:  O(m * n)
// Space: O(m + n)

class Solution {
public:
    int numTriplets(vector<int>& nums1, vector<int>& nums2) {
        int result = 0;
        for (const auto& n : nums1) {
            result += twoProduct(nums2, static_cast<int64_t>(n) * n);
        }
        for (const auto& n : nums2) {
            result += twoProduct(nums1, static_cast<int64_t>(n) * n);
        }
        return result;
    }

private:
    int twoProduct(const vector<int>& nums, int64_t i) {
        unordered_map<int, int> lookup;
        int count = 0;
        for (const auto& num : nums) {
            if (i % num) {
                continue;
            }
            count += lookup[i / num];
            ++lookup[num];
        }
        return count;
    }  
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int minCost(string s, vector<int>& cost) {
        int result = 0, accu = 0, max_cost = 0;
        for (int i = 0; i < s.length(); ++i) {
            if (i && s[i] != s[i - 1]) {
                result += accu - max_cost;
                accu = max_cost = 0;
            }
            accu += cost[i];
            max_cost = max(max_cost, cost[i]);
        }
        result += accu - max_cost;
        return result;
    }
};

// Time:  O(n + m * α(n)) ~= O(n + m)
// Space: O(n)

class Solution {
public:
    int maxNumEdgesToRemove(int n, vector<vector<int>>& edges) {
        int result = 0;
        UnionFind union_find_a(n), union_find_b(n);
        for (const auto& edge : edges) {
            int t = edge[0], i = edge[1], j = edge[2];
            if (t != 3) {
                continue;
            }
            bool a = union_find_a.union_set(i - 1, j - 1);
            bool b = union_find_b.union_set(i - 1, j - 1);
            if (!a && !b) {
                ++result;
            }
        }
        for (const auto& edge : edges) {
            int t = edge[0], i = edge[1], j = edge[2];
            if (t == 1) {
                if (!union_find_a.union_set(i - 1, j - 1)) {
                    ++result;
                }
            } else if (t == 2) {
                if (!union_find_b.union_set(i - 1, j - 1)) {
                    ++result;
                }
            }
        }
        return union_find_a.size() == 1 && union_find_b.size() == 1 ? result : -1;
    }

private:
    class UnionFind {
    public:
        UnionFind(const int n) : set_(n), size_(n) {
            iota(set_.begin(), set_.end(), 0);
        }

        int find_set(const int x) {
           if (set_[x] != x) {
               set_[x] = find_set(set_[x]);  // Path compression.
           }
           return set_[x];
        }

        bool union_set(const int x, const int y) {
            int x_root = find_set(x), y_root = find_set(y);
            if (x_root == y_root) {
                return false;
            }
            set_[max(x_root, y_root)] = min(x_root, y_root);
            --size_;
            return true;
        }

        int size() const {
            return size_;
        }

    private:
        vector<int> set_;
        int size_;
    };
};

// Time:  O(nlogn)
// Space: O(1)

class Solution {
public:
    int maxBoxesInWarehouse(vector<int>& boxes, vector<int>& warehouse) {
        sort(rbegin(boxes), rend(boxes));
        int left = 0, right = size(warehouse) - 1;
        for (const auto& h : boxes) {
            if (h <= warehouse[left]) {
                ++left;
            } else if (h <= warehouse[right]) {
                --right;
            }
            if (left > right) {
                break;
            }
        }
        return left + (size(warehouse) - 1 - right);
    }
};

