// Time:  O(n)
// Space: O(w)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    bool isEvenOddTree(TreeNode* root) {
        vector<TreeNode *> q = {root};
        bool is_odd = false;
        while (!empty(q)) {
            vector<TreeNode *> new_q;
            TreeNode *prev = nullptr;
            for (const auto& node : q) {
                if (is_odd) {
                    if (node->val % 2 || (prev && prev->val <= node->val)) {
                        return false;
                    }
                } else {
                    if (node->val % 2 == 0 || (prev && prev->val >= node->val)) {
                        return false;
                    }
                }
                if (node->left) {
                    new_q.emplace_back(node->left);
                }
                if (node->right) {
                    new_q.emplace_back(node->right);
                }
                prev = node;
            }
            q = move(new_q);
            is_odd = !is_odd;
        }
        return true;
    }
};

// Time:  O(nlogn)
// Space: O(n)

class Solution {
public:
    int visiblePoints(vector<vector<int>>& points, int angle, vector<int>& location) {
        static const double PI = atan2(0, -1);

        vector<double> arr;
        int extra = 0;
        for (const auto& p : points) {
            if (p == location) {
                ++extra;
                continue;
            }
            arr.emplace_back(atan2(p[1] - location[1], p[0] - location[0]));
        }
        sort(begin(arr), end(arr));
        const int n = size(arr);
        for (int i = 0; i < n; ++i) {  // make it circular
            arr.emplace_back(arr[i] + 2.0 * PI);
        }
        const double d = 2.0 * PI * (angle / 360.0);
        int result = 0;
        for (int left = 0, right = 0; right < size(arr); ++right) {
            while (arr[right] - arr[left] > d) {
                ++left;
            }
            result = max(result, right - left + 1);
        }
        return result + extra;
    }
};

// Time:  O(logn)
// Space: O(1)

// reference: https://en.wikipedia.org/wiki/Gray_code
class Solution {
public:
    int minimumOneBitOperations(int n) {
        // [observation]
        // n    f(n)
        // 000    0
        // 001    1
        // 011    2
        // 010    3
        // 110    4
        // 111    5
        // 101    6
        // 100    7
        // f(0XX...X) + f(1XX...X) = f(100...0) implies n is a gray code
        // => f(n) is actually the inverse of gray code
        return gray_to_binary(n);
    }

private:
    int gray_to_binary(int n) {
        int result = 0;
        for (; n > 0; n >>= 1) {
            result ^= n;
        }
        return result;
    }
};

// Time:  O(logn)
// Space: O(1)
class Solution2 {
public:
    int minimumOneBitOperations(int n) {
        // [observation1]:
        // f(1) = 1
        // f(10) = 2 * f(1) + 1 = 3
        // f(100) = 2 * f(10) + 1 = 7
        // by mathematical induction
        // => f(2^k) = 2^(k+1)-1
        //
        // [observation2]:
        // n    f(n)
        // 000    0
        // 001    1
        // 011    2
        // 010    3
        // 110    4
        // 111    5
        // 101    6
        // 100    7
        // let pos be an array of positions where the bit is 1 in ascending order:
        // f(0XX...X) + f(1XX...X) = f(100...0)
        // f(1XX...X) = f(100...0) - f(0XX...X)
        //            = (2^(pos[k-1]+1)-1) - f(0XX...X)
        // by mathematical induction
        // => f(n) = (2^(pos[k-1]+1)-1) - (2^(pos[k-2])+1) + ... + (-1)^(k-1) * (2^(pos[0]+1)-1)
        int result = 0;
        for (; n > 0; n &= n - 1) {
            result = -(result + (n ^ (n - 1)));
        }
        return abs(result);
    }
};

// Time:  O(n)
// Space: O(h)

// morris traversal
class Solution {
public:
    bool checkEquivalence(Node* root1, Node* root2) {
        unordered_map<char, int> count;   
        char prev = '+';
        morrisInorderTraversal(root1, bind(&Solution::addCounter, this,
                                           &count, &prev, 1, placeholders::_1));
        prev = '+';
        morrisInorderTraversal(root2, bind(&Solution::addCounter, this,
                                           &count, &prev, -1, placeholders::_1));
        return all_of(cbegin(count), cend(count),
                      [](const auto& kvp) {
                          return kvp.second == 0;
                      });
    }

private:
    void morrisInorderTraversal(Node *root, const function<void(char)>& cb) {
        auto curr = root;
        while (curr) {
            if (!curr->left) {
                cb(curr->val);
                curr = curr->right;
            } else {
                auto node = curr->left;
                while (node->right && node->right != curr) {
                    node = node->right;
                }
                if (!node->right) {
                    node->right = curr;
                    curr = curr->left;
                } else {
                    cb(curr->val);
                    node->right = nullptr;
                    curr = curr->right;
                }
            }
        }
    }

    void addCounter(unordered_map<char, int> *count, char *prev, int d, char val) {
        if (isalpha(val)) {
            (*count)[val] += (*prev == '+') ? d : -d;
        }
        *prev = val;
    }
};

// Time:  O(n)
// Space: O(h)
class Solution2 {
public:
    bool checkEquivalence(Node* root1, Node* root2) {
        unordered_map<char, int> count;     
        char prev = '+';
        inorderTraversal(root1, bind(&Solution2::addCounter, this,
                                     &count, &prev, 1, placeholders::_1));
        prev = '+';
        inorderTraversal(root2, bind(&Solution2::addCounter, this,
                                     &count, &prev, -1, placeholders::_1));
        return all_of(cbegin(count), cend(count),
                      [](const auto& kvp) {
                          return kvp.second == 0;
                      });
    }

private:
    void traverseLeft(Node* node, vector<Node *> *stk) {
        for (; node; node = node->left) {
            stk->emplace_back(node);
        }
    }

    void inorderTraversal(Node *root, const function<void(char)>& cb) {
        vector<Node *> stk;
        char prev = '+';
        traverseLeft(root, &stk);
        while (!empty(stk)) {
            auto curr = move(stk.back()); stk.pop_back();
            cb(curr->val);
            traverseLeft(curr->right, &stk);
        }
    }

    void addCounter(unordered_map<char, int> *count, char *prev, int d, char val) {
        if (isalpha(val)) {
            (*count)[val] += (*prev == '+') ? d : -d;
        }
        *prev = val;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int maxDepth(string s) {
        int result = 0, curr = 0;
        for (const auto& c : s) {
            if (c == '(') {
                result = max(result, ++curr);
            } else if (c == ')') {
                --curr;
            }
        }
        return result;
    }
};

// Time:  O(m + n + k^2), k is the number of values greater or equal to top2
// Space: O(m + n)

class Solution {
public:
    int maximalNetworkRank(int n, vector<vector<int>>& roads) {
        vector<int> degree(n);
        unordered_map<int, unordered_set<int>> adj;
        for (const auto& road : roads) {
            ++degree[road[0]];
            ++degree[road[1]];
            adj[road[0]].emplace(road[1]);
            adj[road[1]].emplace(road[0]);
        }
        vector<int> sorted_idx(n);
        iota(begin(sorted_idx), end(sorted_idx), 0);
        sorted_idx = counting_sort(sorted_idx,
                                   [&degree](const auto& x) {
                                       return degree[x];
                                   },
                                   true);
        int m = 2;
        for (; m < n; ++m) {
            if (degree[sorted_idx[m]] != degree[sorted_idx[1]]) {
                break;
            }
        }
        int result = degree[sorted_idx[0]] + degree[sorted_idx[1]] - 1;
        for (int i = 0; i < m - 1; ++i) {
            for (int j = i + 1; j < m; ++j) {
                if (degree[sorted_idx[i]] + degree[sorted_idx[j]] - int(adj.count(sorted_idx[i]) && adj[sorted_idx[i]].count(sorted_idx[j])) > result) {
                    return degree[sorted_idx[i]] + degree[sorted_idx[j]] - int(adj.count(sorted_idx[i]) && adj[sorted_idx[i]].count(sorted_idx[j]));
                }
            }
        }
        return result;
    }

 private:
    vector<int> counting_sort(const vector<int>& arr, const function<int(int)>& key, bool is_reverse) {
        static const int MAX_N = 100;
        static const int MAX_NUM = MAX_N - 1;
        vector<int> count(MAX_NUM + 1);
        for (const auto& x : arr) {
            ++count[key(x)];
        }
        for (int i = 1; i < size(count); ++i) {
            count[i] += count[i - 1];
        }
        vector<int> result(size(arr));
        if (!is_reverse) {
            for (int i = size(arr) - 1; i >= 0; --i) {  // stable sort
                result[--count[key(arr[i])]] = arr[i];
            }
        } else {
            for (const auto& x : arr) {  // stable sort
                result[--count[key(x)]] = x;
            }
            reverse(begin(result), end(result));
        }
        return result;
    }
};

