// Space: O(m + n)
class Solution3 {
public:
    int maximalNetworkRank(int n, vector<vector<int>>& roads) {
        vector<int> degree(n);
        unordered_map<int, unordered_set<int>> adj;
        for (const auto& road : roads) {
            ++degree[road[0]];
            ++degree[road[1]];
            adj[road[0]].emplace(road[1]);
            adj[road[1]].emplace(road[0]);
        }
        int result = 0;
        for (int i = 0; i < n - 1; ++i) {
            for (int j = i + 1; j < n; ++j) {
                result = max(result, degree[i] + degree[j] - int(adj.count(i) && adj[i].count(j)));
            }
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    bool checkPalindromeFormation(string a, string b) {
        return check(a, b) || check(b, a);
    }

private:
    bool isPalindrome(const string &s, int i, int j) {
        for (; i < j; ++i, --j) {
            if (s[i] != s[j]) {
                return false;
            }
        }
        return true;
    }

    bool check(const string &a, const string &b) {
        for (int i = 0, j = size(b) - 1; i < j; ++i, --j) {
            if (a[i] != b[j]) {
                return isPalindrome(a, i, j) || isPalindrome(b, i, j);
            }
        }
        return true;
    }

};

// Time:  O(n^6)
// Space: O(n^3)

class Solution {
public:
    vector<int> countSubgraphsForEachDiameter(int n, vector<vector<int>>& edges) {
        vector<vector<int>> adj(n);
        for (const auto& edge : edges) {
            int u = edge[0] - 1, v = edge[1] - 1;
            adj[u].emplace_back(v);
            adj[v].emplace_back(u);
        }
        vector<int> lookup(n), result(n - 1);
        for (int i = 0; i < n; ++i) {  // Time: sum(O(k^5) for k in [1, n]) = O(n^6)
            vector<vector<vector<int>>> dp(n, vector<vector<int>>(n, vector<int>(n)));
            vector<int> count(n, 1);
            dfs(n, adj, i, -1, lookup, &count, &dp);  // Time: O(k^5), k is the number of the remaining cities
            lookup[i] = 1;
            for (int d = 1; d < n; ++d) {  // for each depth from city i
                for (int max_d = d; max_d < min(2 * d + 1, n); ++max_d) {  // for each max distance
                    result[max_d - 1] += dp[i][d][max_d];
                }
            }
        }
        return result;
    }

private:
    void dfs(int n, const vector<vector<int>>& adj,
             int curr, int parent,
             const vector<int>& lookup,
             vector<int> *count,
             vector<vector<vector<int>>> *dp) {

        for (const auto& child : adj[curr]) {
            if (child == parent || lookup[child]) {
                continue;
            }
            dfs(n, adj, child, curr, lookup, count, dp);
        }
        (*dp)[curr][0][0] = 1;
        for (const auto& child : adj[curr]) {
            if (child == parent || lookup[child]) {
                continue;
            }
            vector<vector<int>> new_dp_curr = (*dp)[curr];
            for (int curr_d = 0; curr_d < (*count)[curr]; ++curr_d) {
                for (int curr_max_d = curr_d; curr_max_d < min(2 * curr_d + 1, (*count)[curr]); ++curr_max_d) {
                    if (!(*dp)[curr][curr_d][curr_max_d]) {  // pruning
                        continue;
                    }
                    for (int child_d = 0; child_d < (*count)[child]; ++child_d) {
                        for (int child_max_d = child_d; child_max_d < min(2 * child_d + 1, (*count)[child]); ++child_max_d) {
                            new_dp_curr[max(curr_d, child_d + 1)][max({curr_max_d, child_max_d, curr_d + child_d + 1})] +=
                                (*dp)[curr][curr_d][curr_max_d] * (*dp)[child][child_d][child_max_d];  // count subtrees with new child
                        }
                    }
                }
            }
            (*count)[curr] += (*count)[child];  // merge new child
            (*dp)[curr] = move(new_dp_curr);
        }
    }
};

// Time:  O(n * 2^n)
// Space: O(n)
class Solution2 {
public:
    vector<int> countSubgraphsForEachDiameter(int n, vector<vector<int>>& edges) {
        vector<vector<int>> adj(n);
        for (const auto& edge : edges) {
            int u = edge[0] - 1, v = edge[1] - 1;
            adj[u].emplace_back(v);
            adj[v].emplace_back(u);
        }
        vector<int> result(n - 1);
        int total = 1 << n;
        for (int mask = 1; mask < total; ++mask) {
            int max_d = maxDistance(n, edges, adj, mask);
            if (max_d - 1 >= 0) {
                ++result[max_d - 1];
            }
        }
        return result;
    }

private:
    int maxDistance(int n,
                    const vector<vector<int>>& edges,
                    const vector<vector<int>>& adj,
                    int mask) {
        const auto& [is_valid, farthest, max_d] = bfs(n, adj, mask, log(mask & -mask) / log(2));
        return is_valid ? get<2>(bfs(n, adj, mask, farthest)) : 0;
    }

    tuple<bool, int, int> bfs(int n, const vector<vector<int>>& adj,
                              int mask, int start) {
        queue<pair<int, int>> q({{start, 0}});
        int lookup = (1 << start);
        int count = __builtin_popcount(mask) - 1, u = -1, d = -1;
        while (!empty(q)) {
            tie(u, d) = move(q.front()); q.pop();
            for (const auto& v : adj[u]) {
                if (!(mask & (1 << v)) || (lookup & (1 << v))) {
                    continue;
                }
                lookup |= (1 << v);
                --count;
                q.emplace(v, d + 1);
            }
        }
        return {count == 0, u, d};
    }
};

// Time:  O(n + logm), n is the length of text, m is the number of fonts
// Space: O(1)

class Solution {
public:
    int maxFont(string text, int w, int h, vector<int>& fonts, FontInfo fontInfo) {
        vector<int> count(26);
        for (const auto& c : text) {
            ++count[c - 'a'];
        }
        int left = 0, right = size(fonts) - 1;
        while (left <= right) {
            const auto& mid = left + (right - left) / 2;
            if (!check(count, w, h, fonts, fontInfo, mid)) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return right >= 0 ? fonts[right] : -1;
    }

private:
    bool check(const vector<int>& count, int w, int h, const vector<int>& fonts, FontInfo& fontInfo, int x) {
        if (fontInfo.getHeight(fonts[x]) > h) {
            return false;
        }
        int width = 0;
        for (int c = 0; c < size(count); ++c) {
            width += count[c] * fontInfo.getWidth(fonts[x], 'a' + c);
            if (width > w) {
                return false;
            }
        }
        return true;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    double trimMean(vector<int>& arr) {
        static const int P = 20;
        const int k = size(arr) / P;
        nth_element(begin(arr), begin(arr) + k - 1, end(arr));
        nth_element(begin(arr) + k, end(arr) - k, end(arr));
        return accumulate(begin(arr) + k, end(arr) - k, 0.0) / (size(arr) - 2 * k);
    }
};

// Time:  O(n^2)
// Space: O(1)

class Solution {
public:
    vector<int> bestCoordinate(vector<vector<int>>& towers, int radius) {
        int min_x = numeric_limits<int>::max();
        int max_x = numeric_limits<int>::min();
        int min_y = numeric_limits<int>::max();
        int max_y = numeric_limits<int>::min();
        for (const auto& tower: towers) {
            min_x = min(min_x, tower[0]);
            max_x = max(max_x, tower[0]);
            min_y = min(min_y, tower[1]);
            max_y = max(max_y, tower[1]);
        }
        int max_quality = 0;
        vector<int> result;
        for (int x = min_x; x <= max_x; ++x) {
            for (int y = min_y; y <= max_y; ++y) {
                int q = 0;
                for (const auto& t : towers) {
                    double d = sqrt((t[0] - x) * (t[0] - x) + (t[1] - y) * (t[1] - y));
                    if (d <= radius) {
                        q += int(t[2] / (1 + d));
                    }
                }
                if (q > max_quality) {
                    max_quality = q;
                    result = {x, y};
                }
            }
        }
        return result;
    }
};

// Time:  O(1), excluding precomputation time
// Space: O(n)

class Solution {
public:
    Solution()
     : fact_(2 * MAX_N - 1 + 1)
     , inv_(2 * MAX_N - 1 + 1)
     , inv_fact_(2 * MAX_N - 1 + 1) {

        fact_[0] = inv_fact_[0] = fact_[1] = inv_fact_[1] = inv_[1] = 1;
        for (int i = 2; i < size(fact_); ++i) {
            fact_[i] = mulmod(fact_[i - 1], i, MOD);
            inv_[i] = mulmod(inv_[MOD % i], MOD - MOD / i, MOD);  // https://cp-algorithms.com/algebra/module-inverse.html
            inv_fact_[i] = mulmod(inv_fact_[i - 1], inv_[i], MOD);
        }
    }

    int numberOfSets(int n, int k) {
        // find k segments with 1+ length and (k+1) spaces with 0+ length s.t. total length is n-1
        // => find k segments with 0+ length and (k+1) spaces with 0+ length s.t. total length is n-k-1
        // => find the number of combinations of 2k+1 variables with total sum n-k-1
        // => H(2k+1, n-k-1)
        // => C((2k+1) + (n-k-1) - 1, n-k-1)
        // => C(n+k-1, n-k-1) = C(n+k-1, 2k)
        return nCr(n + k - 1, 2 * k, MOD);
    }

private:
    int nCr(int n, int k, uint32_t mod) {
        return mulmod(mulmod(fact_[n], inv_fact_[n - k], mod), inv_fact_[k], mod);
    }

    uint32_t addmod(uint32_t a, uint32_t b, uint32_t mod) {  // avoid overflow
        a %= mod, b %= mod;
        if (mod - a <= b) {
            b -= mod;  // relied on unsigned integer overflow in order to give the expected results
        }
        return a + b;
    }

    // reference: https://stackoverflow.com/questions/12168348/ways-to-do-modulo-multiplication-with-primitive-types
    uint32_t mulmod(uint32_t a, uint32_t b, uint32_t mod)  {  // avoid overflow
        a %= mod, b %= mod;
        uint32_t result = 0;
        if (a < b) {
            swap(a, b);
        }
        while (b > 0)  { 
            if (b % 2 == 1) {
                result = addmod(result, a, mod);
            }
            a = addmod(a, a, mod);
            b /= 2; 
        } 
        return result; 
    }

    static const int MOD = 1e9 + 7;
    static const int MAX_N = 1000;
    vector<int> fact_;
    vector<int> inv_;
    vector<int> inv_fact_;
};

// Time:  O(1)
// Space: O(n)

// #define USE_UINT64_T

class Fancy {
public:
    Fancy() : ops_{{1, 0}} {

    }

    void append(int val) {
        arr_.emplace_back(val);
        ops_.emplace_back(ops_.back());
    }

    void addAll(int inc) {
        ops_.back().second = addmod(ops_.back().second, inc, MOD);
    }

    void multAll(int m) {
        ops_.back().first = mulmod(ops_.back().first, m, MOD);
        ops_.back().second = mulmod(ops_.back().second, m, MOD);
    }

    int getIndex(int idx) {
        if (idx >= size(arr_)) {
            return -1;
        }
        const auto& [a1, b1] = ops_[idx];
        const auto& [a2, b2] = ops_.back();
        int a = mulmod(a2, powmod(a1, MOD - 2, MOD), MOD);
        int b = submod(b2, mulmod(a, b1, MOD), MOD);
        return addmod(mulmod(arr_[idx], a, MOD), b, MOD);
    }

private:
    uint32_t addmod(uint32_t a, uint32_t b, uint32_t mod) {  // avoid overflow
        // a %= mod, b %= mod;  // assumed a, b have been mod
        if (mod - a <= b) {
            b -= mod;  // relied on unsigned integer overflow in order to give the expected results
        }
        return a + b;
    }

    uint32_t submod(uint32_t a, uint32_t b, uint32_t mod) {
        // a %= mod, b %= mod;  // assumed a, b have been mod
        return addmod(a, mod - b, mod);
    }

    // reference: https://stackoverflow.com/questions/12168348/ways-to-do-modulo-multiplication-with-primitive-types
    uint32_t mulmod(uint32_t a, uint32_t b, uint32_t mod)  {  // avoid overflow
#ifdef USE_UINT64_T
        return uint64_t(a) * b % mod;  // speed up if we can use uint64_t
#else
        uint32_t result = 0;
        if (a < b) {
            swap(a, b);
        }
        while (b > 0)  { 
            if (b % 2 == 1) {
                result = addmod(result, a, mod);
            }
            a = addmod(a, a, mod);
            b /= 2; 
        } 
        return result;
#endif
    }

    uint32_t powmod(uint32_t a, uint32_t b, uint32_t mod) {
        a %= mod;
        uint32_t result = 1;
        while (b) {
            if (b & 1) {
                result = mulmod(result, a, mod);
            }
            a = mulmod(a, a, mod);
            b >>= 1;
        }
        return result;
    }

    static const int MOD = 1e9 + 7;
    vector<int> arr_;
    vector<pair<int, int>> ops_;
};

