// Time:  O((nlogn + q) * α(n)) ~= O(nlogn + q)
// Space: O(n)

class Solution {
public:
    vector<bool> areConnected(int n, int threshold, vector<vector<int>>& queries) {
        UnionFind union_find(n);
        for (int i = threshold + 1; i <= n; ++i) {
            // https://stackoverflow.com/questions/25905118/finding-big-o-of-the-harmonic-series
            // sum of harmonic series is O(logn)
            for (int j = 2 * i; j <= n; j += i) {
                union_find.union_set(i - 1, j - 1);
            }
        }
        vector<bool> result;
        for (const auto& q : queries) {
            result.emplace_back(union_find.find_set(q[0] - 1) == union_find.find_set(q[1] - 1));
        }
        return result;
    }

private:
    class UnionFind {
    public:
        UnionFind(const int n) : set_(n), rank_(n), count_(n) {
            iota(set_.begin(), set_.end(), 0);
        }

        int find_set(const int x) {
           if (set_[x] != x) {
               set_[x] = find_set(set_[x]);  // Path compression.
           }
           return set_[x];
        }

        bool union_set(const int x, const int y) {
            int x_root = find_set(x), y_root = find_set(y);
            if (x_root == y_root) {
                return false;
            }
            if (rank_[x_root] < rank_[y_root]) {  // Union by rank.
                set_[x_root] = y_root;
            } else if (rank_[x_root] > rank_[y_root]) {
                set_[y_root] = x_root;
            } else {
                set_[y_root] = x_root;
                ++rank_[x_root];
            }
            --count_;
            return true;
        }

        int size() const {
            return count_;
        }

    private:
        vector<int> set_;
        vector<int> rank_;
        int count_;
    };
};

// Time:  O(n)
// Space: O(h)

#define ITER

class Node {
public:
    virtual ~Node () {};
    virtual int evaluate() const = 0;
protected:
};

class NodeIter : public Node {
public:
    NodeIter (int val) : val(val) {};
    NodeIter (char op, NodeIter *left, NodeIter *right) : op(op), left(left), right(right) {};
    virtual ~NodeIter () {};
    virtual int evaluate() const {
        int result = 0;
        vector<tuple<int, NodeIter *, unique_ptr<int>, unique_ptr<int>, int*>> stk;
        stk.emplace_back(1, const_cast<NodeIter *>(this), nullptr, nullptr, &result);
        while (!empty(stk)) {
            const auto [step, node, ret1, ret2, ret] = move(stk.back()); stk.pop_back();
            if (step == 1) {
                if (node->op == 0) {
                    *ret = node->val;
                    continue;
                }
                auto ret1 = make_unique<int>(), ret2 = make_unique<int>();
                auto p1 = ret1.get(), p2 = ret2.get();
                stk.emplace_back(2, node, move(ret1), move(ret2), ret);
                stk.emplace_back(1, node->right, nullptr, nullptr, p2);
                stk.emplace_back(1, node->left, nullptr, nullptr, p1);
            } else if (step == 2) {
                int l = *ret1, r = *ret2;
                *ret = (node->op == '+') ? l + r :
                       (node->op == '-') ? l - r :
                       (node->op == '*') ? l * r :
                       (node->op == '/') ? l / r : 0;
            }
        }
        return result;
    }

public:
    int val;
    char op = 0;
    NodeIter *left = nullptr;
    NodeIter *right = nullptr;
};

class NodeRecu : public Node {
public:
    NodeRecu (int val) : val(val) {};
    NodeRecu (char op, NodeRecu *left, NodeRecu *right) : op(op), left(left), right(right) {};
    virtual ~NodeRecu () {};
    virtual int evaluate() const {
        if (op == 0) {
            return val;
        }
        int l = left->evaluate(), r = right->evaluate();
        return (op == '+') ? l + r :
               (op == '-') ? l - r :
               (op == '*') ? l * r :
               (op == '/') ? l / r : 0;
    }

public:
    int val;
    char op = 0;
    NodeRecu *left = nullptr;
    NodeRecu *right = nullptr;
};

class TreeBuilder {
public:
    Node* buildTree(vector<string>& postfix) {
#ifdef ITER
    using TreeNode = NodeIter;
#else
    using TreeNode = NodeRecu;
#endif
        vector<Node *> stk;
        for (const auto& s : postfix) {
            if (isdigit(s[0])) {
                stk.emplace_back(new TreeNode(stoi(s)));
            } else {
                auto right = dynamic_cast<TreeNode*>(stk.back()); stk.pop_back();
                auto left = dynamic_cast<TreeNode*>(stk.back()); stk.pop_back();
                stk.emplace_back(new TreeNode(s[0], left, right));
            } 
        }
        return stk.back();
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    char slowestKey(vector<int>& releaseTimes, string keysPressed) {
        char result = 'a';
        vector<int> lookup(26);
        for (int i = 0; i < size(keysPressed); ++i) {
            auto c = keysPressed[i];
            lookup[c - 'a'] = max(lookup[keysPressed[i] - 'a'],
                                  releaseTimes[i] - (i > 0 ? releaseTimes[i - 1] : 0));
            if (lookup[c - 'a'] > lookup[result - 'a'] ||
                (lookup[c - 'a'] == lookup[result - 'a'] && c > result)) {
                result = c;
            }
        }
        return result;
    }
};

// Time:  O(n * q)
// Space: O(n)

class Solution {
public:
    vector<bool> checkArithmeticSubarrays(vector<int>& nums, vector<int>& l, vector<int>& r) {
        vector<bool> result(size(l));
        for (int i = 0; i < size(l); ++i) {
            result[i] = isArith(vector<int>(cbegin(nums) + l[i], cbegin(nums) + r[i] + 1));
        }
        return result;
    }

private:
    bool isArith(const vector<int>& nums) {
        unordered_set<int> lookup(cbegin(nums), cend(nums));
        int mn = *min_element(cbegin(nums), cend(nums));
        int mx = *max_element(cbegin(nums), cend(nums));
        if (mx == mn) {
            return true;
        }
        if ((mx - mn) % (size(nums) - 1)) {
            return false;
        }
        int d = (mx - mn) / (size(nums) - 1);
        for (int i = mn; i <= mx; i += d) {
            if (!lookup.count(i)) {
                return false;
            }
        }
        return true;
    }
};

// Time:  O(m * n * log(m * n))
// Space: O(m * n)

// Dijkstra algorithm solution
class Solution {
public:
    int minimumEffortPath(vector<vector<int>>& heights) {
        static const vector<pair<int, int>> directions{{0, 1}, {1, 0},
                                                       {0, -1}, {-1, 0}};

        using T = tuple<int, int, int>;
        vector<vector<int>> dist(size(heights), vector<int>(size(heights[0]), numeric_limits<int>::max()));
        dist[0][0] = 0;
        priority_queue<T, vector<T>, greater<T>> min_heap;
        min_heap.emplace(0, 0, 0);
        vector<vector<int>> lookup(size(heights), vector<int>(size(heights[0])));
        while (!empty(min_heap)) {
            const auto [d, r, c] = min_heap.top(); min_heap.pop();
            if (lookup[r][c]) {
                continue;
            }
            lookup[r][c] = true;
            if (r == size(heights) - 1 && c == size(heights[0]) - 1) {
                return d;
            }
            for (const auto& [dr, dc] : directions) {
                int nr = r + dr, nc = c + dc;
                if (!(0 <= nr && nr < size(heights) &&
                      0 <= nc && nc < size(heights[0]) &&
                      !lookup[nr][nc])) {
                    continue;
                }
                int nd = max(d, abs(heights[nr][nc] - heights[r][c]));
                if (nd < dist[nr][nc]) {
                    dist[nr][nc] = nd;
                    min_heap.emplace(nd, nr, nc);
                }
            }
        }
        return -1;
    }
};

// Time:  O(m * n * log(m * n) + m * n * α(m * n)) = O(m * n * log(m * n))
// Space: O(m * n)
// union find solution
class Solution2 {
public:
    int minimumEffortPath(vector<vector<int>>& heights) {
        vector<tuple<int, int, int>> diffs;
        for (int i = 0; i < size(heights); ++i) {
            for (int j = 0; j < size(heights[0]); ++j) {
                if (i > 0) {
                    diffs.emplace_back(abs(heights[i][j] - heights[i - 1][j]), 
                                       index(size(heights[0]), i - 1, j),
                                       index(size(heights[0]), i, j));
                }
                if (j > 0) {
                    diffs.emplace_back(abs(heights[i][j] - heights[i][j - 1]),
                                       index(size(heights[0]), i, j - 1),
                                       index(size(heights[0]), i, j));
                }
            }
        }
        sort(begin(diffs), end(diffs));
        UnionFind union_find(size(heights) * size(heights[0]));
        for (const auto& [d, i, j] : diffs) {
            if (union_find.union_set(i, j)) {
                if (union_find.find_set(index(size(heights[0]), 0, 0)) ==
                    union_find.find_set(index(size(heights[0]), size(heights) - 1, size(heights[0]) - 1))) {
                    return d;
                }
            }
        }
        return 0;
    }

private:
    class UnionFind {
    public:
        UnionFind(const int n)
         : set_(n)
         , rank_(n)
         , count_(n) {
            iota(set_.begin(), set_.end(), 0);
        }

        int find_set(const int x) {
           if (set_[x] != x) {
               set_[x] = find_set(set_[x]);  // Path compression.
           }
           return set_[x];
        }

        bool union_set(const int x, const int y) {
            int x_root = find_set(x), y_root = find_set(y);
            if (x_root == y_root) {
                return false;
            }
            if (rank_[x_root] < rank_[y_root]) {  // Union by rank.
                set_[x_root] = y_root;
            } else if (rank_[x_root] > rank_[y_root]) {
                set_[y_root] = x_root;
            } else {
                set_[y_root] = x_root;
                ++rank_[x_root];
            }
            --count_;
            return true;
        }

        int size() const {
            return count_;
        }

    private:
        vector<int> set_;
        vector<int> rank_;
        int count_;
    };

    int index(int n, int i, int j) {
        return i * n + j;
    }
};

