// Time:  O(m * n * log(m * n) + m * n * α(m * n)) = O(m * n * log(m * n))
// Space: O(m * n)

class Solution {
public:
    vector<vector<int>> matrixRankTransform(vector<vector<int>>& matrix) {
        map<int, vector<pair<int, int>>> lookup;
        for (int i = 0; i < size(matrix); ++i) {
            for (int j = 0; j < size(matrix[0]); ++j) {
                lookup[matrix[i][j]].emplace_back(i, j);
            }
        }
        vector<int> rank(size(matrix) + size(matrix[0]));
        for (const auto& [x, pairs] : lookup) {
            vector<int> new_rank(rank);
            const auto& cb = [&new_rank](int x, int y, int z) {
                                 new_rank[x] = max(new_rank[y], new_rank[z]);
                             };
            UnionFind union_find(size(matrix) + size(matrix[0]), cb);
            for (const auto& [i, j] : pairs) {
                union_find.union_set(i, j + size(matrix));
            }
            for (const auto& [i, j] : pairs) {
                matrix[i][j] = rank[i] = rank[j + size(matrix)] = new_rank[union_find.find_set(i)] + 1;
            }
        }
        return matrix;
    }

private:
    class UnionFind {
    public:
        UnionFind(const int n, function<void(int, int, int)> cb)
         : set_(n)
         , rank_(n)
         , count_(n)
         , cb_(cb) {
            iota(set_.begin(), set_.end(), 0);
        }

        int find_set(const int x) {
           if (set_[x] != x) {
               set_[x] = find_set(set_[x]);  // Path compression.
           }
           return set_[x];
        }

        bool union_set(const int x, const int y) {
            int x_root = find_set(x), y_root = find_set(y);
            if (x_root == y_root) {
                return false;
            }
            if (rank_[x_root] < rank_[y_root]) {  // Union by rank.
                set_[x_root] = y_root;
                cb_(y_root, x_root, y_root);
            } else if (rank_[x_root] > rank_[y_root]) {
                set_[y_root] = x_root;
                cb_(x_root, x_root, y_root);
            } else {
                set_[y_root] = x_root;
                ++rank_[x_root];
                cb_(x_root, x_root, y_root);
            }
            --count_;
            return true;
        }

        int size() const {
            return count_;
        }

    private:
        vector<int> set_;
        vector<int> rank_;
        int count_;
        function<void(int, int, int)> cb_;
    };
};

// Time:  O(m + n)
// Space: O(1)

class Solution {
public:
    PolyNode* addPoly(PolyNode* poly1, PolyNode* poly2) {
        PolyNode dummy;
        auto curr = &dummy;
        while (poly1 && poly2) {
            if (poly1->power > poly2->power) {
                curr->next = poly1;
                curr = curr->next;
                poly1 = poly1->next;
            } else if (poly1->power < poly2->power) {
                curr->next = poly2;
                curr = curr->next;
                poly2 = poly2->next;
            } else {
                auto coef = poly1->coefficient + poly2->coefficient;
                if (coef) {
                    curr->next = new PolyNode(coef, poly1->power);
                    curr = curr->next;
                }
                poly1 = poly1->next;
                poly2 = poly2->next;
            }
        }
        curr->next = poly1 ? poly1 : poly2;
        return dummy.next;
    }
};

// Time:  O(nlogn)
// Space: O(n)

class Solution {
public:
    vector<int> frequencySort(vector<int>& nums) {
        unordered_map<int, int> count;
        for (const auto& x : nums) {
            ++count[x];
        }
        sort(begin(nums), end(nums),
             [&count](const auto& a, const auto& b) {
                 return count[a] == count[b] ? a > b : count[a] < count[b];
             });
        return nums;
    }
};

// Time:  O(nlogn)
// Space: O(n)

class Solution {
public:
    int maxWidthOfVerticalArea(vector<vector<int>>& points) {
        set<int> sorted_x;
        for (const auto& point : points) {
            sorted_x.emplace(point[0]);
        }
        int result = 0, prev = -1;
        for (const auto x : sorted_x) {
            if (prev != -1) {
                result = max(result, x - prev);
            }
            prev = x;
        }
        return result;
    }
};

// Time:  O(m * n)
// Space: O(1)

class Solution {
public:
    int countSubstrings(string s, string t) {
        int result = 0;
        // for each possible alignment, count the number of substrs that differ by 1 char
        for (int i = 0; i < size(s); ++i) {
            result += count(s, t, i, 0);
        }
        for (int j = 1; j < size(t); ++j) {  // j starts from 1 to avoid duplicated count(0, 0)
            result += count(s, t, 0, j);
        }
        return result;
    }

private:
    int count(const string& s, const string& t, int i, int j) {
        int l = min(size(s) - i, size(t) - j);
        int result = 0, left_cnt = 0, right_cnt = 0;  // left and right consecutive same counts relative to the different char
        for (int k = 0; k < l; ++k) {
            ++right_cnt;
            if (s[i + k] != t[j + k]) {
                left_cnt = right_cnt;
                right_cnt = 0;
                // left_i = i+k-left+1
            }
            result += left_cnt;  // target substrs are [s[left_i+c:i+k+1] for c in xrange(left_cnt)]
        }
        return result;
    }
};

// Time:  O(l * (w + n)), l is the length of a word, w is the number of words, n is the length of target
// Space: O(n)

// optimized from Solution2
class Solution {
public:
    int numWays(vector<string>& words, string target) {
        static const int MOD = 1e9 + 7;

        vector<uint64_t> dp(size(target) + 1);  // use uint64_t to avoid overflow
        dp[0] = 1;
        for (int i = 0; i < size(words[0]); ++i) {
            vector<int> count(26);
            for (const auto& w : words) {
                ++count[w[i] - 'a'];
            }
            for (int j = size(target) - 1; j >= 0; --j) {
                dp[j + 1] += dp[j] * count[target[j] - 'a'] % MOD;
            }
        }
        return dp.back() % MOD;
    }
};

// Time:  O(l * (w + n)), l is the length of a word, w is the number of words, n is the length of target
// Space: O(n)
class Solution2 {
public:
    int numWays(vector<string>& words, string target) {
        static const int MOD = 1e9 + 7;

        // dp[i+1][j+1]: number of ways of target[0..j] using count[0..i].
        vector<vector<uint64_t>> dp(2, vector<uint64_t>(size(target) + 1));  // use uint64_t to avoid overflow
        dp[0][0] = dp[1][0] = 1;
        for (int i = 0; i < size(words[0]); ++i) {
            vector<int> count(26);
            for (const auto& w : words) {
                ++count[w[i] - 'a'];
            }
            for (int j = 0; j < size(target); ++j) {
                dp[(i + 1) % 2][j + 1] = dp[i % 2][j + 1] + dp[i % 2][j] * count[target[j] - 'a'] % MOD;
            }
        }
        return dp[size(words[0]) % 2].back() % MOD;
    }
};

// Time:  O(n)
// Space: O(n)

class Solution {
public:
    bool canFormArray(vector<int>& arr, vector<vector<int>>& pieces) {
        unordered_map<int, int> lookup;
        for (int i = 0; i < size(pieces); ++i) {
            lookup[pieces[i][0]] = i;
        }
        for (int i = 0; i < size(arr);) {
            if (!lookup.count(arr[i])) {
                return false;
            }
            for (const auto& c : pieces[lookup[arr[i]]]) {
                if (i == size(arr) || arr[i] != c) {
                    return false;
                }
                ++i;
            }
        }
        return true;
    }
};

// Time:  O(1)
// Space: O(1)

class Solution {
public:
    int countVowelStrings(int n) {
        return nCr(n + 4, 4);  // H(5, n) = C(n+5-1, n) = C(n+4, 4)
    }

private:
    uint64_t nCr(int n, int r) {  // Time: O(n), Space: O(1)
        if (n - r < r) {
            return nCr(n, n - r);
        }
        uint64_t c = 1;
        for (int k = 1; k <= r; ++k) {
            c *= n - k + 1;
            c /= k;
        }
        return c;
    }
};

// Time:  O(nlogk)
// Space: O(k)

class Solution {
public:
    int furthestBuilding(vector<int>& heights, int bricks, int ladders) {
        priority_queue<int, vector<int>, greater<int>> min_heap;
        for (int i = 0; i < size(heights) - 1; ++i) {
            int diff = heights[i + 1] - heights[i];
            if (diff > 0) {
                min_heap.emplace(diff);
            }
            if (size(min_heap) <= ladders) {  // ladders are reserved for largest diffs
                continue;
            }
            auto h = min_heap.top(); min_heap.pop();
            bricks -= h;  // use bricks if ladders are not enough
            if (bricks < 0) {  // not enough bricks
                return i;
            }
        }
        return size(heights) - 1;
    }
};

// Time:  O((m + n)^2)
// Space: O(1)

class Solution {
public:
    string kthSmallestPath(vector<int>& destination, int k) {
        int r = destination[0], c = destination[1];
        string result;
        while (r + c) {
            int count = nCr(r + (c - 1), r);  // the number of HX..X combinations
            if (k <= count) {  // the kth instruction is one of HX..X combinations, so go right
                --c;
                result.push_back('H');
            } else {  // the kth instruction is one of VX..X combinations, so go down
                k -= count;  // the kth one of XX..X combinations is the (k-count)th one of VX..X combinations
                --r;
                result.push_back('V');
            }
        }
        return result;
    }

private:
    uint64_t nCr(int n, int r) {  // Time: O(n), Space: O(1)
        if (n < r) {
            return 0;
        }
        if (n - r < r) {
            return nCr(n, n - r);
        }
        uint64_t c = 1;
        for (int k = 1; k <= r; ++k) {
            c *= n - k + 1;
            c /= k;
        }
        return c;
    }
};

// Time:  O(n)
// Space: O(h)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
        return iter_dfs(root, p, q);
    }

private:
    TreeNode *iter_dfs(TreeNode* node, TreeNode* p, TreeNode* q) {
        TreeNode *result = nullptr;
        int ret = 0;
        vector<tuple<int, TreeNode *, unique_ptr<int>, unique_ptr<int>, int*>> stk;
        stk.emplace_back(1, node, nullptr,  nullptr, &ret);
        while (!empty(stk)) {
            const auto [step, node, ret1, ret2, ret] = move(stk.back()); stk.pop_back();
            if (step == 1) {
                if (!node) {
                    continue;
                }
                auto ret1 = make_unique<int>(), ret2 = make_unique<int>();
                auto p1 = ret1.get(), p2 = ret2.get();
                stk.emplace_back(2, node, move(ret1), move(ret2), ret);
                stk.emplace_back(1, node->right, nullptr, nullptr, p2);
                stk.emplace_back(1, node->left, nullptr, nullptr, p1);
            } else if (step == 2) {
                auto curr = int(node == p || node == q);
                if (curr + *ret1 + *ret2 == 2 && !result) {
                    result = node;
                }
                *ret = curr + *ret1 + *ret2;
            }
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(h)
class Solution2 {
public:
    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
        TreeNode *result = nullptr;
        dfs(root, p, q, &result);
        return result;
    }

private:
    int dfs(TreeNode* node, TreeNode* p, TreeNode* q, TreeNode** result) {
        if (!node) {
            return 0;
        }
        auto left = dfs(node->left, p, q, result);
        auto right = dfs(node->right, p, q, result);
        auto curr = int(node == p || node == q);
        if (curr + left + right == 2 && !(*result)) {
            *result = node;
        }
        return curr + left + right;
    }
};

// Time:  O(n)
// Space: O(n)

vector<int> nums = {0, 1};
vector<int> dp = {0, 1};
class Solution {
public:
    int getMaximumGenerated(int n) {
        if (n + 1 > size(dp)) {
            for (int i = size(nums); i <= n; ++i) {
                if (i % 2 == 0) {
                    nums.emplace_back(nums[i / 2]);
                } else {
                    nums.emplace_back(nums[i / 2] + nums[i / 2 + 1]);
                }
                dp.emplace_back(max(dp.back(), nums.back()));
            }
        }
        return dp[n];
    }
};


// Time:  O(n)
// Space: O(n)
class Solution2 {
public:
    int getMaximumGenerated(int n) {
        if (n == 0) {
