// Time:  O(n)
// Space: O(1)

class Solution {
public:
    bool closeStrings(string word1, string word2) {
        if (size(word1) != size(word2)) {
            return false;
        }
        vector<int> cnt1(26), cnt2(26);
        for (const auto& c : word1) {
            ++cnt1[c - 'a'];
        }
        for (const auto& c : word2) {
            ++cnt2[c - 'a'];
        }
        unordered_map<int, int> diff;
        for (int i = 0; i < size(cnt1); ++i) {
            if (!cnt1[i] && !cnt2[i]) {
                continue;
            }
            if (!cnt1[i] || !cnt2[i]) {
                return false;
            }
            ++diff[cnt1[i]];
            --diff[cnt2[i]];
        }
        return all_of(cbegin(diff), cend(diff),
                      [](const auto& kvp) {
                          return kvp.second == 0;
                      });
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int minOperations(vector<int>& nums, int x) {
        int target = accumulate(cbegin(nums), cend(nums), 0) - x;
        int result = -1;
        int curr = 0, left = 0;
        for (int right = 0; right < size(nums); ++right) {
            curr += nums[right];
            while (left < size(nums) && curr > target) {
                curr -= nums[left++];
            }
            if (curr == target) {
                result = max(result, right - left + 1);
            }
        }
        return result != -1 ? size(nums) - result : -1;
    }
};

// Time:  O(C(m * n, i) * C(m * n - i, e))
// Space: O(min(m * n, i + e))

// iterative solution, 660 ms
class Solution {
public:
    int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        return iter_backtracking(m, n, introvertsCount, extrovertsCount);
    }

private:
    int iter_backtracking(int m, int n, int i, int e) {
        int result = 0;
        vector<int> curr;
        vector<tuple<int, int, int, int, int>> stk = {{2, i, e, 0, 0}};
        while (!empty(stk)) {
            const auto [step, i, e, total, x] = stk.back(); stk.pop_back();
            if (step == 2) {
                if ((size(curr) == m * n) || (i == 0 && e == 0)) {
                    result = max(result, total);
                    continue;
                }
                if (total + (i + e) * 120 < result) {  // pruning
                    continue;
                }
                if (e > 0) {
                    int new_total = count_total(n, curr, 2, total);
                    stk.emplace_back(3, 0, 0, 0, 0);
                    stk.emplace_back(2, i, e - 1, new_total, 0);
                    stk.emplace_back(1, 0, 0, 0, 2);
                }
                if (i > 0) {
                    int new_total = count_total(n, curr, 1, total);
                    stk.emplace_back(3, 0, 0, 0, 0);
                    stk.emplace_back(2, i - 1, e, new_total, 0);
                    stk.emplace_back(1, 0, 0, 0, 1);
                }
                if (left(n, curr) || up(n, curr)) {  // leave unoccupied iff left or up is occupied
                    stk.emplace_back(3, 0, 0, 0, 0);
                    stk.emplace_back(2, i, e, total, 0);
                    stk.emplace_back(1, 0, 0, 0, 0);
                }
            } else if (step == 1) {
                curr.emplace_back(x);
            } else if (step == 3) {
                curr.pop_back();
            }
        }
        return result;
    }

    int left(int n, const vector<int>& curr) {
        return (size(curr) % n) ? curr[size(curr) - 1] : 0;
    }

    int up(int n, const vector<int>& curr) {
        return (size(curr) >= n) ? curr[size(curr) - n] : 0;
    }

    int count_total(int n, const vector<int>& curr, int t, int total) {
        return (total
	        - 30 * ((left(n, curr) == 1) + (up(n, curr) == 1))
                + 20 * ((left(n, curr) == 2) + (up(n, curr) == 2))
                + (120 - 30 * ((left(n, curr) != 0) + (up(n, curr) != 0))) * (t == 1)
                + ( 40 + 20 * ((left(n, curr) != 0) + (up(n, curr) != 0))) * (t == 2));
    }
};

// Time:  O(C(m * n, i) * C(m * n - i, e))
// Space: O(min(m * n, i + e))
// recursive solution, 104 ms
class Solution2 {
public:
    int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        int result = 0;
        vector<int> curr;
        backtracking(m, n, introvertsCount, extrovertsCount, 0, &curr, &result);
        return result;
    }

private:
    void backtracking(int m, int n, int i, int e, int total,
                      vector<int> *curr, int *result) {
        if ((size(*curr) == m * n) || (i == 0 && e == 0)) {
            *result = max(*result, total);
            return;
        }
        if (total + (i + e) * 120 < *result) {  // pruning
            return;
        }
        if (left(n, *curr) || up(n, *curr)) {  // leave unoccupied iff left or up is occupied
            curr->emplace_back(0);
            backtracking(m, n, i, e, total, curr, result);
            curr->pop_back();
        }
        if (i > 0) {
            int new_total = count_total(n, *curr, 1, total);
            curr->emplace_back(1);
            backtracking(m, n, i - 1, e, new_total, curr, result);
            curr->pop_back();
        }
        if (e > 0) {
            int new_total = count_total(n, *curr, 2, total);
            curr->emplace_back(2);
            backtracking(m, n, i, e - 1, new_total, curr, result);
            curr->pop_back();
        }
    }

    int left(int n, const vector<int>& curr) {
        return (size(curr) % n) ? curr[size(curr) - 1] : 0;
    }

    int up(int n, const vector<int>& curr) {
        return (size(curr) >= n) ? curr[size(curr) - n] : 0;
    }

    int count_total(int n, const vector<int>& curr, int t, int total) {
        return (total
	        - 30 * ((left(n, curr) == 1) + (up(n, curr) == 1))
                + 20 * ((left(n, curr) == 2) + (up(n, curr) == 2))
                + (120 - 30 * ((left(n, curr) != 0) + (up(n, curr) != 0))) * (t == 1)
                + ( 40 + 20 * ((left(n, curr) != 0) + (up(n, curr) != 0))) * (t == 2));
    }
};

// Time:  O(n)
// Space: O(w)

class Solution {
public:
    TreeNode* correctBinaryTree(TreeNode* root) {
        unordered_map<TreeNode*, TreeNode*> q = {{root, nullptr}};
        while (!empty(q)) {
            unordered_map<TreeNode*, TreeNode*> new_q;
            for (const auto& [node, parent] : q) {
                if (q.count(node->right)) {
                    if (parent->left == node) {
                        parent->left = nullptr;
                    } else {
                        parent->right = nullptr;
                    }
                    return root;
                }
                if (node->left) {
                    new_q[node->left] = node;
                }
                if (node->right) {
                    new_q[node->right] = node;
                }
            }
            q = move(new_q);
        }
        return nullptr;
    }
};

// Time:  O(n), n is the total length of word1 and word2
// Space: O(1)

class Solution {
public:
    bool arrayStringsAreEqual(vector<string>& word1, vector<string>& word2) {
        int idx1 = 0, idx2 = 0, arrIdx1 = 0, arrIdx2 = 0;
        while (arrIdx1 < size(word1) && arrIdx2 < size(word2)) {
            if (word1[arrIdx1][idx1] != word2[arrIdx2][idx2]) {
                break;
            }
            ++idx1;
            if (idx1 == size(word1[arrIdx1])) {
                idx1 = 0;
                ++arrIdx1;
            }
            ++idx2;
            if (idx2 == size(word2[arrIdx2])) {
                idx2 = 0;
                ++arrIdx2;
            }
        }
        return arrIdx1 == size(word1) && arrIdx2 == size(word2);
    }
};

