class Solution {
public:
    Node* flipBinaryTree(Node* root, Node * leaf) {
        Node *curr = leaf, *parent = nullptr;
        while (true) {
            auto child = curr->parent;
            curr->parent = parent;
            if (curr->left == parent) {
                curr->left = nullptr;
            } else {
                curr->right = nullptr;
            }
            if (curr == root) {
                break;
            }
            if (curr->left) {
                curr->right = curr->left;
            }
            curr->left = child;
            parent = curr, curr = child;
        }
        return leaf;
    }
};

// Time:  O(n), n is the length of sequence
// Space: O(m), m is the length of word

// optimized kmp solution
class Solution {
public:
    int maxRepeating(string sequence, string word) {
        if (size(sequence) < size(word)) {
            return 0;
        }
        const vector<int> prefix = getPrefix(word);
        int result = 0, count = 0, j = -1, prev = -1;
        for (int i = 0; i < size(sequence); ++i) {
            while (j > -1 && word[j + 1] != sequence[i]) {
                j = prefix[j];
            }
            if (word[j + 1] == sequence[i]) {
                ++j;
            }
            if (j + 1 == size(word)) {
                count = (i - prev == size(word)) ? count + 1 : 1;
                result = max(result, count);
                j = -1, prev = i;
            }
        }
        return result;
    }

private:
    vector<int> getPrefix(const string& pattern) {
        vector<int> prefix(size(pattern), -1);
        int j = -1;
        for (int i = 1; i < size(pattern); ++i) {
            while (j > -1 && pattern[j + 1] != pattern[i]) {
                j = prefix[j];
            }
            if (pattern[j + 1] == pattern[i]) {
                ++j;
            }
            prefix[i] = j;
        }
        return prefix;
    }
};

// Time:  O(n), n is the length of sequence
// Space: O(n)
// kmp solution
class Solution2 {
public:
    int maxRepeating(string sequence, string word) {
        if (size(sequence) < size(word)) {
            return 0;
        }
        string new_word;
        for (int i = 0; i < size(sequence) / size(word); ++i) {
            new_word += word;
        }
        const vector<int> prefix = getPrefix(new_word);
        int result = 0, j = -1;
        for (int i = 0; i < size(sequence); ++i) {
            while (j > -1 && new_word[j + 1] != sequence[i]) {
                j = prefix[j];
            }
            if (new_word[j + 1] == sequence[i]) {
                ++j;
            }
            result = max(result, j + 1);
            if (j + 1 == size(new_word)) {
                break;
            }
        }
        return result / size(word);
    }

private:
    vector<int> getPrefix(const string& pattern) {
        vector<int> prefix(size(pattern), -1);
        int j = -1;
        for (int i = 1; i < size(pattern); ++i) {
            while (j > -1 && pattern[j + 1] != pattern[i]) {
                j = prefix[j];
            }
            if (pattern[j + 1] == pattern[i]) {
                ++j;
            }
            prefix[i] = j;
        }
        return prefix;
    }
};

// Time:  O(m + n)
// Space: O(1)

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* mergeInBetween(ListNode* list1, int a, int b, ListNode* list2) {
        ListNode* prev_first = nullptr, *last = list1;
        for (int i = 0; i < b; ++i) {
            if (i == a - 1) {
                prev_first = last;
            }
            last = last->next;
        }
        prev_first->next = list2;
        for (; list2->next; list2 = list2->next);
        list2->next = last->next;
        last->next = nullptr;
        return list1;
    }
};

