// Space: O(1)

class Solution {
public:
    int maximumGain(string s, int x, int y) {
        string a = "ab", b = "ba";
        if (x < y) {
            swap(a, b);
            swap(x, y);
        }
        return remove(s, a, x) + remove(s, b, y);
    }

private:
    int remove(string &s, string a, int x) {
        int i = 0, result = 0;
        for (int j = 0; j < size(s); ++j) {
            s[i++] = s[j];
            if (i >= 2 && s.substr(i - 2, 2) == a) {
                i -= 2;
                result += x;
            }
        }
        s.resize(i);
        return result;
    }
};

// Time:  O(n!)
// Space: O(n)

class Solution {
public:
    vector<int> constructDistancedSequence(int n) {
        vector<int> result(2 * n - 1);
        vector<bool> lookup(n + 1);
        backtracking(n, 0, &lookup, &result);
        return result;
    }

private:
    bool backtracking(int n, int i, vector<bool> *lookup, vector<int> *result) {
        if (i == size(*result)) {
            return true;
        }
        if ((*result)[i]) {
            return backtracking(n, i + 1, lookup, result);
        }
        for (int x = n; x >= 1; --x) {
            int j = (x == 1) ? i : i + x;
            if ((*lookup)[x] || j >= size(*result) || (*result)[j]) {
                continue;
            }
            (*result)[i] = (*result)[j] = x, (*lookup)[x] = true;
            if (backtracking(n, i + 1, lookup, result)) {
                return true;
            }
            (*result)[i] = (*result)[j] = 0, (*lookup)[x] = false;

        }
        return false;
    }
};

// Time:  O(nlogn)
// Space: O(n)

class Solution {
public:
    int checkWays(vector<vector<int>>& pairs) {
        unordered_map<int, unordered_set<int>> adj;
        for (const auto& pair : pairs) {
            adj[pair[0]].emplace(pair[1]);
            adj[pair[1]].emplace(pair[0]);
        }
        int n = size(adj);
        bool mul = false;
        unordered_set<int> lookup;
        vector<int> nodes;
        transform(begin(adj), end(adj), back_inserter(nodes),
                  [](const auto& kvp) { return kvp.first; });
        sort(begin(nodes), end(nodes),
             [&adj](const auto& a, const auto& b) {
                 return size(adj[a]) > size(adj[b]);
             });
        for (const auto& node : nodes) {
            lookup.emplace(node);
            int parent = 0;
            for (const auto& x : adj[node]) {
                if (!lookup.count(x)) {
                    continue;
                }
                if (parent == 0 || size(adj[x]) < size(adj[parent])) {
                    parent = x;
                }
            }
            if (parent) {
                for (const auto& x : adj[node]) {
                    if (x != parent && !adj[parent].count(x)) {
                        return 0;
                    }
                }
                mul |= size(adj[node]) == size(adj[parent]);
            } else if (size(adj[node]) != n - 1) {
                return 0;
            }
        }
        return 1 + mul;
    }
};

