// Time:  O(26 * n) = O(n)
// Space: O(26 * n) = O(n)

class Solution {
public:
    string longestNiceSubstring(string s) {
        array<array<int, 2>, 26> lookup = {0};
        for (const auto& c : s) {
            lookup[tolower(c) - 'a'][isupper(c) != 0] = 1;
        }
        string result;
        for (int i = 0, prev = -1; i <= size(s); ++i) {
            if (!(i == size(s) || !lookup[tolower(s[i]) - 'a'][0] || !lookup[tolower(s[i]) - 'a'][1])) {
                continue;
            }
            if (prev == -1 && i == size(s)) {
                return s;
            }
            auto tmp = longestNiceSubstring(s.substr(prev + 1, i - prev - 1));
            if (size(tmp) > size(result)) {
                result = move(tmp);
            }
            prev = i;
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(n)

class Solution {
public:
    bool canChoose(vector<vector<int>>& groups, vector<int>& nums) {
        int pos = 0;
        for (const auto& group : groups) {
            pos = KMP(nums, group, pos);
            if (pos == -1) {
                return false;
            }
            pos += size(group);
        }
        return true;
    }

private:
    int KMP(const vector<int>& text, const vector<int>& pattern, int start) {
        const auto& prefix = getPrefix(pattern);
        int j = -1;
        for (int i = start; i < size(text); ++i) {
            while (j + 1 > 0 && pattern[j + 1] != text[i]) {
                j = prefix[j];
            }
            if (pattern[j + 1] == text[i]) {
                ++j;
            }
            if (j + 1 == size(pattern)) {
                return i - j;
            }
        }
        return -1;
    }

    vector<int> getPrefix(const vector<int>& pattern) {
        vector<int> prefix(size(pattern), -1);
        int j = -1;
        for (int i = 1; i < size(pattern); ++i) {
            while (j + 1 > 0 && pattern[j + 1] != pattern[i]) {
                j = prefix[j];
            }
            if (pattern[j + 1] == pattern[i]) {
                ++j;
            }
            prefix[i] = j;
        }
        return prefix;
    }
};

