// Space: O(n)
// trie solution
class Solution2 {
public:
    int countPairs(vector<int>& nums, int low, int high) {
        int result = 0;
        Trie trie;
        for (const auto& x : nums) {
            result += trie.query(x, high + 1) - trie.query(x, low);
            trie.insert(x);
        }
        return result;
    }

private:
    class Trie {
    public:
        Trie() : nodes(1) {}

        void insert(int num) {
            int idx = 0;
            for (int i = 31; i >= 0; --i) {
                int curr = (num >> i) & 1;
                if (!nodes[idx][curr]) {
                    nodes.emplace_back();
                    nodes[idx][curr] = size(nodes) - 1;
                }
                idx = nodes[idx][curr];
                ++nodes[idx][2];
            }
        }

        int query(int num, int limit) {
            int result = 0, idx = 0;
            for (int i = 31; i >= 0; --i) {
                int curr = (num >> i) & 1;
                int bit = (limit >> i) & 1;
                if (bit) {
                    if (nodes[idx][curr]) {
                        result += nodes[nodes[idx][0 ^ curr]][2];  // current limit is xxxxx1*****, count xor pair with xxxxx0***** pattern
                    }
                }
                if (!nodes[idx][bit ^ curr]) {
                    break;
                }
                idx = nodes[idx][bit ^ curr];
            }
            return result;
        }

    private:
        vector<array<int, 3>> nodes;
    };
};

// Time:  ctor:         O(1)
//        insert:       O(n)
//        count_word:   O(n)
//        count_prefix: O(n)
//        erase:        O(n)
// Space: O(t), t is the number of nodes in trie

class TrieNode { 
public:
    TrieNode() : children(26) {}
    vector<unique_ptr<TrieNode>> children;
    int pcnt = 0;
    int cnt = 0;
};

class Trie {
public:
    Trie() {
        trie_ = make_unique<TrieNode>();
    }

    void insert(string word) {
        auto curr = trie_.get();
        ++curr->pcnt;
        for (const auto& c : word) {
            if (curr->children[c - 'a'] == nullptr) {
                curr->children[c - 'a'] = make_unique<TrieNode>();
            }
            curr = curr->children[c - 'a'].get();
            ++curr->pcnt;
        }
        ++curr->cnt;
    }

    int countWordsEqualTo(string word) {
        auto curr = trie_.get();
        for (const auto& c : word) {
            if (curr->children[c - 'a'] == nullptr) {
                return 0;
            }
            curr = curr->children[c - 'a'].get();
        }
        return curr->cnt;
    }

    int countWordsStartingWith(string prefix) {
        auto curr = trie_.get();
        for (const auto& c : prefix) {
            if (curr->children[c - 'a'] == nullptr) {
                return 0;
            }
            curr = curr->children[c - 'a'].get();
        }
        return curr->pcnt;
    }

    void erase(string word) {
        int cnt = countWordsEqualTo(word);
        if (!cnt) {
            return;
        }
        auto curr = trie_.get();
        --curr->pcnt;
        for (const auto& c : word) {
            if (curr->children[c - 'a']->pcnt == 1) {
                curr->children[c - 'a'].reset();  // delete all unused nodes
                return;
            }
            curr = curr->children[c - 'a'].get();
            --curr->pcnt;
        }
        --curr->cnt;
    }

private:
    unique_ptr<TrieNode> trie_;
};

