// Time:  O(n)
// Space: O(n)
// top-down solution
class Solution2 {
public:
    int findTheWinner(int n, int k) {
        return f(0, n, k) + 1;
    }

private:
    int f(int idx, int n, int k) {
        if (n == 1) {
            return 0;
        }
        return (k + f((k + idx) % n, n - 1, k)) % n;
    }
};

// Time:  O(n)
// Space: O(1)

// greedy solution
class Solution {
public:
    int minSideJumps(vector<int>& obstacles) {
        int result = 0;
        unordered_set<int> lanes = {2};
        for (int i = 0; i + 1 < size(obstacles); ++i) {
            lanes.erase(obstacles[i + 1]);
            if (!empty(lanes)) {
                continue;
            }
            ++result;
            for (int j = 1; j <= 3; ++j) {
                if (j != obstacles[i] && j != obstacles[i + 1]) {
                    lanes.emplace(j);
                }
            }
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(1)
// dp solution
class Solution2 {
public:
    int minSideJumps(vector<int>& obstacles) {
        static const int MAX_N = 5 * 1e5;
        static const int INF = (MAX_N - 1) + 1;

        array<int, 3> dp{1, 0, 1};
        for (const auto& i : obstacles) {
            if (i) {
                dp[i - 1] = INF;
            }
            for (int j = 0; j < 3; ++j) {
                if (j + 1 != i) {
                    dp[j] = min({dp[0] + (j != 0), dp[1] + (j != 1), dp[2] + (j != 2)});
                }
            }
        }
        return *min_element(cbegin(dp), cend(dp));
    }
};

// Time:  ctor:           O(1)
//        add_element:    O(logn)
//        calc_mkaverage: O(1)
// Space: O(m)

class MKAverage {
public:
    MKAverage(int m, int k)
     : m_{m}
     , k_{k} {

    }

    void addElement(int num) {
        if (size(dq_) == m_) {
            remove(dq_.front());
            dq_.pop_front();
        }
        dq_.emplace_back(num);
        add(num);
    }

    int calculateMKAverage() {
        if (size(dq_) < m_) {
            return -1;
        }
        return total_ / (m_ - 2 * k_);
    }

private:
    void add(int num) {
        left_.emplace(num);
        if (size(left_) > k_) {
            const auto it = prev(end(left_));
            mid_.emplace(*it);
            total_ += *it;
            left_.erase(it);
        }
        if (size(mid_) > (m_ - 2 * k_)) {
            const auto it = prev(end(mid_));
            total_ -= *it;
            right_.emplace(*it);
            mid_.erase(it);
        }
    }

    void remove(int num) {
        if (num <= *rbegin(left_)) {
            left_.erase(left_.find(num));
        } else if (num <= *rbegin(mid_)) {
            auto it = mid_.find(num); 
            total_ -= *it;
            mid_.erase(it);
        } else {
            right_.erase(right_.find(num));
        }
        if (size(left_) < k_) {
            left_.emplace(*begin(mid_));
            total_ -= *begin(mid_);
            mid_.erase(begin(mid_));
        }
        if (size(mid_) < (m_ - 2 * k_)) {
            mid_.emplace(*begin(right_));
            total_ += *begin(right_);
            right_.erase(begin(right_));
        }
    }

    int m_;
    int k_;
    deque<int> dq_;
    multiset<int> left_, mid_, right_;
    int64_t total_ = 0;
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int badSensor(vector<int>& sensor1, vector<int>& sensor2) {
        for (int i = 0; i + 1 < size(sensor1); ++i) {
            if (sensor1[i] == sensor2[i]) {
                continue;
            }
            while (i + 1 < size(sensor2) && sensor2[i + 1] == sensor1[i]) {
                ++i;
            }
            return i + 1 == size(sensor2) ? 1 : 2;
        }
        return -1;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int minOperations(vector<int>& nums) {
        int result = 0, prev = 0;
        for (const auto& curr : nums) {
            if (prev < curr) {
                prev = curr;
                continue;
            }
            result += (++prev) - curr;
        }
        return result;
    }
};

// Time:  O(q * n)
// Space: O(1)

class Solution {
public:
    vector<int> countPoints(vector<vector<int>>& points, vector<vector<int>>& queries) {
        vector<int> result;
        for (const auto& q : queries) {
            result.emplace_back(0);
            for (const auto& p : points) {
                int dx = p[0] - q[0], dy = p[1] - q[1];
                if (dx * dx + dy * dy <= q[2] * q[2]) {
                    ++result.back();
                }
            }
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    vector<int> getMaximumXor(vector<int>& nums, int maximumBit) {
        vector<int> result(size(nums));
        int mask = (1 << maximumBit) - 1;
        for (int i = 0; i < size(nums); ++i) {
            result[size(nums) - 1 - i] = mask ^= nums[i];
        }
        return result;
    }
};

// Time:  O(26 * n) = O(n)
// Space: O(max_n) = O(max_n)

class Solution {
public:
    int makeStringSorted(string s) {  // count of prev_permutation
        static const int MOD = 1e9 + 7;

        array<int, 26> count = {0};
        int result = 0, comb_total = 1;
        for (int i = size(s) - 1; i >= 0; --i) {
            int num = s[i] - 'a';
            comb_total = ((comb_total * int64_t(size(s) - i) % MOD) * inverse(++count[num], MOD)) % MOD;
            result = (result + ((comb_total * accumulate(cbegin(count), cbegin(count) + num, 0LL) % MOD) * inverse(size(s) - i, MOD) % MOD)) % MOD;
        }
        return result;
    }
private:
    int inverse(int n, int m) {
        static vector<int> inv = {0, 1};

        for (int i = size(inv); i <= n; ++i) {  // lazy initialization
            inv.emplace_back(inv[m % i] * int64_t(m - m / i) % m);  // https://cp-algorithms.com/algebra/module-inverse.html  
        }
        return inv[n];
    }
};

