        vector<int> years(MAX_YEAR - MIN_YEAR + 1);
        for (int i = 0; i < size(logs); ++i) {
            ++years[logs[i][0] - MIN_YEAR];
            --years[logs[i][1] - MIN_YEAR];
        }
        int result = 0;
