class Solution {
public:
    int largestPathValue(string colors, vector<vector<int>>& edges) {
        vector<vector<int>> adj(size(colors));
        vector<int> in_degree(size(colors));
        for (const auto& edge : edges) {
            adj[edge[0]].emplace_back(edge[1]);
            ++in_degree[edge[1]];
        }
        vector<int> q;
        for (int i = 0; i < size(colors); ++i) {
            if (!in_degree[i]) {
                q.emplace_back(i);
            }
        }
        vector<vector<int>> dp(size(colors), vector<int>(26));
        int result = -1, cnt = 0;
        while (!empty(q)) {
            vector<int> new_q;
            for (const auto& u : q) {
                ++cnt;
                result = max(result, ++dp[u][colors[u] - 'a']);
                for (const auto& v : adj[u]) {
                    for (int c = 0; c < 26; ++c) {
                        dp[v][c] = max(dp[v][c], dp[u][c]);
                    }
                    if (!--in_degree[v]) {
                        new_q.emplace_back(v);
                    }
                }
            }
            q = move(new_q);
        }
        return cnt == size(colors) ? result : -1;
    }
};

// Time:  O(n)
// Space: O(t), t is the number of nodes in trie

class Solution {
private:
    class TrieNode { 
    public:
        int idx = -1;
        unordered_map<char, unique_ptr<TrieNode>> leaves;

        void Insert(int i, const string& s) {
            auto p = this;
            for (const auto& c : s) {
                if (!p->leaves.count(c)) {
                    p->leaves[c] = make_unique<TrieNode>();
                }
                p = p->leaves[c].get();
            }
            p->idx = i;
        }
    };

public:
    string longestWord(vector<string>& words) {
        auto trie = make_unique<TrieNode>();
        for (int i = 0; i < size(words); ++i) {
            trie->Insert(i, words[i]);
        }
        return iter_dfs(words, trie.get());
    }

private:
    string iter_dfs(const vector<string>& words, TrieNode *node) {
        int result = -1;
        vector<TrieNode *> stk = {node};
        while (!empty(stk)) {
            const auto node = stk.back(); stk.pop_back();
            if (result == -1 || size(words[node->idx]) > size(words[result])) {
                result = node->idx;
            }
            for (char c = 'z'; c >= 'a'; --c) {
                if (!node->leaves.count(c) || node->leaves[c]->idx == -1) {
                    continue;
                }
                stk.emplace_back(node->leaves[c].get());
            }
        }
        return result != -1 ? words[result] : "";
    }
};


