// Space: O(1)

class Solution {
public:
    vector<vector<char>> rotateTheBox(vector<vector<char>>& box) {
        vector<vector<char>> result(size(box[0]), vector<char>(size(box), '.'));
        for (int i = 0; i < size(box); ++i) {
            for (int j = size(box[0]) - 1, k = size(box[0]) - 1; j >= 0; --j) {
                if (box[i][j] == '.') {
                    continue;
                }
                if (box[i][j] == '*') {
                    k = j;
                }
                result[k--][size(box) -1 - i] = box[i][j];
            }
        }
        return result;
    }
};

// Time:  O(n/1+n/2+...+n/n) = O(nlogn), n is the max of nums
// Space: O(n)

class Solution {
public:
    int sumOfFlooredPairs(vector<int>& nums) {
        static const int MOD = 1e9 + 7;
        vector<int> prefix(*max_element(cbegin(nums), cend(nums)) + 1);
        unordered_map<int, int> count;
        for (const auto& num : nums) {
            ++count[num];
        }
        for (const auto& [num, cnt] : count) {
            for (int j = num; j < size(prefix); j += num) {
                prefix[j] += cnt;
            }
        }
        for (int i = 0; i + 1 < size(prefix); ++i) {
            prefix[i + 1] += prefix[i];
        }
        return accumulate(cbegin(nums), cend(nums), 0,
                          [&prefix](int total, int x) {
                              return (total + prefix[x]) % MOD;
                          });
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int subsetXORSum(vector<int>& nums) {
        // given there are k (k >= 1) nums of which ith bit is 1,
        // the bit contributes to sum is:
        // (nCr(k, 1) + nCr(k, 3) + ...) * (nCr(n - k, 0) + nCr(n - k, 1) + ...) * 2^i
        // = 2^(k-1) * 2^(n-k) = 2^(n-1) * 2^i
        int result = 0;
        for (const auto& x : nums) {
            result |= x;
        }
        return result * pow(2, size(nums) - 1);
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int minSwaps(string s) {
        int ones = count(cbegin(s), cend(s), '1');
        int zeros = size(s) - ones;
        if (abs(ones - zeros) > 1) {
            return -1;
        }
        if (ones > zeros) {
            return cost(s, 1);
        }
        if (ones < zeros) {
            return cost(s, 0);
        }
        return min(cost(s, 1), cost(s, 0));
    }

private:
    int cost(const string& s, int x) {
        int diff = 0;
        for (const auto& c : s) {
            diff += (c - '0' != x);
            x ^= 1;
        }
        return diff / 2;
    }
};

// Time:  ctor:  O(n1 + n2)
//        add:   O(1)
//        count: O(n1)
// Space: O(n1 + n2)

class FindSumPairs {
public:
    FindSumPairs(vector<int>& nums1, vector<int>& nums2)
     : nums2_(nums2) {
        for (const auto& x : nums1) {
            ++count1_[x];
        }
        for (const auto& x : nums2) {
            ++count2_[x];
        }
    }

    void add(int index, int val) {
        --count2_[nums2_[index]];
        nums2_[index] += val;
        ++count2_[nums2_[index]];
    }

    int count(int tot) {
        int result = 0;
        for (const auto& [x, cnt] : count1_) {
            if (count2_.count(tot - x)) {
                result += cnt * count2_[tot - x];
            }
        }
        return result;
    }

private:
    vector<int> nums2_;
    unordered_map<int, int> count1_, count2_;
};

// Time:  O(n * k)
// Space: O(k)

class Solution {
public:
    int rearrangeSticks(int n, int k) {
        static const int MOD = 1e9 + 7;
        vector<vector<int>> dp(2, vector<int>(k + 1));
        dp[1][1] = 1;
        for (int i = 2; i <= n; ++i) {
            for (int j = 1; j <= min(i, k); ++j) {
                // choose the tallest as the last one which would be visible:    dp[i-1][j-1]
                // choose the non-tallest as the last one which would be hidden: (i-1)*dp[i-1][j]
                dp[i % 2][j] = (dp[(i - 1) % 2][j - 1] + int64_t(i - 1) * dp[(i - 1) % 2][j]) % MOD;
            }
        }
        return dp[n % 2][k];
    }
};

// Time:  O(m + n)
// Space: O(1)

class Solution {
public:
    vector<vector<int>> findRLEArray(vector<vector<int>>& encoded1, vector<vector<int>>& encoded2) {
        vector<vector<int>> result;
        for (int i = 0, j = 0, remain1 = 0, remain2 = 0;
             (remain1 || i < size(encoded1)) && (remain2 || j < size(encoded2));) {
            if (!remain1) {
                remain1 = encoded1[i++][1];
            }
            if (!remain2) {
                remain2 = encoded2[j++][1];
            }
            int cnt = min(remain1, remain2);
            remain1 -= cnt;
            remain2 -= cnt;
            if (!empty(result) && result.back()[0] == encoded1[i - 1][0] * encoded2[j - 1][0]) {
                result.back()[1] += cnt;
            } else {
                result.push_back({encoded1[i - 1][0] * encoded2[j - 1][0], cnt});
            }
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    bool checkZeroOnes(string s) {
        vector<int> max_cnt(2);
        for (int i = 0, cnt = 0; i <= size(s); ++i, ++cnt) {
            if (i == size(s) || (i >= 1 && s[i] != s[i - 1])) {
                max_cnt[s[i - 1] - '0'] = max(max_cnt[s[i - 1] - '0'], cnt);
                cnt = 0;
            }
        }
        return max_cnt[0] < max_cnt[1];
    }
};

// Time:  O(nlogr), r is the range of speed
// Space: O(1)

class Solution {
public:
    int minSpeedOnTime(vector<int>& dist, double hour) {
        static const double MAX_SPEED = 1e7;
        if (!check(dist, hour, MAX_SPEED)) {
            return -1;
        }
        int left = 1, right = MAX_SPEED;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (check(dist, hour, mid)) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }

private:
    int ceil(int a, int b) {
        return (a + b - 1) / b;
    }

    double total_time(const vector<int>& dist, int x) {
        return accumulate(cbegin(dist), prev(cend(dist)), 0,
                          [this, &x](int total, int i) {
                              return total + ceil(i, x);
                          }) +
               double(dist.back()) / x;
    }

    bool check(const vector<int>& dist, double hour, int x) {
        return total_time(dist, x) <= hour;
    }
};

