// Space: O(1)

class Solution {
public:
    string maxValue(string n, int x) {
        function<bool(int)> check1 = [&n, &x](int i) { return '0' + x > n[i]; };
        function<bool(int)> check2 = [&n, &x](int i) { return '0' + x < n[i]; };
        auto check = (n[0] != '-') ? check1 : check2;
        int i = 0;
        for (; i < size(n); ++i) {
            if (check(i)) {
                break;
            }
        }
        n.insert(begin(n) + i, '0' + x);
        return n;
    }
};

// Time:  O(n + mlogn)
// Space: O(n)

class Solution {
public:
    vector<int> assignTasks(vector<int>& servers, vector<int>& tasks) {
        vector<pair<int, int>> idle;
        for (int i = 0; i < size(servers); ++i) {
            idle.emplace_back(servers[i], i);
        }
        make_heap(begin(idle), end(idle), greater<>());
        vector<tuple<int, int, int>> working;

        vector<int> result;
        for (int i = 0, t = 0; i < size(tasks); ++i) {
            t = !empty(idle) ? max(t, i) : get<0>(working.front());
            while (!empty(working) && get<0>(working.front()) <= t) {
                const auto [_, w, idx] = working.front(); pop_heap(begin(working), end(working), greater<>()); working.pop_back();
                idle.emplace_back(w, idx); push_heap(begin(idle), end(idle), greater<>());
            }
            const auto [w, idx] = idle.front(); pop_heap(begin(idle), end(idle), greater<>()); idle.pop_back();
            working.emplace_back(t + tasks[i], w, idx); push_heap(begin(working), end(working), greater<>());
            result.emplace_back(idx);
        }
        return result;
    }
};

// Time:  O(n^2)
// Space: O(n)

class Solution {
public:
    int minSkips(vector<int>& dist, int speed, int hoursBefore) {
        vector<int> dp((size(dist) - 1) + 1);  // dp[i]: (min time by i skips) * speed
        for (int i = 0; i < size(dist); ++i) {
            for (int j = size(dp) - 1; j >= 0; --j) {
                dp[j] = (i < size(dist) - 1) ? ceil(dp[j] + dist[i], speed) * speed : dp[j] + dist[i];
                if (j - 1 >= 0) {
                    dp[j] = min(dp[j], dp[j - 1] + dist[i]);
                }
            }
        }
        const int64_t target = int64_t(hoursBefore) * speed;
        for (int i = 0; i < size(dist); ++i) {
            if (dp[i] <= target) {
                return i;
            }
        }
        return -1;
    }

private:
    int ceil(int a, int b) {
        return (a + b - 1) / b;
    }
};

