// Time:  O(k * n^2)
// Space: O(n)
class Solution2 {
public:
    int twoEggDrop(int n) {
        static const int K = 2;
        vector<vector<int>> dp(2, vector<int>(n + 1, numeric_limits<int>::max()));
        for (int j = 0; j <= n; ++j) {
            dp[1][j] = j;
        }
        for (int i = 2; i <= K; ++i) {
            dp[i % 2][0] = 0;
            for (int j = 1; j <= n; ++j) {
                for (int k = 1; k <= j; ++k) {
                    dp[i % 2][j] = min(dp[i % 2][j], 1 + max(dp[(i - 1) % 2][k - 1], dp[i % 2][j - k]));
                }
            }
        }
        return dp[K % 2][n];
    }
};

// Time:  O(nlogn)
// Space: O(1)

class Solution {
public:
    long long countPairs(vector<int>& nums1, vector<int>& nums2) {
        for (int i = 0; i < size(nums1); ++i) {
            nums1[i] -= nums2[i];
        }
        sort(begin(nums1), end(nums1));
        long long result = 0;
        int left = 0, right = size(nums1) - 1;
        while (left < right) {
            if (nums1[left] > 0 || -nums1[left] < nums1[right]) {
                result += right - left;
                --right;
            } else {
                ++left;
            }
        }
        return result;
    }
};

// Time:  O(m * n)
// Space: O(1)

class Solution {
public:
    bool findRotation(vector<vector<int>>& mat, vector<vector<int>>& target) {
        vector<function<bool (int, int)>> checks = {
            [&mat, &target](int i, int j) { return mat[i][j] == target[i][j]; },
            [&mat, &target](int i, int j) { return mat[i][j] == target[j][size(mat) - 1 - i]; },
            [&mat, &target](int i, int j) { return mat[i][j] == target[size(mat) - 1 - i][size(mat[0]) - 1 - j]; },
            [&mat, &target](int i, int j) { return mat[i][j] == target[size(mat[0]) - 1 - j][i]; },
        };
        const auto& traverse = [&mat, &target](const auto& check) {
            for (int i = 0; i < size(mat); ++i) {
                for (int j = 0; j < size(mat[0]); ++j) {
                    if (!check(i, j)) {
                        return false;
                    }
                }
            }
            return true;
        };
        for (const auto& check : checks) {
            if (traverse(check)) {
                return true;
            }
        }
        return false;
    }
};

