// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int minFlips(string s) {
        int result = numeric_limits<int>::max();
        int cnt1 = 0, cnt2 = 0;
        int l = (size(s) % 2) ? 2 * size(s) - 1 : size(s);
        for (int i = 0; i < l; ++i) {
            if (i >= size(s)) {
                cnt1 -= (s[i % size(s)] - '0') ^ ((i - size(s)) % 2) ^ 0;
                cnt2 -= (s[i % size(s)] - '0') ^ ((i - size(s)) % 2) ^ 1;
            }
            cnt1 += (s[i % size(s)] - '0') ^ (i % 2) ^ 0;
            cnt2 += (s[i % size(s)] - '0') ^ (i % 2) ^ 1;
            if (i >= size(s) - 1) {
                result = min({result, cnt1, cnt2});
            }
        }
        return result;
    }
};

// Time:  O(mlogm + nlogn + mlogn)
// Space: O(1)

class Solution {
public:
    int minWastedSpace(vector<int>& packages, vector<vector<int>>& boxes) {
        static const int MOD = 1e9 + 7;
        static const int64_t INF = numeric_limits<int64_t>::max();

        sort(begin(packages), end(packages));
        int64_t result = INF;
        for (auto& box : boxes) {
            sort(begin(box), end(box));
            if (box.back() < packages.back()) {
                continue;
            }
            int64_t curr = 0;
            auto left = cbegin(packages);
            for (const auto& b : box) {
                auto right = upper_bound(left, cend(packages), b);
                curr += b * (right - left);
                left = right;
            }
            result = min(result, curr);
        }
        int64_t total = accumulate(cbegin(packages), cend(packages), 0LL);
        return result != INF ? (result - total) % MOD : -1;
    }
};

// Time:  O(nlogr), r is sum(ribbons)/k
// Space: O(1)

class Solution {
public:
    int maxLength(vector<int>& ribbons, int k) {
        int64_t left = 1, right = accumulate(cbegin(ribbons), cend(ribbons), 0LL) / k;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (!check(ribbons, k, mid)) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return right;
    }

private:
    bool check(const vector<int>& ribbons, int k, int s) {
        return accumulate(cbegin(ribbons), cend(ribbons), 0LL,
                          [&s](auto total, auto x) {
                              return total + x / s;
                          }) >= k;
    }
};

