// Time:  O(max(m, n) * min(m, n)^3)
// Space: O(m + n)

class Solution {
public:
    int largestMagicSquare(vector<vector<int>>& grid) {
        vector<vector<int>> prefix_row(size(grid), vector<int>(size(grid[0]) + 1));
        vector<vector<int>> prefix_col(size(grid[0]), vector<int>(size(grid) + 1));
        for (int i = 0; i < size(grid); ++i) {
            for (int j = 0; j < size(grid[0]); ++j) {
                prefix_row[i][j + 1] = prefix_row[i][j] + grid[i][j];
                prefix_col[j][i + 1] = prefix_col[j][i] + grid[i][j];
            }
        }
        for (int l = min(size(grid), size(grid[0])); l >= 1; --l) {
            for (int i = 0; i + l - 1 < size(grid); ++i) {
                for (int j = 0; j + l - 1 < size(grid[0]); ++j) {
                    if (check(grid, prefix_row, prefix_col, l, i, j)) {
                        return l;
                    }
                }
            }
        }
        return 1;
    }

private:
    bool check(const vector<vector<int>>& grid,
               const vector<vector<int>>& prefix_row,
               const vector<vector<int>>& prefix_col,
               int l, int i, int j) {
        int diag = 0, anti_diag = 0;
        for (int d = 0; d < l; ++d) {
            diag += grid[i + d][j + d];
            anti_diag += grid[i + d][j + l - 1 - d];
        }
        if (diag != anti_diag) {
            return false;
        }
        for (int ni = i; ni < i + l; ++ni) {
            if (diag != get_sum(prefix_row[ni], j, j + l - 1)) {
                return false;
            }
        }
        for (int nj = j; nj < j + l; ++nj) {
            if (diag != get_sum(prefix_col[nj], i, i + l - 1)) {
                return false;
            }
        }
        return true;
    }

    int get_sum(const vector<int>& prefix, int a, int b) {
        return prefix[b + 1] - prefix[a];
    }
};

// Time:  O(n)
// Space: O(n)

class Solution {
public:
    int minOperationsToFlip(string expression) {
        static const unordered_map<char, int> precedence = {{'&', 0}, {'|', 0}};

        vector<vector<int>> operands;
        vector<char> operators;
        for (const auto& c : expression) {
            if (isdigit(c)) {
                operands.push_back({int(c != '0'), int(c != '1')});
            } else if (c == '(') {
                operators.emplace_back(c);
            } else if (c == ')') {
                while (operators.back() != '(') {
                    compute(&operands, &operators);
                }
                operators.pop_back();
            } else if (precedence.count(c)) {
                while (!empty(operators) && precedence.count(operators.back()) && 
                       precedence.at(operators.back()) >= precedence.at(c)) {
                     compute(&operands, &operators);
                }
                operators.emplace_back(c);
            }
        }
        while (!empty(operators)) {
            compute(&operands, &operators);
        }
        return *max_element(cbegin(operands.back()), cend(operands.back()));
    }

private:
    template<typename T>
    void compute(vector<T> *operands, vector<char> *operators) {
        const auto right = operands->back(); operands->pop_back();
        const auto left = operands->back(); operands->pop_back();
        const char op = operators->back(); operators->pop_back();
        if (op == '&') {
            operands->push_back({min(left[0], right[0]), min(left[1] + right[1], min(left[1], right[1]) + 1)});
        } else if (op == '|') {
            operands->push_back({min(left[0] + right[0], min(left[0], right[0]) + 1), min(left[1], right[1])});
        }
    }
};

// Time:  O(n)
// Space: O(n)
class Solution2 {
public:
    int minOperationsToFlip(string expression) {
        unordered_set<char> operands_set = {')', '0', '1'};
        vector<tuple<int, int, char>> stk = {{0, 0, ' '}};
        for (const auto& c : expression) {
            if (c == '(') {
                stk.emplace_back(0, 0, ' ');
            } else if (operands_set.count(c)) {
                int dp0 = 0, dp1 = 0;
                if (c == ')') {
                    dp0 = get<0>(stk.back());
                    dp1 = get<1>(stk.back());
                    stk.pop_back();
                } else {
                    dp0 = int(c != '0');
                    dp1 = int(c != '1');
                }
                if (get<2>(stk.back()) == '&') {
                    stk.back() = {min(get<0>(stk.back()), dp0),
                                  min(get<1>(stk.back()) + dp1, min(get<1>(stk.back()), dp1) + 1),
                                  ' '};
                } else if (get<2>(stk.back()) == '|') {
                    stk.back() = {min(get<0>(stk.back()) + dp0, min(get<0>(stk.back()), dp0) + 1),
                                  min(get<1>(stk.back()), dp1),
                                  ' '};
                } else {
                    stk.back() = {dp0, dp1, ' '};
                }
            } else {  // operator
                get<2>(stk.back()) = c;
            }
        }
        return max(get<0>(stk[0]), get<1>(stk[0]));
    }
};

