class Solution {
public:
    int countSubIslands(vector<vector<int>>& grid1, vector<vector<int>>& grid2) {
        int result = 0;
        for (int i = 0; i < size(grid2); ++i) {
            for (int j = 0; j < size(grid2[0]); ++j) {
                if (grid2[i][j]) {
                    result += dfs(grid1, &grid2, i, j);
                }
            }
        }
        return result;
    }

private:
    int dfs(const vector<vector<int>>& grid1,
            vector<vector<int>> *grid2,
            int i, int j) {
        static const vector<pair<int, int>> directions{{0, 1}, {1, 0},
                                                       {0, -1}, {-1, 0}};
        if (!(0 <= i && i < size(*grid2) &&
              0 <= j && j < size((*grid2)[0]) &&
              (*grid2)[i][j] == 1)) {
            return 1;
        }
        (*grid2)[i][j] = 0;
        int result = grid1[i][j];
        for (const auto& [di, dj] : directions) {
            result &= dfs(grid1, grid2, i + di, j + dj);
        }
        return result;
    }
};

// Time:  O(r * (n + q)), r is the max of nums
// Space: O(r * n)

class Solution {
public:
    vector<int> minDifference(vector<int>& nums, vector<vector<int>>& queries) {
        static const int INF = numeric_limits<int>::max();
        vector<vector<int>> prefix(1, vector<int>(*max_element(cbegin(nums), cend(nums)) + 1));
        for (const auto& num : nums) {
            prefix.emplace_back(prefix.back());
            ++prefix.back()[num];
        }
        vector<int> result;
        for (const auto& query : queries) {
            int min_diff = INF, prev = -1;
            for (int num = 0; num < size(prefix[0]); ++num) {
                if (!(prefix[query[0]][num] < prefix[query[1] + 1][num])) {
                    continue;
                }
                if (prev != -1) {
                    min_diff = min(min_diff, num - prev);
                }
                prev = num;
            }
            result.emplace_back((min_diff != INF) ? min_diff : -1);
        }
        return result;
    }
};

// Time:  O(r + n + q * r * logn), r is the max of nums
// Space: O(r + n)
class Solution2 {
public:
    vector<int> minDifference(vector<int>& nums, vector<vector<int>>& queries) {
        static const int INF = numeric_limits<int>::max();
        vector<vector<int>> idxs(*max_element(cbegin(nums), cend(nums)) + 1);
        for (int i = 0; i < size(nums); ++i) {
            idxs[nums[i]].emplace_back(i);
        }
        vector<int> result;
        for (const auto& query : queries) {
            int min_diff = INF, prev = -1;
            for (int num = 0; num < size(idxs); ++num) {
                const auto cit = lower_bound(cbegin(idxs[num]), cend(idxs[num]), query[0]);
                if (!(cit != cend(idxs[num]) && *cit <= query[1])) {
                    continue;
                }
                if (prev != -1) {
                    min_diff = min(min_diff, num - prev);
                }
                prev = num;
            }
            result.emplace_back((min_diff != INF) ? min_diff : -1);
        }
        return result;
    }
};

