class Solution {
public:
    int countGoodNumbers(long long n) {
        static const int MOD = 1e9 + 7;
        return int64_t(powmod(5, (n + 1) / 2 % (MOD - 1), MOD)) * powmod(4, n / 2 % (MOD - 1), MOD) % MOD;
    }

private:
    uint32_t powmod(uint32_t a, uint32_t b, uint32_t mod) {
        a %= mod;
        uint64_t result = 1;
        while (b) {
            if (b & 1) {
                result = result * a % mod;
            }
            a = uint64_t(a) * a % mod;
            b >>= 1;
        }
        return result;
    }
};

// Time:  O(m * nlogn)
// Space: O(n)

class Solution {
public:
    int longestCommonSubpath(int n, vector<vector<int>>& paths) {
        int left = 1, right = size(*min_element(cbegin(paths), cend(paths),
                                                [](const auto& x, const auto& y) {
                                                    return size(x) < size(y);
                                                }));
        while (left <= right) {
            const auto& mid = left + (right - left) / 2;
            if (!check(paths, mid)) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return right;
    }

private:
    template<typename T>
    struct VectorHash {
        size_t operator()(const std::vector<T>& v) const {
            size_t seed = 0;
            for (const auto& i : v) {
                seed ^= std::hash<T>{}(i)  + 0x9e3779b9 + (seed<<6) + (seed>>2);
            }
            return seed;
        }
    };

    bool check(const vector<vector<int>>& paths, int x) {
        unordered_set<vector<int>, VectorHash<int>> intersect = RabinKarp(paths[0], x);
        for (int i = 1; i < size(paths); ++i) {
            intersect = set_intersection<vector<int>, VectorHash<int>>(intersect, RabinKarp(paths[i], x));
            if (empty(intersect)) {
                return false;
            }
        }
        return true;
    }

    unordered_set<vector<int>, VectorHash<int>> RabinKarp(const vector<int>& arr, int x) {
        static const int MOD = 1e9 + 7;  // MOD could be the min prime of 7-digit number (1e6+3)
        static const vector<int> P = {113, 109};  // double hashing, P could be {2, 3}
        vector<int> hashes, powers;
        for (const auto& p : P) {
            int64_t h = 0, power = 1;
            for (int i = 0; i < x; ++i) {
                h = (h * p + arr[i]) % MOD;
                power = (power * p) % MOD;
            }
            hashes.emplace_back(h);
            powers.emplace_back(power);
        }
        unordered_set<vector<int>, VectorHash<int>> lookup = {hashes};
        for (int i = x; i < size(arr); ++i) {
            for (int j = 0; j < size(P); ++j) {
                hashes[j] = ((int64_t(hashes[j]) * P[j] - int64_t(arr[i - x]) * powers[j] + arr[i]) % MOD + MOD) % MOD;
            }
            lookup.emplace(hashes);
        }
        return lookup;
    }

    template<typename T, typename H>
    unordered_set<T, H> set_intersection(const unordered_set<T, H>& a,
                                         const unordered_set<T, H>& b) {
        if (a.size() > b.size()) {
            return set_intersection(b, a);
        }
        unordered_set<T, H> result;
        for (const auto& x : a) {
            if (b.count(x)) {
                result.emplace(x);
            }
        }
        return result;
    }
};

// Time:  O(m * nlogn)
// Space: O(n)
class Solution2 {
public:
    int longestCommonSubpath(int n, vector<vector<int>>& paths) {
        int left = 1, right = size(*min_element(cbegin(paths), cend(paths),
                                                [](const auto& x, const auto& y) {
                                                    return size(x) < size(y);
                                                }));
        while (left <= right) {
            const auto& mid = left + (right - left) / 2;
            if (!check(paths, mid)) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return right;
    }

private:
    bool check(const vector<vector<int>>& paths, int x) {
        unordered_set<int64_t> intersect = RabinKarp(paths[0], x);
        for (int i = 1; i < size(paths); ++i) {
            intersect = set_intersection<int64_t>(intersect, RabinKarp(paths[i], x));
            if (empty(intersect)) {
                return false;
            }
        }
        return true;
    }

    unordered_set<int64_t> RabinKarp(const vector<int>& arr, int x) {
        static const int64_t MOD = 1e11 + 19;  // MOD is the min prime of 12-digit number
        static const int64_t P = 1e5 + 1;  // max(x for p in paths for x in p)+1
        int64_t h = 0, power = 1;
        for (int i = 0; i < x; ++i) {
            h = (h * P + arr[i]) % MOD;
            power = (power * P) % MOD;
        }
        unordered_set<int64_t> lookup = {h};
        for (int i = x; i < size(arr); ++i) {
            h = ((h * P - arr[i - x] * power + arr[i]) % MOD + MOD) % MOD;
            lookup.emplace(h);
        }
        return lookup;
    }

    template<typename T>
    unordered_set<T> set_intersection(const unordered_set<T>& a,
                                      const unordered_set<T>& b) {
        if (a.size() > b.size()) {
            return set_intersection(b, a);
        }
        unordered_set<T> result;
        for (const auto& x : a) {
            if (b.count(x)) {
                result.emplace(x);
            }
        }
        return result;
    }
};

// Time:  O(n) on average
// Space: O(n)

// reference: https://en.wikipedia.org/wiki/Smallest-circle_problem
class Solution {
public:
    vector<double> outerTrees(vector<vector<int>>& trees) {
        random_shuffle(begin(trees), end(trees));
        vector<vector<double>> boundaries;
        const auto& result = Welzl(trees, &boundaries, 0);
        return {result.first[0], result.first[1], result.second};
    }

private:
    pair<vector<double>, double> Welzl(
        const vector<vector<int>>& points,
        vector<vector<double>> *boundaries,
        int curr) {

        if (curr == size(points) || size(*boundaries) == 3) {
            return trivial(*boundaries);
        }
        vector<double> p = {double(points[curr][0]), double(points[curr][1])};
        const auto& result = Welzl(points, boundaries, curr + 1);
        if (!empty(result.first) && inside(result, p)) {
            return result;
        }
        boundaries->emplace_back(move(p));
        const auto& result2 = Welzl(points, boundaries, curr + 1);
        boundaries->pop_back();
        return result2;
    }

    pair<vector<double>, double> trivial(const vector<vector<double>>& boundaries) {  // circumscribed circle
        if (empty(boundaries)) {
            return {{}, 0.0};
        }
        if (size(boundaries) == 1) {
            return {boundaries[0], 0.0};
        }
        if (size(boundaries) == 2) {
            return circle_from_2_points(boundaries[0], boundaries[1]);
        }
        return circle_from_3_points(boundaries[0], boundaries[1], boundaries[2]);
    }

    double dist(const vector<double>& a, const vector<double>& b) {
        return sqrt((a[0] - b[0]) * (a[0] - b[0]) + (a[1] - b[1]) * (a[1] - b[1]));
    }

    bool inside(const pair<vector<double>, double>& c, const vector<double>& p) {
        static const double EPS = 1e-5;
        return dist(c.first, p) < c.second + EPS;
    }

    vector<double> circle_center(int bx, int by, int cx, int cy) {
        double B = bx * bx + by * by;
        double C = cx * cx + cy * cy;
        double D = bx * cy - by * cx;
        return {(cy * B - by * C) / (2 * D), (bx * C - cx * B) / (2 * D)};
    }

    pair<vector<double>, double> circle_from_2_points(
        const vector<double>& A,
        const vector<double>& B) {

        vector<double> C = {(A[0] + B[0]) / 2.0, (A[1] + B[1]) / 2.0};
        return {C, dist(A, B) / 2.0};
    }

    pair<vector<double>, double> circle_from_3_points(
        const vector<double>& A,
        const vector<double>& B,
        const vector<double>& C) {

        vector<double> I = circle_center(B[0] - A[0], B[1] - A[1], C[0] - A[0], C[1] - A[1]);
        I[0] += A[0];
        I[1] += A[1];
        return {I, dist(I, A)};
    }
};

