// Time:  O(m * n)
// Space: O(m + n)

// bi-bfs solution
class Solution {
private:
    template <typename T>
    struct PairHash {
        size_t operator()(const pair<T, T>& p) const {
            size_t seed = 0;
            seed ^= std::hash<T>{}(p.first)  + 0x9e3779b9 + (seed<<6) + (seed>>2);
            seed ^= std::hash<T>{}(p.second) + 0x9e3779b9 + (seed<<6) + (seed>>2);
            return seed;
        }
    };

public:
    int nearestExit(vector<vector<char>>& maze, vector<int>& entrance) {
        static const vector<pair<int, int>> directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        static const char visited = '-';
        maze[entrance[0]][entrance[1]] = visited;
        unordered_set<pair<int, int>, PairHash<int>> left = {{entrance[0], entrance[1]}}, right;
        for (int r = 0; r < size(maze) - 1; ++r) {
            if (maze[r][0] == '.' && vector<int>({r, 0}) != entrance) {
                right.emplace(r, 0);
            }
        }
        for (int c = 0; c < size(maze[0]) - 1; ++c) {
            if (maze[size(maze) - 1][c] == '.' && vector<int>({int(size(maze)) - 1, c}) != entrance) {
                right.emplace(size(maze) - 1, c);
            }
        }
        for (int r = size(maze) - 1; r >= 1; --r) {
            if (maze[r][size(maze[0]) - 1] == '.' && vector<int>({r, int(size(maze[0])) - 1}) != entrance) {
                right.emplace(r, size(maze[0]) - 1);
            }
        }
        for (int c = size(maze[0]) - 1; c >= 1; --c) {
            if (maze[0][c] == '.' && vector<int>({0, c}) != entrance) {
                right.emplace(0, c);
            }
        }
        int steps = 0;
        while (!empty(left)) {
            for (const auto& [r, c] : left) {
                maze[r][c] = visited;
            }
            unordered_set<pair<int, int>, PairHash<int>> new_left;
            for (const auto& pos : left) {
                if (right.count(pos)) {
                    return steps;
                }
                for (const auto& [dr, dc] : directions) {
                    pair<int, int> nei = {pos.first + dr, pos.second + dc};
                    if (!(0 <= nei.first && nei.first < size(maze) &&
                          0 <= nei.second && nei.second < size(maze[0]) &&
                          maze[nei.first][nei.second] == '.')) {
                        continue;
                    }
                    new_left.emplace(nei);
                }
            }
            left = move(new_left);
            ++steps;
            if (size(left) > size(right)) {
                swap(left, right);
            }
        }
        return -1;
    }
};

// Time:  O(m * n)
// Space: O(m + n)
// bfs solution
class Solution2 {
public:
    int nearestExit(vector<vector<char>>& maze, vector<int>& entrance) {
        static const vector<pair<int, int>> directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        static const char visited = '-';
        maze[entrance[0]][entrance[1]] = visited;
        vector<pair<vector<int>, int>> q = {{entrance, 0}};
        while (!empty(q)) {
            vector<pair<vector<int>, int>> new_q;
            for (const auto& [curr, step] : q) {
                if (curr != entrance &&
                    (curr[0] == 0 || curr[0] == size(maze) - 1 ||
                     curr[1] == 0 || curr[1] == size(maze[0]) - 1)) {
                    return step;
                }
                for (const auto& [dr, dc] : directions) {
                    const auto nr = curr[0] + dr, nc = curr[1] + dc;
                    if (!(0 <= nr && nr < size(maze) &&
                          0 <= nc && nc < size(maze[0]) &&
                          maze[nr][nc] == '.')) {
                        continue;
                    }
                    maze[nr][nc] = visited;
                    new_q.emplace_back(vector<int>({nr, nc}), step + 1);
                }
            }
            q = move(new_q);
        }
        return -1;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    bool sumGame(string num) {
        // (1) if both halfs have '?',
        //     alice will optimally choose 9 or 0 from one half to maximize or minimize the diff of both half sums,
        //     and bob will optimally choose the same number from the other half to minimize or maximize the diff of both half sums.
        //     in the end, it turns that only one half has '?' and the diff of both half sums is still the same as original
        // (2) if smaller half has no '?', then alice wins
        // (3) if smaller half has '?'
        //     (3.1) if cnt of '?' is odd, alice can choose the last number to make the diff of both half sums != 0, then alice wins
        //     (3.2) if cnt of '?' is even
        //           (3.2.1) if larger-smaller = cnt/2 * 9, bob can always make a pair of sum 9 no matter what alice chooses, then bob wins
        //           (3.2.2) if larger-smaller > cnt/2 * 9, alice can always choose 0 no matter what bob chooses, then alice wins
        //           (3.2.3) if larger-smaller < cnt/2 * 9, alice can always choose 9 no matter what bob chooses, then alice wins
        int cnt = 0, total = 0;
        for (int i = 0; i < size(num); ++i) {
            if (num[i] == '?') {
                cnt += (i < size(num) / 2) ? -1 : 1;
            } else {
                total += (i < size(num) / 2) ? num[i] - '0' : -(num[i] - '0');
            }
        }
        return cnt % 2 ? true : total != cnt / 2 * 9;
    }
};

// Time:  O((|E| + |V|) * log|V|) = O(|E| * log|V|),
//        if we can further to use Fibonacci heap, it would be O(|E| + |V| * log|V|)
// Space: O(|E| + |V|) = O(|E|)

// Dijkstra's algorithm
class Solution {
public:
    int minCost(int maxTime, vector<vector<int>>& edges, vector<int>& passingFees) {
        using P = pair<int, int>;
        unordered_map<int, vector<P>> adj;
        for (const auto& edge : edges) {
            int u, v, w;
            tie(u, v, w) = make_tuple(edge[0], edge[1],edge[2]);
            adj[u].emplace_back(v, w);
            adj[v].emplace_back(u, w);
        }

        unordered_map<int, int> best;
        best[0] = 0;
        using T = tuple<int, int, int>;
        priority_queue<T, vector<T>, greater<T>> min_heap;
        min_heap.emplace(passingFees[0], 0, 0);
        while (!empty(min_heap)) {
            const auto [result, u, w] = min_heap.top(); min_heap.pop();
            if (w > maxTime) {  // state with best[u] < w can't be filtered, which may have less cost
                continue;
            }
            if (u == size(passingFees) - 1) {
                return result;
            }
            for (const auto& [v, nw] : adj[u]) {
                if (!best.count(v) || w + nw < best[v]) {  // from less cost to more cost, only need to check state with less time
                    best[v] = w + nw;
                    min_heap.emplace(result + passingFees[v], v, w + nw);
                }
            }
        }
        return -1;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    vector<int> getConcatenation(vector<int>& nums) {
        int n = size(nums);
        nums.resize(2 * n);
        for (int i = 0; i < n; ++i) {
            nums[n + i] = nums[i];
        }
        return nums;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int countPalindromicSubsequence(string s) {
        vector<int> first(26, size(s));
        vector<int> last(26, -1);
        for (int i = 0; i < size(s); ++i) {
            first[s[i] - 'a'] = min(first[s[i] - 'a'], i);
            last[s[i] - 'a'] = max(last[s[i] - 'a'], i);
        }
        int result = 0;
        for (int i = 0; i < 26; ++i) {
            if (first[i] < last[i]) {
                result += size(unordered_set<char>(cbegin(s) + first[i] + 1, cbegin(s) + last[i]));
            }
        }
        return result;
    }
};

// Time:  O(m * 2^m + 3^m + 2^(3 * m) * logn) = O(2^(3 * m) * logn)
// Space: O(2^(2 * m))

// better complexity for small m, super large n
class Solution {
public:
    int colorTheGrid(int m, int n) {
        if (m > n) {
            swap(m, n);
        }
        const int basis = pow(3, m - 1);
        vector<int> masks;
        backtracking(-1, -1, basis, &masks);  // Time: O(2^m), Space: O(2^m)
        assert(size(masks) == 3 * pow(2, m - 1));
        unordered_map<int, int> lookup;
        for (const auto& mask : masks) {  // Time: O(m * 2^m)
            lookup[mask] = normalize(basis, mask);
        }
        unordered_map<int, int> normalized_mask_cnt;
        for (const auto& mask : masks) {
            normalized_mask_cnt[lookup[mask]] = (normalized_mask_cnt[lookup[mask]] + 1) % MOD;
        }
        assert(size(normalized_mask_cnt) == 3 * pow(2, m - 1) / 3 / (m >= 2 ? 2 : 1));  // divided by 3 * 2 is since the first two colors are normalized to speed up performance
        unordered_map<int, vector<int>> adj;
        for (const auto& [mask, _] : normalized_mask_cnt) {  // O(3^m) leaves which are all in depth m => Time: O(3^m), Space: O(3^m)
            backtracking(mask, -1, basis, &adj[mask]);
        }
        unordered_map<int, unordered_map<int, int>> normalized_adj;
        for (const auto& [mask1, mask2s] : adj) {
            for (const auto& mask2 : mask2s) {
                normalized_adj[mask1][lookup[mask2]] = (normalized_adj[mask1][lookup[mask2]] + 1) % MOD;
            }
        }
        // divided by 3 * 2 is since the first two colors in upper row are normalized to speed up performance
        assert(accumulate(cbegin(normalized_adj), cend(normalized_adj), 0,
                          [](const auto& total, const auto& kvp) {
                              return total + size(kvp.second);
                          }) <= 2 * pow(3, m) / 3 / 2);
        // since first two colors in lower row which has at most 3 choices could be also normalized, lower bound is upper bound divided by at most 3
        assert(accumulate(cbegin(normalized_adj), cend(normalized_adj), 0,
                          [](const auto& total, const auto& kvp) {
                              return total + size(kvp.second);
                          }) >= 2 * pow(3, m) / 3 / 2 / 3);
        vector<vector<int>> matrix;
        vector<vector<int>> counts(1);
        for (const auto& [mask1, cnt] : normalized_mask_cnt) {
            matrix.emplace_back();
            for (const auto& [mask2, cnt] : normalized_mask_cnt)  {
                matrix.back().emplace_back(normalized_adj[mask1][mask2]);
            }
            counts[0].emplace_back(cnt);
        }
        const auto& result = matrixMult(counts, matrixExpo(matrix, n - 1));  // Time: O((2^m)^3 * logn), Space: O((2^m)^2)
        return accumulate(cbegin(result[0]), cend(result[0]), 0,
                          [](const auto& total, const auto& x) {
                              return (total + x) % MOD;
                          });  // Time: O(2^m)
    }

private:
    void backtracking(int mask1, int mask2, int basis, vector<int> *result) {  // Time: O(2^m), Space: O(2^m)
        if (!basis) {
            result->emplace_back(mask2);
            return;
        }
        for (int i = 0; i < 3; ++i) {
            if ((mask1 == -1 || mask1 / basis % 3 != i) && (mask2 == -1 || mask2 / (basis * 3) % 3 != i)) {
                backtracking(mask1, mask2 != -1 ? mask2 + i * basis : i * basis, basis / 3, result);
            }
        }
    }

    vector<vector<int>> matrixExpo(const vector<vector<int>>& A, int pow) {
        vector<vector<int>> result(A.size(), vector<int>(A.size()));
        vector<vector<int>> A_exp(A);
        for (int i = 0; i < A.size(); ++i) {
            result[i][i] = 1;
        }
        while (pow) {
            if (pow % 2 == 1) {
                result = matrixMult(result, A_exp);
            }
            A_exp = matrixMult(A_exp, A_exp);
            pow /= 2;
        }
        return result;
    }

    vector<vector<int>> matrixMult(const vector<vector<int>>& A, const vector<vector<int>>& B) {
        vector<vector<int>> result(A.size(), vector<int>(B[0].size()));
        for (int i = 0; i < A.size(); ++i) {
            for (int j = 0; j < B[0].size(); ++j) {
                int64_t entry = 0;
                for (int k = 0; k < B.size(); ++k) {
                    entry = (static_cast<int64_t>(A[i][k]) * B[k][j] % MOD + entry) % MOD;
                }
                result[i][j] = static_cast<int>(entry);
            }
        }
        return result;
    }

    int normalize(int basis, int mask) {
        unordered_map<int, int> norm;
        int result = 0;
        for (; basis; basis /= 3) {
            int x = mask / basis % 3;
            if (!norm.count(x)) {
                norm[x] = size(norm);
            }
            result += norm[x] * basis;
        }
        return result;
    }

    static const int MOD = 1e9 + 7;
};

// Time:  O(n * 3^m)
// Space: O(3^m)
// better complexity for small m, large n
class Solution2 {
public:
    int colorTheGrid(int m, int n) {
        static const int MOD = 1e9 + 7;

        if (m > n) {
            swap(m, n);
        }
        const int basis = pow(3, m - 1);
        const auto& masks = find_masks(m, basis);  // alternative of backtracking, Time: O(2^m), Space: O(2^m)
        assert(size(masks) == 3 * pow(2, m - 1));
        unordered_map<int, int> lookup;
        for (const auto& mask : masks) {  // Time: O(m * 2^m)
            lookup[mask] = normalize(basis, mask);
        }
        unordered_map<int, int> dp;
        for (const auto& mask : masks) {  // normalize colors to speed up performance
            ++dp[lookup[mask]];
        }
        const auto& adj = find_adj(m, basis, dp);  // alternative of backtracking, Time: O(3^m), Space: O(3^m)
        // proof:
        //   'o' uses the same color with its bottom-left one, 
        //   'x' uses the remaining color different from its left one and bottom-left one,
        //   k is the cnt of 'o', 
        //    [3, 1(o), 1(x), 1(o), ..., 1(o), 1(x)] => nCr(m-1, k) * 3 * 2 * 2^k for k in xrange(m) = 3 * 2 * (2+1)^(m-1) = 2*3^m combinations
        //    [2,    2,    1,    2, ...,  2,      1]
        // another proof:
        //   given previous pair of colors, each pair of '?' has 3 choices of colors
        //     [3, ?, ?, ..., ?] => 3 * 2 * 3^(m-1) = 2*3^m combinations
        //         |  |       |
        //         3  3       3
        //         |  |       |
        //     [2, ?, ?, ..., ?]
        unordered_map<int, unordered_map<int, int>> normalized_adj;
        for (const auto& [mask1, mask2s] : adj) {
            for (const auto& mask2 : mask2s) {
                normalized_adj[lookup[mask1]][lookup[mask2]] = (normalized_adj[lookup[mask1]][lookup[mask2]] + 1) % MOD;
            }
        }
        // divided by 3 * 2 is since the first two colors in upper row are normalized to speed up performance
        assert(accumulate(cbegin(normalized_adj), cend(normalized_adj), 0,
                          [](const auto& total, const auto& kvp) {
                              return total + size(kvp.second);
                          }) <= 2 * pow(3, m) / 3 / 2);
        // since first two colors in lower row which has at most 3 choices could be also normalized, lower bound is upper bound divided by at most 3
        assert(accumulate(cbegin(normalized_adj), cend(normalized_adj), 0,
                          [](const auto& total, const auto& kvp) {
                              return total + size(kvp.second);
                          }) >= 2 * pow(3, m) / 3 / 2 / 3);
        for (int i = 0; i < n - 1; ++i) {  // Time: O(n * 3^m), Space: O(2^m)
            assert(size(dp) == 3 * pow(2, m - 1) / 3 / (m >= 2 ? 2 : 1));  // divided by 3 * 2 is since the first two colors are normalized to speed up performance
            unordered_map<int, int> new_dp;
            for (const auto [mask, v] : dp) {
                for (const auto& [new_mask, cnt] : normalized_adj[mask]) {
                    new_dp[lookup[new_mask]] = (new_dp[lookup[new_mask]] + (v * int64_t(cnt)) % MOD) % MOD;
                }
            }
            dp = move(new_dp);
        }
        return accumulate(cbegin(dp), cend(dp), 0,
                          [](const auto& total, const auto& kvp) {
                              return (total + kvp.second) % MOD;
                          });  // Time: O(2^m)
    }

private:
    vector<int> find_masks(int m, int basis) {  // Time: 3 + 3*2 + 3*2*2 + ... + 3*2^(m-1) = 3 * (2^m - 1) = O(2^m), Space: O(2^m)
        vector<int> masks = {0};
        for (int c = 0; c < m; ++c) {
            vector<int> new_masks;
            for (const auto& mask : masks) {
                vector<bool> used(3);
                if (c > 0) {
                    used[mask / basis] = true;  // get left grid
                }
                for (int x = 0; x < 3; ++x) {
                    if (used[x]) {
                        continue;
                    }
                    new_masks.emplace_back((x * basis) + (mask / 3));  // encoding mask
                }
            }
            masks = move(new_masks);
        }
        return masks;
    }

    unordered_map<int, vector<int>> find_adj(int m, int basis, const unordered_map<int, int>& dp) {
        // Time:  3*2^(m-1) * (1 + 2 + 2 * (3/2) + 2 * (3/2)^2 + ... + 2 * (3/2)^(m-2)) =
        //        3*2^(m-1) * (1+2*((3/2)^(m-1)-1)/((3/2)-1)) =
        //        3*2^(m-1) * (1+4*((3/2)^(m-1)-1)) =
        //        3*2^(m-1) * (4*(3/2)^(m-1)-3) =
        //        4*3^m-9*2^(m-1) =
        //        O(3^m),
        // Space: O(3^m)
        unordered_map<int, vector<int>> adj;
        for (const auto& [mask, _] : dp) {  // O(2^m)
            adj[mask].emplace_back(mask);
        }
        for (int c = 0; c < m; ++c) {
            assert(accumulate(cbegin(adj), cend(adj), 0,
                              [](const auto& total, const auto& kvp) {
                                  return total + size(kvp.second);
                              }) == (c ? pow(3, c) * pow(2, m - (c - 1)) : 3 * pow(2, m - 1)) / 3 / (m >= 2 ? 2 : 1));  // divided by 3 * 2 is since the first two colors are normalized to speed up performance
            unordered_map<int, vector<int>> new_adj;
            for (const auto& [mask1, mask2s] : adj) {
                for (const auto& mask : mask2s) {
                    vector<bool> used(3);
                    used[mask % 3] = true;  // get up grid
                    if (c > 0) {
                        used[mask / basis] = true;  // get left grid
                    }
                    for (int x = 0; x < 3; ++x) {
                        if (used[x]) {
                            continue;
                        }
                        new_adj[mask1].emplace_back((x * basis) + (mask / 3));  // encoding mask
                    }
                }
            }
            adj = move(new_adj);
        }
        return adj;
    }

    int normalize(int basis, int mask) {
        unordered_map<int, int> norm;
        int result = 0;
        for (; basis; basis /= 3) {
            int x = mask / basis % 3;
            if (!norm.count(x)) {
                norm[x] = size(norm);
            }
            result += norm[x] * basis;
        }
        return result;
    }
};

// Time:  (m * n grids) * (O(3*3*2^(m-2)) possible states per grid) = O(n * m * 2^m)
// Space: O(3*3*2^(m-2)) = O(2^m)
// better complexity for large m, large n
class Solution3 {
public:
    int colorTheGrid(int m, int n) {
        static const int MOD = 1e9 + 7;

        if (m > n) {
            swap(m, n);
        }
        const int basis = pow(3, m - 1);
        int b = basis;
        unordered_map<int, unordered_map<int, int>> lookup;
        unordered_map<int, int> dp = {{0, 1}};
        for (int idx = 0; idx < m * n; ++idx) {
            int r = idx / m;
            int c = idx % m;
            // sliding window with size m doesn't cross rows:
            //   [3, 2, ..., 2] => 3*2^(m-1) combinations
            assert(r != 0 || c != 0 || size(dp) == 1);
            assert(r != 0 || c == 0 || size(dp) == 3 * pow(2, c - 1) / 3 / (c >= 2 ? 2 : 1));  // divided by 3 * 2 is since the first two colors are normalized to speed up performance
            assert(r == 0 || c != 0 || size(dp) == 3 * pow(2, m - 1) / 3 / (m >= 2 ? 2 : 1));  // divided by 3 * 2 is since the first two colors are normalized to speed up performance
            // sliding window with size m crosses rows:
            //   [*, ..., *, *, 3, 2, ..., 2] => 3*3 * 2^(m-2) combinations
            //   [2, ..., 2, 3, *, *, ..., *]
            assert(r == 0 || c == 0 || size(dp) == (m == 1 ? 1 : m == 2 ? 2 : (3 * 3 * pow(2, m - 2) / 3 / 2)));  // divided by 3 * 2 for m >= 3 is since the first two colors of window are normalized to speed up performance
            unordered_map<int, int> new_dp;
            for (const auto [mask, v] : dp) {
                vector<bool> used(3);
                if (r > 0) {
                    used[mask % 3] = true;  // get up grid
                }
                if (c > 0) {
                    used[mask / basis] = true;  // get left grid
                }
                for (int x = 0; x < 3; ++x) {
                    if (used[x]) {
                        continue;
                    }
                    const auto new_mask = normalize(basis / b, ((x * basis) + (mask / 3)) / b, &lookup) * b;  // encoding mask
                    new_dp[new_mask] = (new_dp[new_mask] + v) % MOD;
                }
            }
            if (b > 1) {
                b /= 3;
            }
            dp = move(new_dp);
        }
        return accumulate(cbegin(dp), cend(dp), 0,
                          [](const auto& total, const auto& kvp) {
                              return (total + kvp.second) % MOD;
                          });  // Time: O(2^m)
    }

    int normalize(int basis, int mask, unordered_map<int, unordered_map<int, int>> *lookup) {  // compute and cache, at most O(3*2^(m-3)) time and space
        if (!(*lookup)[basis].count(mask)) {
            unordered_map<int, int> norm;
            int result = 0;
            for (int b = basis; b; b /= 3) {
                int x = mask / b % 3;
                if (!norm.count(x)) {
                    norm[x] = size(norm);
                }
                result += norm[x] * b;
            }
            (*lookup)[basis][mask] = result;
        }
        return (*lookup)[basis][mask];
    }
};

// Time:  O(n)
// Space: O(n)

class Solution {
public:
    TreeNode* canMerge(vector<TreeNode*>& trees) {
        unordered_set<int> leaf_vals_set;
        unordered_map<int, TreeNode*> val_to_root;
        find_leaves_and_roots(trees, &leaf_vals_set, &val_to_root);    
        const auto& root = find_root(trees, leaf_vals_set, val_to_root);
        return merge_bsts(root, leaf_vals_set, &val_to_root);
    }

private:
    void find_leaves_and_roots(
        const vector<TreeNode*>& trees,
        unordered_set<int> *leaf_vals_set,
        unordered_map<int, TreeNode*> *val_to_root) {

        for (const auto& root : trees) {
            (*val_to_root)[root->val] = root;
            vector<TreeNode*> q = {root};
            while (!empty(q)) {
                vector<TreeNode*> new_q;
                for (const auto& node : q) {
                    if (!node->left && !node->right) {
                        if (node != root) {
                            leaf_vals_set->emplace(node->val);
                        }
                        continue;
                    }
                    if (node->left) {
                        new_q.emplace_back(node->left);
                    }
                    if (node->right) {
                        new_q.emplace_back(node->right);
                    }
                }
                q = move(new_q);
            }
        }
    }

    TreeNode* find_root(
        const vector<TreeNode*>& trees,
        const unordered_set<int>& leaf_vals_set,
        const unordered_map<int, TreeNode*>& val_to_root) {

        TreeNode *root = nullptr;
        for (const auto& node : trees) {
            if (leaf_vals_set.count(node->val)) {
                continue;
            }
            if (root) {  // multiple roots
                return nullptr;
            }
            root = node;
        }
        return root;
    }

    TreeNode* merge_bsts(
        TreeNode *root,
        const unordered_set<int>& leaf_vals_set,
        unordered_map<int, TreeNode*> *val_to_root) {

        if (!root) {
            return nullptr;
        }
        val_to_root->erase(root->val);
        vector<tuple<TreeNode*, int, int>> q = {{root, numeric_limits<int>::min(), numeric_limits<int>::max()}};
        while (!empty(q)) {
            vector<tuple<TreeNode*, int, int>> new_q;
            for (const auto& [node, left, right] : q) {
                if (!(left < node->val && node->val < right)) {
                    return nullptr;
                }
                if (node->left) {
                    if (leaf_vals_set.count(node->left->val) && val_to_root->count(node->left->val)) {
                        node->left = (*val_to_root)[node->left->val];
                        val_to_root->erase(node->left->val);
                    }
                    new_q.emplace_back(node->left, left, node->val);
                }
                if (node->right) {
                    if (leaf_vals_set.count(node->right->val) && val_to_root->count(node->right->val)) {
                        node->right = (*val_to_root)[node->right->val];
                        val_to_root->erase(node->right->val);
                    }
                    new_q.emplace_back(node->right, node->val, right);
                }
            }
            q = move(new_q);
        }
        return empty(*val_to_root) ? root : nullptr;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    bool isDecomposable(string s) {
        if (size(s) % 3 != 2) {
            return false;
        }
        int left;
        for (left = 0; left < size(s); left += 3) {
            if (std::adjacent_find(cbegin(s) + left, cbegin(s) + min(left + 3, int(size(s))),
                                   std::not_equal_to<>()) != cbegin(s) + min(left + 3, int(size(s)))) {
                break;
            }
        }
        int right;
        for (right = size(s) - 1; right >= left + 1  ; right -= 3) {
            if (std::adjacent_find(cbegin(s) + max(right - 2, left), cbegin(s) + right + 1,
                                   std::not_equal_to<>()) != cbegin(s) + right + 1) {
                break;
            }
        }
        return (right + 3) - left == 1;
    }
};

// Time:  O(n)
// Space: O(1)
class Solution2 {
public:
    bool isDecomposable(string s) {
        bool found = false;
        for (int i = 0, l; i < size(s); i += l) {
            l = 1;
            for (int j = i + 1; j < min(i + 3, int(size(s))); ++j, ++l) {
                if (s[j] != s[i]) {
                    break;
                }
            }
            if (l < 2) {
                return false;
            }
            if (l == 2) {
                if (found) {
                    return false;
                }
                found = true;
            }
        }
        return found;
    }
};

// Time:  O(n)
// Space: O(1)
class Solution3 {
public:
    bool isDecomposable(string s) {
        bool found = false;
        for (int i = 0, l = 0; i < size(s); ++i) {
            if (!l || s[i] != s[i - 1]) {
                if (l) {
                    return false;
                }
                l = 1;
                continue;
            }
            ++l;
            if (l == 2) {
                if (i == size(s) - 1 || s[i] != s[i + 1]) {
                    if (found) {
                        return false;
                    }
                    found = true;
                    l = 0;
                }
            } else if (l == 3) {
                l = 0;
            }
        }
        return found;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int canBeTypedWords(string text, string brokenLetters) {
        unordered_set<char> lookup(cbegin(brokenLetters), cend(brokenLetters));
        int result = 0;
        bool broken = false;
        for (const auto& c : text) {
            if (c == ' ') {
              result += int(broken == false);
              broken = false;
            } else if (lookup.count(c)) {
                broken = true;
            }
        }
        return result + int(broken == false);
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int addRungs(vector<int>& rungs, int dist) {
        int result = 0, prev = 0;
        for (const auto& curr : rungs) {
            result += ceil_divide(curr - prev, dist) - 1;
            prev = curr;
        }
        return result;
    }

private:
    int ceil_divide(int a, int b) {
        return (a + (b - 1)) / b;
    }
};

// Time:  O(m * n)
// Space: O(n)

class Solution {
public:
    long long maxPoints(vector<vector<int>>& points) {
        vector<int64_t> dp(cbegin(points[0]), cend(points[0]));
        for (int i = 1; i < size(points); ++i) {
            vector<int64_t> prefix(size(points[i]));
            prefix[0] = dp[0];
            for (int j = 1; j < size(points[i]); ++j) {
                prefix[j] = max(prefix[j - 1], dp[j] + j);
            }
            vector<int64_t> suffix(size(points[i]));
            suffix.back() = dp.back() - (size(points[i]) - 1);
            for (int j = size(points[i]) - 2; j >= 0; --j) {
                suffix[j] = max(suffix[j + 1], dp[j] - j);
            }
            vector<int64_t> new_dp(size(points[i]));
            for (int j = 0; j < size(points[i]); ++j) {
                new_dp[j] = max(prefix[j] - j, suffix[j] + j) + points[i][j];
            }
            dp = move(new_dp);
        }
        return *max_element(cbegin(dp), cend(dp));
    }
};

// Time:  O(nlogk + mlogk), k is max(max(vals), n-1)
// Space: O(n + logk)

class Solution {
private:
    class Trie {
    public:
        Trie(int bit_length)
         : bit_length_(bit_length)
         , nodes_(1) {}

        void insert(int num, int v) {
            int idx = 0;
            for (int i = bit_length_; i >= 0; --i) {
                int curr = (num >> i) & 1;
                if (!nodes_[idx][curr]) {
                    if (!empty(pools_)) {
                        nodes_[idx][curr] = pools_.back(); pools_.pop_back();
                    } else {
                        nodes_.emplace_back();
                        nodes_[idx][curr] = size(nodes_) - 1;
                    }
                }
                int new_idx = nodes_[idx][curr];
                nodes_[new_idx][2] += v;
                if (!nodes_[new_idx][2]) {
                    nodes_[idx][curr] = 0;
                    pools_.emplace_back(new_idx);
                }
                idx = new_idx;
            }
        }

        int query(int num) {
            int result = 0, idx = 0;
            for (int i = bit_length_; i >= 0; --i) {
                int curr = (num >> i) & 1;
                if (nodes_[idx][1 ^ curr]) {
                    idx = nodes_[idx][1 ^ curr];
                    result |= 1 << i;
                } else {
                    idx = nodes_[idx][curr];
                }
            }
            return result;
        }

    private:
        const int bit_length_;
        vector<array<int, 3>> nodes_;
        vector<int> pools_;
    };

public:
    vector<int> maxGeneticDifference(vector<int>& parents, vector<vector<int>>& queries) {
        unordered_map<int, vector<int>> adj;
        for (int i = 0; i < size(parents); ++i) {
            adj[parents[i]].emplace_back(i);
        }
        int max_val = size(parents) - 1;
        unordered_map<int, vector<pair<int, int>>> qs;
        for (int i = 0; i < size(queries); ++i) {
            qs[queries[i][0]].emplace_back(i, queries[i][1]);
            max_val = max(max_val, queries[i][1]);
        }
        vector<int> result(size(queries));
        Trie trie(bit_length(max_val));
        iter_dfs(adj, qs, adj[-1][0], &trie, &result);
        return result;
    }

private:
    void iter_dfs(const unordered_map<int, vector<int>>& adj,
                  const unordered_map<int, vector<pair<int, int>>>& qs,
                  int node,
                  Trie *trie,
                  vector<int> *result) {

        vector<pair<int, int>> stk{{1, node}};
        while (!empty(stk)) {
            const auto [step, node] = stk.back(); stk.pop_back();
            if (step == 1) {
                trie->insert(node, 1);
                if (qs.count(node)) {
                    for (const auto& [i, val] : qs.at(node)) {
                        (*result)[i] = trie->query(val);
                    }
                }
                stk.emplace_back(2, node);
                if (adj.count(node)) {
                    for (const auto& child : adj.at(node)) {
                        stk.emplace_back(1, child);
                    }
                }
            } else if (step == 2) {
                trie->insert(node, -1);
            }
        }
    }

    int bit_length(int x) {
        return x != 0 ? 32 - __builtin_clz(x) : 1;
    }
};

