        unordered_map<int, int> lookup;
        for (const auto& arr : arrays) {
            for (const auto& x : arr) {
                ++lookup[x];
            }
        }
        vector<int> result;
        for (const auto& x : arrays[0]) {
            if (lookup[x] == size(arrays)) {
                result.emplace_back(x);
            }
        }
        return result;
    }
};

