// Time:  O(nlogn)
// Space: O(n)

class Solution {
public:
    int smallestChair(vector<vector<int>>& times, int targetFriend) {
        vector<tuple<int, bool, int>> events;
        for (int i = 0; i < size(times); ++i) {
            events.emplace_back(times[i][0], true, i);
            events.emplace_back(times[i][1], false, i);
        }
        sort(begin(events), end(events));

        unordered_map<int, int> lookup;
        priority_queue<int, vector<int>, greater<int>> min_heap;
        for (const auto& [_, arrival, i] : events) {
            if (!arrival) {
                min_heap.emplace(lookup[i]);
                lookup.erase(i);
                continue;
            }
            if (!empty(min_heap)) {
                lookup[i] = min_heap.top(); min_heap.pop();
            } else {
                lookup[i] = size(lookup);
            }
            if (i == targetFriend) {
                break;
            }
        }
        return lookup[targetFriend];
    }
};

// Time:  O(nlogn)
// Space: O(n)

class Solution {
public:
    vector<vector<long long>> splitPainting(vector<vector<int>>& segments) {
        unordered_map<int, int64_t> counts;
        for (const auto& s : segments) {
            counts[s[0]] += s[2];
            counts[s[1]] -= s[2];
        }
        vector<pair<int, int64_t>> points(cbegin(counts), cend(counts));
        sort(begin(points), end(points));

        vector<vector<long long>> result;
        int64_t overlap = 0, prev = 0;
        for (const auto& [curr, cnt] : points) {
            if (overlap) {
                result.push_back({prev, curr, overlap});
            }
            overlap += cnt;
            prev = curr;
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(n)

class Solution {
public:
    vector<int> canSeePersonsCount(vector<int>& heights) {
        vector<int> result(size(heights));
        vector<int> stk;
        for (int i = 0; i < size(heights); ++i) {
            while (!empty(stk) && heights[stk.back()] < heights[i]) {
                ++result[stk.back()]; stk.pop_back();
            }
            if (!empty(stk)) {
                ++result[stk.back()];
            }
            if (!empty(stk) && heights[stk.back()] == heights[i]) {
                stk.pop_back();
            }
            stk.emplace_back(i);
        }
        return result;
    }
};

