// Time:  O(n + logn + log(logn) + ...) = O(n)
// Space: O(1)

class Solution {
public:
    int getLucky(string s, int k) {
        int total = accumulate(cbegin(s), cend(s), 0,
                               [](const auto& total, const auto& x) {
                                   const auto num = x - 'a' + 1;
                                   return total + num / 10 + num % 10;
                               });
        while (--k && total > 9) {
            int new_total = 0;
            for (; total; total /= 10) {
                new_total += total % 10;
            }
            total = new_total;
        }
        return total;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    string maximumNumber(string num, vector<int>& change) {
        bool mutated = false;
        for (int i = 0; i < size(num); ++i) {
            int d = num[i] - '0';
            if (change[d] < d) {
                if (mutated) {
                    break;
                }
            } else if (change[d] > d) {
                num[i] = '0' + change[d];
                mutated = true;
            }
        }
        return num;
    }
};

// Time:  O(m^2 * (n + m))
// Space: O(m^2)

// weighted bipartite matching solution
class Solution {
public:
    int maxCompatibilitySum(vector<vector<int>>& students, vector<vector<int>>& mentors) {
        vector<vector<int>> cost(size(students), vector<int>(size(mentors)));
        for (int i = 0; i < size(students); ++i) {
            for (int j = 0; j < size(mentors); ++j) {
                cost[i][j] = -score(students[i], mentors[j]);
            }
        }
        return -hungarian(cost).first;
    }

private:
    int score(const vector<int>& s, const vector<int>& m) {
        int result = 0;
        for (int i = 0; i < size(s); ++i) {
            result += int(s[i] == m[i]);
        }
        return result;
    }

    // Template modified from:
    // https://github.com/kth-competitive-programming/kactl/blob/main/content/graph/WeightedMatching.h
    pair<int, vector<int>> hungarian(const vector<vector<int>> &a) {  // Time: O(n^2 * m), Space: O(n + m)
        if (a.empty()) return {0, {}};
        int n = size(a) + 1, m = size(a[0]) + 1;
        vector<int> u(n), v(m), p(m), ans(n - 1);
        for (int i = 1; i < n; ++i) {
            p[0] = i;
            int j0 = 0; // add "dummy" worker 0
            vector<int> dist(m, numeric_limits<int>::max()), pre(m, -1);
            vector<bool> done(m + 1);
            do { // dijkstra
                done[j0] = true;
                int i0 = p[j0], j1, delta = numeric_limits<int>::max();
                for (int j = 1; j < m; ++j) {
                    if (!done[j]) {
                        auto cur = a[i0 - 1][j - 1] - u[i0] - v[j];
                        if (cur < dist[j]) dist[j] = cur, pre[j] = j0;
                        if (dist[j] < delta) delta = dist[j], j1 = j;
                    }
                }
                for (int j = 0; j < m; ++j) {
                    if (done[j]) u[p[j]] += delta, v[j] -= delta;
                    else dist[j] -= delta;
                }
                j0 = j1;
            } while (p[j0]);
            while (j0) { // update alternating path
                int j1 = pre[j0];
                p[j0] = p[j1], j0 = j1;
            }
        }
        for (int j = 1; j < m; ++j) if (p[j]) ans[p[j] - 1] = j - 1;
        return {-v[0], ans}; // min cost
    }
};

// Time:  O(m * (n + 2^m))
// Space: O(2^m)
// dp solution
class Solution2 {
public:
    int maxCompatibilitySum(vector<vector<int>>& students, vector<vector<int>>& mentors) {
        const auto& nums1 = masks(students);
        const auto& nums2 = masks(mentors);
        vector<pair<int, int>> dp(1 << size(nums2));
        for (int mask = 0; mask < size(dp); ++mask) {
            for (int i = 0, bit = 1; i < size(nums2); ++i, bit <<= 1) {
                if ((mask & bit) == 0) {
                    dp[mask | bit] = max(dp[mask | bit],
                                         {dp[mask].first + (size(students[0]) - __builtin_popcount(nums1[dp[mask].second] ^ nums2[i])),
                                          dp[mask].second + 1});
                }
            }
        }
        return dp.back().first;
    }

private:
    vector<int> masks(const vector<vector<int>>& vvi) {
        vector<int> result;
        for (const auto& vi : vvi) {
            int mask = 0;
            for (int i = 0, bit = 1; i < size(vi); ++i, bit <<= 1) {
                if (vi[i]) {
                    mask |= bit;
                }
            }
            result.emplace_back(mask);
        }
        return result;
    }
};

// Time:  O(n * m * l + tlogt + l * t), m is the max number of folders in a path,
//                                    , n is the number of paths
//                                    , l is the max length of folder name
//                                    , t is the size of trie
// Space: O(l * t)

class Solution {
private:
    template <typename T>
    struct PairHash {
        size_t operator()(const pair<T, T>& p) const {
            size_t seed = 0;
            seed ^= std::hash<T>{}(p.first)  + 0x9e3779b9 + (seed<<6) + (seed>>2);
            seed ^= std::hash<T>{}(p.second) + 0x9e3779b9 + (seed<<6) + (seed>>2);
            return seed;
        }
    };

    template<typename T>
    struct VectorPairHash {
        size_t operator()(const std::vector<pair<T, T>>& v) const {
            size_t seed = 0;
            for (const auto& i : v) {
                seed ^= PairHash<T>{}(i)  + 0x9e3779b9 + (seed<<6) + (seed>>2);
            }
            return seed;
        }
    };

    class TrieNode { 
    public:
        void Insert(const vector<string>& s,
                    unordered_map<string, int> *folder_ids,
                    unordered_map<int, string> *id_folders) {
            auto p = this;
            for (const auto& c : s) {
                if (!folder_ids->count(c)) {
                    (*folder_ids)[c] = size(*folder_ids);
                    (*id_folders)[(*folder_ids)[c]] = c;
                }
                const auto folder_id = (*folder_ids)[c];
                if (!p->leaves.count(folder_id)) {
                    p->leaves[folder_id] = make_unique<TrieNode>();
                }
                p = p->leaves[folder_id].get();
            }
        }

        bool deleted = false;
        unordered_map<int, unique_ptr<TrieNode>> leaves;
    };

public:
    vector<vector<string>> deleteDuplicateFolder(vector<vector<string>>& paths) {
        auto trie = make_unique<TrieNode>();
        unordered_map<string, int> folder_ids;
        unordered_map<int, string> id_folders;
        for (const auto& path : paths) {
            trie->Insert(path, &folder_ids, &id_folders);
        }
        unordered_map<int, TrieNode*> lookup;
        unordered_map<vector<pair<int, int>>, int, VectorPairHash<int>> node_ids;
        mark(trie.get(), &lookup, &node_ids);
        vector<vector<string>> result;
        vector<int> path;
        sweep(trie.get(), id_folders, &path, &result);
        return result;
    }

private:
    int mark(TrieNode *node,
             unordered_map<int, TrieNode*> *lookup,
             unordered_map<vector<pair<int, int>>, int, VectorPairHash<int>> *node_ids) {
        vector<pair<int, int>> id_pairs;
        for (const auto& [subfolder_id, child] : node->leaves) {
            id_pairs.emplace_back(subfolder_id, mark(child.get(), lookup, node_ids));
        }
        sort(begin(id_pairs), end(id_pairs));
        if (!node_ids->count(id_pairs)) {
            (*node_ids)[id_pairs] = size(*node_ids);
        }
        int node_id = (*node_ids)[id_pairs];
        if (node_id) {
            if (lookup->count(node_id)) {
                (*lookup)[node_id]->deleted = true;
                node->deleted = true;
            } else {
                (*lookup)[node_id] = node;
            }
        }
        return node_id;
    }

    void sweep(TrieNode *node,
               const unordered_map<int, string>& id_folders,
               vector<int> *path,
               vector<vector<string>> *result) {
        if (!empty(*path)) {
            result->emplace_back();
            transform(cbegin(*path), cend(*path), back_inserter(result->back()),
                      [&id_folders](const auto& i) {
                          return id_folders.at(i);
                      });
        }
        for (const auto& [subfolder_id, child] : node->leaves) {
            if (child->deleted) {
                continue;
            }
            path->emplace_back(subfolder_id);
            sweep(child.get(), id_folders, path, result);
            path->pop_back();
        }
    }
};

// Time:  O(n * m * l + l * tlogt + l * t^2), m is the max number of folders in a path,
//                                          , n is the number of paths
//                                          , l is the max length of folder name
//                                          , t is the size of trie
// Space: O(l * t^2)
class Solution2 {
private:
    class TrieNode { 
    public:
        void Insert(const vector<string>& s) {
            auto p = this;
            for (const auto& c : s) {
                if (!p->leaves.count(c)) {
                    p->leaves[c] = make_unique<TrieNode>();
                }
                p = p->leaves[c].get();
            }
        }

        bool deleted = false;
        map<string, unique_ptr<TrieNode>> leaves;
    };

public:
    vector<vector<string>> deleteDuplicateFolder(vector<vector<string>>& paths) {
        auto trie = make_unique<TrieNode>();
        for (const auto& path : paths) {
            trie->Insert(path);
        }
        unordered_map<string, TrieNode*> lookup;
        mark(trie.get(), &lookup);
        vector<vector<string>> result;
        vector<string> path;
        sweep(trie.get(), &path, &result);
        return result;
    }

private:
    string mark(TrieNode *node, unordered_map<string, TrieNode*> *lookup) {
        string serialized_tree = "(";
        for (const auto& [subfolder, child] : node->leaves) {
            serialized_tree += subfolder + mark(child.get(), lookup);
        }
        serialized_tree += ")";
        if (serialized_tree != "()") {
            if (lookup->count(serialized_tree)) {
                (*lookup)[serialized_tree]->deleted = true;
                node->deleted = true;
            } else {
                (*lookup)[serialized_tree] = node;
            }
        }
        return serialized_tree;
    }

    void sweep(TrieNode *node, vector<string> *path, vector<vector<string>> *result) {
        if (!empty(*path)) {
            result->emplace_back(*path);
        }
        for (const auto& [subfolder, child] : node->leaves) {
            if (child->deleted) {
                continue;
            }
            path->emplace_back(subfolder);
            sweep(child.get(), path, result);
            path->pop_back();
        }
    }
};

// Time:  O(n)
// Space: O(n)

class Solution {
public:
    vector<int> findMaximums(vector<int>& nums) {
        const auto& left = find_bound(nums, 1);
        const auto& right = find_bound(nums, -1);
        vector<int> result(size(nums), -1);
        for (int i = 0; i < size(nums); ++i) {
            result[((right[i] - 1) - left[i]) - 1] = max(result[((right[i] - 1) - left[i]) - 1], nums[i]);
        }
        for (int i = size(nums) - 2; i >= 0; --i) {
            result[i] = max(result[i], result[i + 1]);
        }
        return result;
    }

private:
    vector<int> find_bound(const vector<int>& nums, int d) {
        const int init = d > 0 ? -1 : size(nums);
        const int begin = d > 0 ? 0 : size(nums) - 1;
        const int end = d > 0 ? size(nums) : -1;
        vector<int> result(size(nums), init);
        vector<int> stk = {init};
        for (int i = begin; i != end; i += d) {
            while (stk.back() != init && nums[stk.back()] >= nums[i]) {
                stk.pop_back();
            }
            result[i] = stk.back();
            stk.emplace_back(i);
        }
        return result;
    }
};

// Time:  O(sqrt(n))
// Space: O(1)

class Solution {
public:
    bool isThree(int n) {
        int cnt = 0;
        for (int i = 1; i <= n / i && cnt <= 3; ++i) {
            if (n % i == 0) {
                cnt += (i == n / i) ? 1 : 2;
            }
        }
        return cnt == 3;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    long long numberOfWeeks(vector<int>& milestones) {
        const int64_t total = accumulate(cbegin(milestones), cend(milestones), 0LL);
        const int64_t max_num = *max_element(cbegin(milestones), cend(milestones));
        const int64_t other_total = total - max_num;
