// Time:  O(nlogn)
// Space: O(n)
// segment tree solution
class Solution2 {
public:
    vector<int> longestObstacleCourseAtEachPosition(vector<int>& obstacles) {
        set<int> sorted_obstacles(cbegin(obstacles), cend(obstacles));
        unordered_map<int, int> lookup;
        for (const auto& x : sorted_obstacles) {
            lookup[x] = size(lookup);
        }
        SegmentTree segment_tree(size(lookup));
        vector<int> result;
        for (const auto& x : obstacles) {
            const auto& cnt = segment_tree.query(0, lookup[x]) + 1;
            result.emplace_back(cnt);
            segment_tree.update(lookup[x], lookup[x], cnt);
        }
        return result;
    }

private:
    class SegmentTree {
    public:
        SegmentTree(int N)
            : N_(N),
              tree_(2 * N),
              lazy_(N)
        {
            H_ = 1;
            while ((1 << H_) < N) {
                ++H_;
            }
        }

        void update(int L, int R, int h) {
            L += N_; R += N_;
            int L0 = L, R0 = R;
            while (L <= R) {
                if ((L & 1) == 1) {
                    apply(L++, h);
                }
                if ((R & 1) == 0) {
                    apply(R--, h);
                }
                L >>= 1; R >>= 1;
            }
            pull(L0); pull(R0);
        }

        int query(int L, int R) {
            L += N_; R += N_;
            auto result = 0;
            push(L); push(R);
            while (L <= R) {
                if ((L & 1) == 1) {
                    result = max(result, tree_[L++]);
                }
                if ((R & 1) == 0) {
                    result = max(result, tree_[R--]);
                }
                L >>= 1; R >>= 1;
            }
            return result;
        }

    private:
        int N_, H_;
        vector<int> tree_, lazy_;

        void apply(int x, int val) {
            tree_[x] = max(tree_[x], val);
            if (x < N_) {
                lazy_[x] = max(lazy_[x], val);
            }
        }

        void pull(int x) {
            while (x > 1) {
                x >>= 1;
                tree_[x] = max(tree_[x * 2], tree_[x * 2 + 1]);
                tree_[x] = max(tree_[x], lazy_[x]);
            }
        }

        void push(int x) {
            for (int h = H_; h > 0; --h) {
                int y = x >> h;
                if (lazy_[y] > 0) {
                    apply(y * 2, lazy_[y]);
                    apply(y * 2 + 1, lazy_[y]);
                    lazy_[y] = 0;
                }
            }
        }
    };
};

// Time:  O(n)
// Space: O(n)

class Solution {
public:
    int binarySearchableNumbers(vector<int>& nums) {
        vector<int> right(size(nums) + 1, numeric_limits<int>::max());
        for (int i = size(nums); i >= 1; --i) {
            right[i - 1] = min(right[i], nums[i - 1]);
        }
        unordered_set<int> result;
        int left = numeric_limits<int>::min();
        for (int i = 0; i < size(nums); ++i) {
            if (left <= nums[i] && nums[i] <= right[i + 1]) {
                result.emplace(nums[i]);
            }
            left = max(left, nums[i]);
        }
        return size(result);
    }
};

// Time:  O(n * l + m), n is the number of patterns
//                    , l is the max length of patterns
//                    , m is the length of word     
// Space: O(t)        , t is the total size of ac automata trie

struct AhoNode {
    vector<unique_ptr<AhoNode>> children;
    vector<int> indices;
    AhoNode *suffix;
    AhoNode *output;
    AhoNode()
      : children(26)
      , suffix(nullptr)
      , output(nullptr) {}
};

class AhoTrie {
public:
    AhoTrie(const vector<string>& patterns) : root_(createACTrie(patterns)) {
        node_ = createACSuffixAndOutputLinks(root_.get());
    }

    vector<int> step(char letter) {
        while (node_ && !node_->children[letter - 'a']) {
            node_ = node_->suffix;
        }
        node_ = node_ ? node_->children[letter - 'a'].get() : root_.get();
        return getACNodeOutputs(node_);
    }

    void reset() {
        node_ = root_.get();
    }

private:
    unique_ptr<AhoNode> createACTrie(const vector<string>& patterns) {  // Time:  O(n * l), Space: O(t)
        auto root = make_unique<AhoNode>();
        for (int i = 0; i < patterns.size(); ++i) {
            auto node = root.get();
            for (const auto& c : patterns[i]) {
                if (!node->children[c - 'a']) {
                    node->children[c - 'a'] = make_unique<AhoNode>();
                }
                node = node->children[c - 'a'].get();
            }
            node->indices.emplace_back(i);
        }
        return root;
    }

    AhoNode *createACSuffixAndOutputLinks(AhoNode *root) {  // Time: O(n * l), Space: O(t)
        queue<AhoNode *> q;
        for (int c = 0; c < size(root->children); ++c) {
            auto node = root->children[c].get();
            if (!node) {
                continue;
            }
            q.emplace(node);
            node->suffix = root;
        }

        while (!q.empty()) {
            auto node = q.front(); q.pop();
            for (int c = 0; c < size(node->children); ++c) {
                if (!node->children[c]) {
                    continue;
                }
                auto child = node->children[c].get();
                q.emplace(child);
                auto suffix = node->suffix;
                while (suffix && !suffix->children[c]) {
                    suffix = suffix->suffix;
                }
                child->suffix = suffix ? suffix->children[c].get() : root;
                child->output = !child->suffix->indices.empty() ?
                    child->suffix : child->suffix->output;
            }
        }

        return root;
    }

    vector<int> getACNodeOutputs(AhoNode *node) {  // Total Time: O(n), modified
        vector<int> result;
        if (!lookup_.count(node)) {  // modified
            lookup_.emplace(node);  // modified
            for (const auto& i : node_->indices) {
                result.emplace_back(i);
            }
            auto output = node_->output;
            while (output && !lookup_.count(output)) {  // modified
                lookup_.emplace(output);
                for (const auto& i : output->indices) {  // modified
                    result.emplace_back(i);
                }
                output = output->output;
            }
        }
        return result;
    }

    unique_ptr<AhoNode> root_;
    AhoNode *node_;
    unordered_set<AhoNode *> lookup_;  // modified
};

