// Time:  O(n) ~ O(n^2), O(n) on average
// Space: O(1)

// Tri Partition (aka Dutch National Flag Problem) with virtual index solution
class Solution {
public:
    vector<int> rearrangeArray(vector<int>& nums) {
        int mid = (size(nums) - 1) / 2;
        nth_element(begin(nums), begin(nums) + mid, end(nums));  // O(n) ~ O(n^2) time
        reversedTriPartitionWithVI(nums, nums[mid]);  // O(n) time, O(1) space
        return nums;
    }

private:
    void reversedTriPartitionWithVI(vector<int>& nums, int val) {
        const int N = size(nums) / 2 * 2 + 1;
        #define Nums(i) nums[(1 + 2 * (i)) % N]
        for (int i = 0, j = 0, n = size(nums) - 1; j <= n;) {
            if (Nums(j) > val) {
                swap(Nums(i++), Nums(j++));
            } else if (Nums(j) < val) {
                swap(Nums(j), Nums(n--));
            } else {
                ++j;
            }
        }
    }
};

// Time:  O(nlogn)
// Space: O(n)
// Sorting and reorder solution
class Solution2 {
public:
    vector<int> rearrangeArray(vector<int>& nums) {
        int mid = (size(nums) - 1) / 2;
        sort(begin(nums), end(nums));  // O(nlogn) time
        vector<int> result(size(nums));  // O(n) space
        for (int i = 0, smallEnd = mid;  i < size(nums); i += 2, --smallEnd) {
            result[i] = nums[smallEnd];
        }
        for (int i = 1, largeEnd = size(nums) - 1; i < size(nums); i += 2, --largeEnd) {
            result[i] = nums[largeEnd];
        }
        return result;
    }
};

// Time:  O(min(p, logM))
// Space: O(1)

class Solution {
public:
    int minNonZeroProduct(int p) {
        static const int MOD = 1e9 + 7;
        // max_num = 2^p-1
        uint32_t max_num_mod = submod(powmod(2, p, MOD), 1, MOD);  // max_num % MOD

        // pair_num = max_num-1
        uint32_t pair_product_mod = submod(max_num_mod, 1, MOD); // (max_num_mod-1) % MOD

        // since pair_product^MOD % MOD = pair_product_mod^MOD % MOD  = pair_product_mod
        // => pair_product_mod^(MOD-1) % MOD = 1
        // => pair_product_mod^(pair_cnt) % MOD = pair_product_mod^(pair_cnt%(MOD-1)) %MOD
        uint32_t pair_cnt_mod_m_1 = submod(powmod(2, p - 1, MOD - 1), 1, MOD - 1);  // pair_cnt%(MOD-1)

        // the ans is:
        //   max_num * pair_num^pair_cnt % MOD
        // = max_num_mod * pair_product_mod^(pair_cnt_mod_m_1) % MOD
        return mulmod(max_num_mod, powmod(pair_product_mod, pair_cnt_mod_m_1, MOD), MOD);
    }

private:
    uint32_t addmod(uint32_t a, uint32_t b, uint32_t mod) {  // avoid overflow
        // a %= mod, b %= mod;  // assumed a, b have been mod
        if (mod - a <= b) {
            b -= mod;  // relied on unsigned integer overflow in order to give the expected results
        }
        return a + b;
    }

    uint32_t submod(uint32_t a, uint32_t b, uint32_t mod) {
        // a %= mod, b %= mod;  // assumed a, b have been mod
        return addmod(a, mod - b, mod);
    }

    // reference: https://stackoverflow.com/questions/12168348/ways-to-do-modulo-multiplication-with-primitive-types
    uint32_t mulmod(uint32_t a, uint32_t b, uint32_t mod)  {  // avoid overflow
        uint32_t result = 0;
        if (a < b) {
            swap(a, b);
        }
        while (b > 0)  { 
            if (b % 2 == 1) {
                result = addmod(result, a, mod);
            }
            a = addmod(a, a, mod);
            b /= 2; 
        } 
        return result;
    }

    uint32_t powmod(uint32_t a, uint32_t b, uint32_t mod) {
        a %= mod;
        uint32_t result = 1;
        while (b) {
            if (b & 1) {
                result = mulmod(result, a, mod);
            }
            a = mulmod(a, a, mod);
            b >>= 1;
        }
        return result;
    }
};

// Time:  O(m * n *  α(c)) = O(m * n)
// Space: O(m * n)

class Solution {
public:
    int latestDayToCross(int row, int col, vector<vector<int>>& cells) {
        static const vector<pair<int, int>> directions{{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

        const int start = row * col, end = row * col + 1;
        UnionFind uf(row * col + 2);
        vector<vector<bool>> lookup(row, vector<bool>(col));
        for (int i = size(cells) - 1; i >= 0; --i) {
            const int r = cells[i][0] - 1, c = cells[i][1] - 1;
            for (const auto& [dr, dc] : directions) {
                const int nr = r + dr, nc = c + dc;
                if (!(0 <= nr && nr < row && 0 <= nc && nc < col && lookup[nr][nc])) {
                    continue;
                }
                uf.union_set(index(col, r, c), index(col, nr, nc));
            }
            if (r == 0) {
                uf.union_set(start, index(col, r, c));
            }
            if (r == row - 1) {
                uf.union_set(end, index(col, r, c));
            }
            if (uf.find_set(start) == uf.find_set(end)) {
                return i;
            }
            lookup[r][c] = true;
        }
        return -1;
    }

private:
    int index(int n, int i, int j) {
        return i * n + j;
    }

    class UnionFind {
    public:
        UnionFind(const int n)
         : set_(n)
         , rank_(n)
         , count_(n) {
            iota(set_.begin(), set_.end(), 0);
        }

        int find_set(const int x) {
           if (set_[x] != x) {
               set_[x] = find_set(set_[x]);  // Path compression.
           }
           return set_[x];
        }

        bool union_set(const int x, const int y) {
            int x_root = find_set(x), y_root = find_set(y);
            if (x_root == y_root) {
                return false;
            }
            if (rank_[x_root] < rank_[y_root]) {  // Union by rank.
                set_[x_root] = y_root;
            } else if (rank_[x_root] > rank_[y_root]) {
                set_[y_root] = x_root;
            } else {
                set_[y_root] = x_root;
                ++rank_[x_root];
            }
            --count_;
            return true;
        }

        int size() const {
            return count_;
        }

    private:
        vector<int> set_;
        vector<int> rank_;
        int count_;
    };
};

// Time:  O(|V| + |E|)
// Space: O(|V| + |E|)

// bi-bfs solution
class Solution {
public:
    bool validPath(int n, vector<vector<int>>& edges, int start, int end) {
        unordered_map<int, vector<int>> adj;
        for (const auto& edge : edges) {
            adj[edge[0]].emplace_back(edge[1]);
            adj[edge[1]].emplace_back(edge[0]);
        }
        return bi_bfs(adj, start, end) >= 0;
    }

private:
    int bi_bfs(const unordered_map<int, vector<int>>& adj,
               const int start,
               const int target) {
        unordered_set<int> left = {start}, right = {target};
        unordered_set<int> lookup;
        int steps = 0;
        while (!empty(left)) {
            for (const auto& pos : left) {
                lookup.emplace(pos);
            }
            unordered_set<int> new_left;
            for (const auto& pos : left) {
                if (right.count(pos)) {
                    return steps;
                }
                if (!adj.count(pos)) {
                    continue;
                }
                for (const auto& nei : adj.at(pos)) {
                    if (lookup.count(nei)) {
                        continue;
                    }
                    new_left.emplace(nei);
                }
            }
            left = move(new_left);
            ++steps;
            if (size(left) > size(right)) {
                swap(left, right);
            }
        }
        return -1;
    }
};

