// Time:  O(m * n)
// Space: O(1)

class Solution {
public:
    vector<vector<int>> findFarmland(vector<vector<int>>& land) {
        vector<vector<int>> result;
        for (int i = 0; i < size(land); ++i) {
            for (int j = 0; j < size(land[0]); ++j) {
                if (land[i][j] != 1) {
                    continue;
                }
                int ni = i, nj = j;
                while (ni + 1 < size(land) && land[ni + 1][j]) {
                    ++ni;
                }
                while (nj + 1 < size(land[0]) && land[i][nj + 1]) {
                    ++nj;
                }
                for (int r = i; r <= ni; ++r) {
                    for (int c = j; c <= nj; ++c) {
                        land[r][c] = -1;
                    }
                }
                result.push_back({i, j, ni, nj});
            }
        }
        return result;
    }
};

// Time:  ctor:    O(n)
//        lock:    O(1)
//        unlock:  O(1)
//        upgrade: O(n)
// Space: O(n)

class LockingTree {
public:
    LockingTree(vector<int>& parent)
      : parent_(parent)
      , children_(size(parent)) {
        for (int i = 0; i < size(parent); ++i) {
            if (parent[i] != -1) {
                children_[parent_[i]].emplace_back(i);
            }
        }
    }

    bool lock(int num, int user) {
        if (locked_.count(num)) {
            return false;
        }
        locked_[num] = user;
        return true;
    }

    bool unlock(int num, int user) {
        if (!locked_.count(num) || locked_[num] != user) {
            return false;
        }
        locked_.erase(num);
        return true;
    }

    bool upgrade(int num, int user) {
        for (int node = num; node != -1; node = parent_[node]) {
            if (locked_.count(node)) {
                return false;
            }
        }
        bool result = false;
        vector<int> stk = {num};
        while (!empty(stk)) {
            auto node = stk.back(); stk.pop_back();
            for (const auto& child : children_[node]) {
                if (locked_.count(child)) {
                    locked_.erase(child);
                    result = true;
                }
                stk.emplace_back(child);
            }
        }
        if (result) {
            locked_[num] = user;
        }
        return result;
    }

private:
    const vector<int>& parent_;
    vector<vector<int>> children_;
    unordered_map<int, int> locked_;
};

// Time:  O(n * 2^p), p is the number of primes in [1, n]
// Space: O(2^p)

class Solution {
public:
    int numberOfGoodSubsets(vector<int>& nums) {
        static const int MOD = 1e9 + 7;
        const auto& primes = sieve_of_eratosthenes(*max_element(cbegin(nums), cend(nums)));
        vector<int> dp(1 << size(primes));  // dp[i] = the number of different good subsets of which the total product equals to the product of the primes in bitset i
        dp[0] = 1;
        unordered_map<int, int> cnts;
        for (const auto& x : nums) {
            ++cnts[x];
        }
        for (const auto& [x, cnt] : cnts) {
            if (x == 1 || any_of(cbegin(primes), cend(primes), [&x=x](const auto& p) { return p * p <= x && x % (p * p) == 0;} )) {  // [&x=x] is to avoid the problem that lambda function captures variables declared from structured binding
                continue;
            }
            const uint32_t mask = to_mask(primes, x);
            for (int i = 0; i < size(dp) - 1; ++i) {
                if (i & mask) {
                    continue;
                }
                dp[i | mask] = (dp[i | mask] + static_cast<uint64_t>(cnt) * dp[i]) % MOD;
            }
        }
        return powmod(2, cnts[1], MOD) * (accumulate(cbegin(dp), cend(dp), 0ull,
                                                     [](const auto& total, const auto& x) {
                                                         return (total + x) % MOD;
                                                     }) - 1) % MOD;
    }

private:
    vector<int> sieve_of_eratosthenes(int n) {  // Time: O(n * log(logn)), Space: O(n)
        if (n < 2) {
            return {};
        }
        vector<int> primes = {2};
        vector<bool> is_prime((n + 1) / 2, true);
        for (int i = 1; i < size(is_prime); ++i) {
            if (!is_prime[i]) {
                continue;
            }
            primes.emplace_back(2 * i + 1);
            for (int j = 2 * i * (i + 1); j < size(is_prime); j += (2 * i + 1)) {
                is_prime[j] = false;
            }
        }
        return primes;
    }

    uint32_t to_mask(const vector<int>& primes, int x) {
        uint32_t mask = 0, basis = 1;
        for (const auto& p : primes) {
            if (x % p == 0) {
                mask |= basis;
            }
            basis <<= 1;
        }
        return mask;
    }

    uint32_t powmod(uint32_t a, uint32_t b, uint32_t mod) {
        a %= mod;
        uint64_t result = 1;
        while (b) {
            if (b & 1) {
                result = result * a % mod;
            }
            a = uint64_t(a) * a % mod;
            b >>= 1;
        }
        return result;
    }
};

// Time:  O(n^3)
// Space: O(n)

class Solution {
public:
    int countQuadruplets(vector<int>& nums) {
        int result = 0;
        unordered_map<int, int> lookup;
        lookup[nums.back()] = 1;
        for (int c = size(nums) - 2; c >= 2; --c) {
            for (int b = 1; b < c; ++b) {
                for (int a = 0; a < b; ++a) {
                    if (lookup.count(nums[a] + nums[b] + nums[c])) {
                        result += lookup[nums[a] + nums[b] + nums[c]];
                    }
                }
            }
            ++lookup[nums[c]];
        }
        return result;
    }
};

// Time:  O(n^2) ~ O(n^4)
// Space: O(n^2)
class Solution2 {
public:
    int countQuadruplets(vector<int>& nums) {
        int result = 0;
        unordered_map<int, unordered_set<int>> lookup;
        for (int d = size(nums) - 1; d >= 3; --d) {
            for (int c = 2; c < d; ++c) {
                lookup[nums[d] - nums[c]].emplace(c);
            }
        }
        for (int b = 1; b < size(nums) - 2; ++b) {
            for (int a = 0; a < b; ++a) {
                result += accumulate(cbegin(lookup[nums[a] + nums[b]]), cend(lookup[nums[a] + nums[b]]), 0,
                                     [&b](const auto&total, const auto& x) {
                                         return b < x ? total + 1 : total;
                                     });
            }
        }
        return result;
    }
};

