class Solution {
public:
    int sumOfBeauties(vector<int>& nums) {
        vector<int> right(size(nums), nums.back());
        for (int i = size(nums) - 2; i >= 2; --i) {
            right[i] = min(right[i + 1], nums[i]);
        }
        int result = 0, left = nums.front();
        for (int i = 1; i <= size(nums) - 2; ++i) {
            if (left < nums[i] && nums[i] < right[i + 1]) {
                result += 2;
            } else if (nums[i - 1] < nums[i] && nums[i] < nums[i + 1]) {
                ++result;
            }
            left = max(left, nums[i]);
        }
        return result;
    }
};

// Time:  ctor:  O(1)
//        add:   O(1)
//        count: O(n)
// Space: O(n)

class DetectSquares {
public:
    DetectSquares() {

    }

    void add(vector<int> point) {
        x_to_ys[point[0]].emplace(point[1]);
        ++point_counts_[point[0]][point[1]];
    }

    int count(vector<int> point) {
        int result = 0;
        for (const auto& y : x_to_ys[point[0]]) {
            if (y == point[1]) {
                continue;
            }
            const int dy = point[1] - y;
            result += point_counts_[point[0]][y] * point_counts_[point[0] + dy][point[1]] *  point_counts_[point[0] + dy][y];
            result += point_counts_[point[0]][y] * point_counts_[point[0] - dy][point[1]] *  point_counts_[point[0] - dy][y];
        }
        return result;
    }

private:
    unordered_map<int, unordered_set<int>> x_to_ys;
    unordered_map<int, unordered_map<int, int>> point_counts_;
};


