    }

    void update(int timestamp, int price) {
        if (timestamp > curr_) {
            curr_ = timestamp;
        }
        if (lookup_.count(timestamp)) {
            min_bst_.erase(min_bst_.find(lookup_[timestamp]));
        }
        lookup_[timestamp] = price;
