// Time:  O(n)
// Space: O(n)

class Solution {
public:
    int countHighestScoreNodes(vector<int>& parents) {
        vector<vector<int>> adj(size(parents));  // Space: O(n)
        for (int i = 1; i < size(parents); ++i) {
            adj[parents[i]].emplace_back(i);
        }
        return iter_dfs(adj);
    }
private:
    int iter_dfs(const vector<vector<int>>& adj) {
        pair<int64_t, int> result;
        using RET = shared_ptr<int>;
        auto ret = make_shared<int>();
        vector<tuple<int, int, vector<RET>, RET>> stk;
        stk.emplace_back(1, 0, vector<RET>(), ret);
        while (!empty(stk)) {
            auto [step, i, cnts, ret] = stk.back(); stk.pop_back();
            if (step == 1) {
                vector<RET> cnts(size(adj[i]));
                for (auto& cnt : cnts) {
                    cnt = make_shared<int>();
                }
                stk.emplace_back(2, i, cnts, ret);
                for (int j = 0; j < size(adj[i]); ++j) {
                    stk.emplace_back(1, adj[i][j], vector<RET>(), cnts[j]);
                }
            } else if (step == 2) {
                *ret = accumulate(cbegin(cnts), cend(cnts), 0,
                                  [](const auto& total, const auto& x) {
                                      return total + *x;
                                  }) + 1;
                const int64_t score = max(static_cast<int64_t>(size(adj)) - *ret, 1l) *
                                      accumulate(cbegin(cnts), cend(cnts), 1ul,
                                                 [](const auto& total, const auto& x) {
                                                     return total * *x;
                                                 });
                if (score > result.first) {
                    result = {score, 1};
                } else if (score == result.first) {
                    ++result.second;
                }
            }
        }
        return result.second;
    }
};

// Time:  O(n)
// Space: O(n)
class Solution2 {
public:
    int countHighestScoreNodes(vector<int>& parents) {
        vector<vector<int>> adj(size(parents));  // Space: O(n)
        for (int i = 1; i < size(parents); ++i) {
            adj[parents[i]].emplace_back(i);
        }
        pair<int64_t, int> result;
        dfs(adj, 0, &result);
        return result.second;
    }
private:
    int dfs(const vector<vector<int>>& adj, int i, pair<int64_t, int> *result) {
        vector<int> cnts;
        for (const auto& child : adj[i]) {
            cnts.emplace_back(dfs(adj, child, result));
        }
        const int total = accumulate(cbegin(cnts), cend(cnts), 0) + 1;
        const int64_t score = max(static_cast<int64_t>(size(adj)) - total, 1l) *
                              accumulate(cbegin(cnts), cend(cnts), 1ul,
                                         [](const auto& total, const auto& x) {
                                             return total * x;
                                         });
        if (score > result->first) {
            *result = {score, 1};
        } else if (score == result->first) {
            ++result->second;
        }
        return total;
    }
};

// Time:  O(|V| + |E|)
// Space: O(|E|)

class Solution {
public:
    int minimumTime(int n, vector<vector<int>>& relations, vector<int>& time) {
        vector<vector<int>> adj(n);
        vector<int> in_degree(n);
        for (const auto& relation : relations) {
            adj[relation[0] - 1].emplace_back(relation[1] - 1);
            ++in_degree[relation[1] - 1];
        }
        vector<int> q;
        vector<int> dist(n);
        for (int u = 0; u < n; ++u) {
            if (in_degree[u]) {
                continue;
            }
            q.emplace_back(u);
            dist[u] = time[u];
        }
        while (!empty(q)) {
            vector<int> new_q;
            for (const auto& u : q) {
                for (const auto& v : adj[u]) {
                    dist[v] = max(dist[v], dist[u] + time[v]);
                    --in_degree[v];
                    if (!in_degree[v]) {
                        new_q.emplace_back(v);
                    }
                }
            }
            q = move(new_q);
        }
        return *max_element(cbegin(dist), cend(dist));
    }
};

// Time:  O(s + n * k), n is the number of the word_lens
// Space: O(k)

class Solution {
public:
    int minimumCost(string sentence, int k) {
        vector<int> word_lens, dp;  // dp[i]: min cost of word_lens[-1-i:]
        for (int i = size(sentence) - 1, j = size(sentence) - 1, t = -1; i >= -1; --i) {
            if (i != -1 && sentence[i] != ' ') {
                continue;
            }
            const int l = j - i;
            j = i - 1;
            word_lens.emplace_back(l);
            dp.emplace_back(numeric_limits<int>::max());
            t += l + 1;
            if (t <= k) {
                dp.back() = 0;
                continue;
            }
            int total = l;
            for (int j = size(dp) - 2; j >= 0; --j) {
                dp.back() = min(dp.back(), dp[j] + (k - total) * (k - total));
                total += (word_lens[j] + 1);
                if (total > k) {
                    word_lens = vector<int>(cbegin(word_lens) + j, cend(word_lens));  // minimize len(word_lens) s.t. sum(word_lens) > k
                    dp = vector<int>(cbegin(dp) + j, cend(dp));
                    break;
                }
            }
        }
        return !empty(dp) ? dp.back() : 0;
    }
};

// Time:  O(s + n * k), n is the number of the word_lens
// Space: O(n)
class Solution2 {
public:
    int minimumCost(string sentence, int k) {
        vector<int> word_lens;
        for (int i = 0, j = 0; i <= size(sentence); ++i) {
            if (i != size(sentence) && sentence[i] != ' ') {
                continue;
            }
            word_lens.emplace_back(i - j);
            j = i + 1;
        }
        vector<int> dp(size(word_lens), numeric_limits<int>::max());  // dp[i]: min cost of word_lens[i:]
        int i = size(word_lens) - 1;
        for (int total = -1; i >= 0 && total + (word_lens[i] + 1) <= k; --i) {  // find max i s.t. the length of the last line > k
            total += (word_lens[i] + 1);
            dp[i] = 0;
        }
        for (; i >= 0; --i) {
            for (int j = i + 1, total = word_lens[i]; j < size(dp) && total <= k; total += (word_lens[j++] + 1)) {
                dp[i] = min(dp[i], dp[j] + (k - total) * (k - total));
            }
        }
        return dp[0];
    }
};

// Time:  O(s + n * k), n is the number of the word_lens
