                (*lookup)[i][j][k] = false;
                for (int ni = i + 1; ni <= size(s1); ++ni) {
                    if ((ni == size(s1) || s1[ni] != '0') && memoization(s1, s2, ni, j, k + stoi(s1.substr(i, ni - i)), lookup)) {
                        (*lookup)[i][j][k] = true;
                        break;
                    }
                    if (ni == size(s1) || !isdigit(s1[ni])) {
                        break;
                    }
                }
