                (*lookup)[i][j][k] = false;
                for (int nj = j + 1; nj <= size(s2); ++nj) {
                    if ((nj == size(s2) || s2[nj] != '0') && memoization(s1, s2, i, nj, k - stoi(s2.substr(j, nj - j)), lookup)) {
                        (*lookup)[i][j][k] = true;
                        break;
                    }
                    if (nj == size(s2) || !isdigit(s2[nj])) {
                        break ;
                    }
                }
            } else if (k < 0) {
                (*lookup)[i][j][k] = (i != size(s1)) ? memoization(s1, s2, i + 1, j, k + 1, lookup) : false;
            } else if (k > 0) {
                (*lookup)[i][j][k] = (j != size(s2)) ? memoization(s1, s2, i, j + 1, k - 1, lookup) : false;
            } else {
                (*lookup)[i][j][k] = (i != size(s1) && j != size(s2) && s1[i] == s2[j]) ? memoization(s1, s2, i + 1, j + 1, k, lookup) : false;
            }
        }
        return (*lookup)[i][j][k];
    }
};

// Time:  O(m * n * k), k is the max number of consecutive digits in s1 and s2
// Space: O(min(m, n) * k)
// bottom-up dp
class Solution3 {
public:
    bool possiblyEquals(string s1, string s2) {
        static const int MAX_DIGIT_LEN = 3;
        static const int w = 1 + MAX_DIGIT_LEN;

        if (size(s1) < size(s2)) {
            swap(s1, s2);
        }
        vector<vector<unordered_set<int>>> dp(w, vector<unordered_set<int>>(size(s2) + 1));
        dp[0][0].emplace(0);
        for (int i = 0; i <= size(s1); ++i) {
            if (i >= 1) {
                dp[(i - 1) % w] = vector<unordered_set<int>>(size(s2) + 1);
            }
            if (i != size(s1) && s1[i] == '0') {
                continue;
            }
            for (int j = 0; j <= size(s2); ++j) {
                for (const auto& k : dp[i % w][j]) {
                    if (i != size(s1) && j != size(s2) && s1[i] == s2[j] && k == 0) {
                        dp[(i + 1) % w][j + 1].emplace(k);
                    }
                    if (k <= 0 && i != size(s1)) {
                        if (!isdigit(s1[i])) {
                            if (k) {
                                dp[(i + 1) % w][j].emplace(k + 1);
                            }
                        } else if (s1[i] != '0') {
                            int curr = 0;
                            for (int ni = i; ni < size(s1) && isdigit(s1[ni]); ++ni) {
                                curr = curr * 10 + (s1[ni] - '0');
                                dp[(ni + 1) % w][j].emplace(k + curr);
                            }
                        }
                    }
                    if (k >= 0 && j != size(s2)) {
                        if (!isdigit(s2[j])) {
                            if (k) {
                                dp[i % w][j + 1].emplace(k - 1);
                            }
                        } else if (s2[j] != '0') {
                            int curr = 0;
                            for (int nj = j; nj < size(s2) && isdigit(s2[nj]); ++nj) {
                                curr = curr * 10 + (s2[nj] - '0');
                                dp[i % w][nj + 1].emplace(k - curr);
                            }
                        }
                    }
                }
            }
        }
        return dp[size(s1) % w][size(s2)].count(0);
    }
};

// Time:  O(m * n)
// Space: O(1)

class Solution {
public:
    int numberOfCleanRooms(vector<vector<int>>& room) {
        static const vector<pair<int, int>> directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        int result = 0, r = 0, c = 0, d = 0;
        while (!(room[r][c] & (1 << (d + 1)))) {
            result += (room[r][c] >> 1) == 0;
            room[r][c] |= (1 << (d + 1));
            const auto& [dr, dc] = directions[d];
            const int nr = r + dr, nc = c + dc;
            if ((0 <= nr && nr < size(room)) && (0 <= nc && nc < size(room[0])) && !(room[nr][nc] & 1)) {
                r = nr, c = nc;
            } else {
                d = (d + 1) % 4;
            }
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int countVowelSubstrings(string word) {
        static const int k = 5;
        return atLeastK(word, k);
    }

private:
    int atLeastK(const string& word, int k) {
        static const unordered_set<int> VOWELS = {'a', 'e', 'i', 'o', 'u'};

        unordered_map<int, int> cnt;
        int result = 0;
        for (int i = 0, left = 0, right = 0; i < size(word); ++i) {
            if (!VOWELS.count(word[i])) {
                cnt.clear();
                left = right = i + 1;
                continue;
            }
            ++cnt[word[i]];
            for (; size(cnt) > k - 1; ++right) {
                if (!--cnt[word[right]]) {
                    cnt.erase(word[right]);
                }
            }
            result += right - left;
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(1)
class Solution2 {
public:
    int countVowelSubstrings(string word) {
        static const int k = 5;

        return atMostK(word, k) - atMostK(word, k - 1);
    }

private:
    int atMostK(const string& word, int k) {
        static const unordered_set<int> VOWELS = {'a', 'e', 'i', 'o', 'u'};

        unordered_map<int, int> cnt;
        int result = 0, left = 0;
        for (int right = 0; right < size(word); ++right) {
            if (!VOWELS.count(word[right])) {
                cnt.clear();
                left = right + 1;
                continue;
            }
            ++cnt[word[right]];
            for (; size(cnt) > k; ++left) {
                if (!--cnt[word[left]]) {
                    cnt.erase(word[left]);
                }
            }
            result += right - left + 1;
        }
        return result;
    }
};

