// Time:  O(nlogm), m is the max of quantities
// Space: O(1)

class Solution {
public:
    int minimizedMaximum(int n, vector<int>& quantities) {
        int left = 1, right = *max_element(cbegin(quantities), cend(quantities));
        while (left <= right) {
            const auto& mid = left + (right - left) / 2;
            if (check(n, quantities, mid)) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }

private:
    bool check(int n, const vector<int>& quantities, int x) {
        return accumulate(cbegin(quantities), cend(quantities), 0,
                          [this, &x](const auto& total, const auto& q) {
                              return total + ceil_divide(q, x);
                          }) <= n;
    }

    int ceil_divide(int a, int b) {
        return (a + (b - 1)) / b;
    }
};

// Time:  O(|V| + |E| + 4^(maxTime/min(times))) = O(|V| + |E| + 4^10)
// Space: O(|V| + |E|)

class Solution {
public:
    int maximalPathQuality(vector<int>& values, vector<vector<int>>& edges, int maxTime) {
        vector<vector<pair<int, int>>> adj(size(values));
        for (const auto& edge : edges) {
            adj[edge[0]].emplace_back(edge[1], edge[2]);
            adj[edge[1]].emplace_back(edge[0], edge[2]);
        }
        return iter_dfs(values, adj, maxTime);
    }

private:
    int iter_dfs(const vector<int>& values,
                 const vector<vector<pair<int, int>>>& adj,
                 int maxTime) {

        vector<int> lookup(size(values));
        vector<unordered_set<int>> lookup2(size(values));
        int result = 0;
        vector<tuple<int, int, int, int, int>> stk = {{1, 0, -1, maxTime, 0}};
        while (!empty(stk)) {
            auto [step, u, v, time, total] = stk.back(); stk.pop_back();
            if (step == 1) {
                if (++lookup[u] == 1) {
                    total += values[u];
                }
                if (!u) {
                    result = max(result, total);
                }
                stk.emplace_back(4, u, -1, -1, -1);
                for (const auto& [v, t] : adj[u]) {
                    if (lookup2[u].count(v) || time < t) {  // same directed edge won't be visited twice
                        continue;
                    }
                    stk.emplace_back(3, u, v, -1, -1);
                    stk.emplace_back(1, v, -1, time - t, total);
                    stk.emplace_back(2, u, v, -1, -1);
                }
            } else if (step == 2) {
                lookup2[u].emplace(v);
            } else if (step == 3) {
                lookup2[u].erase(v);
            } else if (step == 4) {
                --lookup[u];
            }
        }
        return result;
    }
};


// Time:  O(|V| + |E| + 4^(maxTime/min(times))) = O(|V| + |E| + 4^10)
// Space: O(|V| + |E|)
class Solution2 {
public:
    int maximalPathQuality(vector<int>& values, vector<vector<int>>& edges, int maxTime) {
        vector<vector<pair<int, int>>> adj(size(values));
        for (const auto& edge : edges) {
            adj[edge[0]].emplace_back(edge[1], edge[2]);
            adj[edge[1]].emplace_back(edge[0], edge[2]);
        }
        vector<int> lookup(size(values));
        vector<unordered_set<int>> lookup2(size(values));
        int result = 0;
        dfs(values, adj, 0, maxTime, 0, &lookup, &lookup2, &result);
        return result;
    }

private:
    void dfs(const vector<int>& values,
             const vector<vector<pair<int, int>>>& adj,
             int u, int time, int total,
             vector<int> *lookup,
             vector<unordered_set<int>> *lookup2,
             int *result) {

        if (++(*lookup)[u] == 1) {
            total += values[u];
        }
        if (!u) {
            *result = max(*result, total);
        }
        for (const auto& [v, t] : adj[u]) {
            if ((*lookup2)[u].count(v) || time < t) {  // same directed edge won't be visited twice
                continue;
            }
            (*lookup2)[u].emplace(v);
            dfs(values, adj, v, time - t, total, lookup, lookup2, result);
            (*lookup2)[u].erase(v);
        }
        --(*lookup)[u];
    }
};

// Time:  O(|V| + |E| + 4^(maxTime/min(times))) = O(|V| + |E| + 4^10)
// Space: O(|V| + |E|)
class Solution3 {
public:
    int maximalPathQuality(vector<int>& values, vector<vector<int>>& edges, int maxTime) {
        vector<vector<pair<int, int>>> adj(size(values));
        for (const auto& edge : edges) {
            adj[edge[0]].emplace_back(edge[1], edge[2]);
            adj[edge[1]].emplace_back(edge[0], edge[2]);
        }
        vector<int> lookup(size(values));
        vector<unordered_set<int>> lookup2(size(values));
        return dfs(values, adj, 0, maxTime, 0, &lookup, &lookup2);
    }

private:
    int dfs(const vector<int>& values,
            const vector<vector<pair<int, int>>>& adj,
            int u, int time, int total,
            vector<int> *lookup,
            vector<unordered_set<int>> *lookup2) {

        if (++(*lookup)[u] == 1) {
            total += values[u];
        }
        int result = !u ? total : 0;
        for (const auto& [v, t] : adj[u]) {
            if ((*lookup2)[u].count(v) || time < t) {  // same directed edge won't be visited twice
                continue;
            }
            (*lookup2)[u].emplace(v);
            result = max(result, dfs(values, adj, v, time - t, total, lookup, lookup2));
            (*lookup2)[u].erase(v);
        }
        --(*lookup)[u];
        return result;
    }
};

// Time:  O(26 * n) = O(n)
// Space: O(26) = O(1)

class Solution {
public:
    int equalCountSubstrings(string s, int count) {
        int result = 0;
        const int max_l = min(size(unordered_set<char>(cbegin(s), cend(s))), size(s) / count);
        for (int l = 1; l <= max_l; ++l) {
            unordered_map<char, int> cnt;
            for (int i = 0, equal_cnt = 0; i < size(s); ++i) {
                equal_cnt += static_cast<int>(++cnt[s[i]] == count);
                if (i >= count * l) {
                    equal_cnt -= static_cast<int>(cnt[s[i - count * l]]-- == count);
                }
                result += static_cast<int>(equal_cnt == l);
            }
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    bool checkAlmostEquivalent(string word1, string word2) {
        static const int K = 3;

        unordered_map<char, int> cnt1;
        for (const auto& c : word1) {
            ++cnt1[c];
        }
        unordered_map<char, int> cnt2;
        for (const auto& c : word2) {
            ++cnt2[c];
        }
        for (const auto& [k, v] : cnt1) {
            if (abs(cnt2[k] - v) > K) {
                return false;
            }
        }
        for (const auto& [k, v] : cnt2) {
            if (abs(cnt1[k] - v) > K) {
                return false;
            }
        }
        return true;
    }
};

// Time:  O(1)
// Space: O(1)

class Robot {
public:
    Robot(int width, int height) : w_(width), h_(height) {

    }

    void move(int num) {
        curr_ += num;
    }

    vector<int> getPos() {
        int n = curr_ % (2 * ((w_ - 1) + h_ - 1));
        if (n < w_) {
            return {n, 0};
        }
        n -= (w_ - 1);
        if (n < h_) {
            return {w_ - 1, n};
        }
        n -= (h_ - 1);
        if (n < w_) {
            return {(w_ - 1) - n, h_ - 1};
        }
        n -= (w_ - 1);
        return {0, (h_ - 1) - n};
    }

    string getDir() {
        int n = curr_ % (2 * ((w_ - 1) + h_ - 1));
        if (n < w_) {
            return n == 0 && curr_ ? "South" : "East";
        }
        n -= (w_ - 1);
        if (n < h_) {
            return "North";
        }
        n -= (h_ - 1);
        if (n < w_) {
            return "West";
        }
        n -= (w_ - 1);
        return "South";
    }

    const int w_;
    const int h_;
    int curr_ = 0;
};

