        sort(begin(meetings), end(meetings), [](const auto& a, const auto& b) { return a[2] < b[2]; });
        UnionFind uf(n);
        uf.union_set(0, firstPerson);
        unordered_set<int> group;
        for (int i = 0; i < size(meetings); ++i) {
            int x = meetings[i][0], y = meetings[i][1];
            group.emplace(x);
            group.emplace(y);
            uf.union_set(x, y);
            if (i + 1 != size(meetings) && meetings[i + 1][2] == meetings[i][2]) {
                continue;
            }
            for (const auto& x: group) {
                if (uf.find_set(x) != uf.find_set(0)) {
                    uf.reset(x);
                }
            }
            group.clear();
        }
        vector<int> result;
        for (int i = 0; i < n; ++i) {
            if (uf.find_set(i) == uf.find_set(0)) {
                result.emplace_back(i);
            }
        }
        return result;
    }

private:
    class UnionFind {
    public:
        UnionFind(int n)
         : set_(n)
         , rank_(n)  {
            iota(set_.begin(), set_.end(), 0);
        }

        int find_set(int x) {
           if (set_[x] != x) {
               set_[x] = find_set(set_[x]);  // Path compression.
           }
           return set_[x];
        }

        bool union_set(int x, int y) {
            x = find_set(x), y = find_set(y);
            if (x == y) {
                return false;
            }
            if (rank_[x] > rank_[y]) {
                swap(x, y);
            }
            set_[x] = y;  // Union by rank.
            if (rank_[x] == rank_[y]) {
                ++rank_[y];
            }
            return true;
        }

        void reset(int x) {
            set_[x] = x;
            rank_[x] = 0;
         }

    private:
        vector<int> set_;
        vector<int> rank_;
    };
};

// Time:  O((|E| + |V|) * log|V|) = O(|E| * log|V|) by using binary heap,
//        if we can further to use Fibonacci heap, it would be O(|E| + |V| * log|V|)
// Space: O(|E| + |V|) = O(|E|)

class Solution {
public:
    int minimumCost(int n, vector<vector<int>>& highways, int discounts) {
        using P = pair<int, int>;
        unordered_map<int, vector<P>> adj;
        for (const auto& highway : highways) {
            int u, v, w;
            tie(u, v, w) = make_tuple(highway[0], highway[1], highway[2]);
            adj[u].emplace_back(v, w);
            adj[v].emplace_back(u, w);
        }

        unordered_map<int, unordered_map<int, int>> best;
        best[0][discounts] = 0;
        using T = tuple<int, int, int>;
        priority_queue<T, vector<T>, greater<T>> min_heap;
        min_heap.emplace(0, 0, discounts);
        while (!empty(min_heap)) {
            auto [total, u, k] = min_heap.top(); min_heap.pop();
            if ((best.count(u) && best[u].count(k) &&  best[u][k] < total)) {
                continue;
            }
            if (u == n - 1) {
                return total;
            }
            for (const auto& [v, w] : adj[u]) {
                if (!best.count(v) ||
                    !best[v].count(k) ||
                    total + w < best[v][k]) {
                    best[v][k] = total + w;
                    min_heap.emplace(total + w, v, k);
                }
                if (k > 0 &&
                    (!best.count(v) ||
                    !best[v].count(k - 1) ||
                    total + w / 2 < best[v][k - 1])) {
                    best[v][k - 1] = total + w / 2;
                    min_heap.emplace(total + w / 2, v, k - 1);
                }
            }
        }
        return -1;
    }
};

// Time:  O(1) ~ O(n), n is 10^3
// Space: O(1)

class Solution {
public:
    vector<int> findEvenNumbers(vector<int>& digits) {
        vector<int> cnt(10);
        for (const auto& d : digits) {
            ++cnt[d];
        }
        vector<int> result, curr;
        backtracking(&curr, &cnt, &result);
        return result;
    }

private:
    void backtracking(vector<int> *curr, vector<int> *cnt, vector<int> *result) {
        static const int k = 3;
        if (size(*curr) == k) {
            result->emplace_back(accumulate(cbegin(*curr), cend(*curr), 0,
                                            [](const auto& total, const auto& x) {
                                                return total * 10 + x;
                                            }));
            return;
        }
        for (int i = 0; i < size(*cnt); ++i) {
            if ((*cnt)[i] == 0 ||
                (empty(*curr) && (i == 0)) ||
                (size(*curr) == k - 1 && i % 2 != 0)) {
                continue;
            }
            --(*cnt)[i];
            curr->emplace_back(i);
            backtracking(curr, cnt, result);
            curr->pop_back();
            ++(*cnt)[i];
        }
    }
};

