// Time:  O(n)
// Space: O(n)

class Solution {
public:
    long long subArrayRanges(vector<int>& nums) {
        int64_t result = 0;
        vector<int> stk;
        for (int i = 0; i <= size(nums); ++i) {
            const int x = (i < size(nums)) ? nums[i] : numeric_limits<int>::max();
            while (!empty(stk) && nums[stk.back()] <= x) {
                const int64_t j = stk.back(); stk.pop_back();
                const int64_t k = !empty(stk) ? stk.back() : -1;
                result += nums[j] * (j - k) * (i - j);
            }
            stk.emplace_back(i);
        }
        stk.clear();
        for (int i = 0; i <= size(nums); ++i) {
            const int x = (i < size(nums)) ? nums[i] : numeric_limits<int>::min();
            while (!empty(stk) && nums[stk.back()] >= x) {
                const int64_t j = stk.back(); stk.pop_back();
                const int64_t k = !empty(stk) ? stk.back() : -1;
                result -= nums[j] * (j - k) * (i - j);
            }
            stk.emplace_back(i);
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int minimumRefill(vector<int>& plants, int capacityA, int capacityB) {
        int result = 0 ;
        int left = 0, right = size(plants) - 1;
        int canA = capacityA, canB = capacityB;
        while (left < right) {
            if (canA < plants[left]) {
                 ++result;
                canA = capacityA;
            }
            canA -= plants[left++];
            if (canB < plants[right]) {
                 ++result;
                canB = capacityB;
            }
            canB -= plants[right--];
        }
        if (left == right) {
            if (max(canA, canB) < plants[left]) {
                ++result;
            }
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(n)

class Solution {
public:
    int maxTotalFruits(vector<vector<int>>& fruits, int startPos, int k) {
        const int max_pos = max(startPos, fruits.back()[0]);
        vector<int> cnt(max_pos + 1);
        for (const auto& x : fruits) {
            cnt[x[0]] += x[1];
        }
        vector<int> prefix(1);
        for (int i = 0; i < size(cnt); ++i) {
            prefix.emplace_back(prefix.back() + cnt[i]);
        }
        int result = 0;
        for (int left_dist = 0; left_dist <= min(startPos, k); ++left_dist) {
            const int right_dist = max(k - 2 * left_dist, 0);
            const int left = startPos - left_dist;
            const int right = min(startPos + right_dist, max_pos);
            result = max(result, prefix[right + 1] - prefix[left]);
        }
        for (int right_dist = 0; right_dist <= min(max_pos - startPos, k); ++right_dist) {
            const int left_dist = max(k - 2 * right_dist, 0);
            const int left = max(startPos - left_dist, 0);
            const int right = startPos + right_dist;
            result = max(result, prefix[right + 1] - prefix[left]);
        }
        return result;
    }
};

