        }
        int curr = result = size(cnt);
        for (int i = k; i < size(candies); ++i) {
            curr += (cnt[candies[i - k]]++ == 0) - (--cnt[candies[i]] == 0);
            result = max(result, curr);
        }
        return result;
    }
};

