// bitmasks, union find
class Solution {
public:
    vector<int> groupStrings(vector<string>& words) {
        UnionFind uf(size(words));
        unordered_map<int, int> lookup;
        for (int i = 0; i < size(words); ++i) {
            const int mask = accumulate(cbegin(words[i]), cend(words[i]), 0, [](int total, int x) {
                return total | (1 << (x - 'a'));
            });
            if (!lookup.count(mask)) {
                lookup[mask] = i;
            }
            uf.union_set(i, lookup[mask]);
            for (int bit = 1; bit <= mask; bit <<= 1) {
                if (mask & bit) {
                    if (!lookup.count(mask ^ bit)) {
                        lookup[mask ^ bit] = i;
                    }
                    uf.union_set(i, lookup[mask ^ bit]);
                }
            }
        }
        return {uf.total(), uf.max_size()};
    }

private:
    class UnionFind {
    public:
        UnionFind(int n)
         : set_(n)
         , rank_(n)
         , size_(n, 1)
         , total_(n) {
            iota(set_.begin(), set_.end(), 0);
        }

        int find_set(int x) {
           if (set_[x] != x) {
               set_[x] = find_set(set_[x]);  // Path compression.
           }
           return set_[x];
        }

        bool union_set(int x, int y) {
            x = find_set(x), y = find_set(y);
            if (x == y) {
                return false;
            }
            if (rank_[x] > rank_[y]) {
                swap(x, y);
            }
            set_[x] = y;  // Union by rank.
            if (rank_[x] == rank_[y]) {
                ++rank_[y];
            }
            size_[y] += size_[x];
            --total_;
            return true;
        }

        int max_size() {
            return *max_element(cbegin(size_), cend(size_));
        }

        int total() {
            return total_;
        }

    private:
        vector<int> set_;
        vector<int> rank_;
        vector<int> size_;
        int total_;
    };
};

// Time:  O(nlogr), r is the max position
// Space: O(r)

template <typename T>
class SegmentTree {
 public:
    explicit SegmentTree(
        int N,
        const function<T(const T&, const T&)>& query_fn,
        const function<T(const T&, const T&)>& update_fn)
      : base_(N),
        tree_(2 * N),
        lazy_(2 * N),
        count_(2 * N, 1),
        query_fn_(query_fn),
        update_fn_(update_fn) {
        H_ = 1;
        while ((1 << H_) < N) {
            ++H_;
        }
        for (int i = N - 1; i >= 1; --i) {
            count_[i] = count_[2 * i] + count_[2 * i + 1];
        }
    }

    void update(int L, int R, const T& val) {
        L += base_;
        R += base_;
        push(L);  // key point
        push(R);  // key point
        int L0 = L, R0 = R;
        for (; L <= R; L >>= 1, R >>= 1) {
            if ((L & 1) == 1) {
                apply(L++, val);
            }
            if ((R & 1) == 0) {
                apply(R--, val);
            }
        }
        pull(L0);
        pull(R0);
    }

    T query(int L, int R) {
        T result{};
        if (L > R) {
            return result;
        }
        L += base_;
        R += base_;
        push(L);
        push(R);
        for (; L <= R; L >>= 1, R >>= 1) {
            if ((L & 1) == 1) {
                result = query_fn_(result, tree_[L++]);
            }
            if ((R & 1) == 0) {
                result = query_fn_(result, tree_[R--]);
            }
        }
        return result;
    }

 private:
    void apply(int x, const T val) {
        tree_[x] = update_fn_(tree_[x], val * count_[x]);
        if (x < base_) {
            lazy_[x] = update_fn_(lazy_[x], val);
        }
    }

    void pull(int x) {
        while (x > 1) {
            x >>= 1;
            tree_[x] = query_fn_(tree_[x * 2], tree_[x * 2 + 1]);
            if (lazy_[x]) {
                tree_[x] = update_fn_(tree_[x], lazy_[x] * count_[x]);
            }
        }
    }

    void push(int x) {
       for (int h = H_; h > 0; --h) {
           int y = x >> h;
           if (lazy_[y]) {
                apply(y * 2, lazy_[y]);
                apply(y * 2 + 1, lazy_[y]);
                lazy_[y] = 0;
            }
        }
    }

    int base_;
    int H_;
    vector<T> tree_;
    vector<T> lazy_;
    vector<T> count_;
    const function<T(const T&, const T&)> query_fn_;
    const function<T(const T&, const T&)> update_fn_;
};

// segment tree
class Solution {
public:
    vector<int> amountPainted(vector<vector<int>>& paint) {
        const auto& query = [] (const auto& x, const auto& y) {
            return x + y;
        };
        const auto& update = [] (const auto& x, const auto& y) {
            return y;
        };
        const int max_pos = (*max_element(cbegin(paint), cend(paint),
            [](const auto& x, const auto& y) { return x[1] < y[1]; }
        ))[1];
        SegmentTree<int> st(max_pos, query, update);
        vector<int> result;
        for (const auto& x : paint) {
            const int cnt = st.query(x[0], x[1] - 1);
            st.update(x[0], x[1] - 1, 1);
            result.emplace_back(st.query(x[0], x[1] - 1) - cnt);
        }
        return result;
    }
};

