// Space: O(1)

// two pointers
class Solution {
public:
    vector<int> findKDistantIndices(vector<int>& nums, int key, int k) {
        vector<int> result;
        int prev = -1;
        for (int i = 0; i < size(nums); ++i) {
            if (nums[i] != key) {
                continue;
            }
            for (int j = max(i - k, prev + 1); j <= min(i + k, static_cast<int>(size(nums) - 1)); ++j) {
                result.emplace_back(j);
            }
            prev = min(i + k, static_cast<int>(size(nums) - 1));
        }
        return result;
    }
};

// Time:  O(a + d), a is the number of grids covered by artifacts, d is the size of dig
// Space: O(d)

// hash table
class Solution {
public:
    int digArtifacts(int n, vector<vector<int>>& artifacts, vector<vector<int>>& dig) {
        unordered_set<int> lookup;
        for (const auto& x : dig) {
            lookup.emplace(x[0] * n + x[1]);
        }
        int result = 0;
        for (const auto& x : artifacts) {
            int cnt = (x[2] - x[0] + 1) * (x[3] - x[1] + 1);
            for (int i = x[0]; i <= x[2]; ++i) {
                for (int j = x[1]; j <= x[3]; ++j) {
                    cnt -= lookup.count(i * n + j);
                }
            }
            if (!cnt) {
                ++result;
            }
        }
        return result;
    }
};


// Time:  O(a + d), a is the number of grids covered by artifacts, d is the size of dig
// Space: O(a)
// hash table
class Solution2 {
public:
    int digArtifacts(int n, vector<vector<int>>& artifacts, vector<vector<int>>& dig) {
        unordered_map<int, int> lookup, cnt;
        for (int idx = 0; idx < size(artifacts); ++idx) {
            const auto& x = artifacts[idx];
            cnt[idx] = (x[2] - x[0] + 1) * (x[3] - x[1] + 1);
            for (int i = x[0]; i <= x[2]; ++i) {
                for (int j = x[1]; j <= x[3]; ++j) {
                    lookup[i * n + j] = idx;
                }
            }
        }
        int result = 0;
        for (const auto& x : dig) {
            if (!lookup.count(x[0] * n + x[1])) {
                continue;
            }
            result += static_cast<int>(--cnt[lookup[x[0] * n + x[1]]] == 0);
        }
        return result;
    }
};

// Time:  O(min(n, k))
// Space: O(1)

// constructive algorithms
class Solution {
public:
    int maximumTop(vector<int>& nums, int k) {
        if (size(nums) == 1 && k % 2 == 1) {
            return -1;
        }
        if (k <= 1) {
            return nums[k];
        }
        int result = 0;
        for (int i = 0; i < min(k + 1, static_cast<int>(size(nums))); ++i) {
            if (i != k - 1) {
                result = max(result, nums[i]);
            }
        }
        return result;
    }
};

// Time:  O((|E| + |V|) * log|V|) = O(|E| * log|V|),
//        if we can further to use Fibonacci heap, it would be O(|E| + |V| * log|V|)
// Space: O(|E| + |V|) = O(|E|)

// dijkstra's algorithm
class Solution {
public:
    long long minimumWeight(int n, vector<vector<int>>& edges, int src1, int src2, int dest) {
        vector<vector<pair<int, int>>> adj1(n), adj2(n);
        for (const auto& e : edges) {
            adj1[e[0]].emplace_back(e[1], e[2]);
            adj2[e[1]].emplace_back(e[0], e[2]);
        }
        const auto& dist1 = dijkstra(adj1, src1);
        const auto& dist2 = dijkstra(adj1, src2);
        const auto& dist3 = dijkstra(adj2, dest);
        int64_t result = INF;
        for (int i = 0; i < n; ++i) {
            if (dist1[i] != INF && dist2[i] != INF && dist3[i] != INF) {
                result = min(result, dist1[i] + dist2[i] + dist3[i]);
            }
        }
        return result != INF ? result : -1;
    }

private:
    vector<int64_t> dijkstra(const vector<vector<pair<int, int>>>& adj, int start) {
        vector<int64_t> best(size(adj), INF);
        best[start] = 0;
        priority_queue<pair<int64_t, int>, vector<pair<int64_t, int>>, greater<pair<int64_t, int>>> min_heap;
        min_heap.emplace(0, start);
        while (!empty(min_heap)) {
            const auto [curr, u] = min_heap.top(); min_heap.pop();
            if (best[u] < curr) {
                continue;
            }
            for (const auto& [v, w] : adj[u]) {
                if (best[v] - curr <= w) {
                    continue;
                }
                best[v] = curr + w;
                min_heap.emplace(curr + w, v);
            }
        }
        return best;
    }

    const int64_t INF = numeric_limits<int64_t>::max();
};

// Time:  O(|V| + |E|)
// Space: O(|V| + |E|)

// graph, dfs, bfs
class Solution {
public:
    vector<int> distanceToCycle(int n, vector<vector<int>>& edges) {
        vector<vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].emplace_back(e[1]);
            adj[e[1]].emplace_back(e[0]);
        }
        return bfs(adj, iter_dfs(adj));
    }

private:
    vector<int> cycle(const vector<int>& parent, int v, int u) {
        vector<int> result = {parent[v], v};
        for (; u != parent[v]; u = parent[u]) {
            result.emplace_back(u);
        }
        return result;
    }

    vector<int> iter_dfs(const vector<vector<int>>& adj) {
        vector<int> stk = {0};
        vector<int> parent(size(adj), -2);
        parent[0] = -1;
        while (!empty(stk)) {
            const int u = stk.back(); stk.pop_back();
            for (const auto& v : adj[u]) {
                if (parent[v] != -2) {
                    if (v == parent[u]) {
                        continue;
                    }
                    return cycle(parent, v, u);
                }
                parent[v] = u;
                stk.emplace_back(v);
            }
        }
        return {};
    }

    vector<int> bfs(const vector<vector<int>>& adj, vector<int> q) {
        vector<int> result(size(adj), -1);
        for (const auto& x : q) {
            result[x] = 0;
        }
        for (int d = 1; !empty(q); ++d) {
            vector<int> new_q;
            for (const auto& u : q) {
                for (const auto& v : adj[u]) {
                    if (result[v] != -1) {
                        continue;
                    }
                    result[v] = d;
                    new_q.emplace_back(v);
                }
            }
            q = move(new_q);
        }
        return result;
    }
};

