// string
class Solution {
public:
    int countPrefixes(vector<string>& words, string s) {
        const auto& startsWith = [](const auto& s, const auto& prefix) {
            return (size(prefix) <= size(s) && s.compare(0, size(prefix), prefix, 0, size(prefix)) == 0);
        };
        return accumulate(cbegin(words), cend(words), 0,
                          [&](const auto& total, const auto& x) {
                              return total + startsWith(s, x);
                          });
    }
};

// Time:  O(n)
// Space: O(1)

// prefix sum
class Solution {
public:
    int minimumAverageDifference(vector<int>& nums) {
        int64_t total = accumulate(cbegin(nums), cend(nums), 0ll);
        int64_t mn = numeric_limits<int64_t>::max(), idx = -1;
        int64_t prefix = 0;
        for (int i = 0; i < size(nums); ++i) {
            prefix += nums[i];
            const int a = prefix / (i + 1);
            const int b = i + 1 < size(nums) ? (total - prefix) / (size(nums) - (i + 1)) : 0;
            const int diff = abs(a - b);
            if (diff < mn) {
                mn = diff;
                idx = i;
            }
        }
        return idx;
    }
};

// Time:  O(m * n)
// Space: O(m * n)

// array, simulation
class Solution {
public:
    int countUnguarded(int m, int n, vector<vector<int>>& guards, vector<vector<int>>& walls) {
        static const vector<pair<int, int>> directions{{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        enum State {GREEN, RED, BLOCK};
        vector<vector<int>> grid(m, vector<int>(n, GREEN));
        for (const auto& x : guards) {
            grid[x[0]][x[1]] = BLOCK;
        }
        for (const auto& x : walls) {
            grid[x[0]][x[1]] = BLOCK;
        }
        for (const auto& x : guards) {
            for (const auto& [dr, dc] : directions) {
                for (int nr = x[0] + dr, nc = x[1] + dc;
                     0 <= nr && nr < m && 0 <= nc && nc < n && grid[nr][nc] != BLOCK;
                     nr += dr, nc += dc) {
                    grid[nr][nc] = RED;
                }
            }
        }
        int result = 0;
        for (const auto& row : grid) {
            for (const auto& x : row) {
                result += (x == GREEN);
            }
        }
        return result;
    }
};

