                q = move(new_q);
            }
            return dist;
        };
        vector<vector<int>> dist(n);
        for (int i = 0; i < n; ++i) {
            dist[i] = bfs(i);
        }
        vector<int> result;
        for (const auto& q : query) {
            int j = -1;
            for (int i = 0; i < n; ++i) {
                if (dist[q[0]][q[2]] + dist[q[2]][q[1]] - 2 * dist[q[2]][i] == dist[q[0]][i] + dist[i][q[1]]) {
                    if (j == -1 || dist[q[2]][j] < dist[q[2]][i]) {
                        j = i;
                    }
                }
            }
            result.emplace_back(j);
        }
        return result;
    }
};

