                stk->pop_back();
                ++cnt;
            }
            if (!empty(*stk)) {
                ++cnt;
            }
            if (empty(*stk) || stk->back() != h) {
                stk->emplace_back(h);
            }
            return cnt;
        };

        for (int i = 0; i < size(heights); ++i) {
