                result[i][j] += count(heights[i][j], &stk);
            }
        }
        for (int j = 0; j < size(heights[0]); ++j) {
            vector<int> stk;
            for (int i = size(heights) - 1; i >= 0; --i) {
                result[i][j] += count(heights[i][j], &stk);
            }
        }
