class Solution2 {
public:
    string discountPrices(string sentence, int discount) {
        const auto& format = [&](const auto& x) {
            string result;
            const auto& integers = to_string(stoll(x) * (100 - discount) / 100);
            const auto& decimals = to_string(stoll(x) * (100 - discount) % 100);
