        for (int i = 1; i < n; ++i) {
            dp[i % forget] = (((i - 1 ? dp[(i - 1) % forget] : 0) - dp[i % forget] + dp[((i - delay) % forget + forget) % forget]) % MOD + MOD) % MOD;

        }
