            }
            int i = -1;
            if (!empty(unused)) {
                i = unused.top(); unused.pop();
                used.emplace(e, i);
            } else {
                const int64_t e2 = used.top().first;
                i = used.top().second;
                used.pop();
                used.emplace(e2 + (e - s), i);
            }
            ++result[i];
