        int result = 0;
        int left = -1, right = size(nums);
        int64_t l = nums[++left], r = nums[--right];
        while (left < right) {
            if (l == r) {
                l = nums[++left];
                r = nums[--right];
                continue;
            }
            if (l < r) {
                l += nums[++left];
            } else {
                r += nums[--right];
            }
            ++result;
        }
        return result;
    }
};

