        for (const auto& c : word) {
            --cnt[c - 'a'];
            int i = 0;
            for (int prev = 0; i < size(cnt); ++i) {
                if (!cnt[i]) {
                    continue;
                }
                if (prev && prev != cnt[i]) {
                    break;
                }
                prev = cnt[i];
            }
            if (i == size(cnt)) {
