// bst
class Allocator {
public:
    Allocator(int n) : avails_{{0, n}} {
    }

    int allocate(int size, int mID) {
        for (const auto [l, s] : avails_) {
            if (s < size) {
                continue;
            }
            avails_.erase(l);
            lookup_[mID].emplace_back(l, size);
            if (s - size > 0) {
                avails_.emplace(l + size, s - size);
            }
            return l;
        }
        return -1;
    }

    int free(int mID) {
        if (!lookup_.count(mID)) {
            return 0;
        }
        int result = 0;
        for (const auto& [l, s] : lookup_[mID]) {
            auto it = avails_.emplace(l, s).first;
            if (next(it) != end(avails_) && it->first + it->second == next(it)->first) {
                it->second += next(it)->second;
                avails_.erase(next(it));
            }
            if (it != begin(avails_) && prev(it)->first + prev(it)->second == it->first) {
                prev(it)->second += it->second;
                avails_.erase(it);
            }
            result += s;
        }
        lookup_.erase(mID);
        return result;
    }

private:
    map<int, int> avails_;
    unordered_map<int, vector<pair<int, int>>> lookup_;
};

// Time:  O((m * n + q) * log(m * n))
// Space: O(m * n)

// bfs, heap, prefix sum, binary search
class Solution {
public:
    vector<int> maxPoints(vector<vector<int>>& grid, vector<int>& queries) {
        static const vector<pair<int, int>> directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

        priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<tuple<int, int, int>>> min_heap;
        min_heap.emplace(grid[0][0], 0, 0);
        vector<vector<bool>> lookup(size(grid), vector<bool>(size(grid[0])));
        lookup[0][0] = true;
        unordered_map<int, int> cnt;
        int mx = 0;
        while (!empty(min_heap)) {
            const auto [curr, i, j] = min_heap.top(); min_heap.pop();
            mx = max(mx, curr);
            ++cnt[mx];
            for (const auto& [di, dj] : directions) {
                const int ni = i + di, nj = j + dj;
                if (!(0 <= ni && ni < size(grid) &&
                      0 <= nj && nj < size(grid[0]) &&
                      !lookup[ni][nj])) {
                    continue;
                }
                lookup[ni][nj] = true;
                min_heap.emplace(grid[ni][nj], ni, nj);
            }
        }
        vector<int> vals;
        for (const auto& [k, _] : cnt) {
            vals.emplace_back(k);
        }
        sort(begin(vals), end(vals));
        vector<int> prefix(size(vals) + 1);
        for (int i = 0; i < size(vals); ++i) {
            prefix[i + 1] = prefix[i] + cnt[vals[i]];
        }
        vector<int> result(size(queries));
        for (int i = 0; i < size(queries); ++i) {
            result[i] = prefix[distance(cbegin(vals), lower_bound(cbegin(vals), cend(vals), queries[i]))];
        }
        return result;
    }
};

