// sliding window, two pointers
class Solution {
public:
    int takeCharacters(string s, int k) {
        vector<int> cnt(3);
        for (const auto& c : s) {
            ++cnt[c - 'a'];
        }
        if (*min_element(cbegin(cnt), cend(cnt)) < k) {
            return -1;
        }
        int result = 0;
        for (int right = 0, left = 0; right < size(s); ++right) {
            --cnt[s[right] - 'a'];
            while (cnt[s[right] - 'a'] < k) {
                ++cnt[s[left++] - 'a'];
            }
            result = max(result, right - left + 1);
        }
        return size(s) - result;
    }
};

// Time:  O(nlogr), r = max(price)-min(price)
// Space: O(1)

// binary search, greedy
class Solution {
public:
    int maximumTastiness(vector<int>& price, int k) {
        const auto& check = [&](int x) {  // find max cnt if smallest absolute difference >= x
            int cnt = 0, prev = 0;
            for (int i = 0, j = 0; i < size(price); ++i) {
                if (prev && price[i] - prev < x) {
                    continue;
                }
                if (++cnt == k) {
                    break;
                }
                prev = price[i];
            }
            return cnt >= k;
        };

        sort(begin(price), end(price));
        int left = 1, right = price.back() - price.front();
        while (left <= right) {
            const int mid = left + (right - left) / 2;
            if (!check(mid)) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return right;
    }
};

// Time:  O(n * k)
// Space: O(k)

// knapsack dp
class Solution {
public:
    int countPartitions(vector<int>& nums, int k) {
        static const int MOD = 1e9 + 7;

        if (accumulate(cbegin(nums), cend(nums), 0ll) < 2 * k) {
            return 0;
        }
        int result = 1;
        vector<int> dp(k);
        dp[0] = 1;
        for (const auto& x : nums) {
            for (int i = k - 1 - x; i >= 0; --i) {
                dp[i + x] = (dp[i + x] + dp[i]) % MOD;
            }
            result = (result * 2) % MOD;
       }
       return ((result - 2 * accumulate(cbegin(dp), cend(dp), 0, [&](const auto& total, const auto& x) {
           return (total + x) % MOD;
       })) % MOD + MOD) % MOD;
    }
};

