        const auto& ceil_divide = [](const auto& a, const auto& b) {
            return (a + b - 1) / b;
        };

        int64_t result = 0;
        make_heap(begin(nums), end(nums));
        while (k-- && !empty(nums)) {
            int x = nums.front();
