        vector<int> cnt1(26);
        for (const auto& c : word1) {
            ++cnt1[c - 'a'];
        }
        vector<int> cnt2(26);
        for (const auto& c : word2) {
            ++cnt2[c - 'a'];
        }
        const auto& op = [](const auto& total, const auto& x) {
            return total + static_cast<int>(x != 0);
        };
        const int c1 = accumulate(cbegin(cnt1), cend(cnt1), 0, op);
        const int c2 = accumulate(cbegin(cnt2), cend(cnt2), 0, op);
        for (int i = 0; i < size(cnt1); ++i) {
            if (!cnt1[i]) {
                continue;
            }
            for (int j = 0; j < size(cnt2); ++j) {
                if (!cnt2[j]) {
                    continue;
                }
                if (i == j) {
                    if (c1 == c2) {
                        return true;
                    }
                } else {
                    int new_c1 = c1, new_c2 = c2;
                    if (cnt1[i] == 1) {
                        --new_c1;
                    }
                    if (cnt1[j] == 0) {
                        ++new_c1;
                    }
                    if (cnt2[j] == 1) {
                        --new_c2;
                    }
                    if (cnt2[i] == 0) {
                        ++new_c2;
                    }
                    if (new_c1 == new_c2) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
};

// Time:  O(k + nlogk)
// Space: O(k)

// heap, simulation
class Solution {
public:
    int findCrossingTime(int n, int k, vector<vector<int>>& time) {
        vector<pair<int, int>> workers;
        for (int i = 0; i < k; ++i) {
            workers.emplace_back(time[i][0] + time[i][2], i);
        }
        priority_queue<pair<int, int>> left_bridge(cbegin(workers), cend(workers)), right_bridge;
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> left_ware, right_ware;
        int curr = 0;
        while (n) {
            while (!empty(left_ware) && left_ware.top().first <= curr) {
                const auto [_, i] = left_ware.top(); left_ware.pop();
                left_bridge.emplace(time[i][0] + time[i][2], i);
            }
            while (!empty(right_ware) && right_ware.top().first <= curr) {
                const auto [_, i] = right_ware.top(); right_ware.pop();
                right_bridge.emplace(time[i][0] + time[i][2], i);
            }
            if (!empty(right_bridge)) {
                const auto [_, i] = right_bridge.top(); right_bridge.pop();
                curr += time[i][2];
                left_ware.emplace(curr + time[i][3], i);
                --n;
            } else if (!empty(left_bridge) && n - size(right_ware)) {
                const auto [_, i] = left_bridge.top(); left_bridge.pop();
                curr += time[i][0];
                right_ware.emplace(curr + time[i][1], i);
            } else {
                curr = min(!empty(left_ware) ? left_ware.top().first : numeric_limits<int>::max(),
                           !empty(right_ware) ? right_ware.top().first : numeric_limits<int>::max());
            }
        }
        return curr;
    }
};

// Time:  O(n), n = maxLength
// Space: O(w), w = max(oneGroup, zeroGroup)+1

// dp
class Solution {
public:
    int goodBinaryStrings(int minLength, int maxLength, int oneGroup, int zeroGroup) {
        static const int MOD = 1e9 + 7;

        int result = 0;
        const int w = max(oneGroup, zeroGroup) + 1;
        vector<int> dp(w);
        for (int i = 0; i <= maxLength; ++i) {
            dp[i % w] = i == 0 ? 1 : 0;
            if (i - oneGroup >= 0) {
                dp[i % w] = (dp[i % w] + dp[(i - oneGroup) % w]) % MOD;
            }
            if (i - zeroGroup >= 0 ) {
                dp[i % w] = (dp[i % w] + dp[(i - zeroGroup) % w]) % MOD;
            }
            if (i >= minLength) {
                result = (result + dp[i % w]) % MOD;
            }
        }
        return result;
    }
};

// Time:  O(n), n = maxLength
// Space: O(w), w = max(oneGroup, zeroGroup)+1
// dp
class Solution2 {
public:
    int goodBinaryStrings(int minLength, int maxLength, int oneGroup, int zeroGroup) {
        static const int MOD = 1e9 + 7;

        int result = 0;
        const int w = max(oneGroup, zeroGroup) + 1;
        vector<int> dp(w);
        dp[0] = 1;
        for (int i = 0; i <= maxLength; ++i) {
            if (i >= minLength) {
                result = (result + dp[i % w]) % MOD;
            }
            if (i + oneGroup <= maxLength) {
                dp[(i + oneGroup) % w] = (dp[(i + oneGroup) % w] + dp[i % w]) % MOD;
            }
            if (i + zeroGroup <= maxLength) {
                dp[(i + zeroGroup) % w] = (dp[(i + zeroGroup) % w] + dp[i % w]) % MOD;
            }
            dp[i % w] = 0;
        }
        return result;
    }
};

