            return false;
        }
        vector<pair<int, int>> lookup(size(grid) * size(grid[0]));
        for (int i = 0; i < size(grid); ++i) {
            for (int j = 0; j < size(grid[0]); ++j) {
                lookup[grid[i][j]] = {i, j};
            }
        }
        for (int i = 0; i + 1 < size(lookup); ++i) {
