// tree, bfs
class Solution {
public:
    int collectTheCoins(vector<int>& coins, vector<vector<int>>& edges) {
        static const int DISTANCE = 2;

        vector<unordered_set<int>> adj(size(coins));
        for (const auto& e : edges) {
            adj[e[0]].emplace(e[1]);
            adj[e[1]].emplace(e[0]);
        }
        int n = size(coins);
        for (int i = 0; i < size(coins); ++i) {
            int u = i;
            while (size(adj[u]) == 1 && !coins[u]) {
                const int v = *cbegin(adj[u]);
                adj[u].erase(v);
                adj[v].erase(u);
                --n;
                u = v;
            }
        }
        vector<int> q;
        for (int u = 0; u < size(coins); ++u) {
            if (size(adj[u]) == 1) {
                q.emplace_back(u);
            }
        }
        for (int _ = 0; _ < DISTANCE; ++_) {
            vector<int> new_q;
            for (const auto& u : q) {
                if (empty(adj[u])) {
                    assert(n == 1);
                    break;
                }
                const int v = *cbegin(adj[u]);
                adj[u].erase(v);
                adj[v].erase(u);
                --n;
                if (size(adj[v]) == 1) {
                    new_q.emplace_back(v);
                }
            }
            q = move(new_q);
        }
        return (n - 1) * 2;
    }
};

// Time:  O(mlogm + nlogn + (m + n) * logr), r = 2*(max(max(hens), max(grains))-min(min(hens), min(grains))
// Space: O(1)

// binary search, greedy
class Solution {
public:
    int minimumTime(vector<int>& hens, vector<int>& grains) {
        const auto& check = [&](const int x) {
            int i = 0;
            for (const auto& h : hens) {
                int c = x;
                if (h - grains[i] > x) {
                    return false;
                } else if (h - grains[i] > 0) {
                    const int d = h - grains[i];
                    c = max(x - 2 * d, (x - d) / 2);  // # max(go left then right, go right then left)
                }
                for (; i < size(grains) && grains[i] <= h + c; ++i);
                if (i == size(grains)) {
                    return true;
                }
            }
            return false;
        };

        sort(begin(hens), end(hens));
        sort(begin(grains), end(grains));
        int left = 0, right = 2 * (max(hens.back(), grains.back()) - min(hens.front(), grains.front()));
        while (left <= right) {
            const int mid = left + (right - left) / 2;
            if (check(mid)) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }
};

