        for (int i = 0; i < size(chars); ++i) {
            lookup[chars[i]] = vals[i];
        }
        const auto& kadane = [&](const auto& s) {
            int result = 0, curr = 0;
            for (const auto& c : s) {
                curr = max(curr + (lookup.count(c) ? lookup[c] : c - 'a' + 1), 0);
