public:
    int findTheLongestBalancedSubstring(string s) {
        int result = 0;
        vector<int> prev(2), cnt(2);
        for (const auto& c : s) {
            ++cnt[c - '0'];
            if (cnt[(c - '0') ^ 1]) {
                prev[(c - '0') ^ 1] = cnt[(c - '0') ^ 1];
                cnt[(c - '0') ^ 1] = 0;
            }
            result = max(result, 2 * min(prev[0], cnt[1]));
        }
        return result;
    }
};

