// segment tree
class Solution4 {
private:
    template<typename T>
    struct VectorHash {
        size_t operator()(const std::vector<T>& v) const {
            size_t seed = 0;
            for (const auto& i : v) {
                seed ^= std::hash<T>{}(i)  + 0x9e3779b9 + (seed<<6) + (seed>>2);
            }
            return seed;
        }
    };

public:
    vector<int> beautifulPair(vector<int>& nums1, vector<int>& nums2) {
        static const int INF = numeric_limits<int>::max();

        vector<vector<int>> points;
        for (int i = 0; i < size(nums1); ++i) {
            points.push_back({nums1[i], nums2[i]});
        }
        vector<int> result(3, INF);
        unordered_map<vector<int>, int, VectorHash<int>> lookup;
        for (int i = size(points) - 1; i >= 0; --i) {
            if (lookup.count(points[i])) {
                result = min(result, vector<int>{0, i, lookup[points[i]]});
            }
            lookup[points[i]] = i;
        }
        if (result[0] == 0) {
            return {result[1], result[2]};
        }
        vector<int> order(size(points));
        iota(begin(order), end(order), 0);
        sort(begin(order), end(order), [&](const auto& a, const auto& b) {
            return points[a][0] < points[b][0];
        });
        const auto& dist = [&](auto a, auto b) {
            if (a > b) {
                swap(a, b);
            }
            return vector<int>{abs(points[a][0] - points[b][0]) + abs(points[a][1] - points[b][1]), a, b};
        };

        unordered_set<int> y_set;
        for (const auto& p : points) {
            y_set.emplace(p[1]);
        }
        vector<int> sorted_y(cbegin(y_set), cend(y_set));
        sort(begin(sorted_y), end(sorted_y));
        unordered_map<int, int> y_to_idx;
        for (int i = 0; i < size(sorted_y); ++i) {  // coordinate compression
            y_to_idx[sorted_y[i]] = i;
        }
        SegmentTree st1(size(y_to_idx)), st2(size(y_to_idx));
        for (const auto& i : order) {
            int j = -st1.query(0, y_to_idx[points[i][1]] - 1)[1];  // min((xi-xj)+(yi-yj) for j in range(y_to_idx[points[i][1])) = (xi+yi)-max((xj+yj) for j in range(y_to_idx[points[i][1]))
            if (j != INF) {
                assert(points[j][1] < points[i][1]);
                result = min(result, dist(i, j));
            }
            st1.update(y_to_idx[points[i][1]], vector<int>{points[i][0] + points[i][1], -i});
            j = -st2.query(y_to_idx[points[i][1]], size(y_to_idx) - 1)[1];   // min((xi-xj)+(yj-yi) for j in range(y_to_idx[points[i][1], len(y_to_idx))) = (xi-yi)-max((xj-yj) for j in range(y_to_idx[points[i][1], len(y_to_idx))
            if (j != INF) {
                assert(points[j][1] >= points[i][1]);
                result = min(result, dist(i, j));
            }
            st2.update(y_to_idx[points[i][1]], vector<int>{points[i][0] - points[i][1], -i});
        }
        return {result[1], result[2]};
    }

private:
    class SegmentTree {
    private:
        static const int INF = numeric_limits<int>::max();

    public:
        explicit SegmentTree(int N)
          : tree(N > 1 ? 1 << (__lg(N - 1) + 2) : 2, vector<int>{-INF, -INF}),
            base(N > 1 ? 1 << (__lg(N - 1) + 1) : 1) {

        }

        void update(int i, const vector<int>& h) {
            int x = base + i;
            tree[x] = h;
            while (x > 1) {
                x /= 2;
                tree[x] = max(tree[x * 2], tree[x * 2 + 1]);
            }
        }

        vector<int> query(int L, int R) {
            vector<int> result = {-INF, -INF};
            if (L > R) {
                return result;
            }
            L += base;
            R += base;
            for (; L <= R; L /= 2, R /= 2) {
                if (L & 1) {
                    result = max(result, tree[L]);
                    ++L;
                }
                if ((R & 1) == 0) {
                    result = max(tree[R], result);
                    --R;
                }
            }
            return result;
        }

        vector<vector<int>> tree;
        int base;
    };
};

// Time:  precompute: O(MAX_N)
//        runtime: O(n)
// Space: O(MAX_N)

// number theory
vector<int> linear_sieve_of_eratosthenes(int n) {  // Time: O(n), Space: O(n)
    vector<int> spf(n + 1, -1);
    vector<int> primes;
    for (int i = 2; i <= n; ++i) {
        if (spf[i] == -1) {
            spf[i] = i;
            primes.emplace_back(i);
        }
        for (const auto& p : primes) {
            if (i * p > n || p > spf[i]) {
                break;
            }
            spf[i * p] = p;
        }
    }
    return primes;  // len(primes) = O(n/(logn-1)), reference: https://math.stackexchange.com/questions/264544/how-to-find-number-of-prime-numbers-up-to-to-n
}

const int MAX_N = 4 * 1e6;
const auto& PRIMES = linear_sieve_of_eratosthenes(MAX_N);
const unordered_set<int> PRIMES_SET(cbegin(PRIMES), cend(PRIMES));
class Solution {
public:
    int diagonalPrime(vector<vector<int>>& nums) {
        int result = 0;
        for (int i = 0; i < size(nums); ++i) {
            if (PRIMES_SET.count(nums[i][i])) {
                result = max(result, nums[i][i]);
            }
            if (PRIMES_SET.count(nums[i][size(nums) - 1 - i])) {
                result = max(result, nums[i][size(nums) - 1 - i ]);
            }
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(n)

// freq table, prefix sum
class Solution {
public:
    vector<long long> distance(vector<int>& nums) {
        vector<long long> result(size(nums));
        unordered_map<int, long long> cnt1, left;
        for (int i = 0; i < size(nums); ++i) {
            result[i] += cnt1[nums[i]] * i - left[nums[i]];
            ++cnt1[nums[i]];
            left[nums[i]] += i;
        }
        unordered_map<int, long long> cnt2, right;
        for (int i = size(nums) - 1; i >= 0; --i) {
            result[i] += right[nums[i]] - cnt2[nums[i]] * i ;
            ++cnt2[nums[i]];
            right[nums[i]] += i;
        }
        return result;
    }
};

// Time:  O(nlogn + nlogr), r = max(nums)-min(nums)
// Space: O(1)

// sort, binary search, greedy
class Solution {
public:
    int minimizeMax(vector<int>& nums, int p) {
        const auto& check = [&](int x) {
            int cnt = 0;
            for (int i = 0; i + 1 < size(nums) && cnt < p; ++i) {
                if (nums[i + 1] - nums[i] <= x) {
                    ++i;
                    ++cnt;
                }
            }
            return cnt == p;
        };

        sort(begin(nums), end(nums));
        int left = 0, right = nums.back() - nums.front();
        while (left <= right) {
            const int mid = left + (right - left) / 2;
            if (check(mid)) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }
};

// Time:  O(m * n * alpha(m + n)) = O(m + n)
// Space: O(m * n)

// bfs, union find
class Solution {
public:
    int minimumVisitedCells(vector<vector<int>>& grid) {
        const int m = size(grid), n = size(grid[0]);
        vector<UnionFind> uf1(m, UnionFind(n + 1));
        vector<UnionFind> uf2(n, UnionFind(m + 1));
        int d = 1, i = 0, j = 0;
        vector<pair<int, int>> q = {{i, j}};
        uf1[i].union_set(j, j + 1);
        uf2[j].union_set(i, i + 1);
        while (!empty(q)) {
            vector<pair<int, int>> new_q;
            for (const auto& [i, j] : q) {
                if (i == m - 1 && j == n - 1) {
                    return d;
                }
                while (uf1[i].right_set(j) <= min(j + grid[i][j], n - 1)) {
                    const int k = uf1[i].right_set(j);
                    new_q.emplace_back(i, k);
                    uf2[k].union_set(i, i + 1);
                    uf1[i].union_set(k, k + 1);
                }
                while (uf2[j].right_set(i) <= min(i+grid[i][j], m - 1)) {
                    const int k = uf2[j].right_set(i);
                    new_q.emplace_back(k, j);
                    uf1[k].union_set(j, j + 1);
                    uf2[j].union_set(k, k + 1);
                }
            }
            q = move(new_q);
            ++d;
        }
        return -1;
    }

private:
class UnionFind {
    public:
        UnionFind(int n)
         : set_(n)
         , rank_(n)
         , right_(n) {  // added
            iota(begin(set_), end(set_), 0);
            iota(begin(right_), end(right_), 0);  // added
        }

        int find_set(int x) {
           if (set_[x] != x) {
               set_[x] = find_set(set_[x]);  // Path compression.
           }
           return set_[x];
        }

        bool union_set(int x, int y) {
            x = find_set(x), y = find_set(y);
            if (x == y) {
                return false;
            }
            if (rank_[x] > rank_[y]) {
                swap(x, y);
            }
            set_[x] = y;  // Union by rank.
            if (rank_[x] == rank_[y]) {
                ++rank_[y];
            }
            right_[y] = max(right_[x], right_[y]);  // added
            return true;
        }

        int right_set(int x) {  // added
            return right_[find_set(x)];
        }

    private:
        vector<int> set_;
        vector<int> rank_;
        vector<int> right_;  // added
    };
};

// Time:  O(m * n * alpha(m + n)) = O(m + n)
