// freq table
class FrequencyTracker {
public:
    FrequencyTracker() {

    }

    void add(int number) {
        if (--freq_[cnt_[number]] == 0) {
            freq_.erase(cnt_[number]);
        };
        ++freq_[++cnt_[number]];
    }

    void deleteOne(int number) {
        if (!cnt_.count(number)) {
            return;
        }
        if (--freq_[cnt_[number]] == 0) {
            freq_.erase(cnt_[number]);
        }
        ++freq_[--cnt_[number]];
        if (cnt_[number] == 0) {
            cnt_.erase(number);
        }
    }

    bool hasFrequency(int frequency) {
        return freq_.count(frequency);
    }

private:
    unordered_map<int, int> cnt_;
    unordered_map<int, int> freq_;
};

// Time:  O(n + q)
// Space: O(n)

// array
class Solution {
public:
    vector<int> colorTheArray(int n, vector<vector<int>>& queries) {
        vector<int> nums(n);
        const auto& update = [&](int i) {
            if (!nums[i]) {
                return 0;
            }
            int cnt = 0;
            if (i - 1 >= 0 && nums[i - 1] == nums[i]) {
                ++cnt;
            }
            if (i + 1 < n && nums[i + 1] == nums[i]) {
                ++cnt;
            }
            return cnt;
        };

        vector<int> result(size(queries));
        for (int idx = 0, curr = 0; idx < size(queries); ++idx) {
            curr -= update(queries[idx][0]);
            nums[queries[idx][0]] = queries[idx][1];
            curr += update(queries[idx][0]);
            result[idx] = curr;
        }
        return result;
    }
};

