// Boyer–Moore majority vote algorithm, linear search
class Solution {
public:
    int minimumIndex(vector<int>& nums) {
        const auto& boyer_moore_majority_vote = [&]() {
            int result = 0, cnt = 0;
            for (const auto& x : nums) {
                if (cnt == 0) {
                    result = x;
                }
                if (x == result) {
                    ++cnt;
                } else {
                    --cnt;
                }
            }
            return result; 
        };

        const auto& m = boyer_moore_majority_vote();
        const auto& total = count(cbegin(nums), cend(nums), m);
        for (int i = 0, cnt = 0; i < size(nums); ++i) {
            if (nums[i] == m) {
                ++cnt;
            }
            if (cnt * 2 > i + 1 && (total - cnt) * 2 > size(nums) - (i + 1)) {
                return i;
            }
        }
        return -1;
    }
};

// Time:  O((m + n) * l), n = len(word), m = len(forbidden), l = max(len(w) for w in forbidden)
// Space: O(t), t is the size of trie

// two pointers, sliding window, trie
class Solution {
public:
    int longestValidSubstring(string word, vector<string>& forbidden) {
        Trie trie;
        for (const auto& w : forbidden) {
            trie.insert(w);
        }
        int result = 0;
        for (int left = size(word) - 1, right = size(word) - 1; left >= 0; --left) {
            for (int i = left, curr = 0; i <= right; ++i) {
                curr = trie.child(curr, word[i]);
                if (!curr) {  // O(l) times
                    break;
                }
                if (trie.is_string(curr)) {
                    right = i - 1;
                    break;
                }
            }
            result = max(result, right - left + 1);
        }
        return result;
    }

private:
class Trie {
    public:
        Trie() {
            create_node(); 
        }

        void insert(const string& s) {
            int curr = 0;
            for (const auto& c : s) {
                if (!nodes_[curr][c - 'a']) {
                    nodes_[curr][c - 'a'] = create_node();
                }
                curr = nodes_[curr][c - 'a'];
            }
            ++nodes_[curr].back();
        }

        int child(int curr, char c) const {
            return nodes_[curr][c - 'a'];
        }

        bool is_string(int curr) const {
            return nodes_[curr].back();
        }

    private:
        int create_node() {
            nodes_.emplace_back(26 + 1);
            return size(nodes_) - 1;
        }

        using TrieNode = vector<int>;
        vector<TrieNode> nodes_;
    };
};

