// bfs, dijkstra's algorithm
class Solution2 {
public:
    int maximumSafenessFactor(vector<vector<int>>& grid) {
        static const vector<pair<int, int>> DIRECTIONS = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
        const auto& bfs = [&]() {
            vector<vector<int>> dist(size(grid), vector<int>(size(grid[0]), -1));
            vector<pair<int, int>> q;
            for (int r = 0; r < size(grid); ++r) {
                for (int c = 0; c < size(grid[0]); ++c) {
                    if (grid[r][c]) {
                        dist[r][c] = 0;
                        q.emplace_back(r, c);
                    }
                }
            }
            int d = 0;
            for (int d = 0; !empty(q); ++d) {
                vector<pair<int, int>> new_q;
                for (const auto& [r, c] : q) {
                    for (const auto& [dr, dc] : DIRECTIONS) {
                        const int nr = r + dr, nc = c + dc;
                        if (!(0 <= nr && nr < size(dist) && 0 <= nc && nc < size(dist[0]) && dist[nr][nc] == -1)) {
                            continue;
                        }
                        dist[nr][nc] = d + 1;
                        new_q.emplace_back(nr, nc);
                    }
                }
                q = move(new_q);
            }
            return dist;
        };

        auto dist = bfs();
        const auto& dijkstra = [&](const auto& start, const auto& target) {
            priority_queue<pair<int, pair<int, int>>> max_heap;
            max_heap.emplace(dist[start.first][start.second], start);
            dist[start.first][start.second] = -1;
            while (!empty(max_heap)) {
                auto [curr, u] = max_heap.top(); max_heap.pop();
                if (u == target) {
                    return curr;
                }
                for (const auto& [dr, dc] : DIRECTIONS) {
                    const int nr = u.first + dr, nc = u.second + dc;
                    if (!(0 <= nr && nr < size(dist) && 0 <= nc && nc < size(dist[0]) && dist[nr][nc] != -1)) {
                        continue;
                    }
                    max_heap.emplace(min(curr, dist[nr][nc]), pair(nr, nc));
                    dist[nr][nc] = -1;
                }
            }
            return -1;
        };

        return dijkstra(pair(0, 0), pair(static_cast<int>(size(dist) - 1), static_cast<int>(size(dist[0]) - 1)));
    }
};

// Time:  O(n^2 * logn)
// Space: O(n^2)
// bfs, binary search
class Solution3 {
public:
    int maximumSafenessFactor(vector<vector<int>>& grid) {
        static const vector<pair<int, int>> DIRECTIONS = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
        const auto& bfs = [&]() {
            vector<vector<int>> dist(size(grid), vector<int>(size(grid[0]), -1));
            vector<pair<int, int>> q;
            for (int r = 0; r < size(grid); ++r) {
                for (int c = 0; c < size(grid[0]); ++c) {
                    if (grid[r][c]) {
                        dist[r][c] = 0;
                        q.emplace_back(r, c);
                    }
                }
            }
            int d = 0;
            for (int d = 0; !empty(q); ++d) {
                vector<pair<int, int>> new_q;
                for (const auto& [r, c] : q) {
                    for (const auto& [dr, dc] : DIRECTIONS) {
                        const int nr = r + dr, nc = c + dc;
                        if (!(0 <= nr && nr < size(dist) && 0 <= nc && nc < size(dist[0]) && dist[nr][nc] == -1)) {
                            continue;
                        }
                        dist[nr][nc] = d + 1;
                        new_q.emplace_back(nr, nc);
                    }
                }
                q = move(new_q);
            }
            return dist;
        };

        const auto& dist = bfs();
        const auto& check = [&](int x) {
            vector<vector<int>> lookup(size(dist), vector<int>(size(dist[0])));
            vector<pair<int, int>> q = {{0, 0}};
            lookup[0][0] = 1;
            while (!empty(q)) {
                vector<pair<int, int>> new_q;
                for (const auto& [r, c] : q) {
                    for (const auto& [dr, dc] : DIRECTIONS) {
                        const int nr = r + dr, nc = c + dc;
                        if (!(0 <= nr && nr < size(dist) && 0 <= nc && nc < size(dist[0]) && dist[nr][nc] >= x && !lookup[nr][nc])) {
                            continue;
                        }
                        lookup[nr][nc] = 1;
                        new_q.emplace_back(nr, nc);
                    }
                }
                q = move(new_q);
            }
            return lookup.back().back();
        };

        int left = 0, right = dist[0][0];
        while (left <= right) {
            const auto& mid = left + (right - left) / 2;
            if (!check(mid)) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return right;
    }
};

// Time:  O(nlogk)
// Space: O(k)

// partial sort, bst, greedy
class Solution {
public:
    long long findMaximumElegance(vector<vector<int>>& items, int k) {
        partial_sort(begin(items), begin(items) + k, end(items), greater<vector<int>>());
        vector<bool> lookup(size(items));
        vector<int> stk;
        int64_t curr = 0, l = 0;
        for (int i = 0; i < k; ++i) {
            if (lookup[items[i][1] - 1]) {
                stk.emplace_back(items[i][0]);
            }
            curr += items[i][0];
            if (!lookup[items[i][1] - 1]) {
                lookup[items[i][1] - 1] = true;
                ++l;
            }
        }
        set<pair<int, int>> bst;
        vector<int> lookup2(size(items));
        for (int i = k; i < size(items); ++i) {
            const auto& p = items[i][0], &c = items[i][1];
            if (lookup[c - 1]) {
                continue;
            }
            if (lookup2[c - 1]) {
                if (lookup2[c - 1] >= p) {
                    continue;
                }
                bst.erase({lookup2[c - 1], c});
            }
            bst.emplace(p, c);
            lookup2[c - 1] = p;
            if (size(bst) > size(stk)) {
                auto it = begin(bst);
                lookup2[it->second - 1] = 0;
                bst.erase(it);
            }
        }
        int64_t result = curr + l * l;
        for (auto rit = rbegin(bst); rit != rend(bst); ++rit) {
            curr += rit->first - stk.back(); stk.pop_back();
            ++l;
            result = max(result, curr + l * l);
        }
        return result;
    }
};

// Time:  O(n + klogk)
// Space: O(n)
// quick select, sort, greedy
class Solution2 {
public:
    long long findMaximumElegance(vector<vector<int>>& items, int k) {
        const auto& nlargest = [](const auto& k, auto nums) {
            if (empty(nums)) {
                return vector<vector<int>>();
            }
            nth_element(begin(nums), begin(nums) + (k - 1), end(nums), greater<vector<int>>());
            sort(begin(nums), begin(nums) + k, greater<vector<int>>());
            return vector<vector<int>>(begin(nums), begin(nums) + k);
        };

        vector<bool> lookup(size(items));
        vector<int> stk;
        int64_t curr = 0, l = 0;
        for (const auto& x : nlargest(k, items)) {
            if (lookup[x[1] - 1]) {
                stk.emplace_back(x[0]);
            }
            curr += x[0];
            if (!lookup[x[1] - 1]) {
                lookup[x[1] - 1] = true;
                ++l;
            }
        }
        vector<int> lookup2(size(items));
        for (const auto& x : items) {
            if (lookup[x[1] - 1]) {
                continue;
            }
            lookup2[x[1] - 1] = max(lookup2[x[1] - 1], x[0]);
        }
        vector<vector<int>> candidates;
        for (int c = 0; c < size(lookup2); ++c) {
            if (lookup2[c]) {
                candidates.push_back({lookup2[c], c});
            }
        }
        int64_t result = curr + l * l;
        for (const auto& x : nlargest(min(size(stk), size(candidates)), candidates)) {
            curr += x[0] - stk.back(); stk.pop_back();
            ++l;
            result = max(result, curr + l * l);
        }
        return result;
    }
};

