// promise
function delayAll(functions: Function[], ms: number): Function[] {
    return functions.map(fn => {
        return async () => {
            await new Promise(resolve => setTimeout(resolve, ms));
            try {
                const result = await fn();
                return Promise.resolve(result);
            } catch (err) {
                return Promise.reject(err);
            }
        }
    });
};

// Time:  O(n)
// Space: O(1)

function invertObject(obj: Record<any, any>): Record<any, any> {
    let result = {};
    for (let [k, v] of Object.entries(obj)) {
        if (!(v in result)) {
            result[v] = k;
        } else if (!Array.isArray(result[v])) {
            result[v] = [result[v], k];
        } else {
            result[v].push(k);
        }
    }
    return result;
};

// Time:  O(n)
// Space: O(h)

// dfs
function deepFilter(obj: Record<string, any>, fn: Function): Record<string, any> | undefined {
    if (typeof obj !== 'object' || obj === null) {
        return fn(obj) ? obj : undefined;
    }
    if (Array.isArray(obj)) {
        const result = obj.map(x => deepFilter(x, fn)).filter(x => x !== undefined);
        return result.length !== 0 ? result : undefined;
    }
    const result = {};
    for (const key in obj) {
        const value = deepFilter(obj[key], fn);
        if (value !== undefined) {
            result[key] = value;
        }
    }
    return Object.keys(result).length !== 0 ? result : undefined;
};

