        int64_t result = 0;
        for (int i = 1; i <= size(nums); ++i) {
            int64_t curr = 0;
            for (int x = 1; i * x * x - 1 < size(nums); ++x) {
                curr += nums[i * x * x - 1];
            }
            result = max(result, curr);
