            const int j = lookup.count(nums[i]) ? lookup[nums[i]] : -1;
            // sum(count(k, i)^2 for k in range(i+1)) - sum(count(k, i-1)^2 for k in range(i))
            // = sum(2*count(k, i-1)+1 for k in range(j+1, i+1))
            // = (i-j) + sum(2*count(k, i-1) for k in range(j+1, i+1))
            accu = (accu + ((i - j) + 2ll * st.query(j + 1, i))) % MOD;
            result = (result + accu) % MOD;
            st.update(j + 1, i, 1);  // count(k, i) = count(k, i-1)+(1 if k >= j+1 else 0) for k in range(i+1)
            lookup[nums[i]] = i;
        }
        return result;
    }

private:
    template <typename T>
    class SegmentTree {
    private:
        static const int MOD = 1e9 + 7;

    public:
        explicit SegmentTree(
            int N,
            const function<T(const T&, const T&)>& query_fn,
            const function<T(const T&, const T&)>& update_fn)
         :  base_(N > 1 ? 1 << (__lg(N - 1) + 1) : 1),
            lazy_(base_),
            tree_(N > 1 ? 1 << (__lg(N - 1) + 2) : 2),
            count_(size(tree_), 1),
            query_fn_(query_fn),
            update_fn_(update_fn) {

            for (int i = base_ - 1; i >= 1; --i) { // added
                count_[i] = count_[i << 1] + count_[(i << 1) + 1];
            }
        }

        void update(int L, int R, const T& val) {
            L += base_;
            R += base_;
            // push(L);  // enable if range assignment
            // push(R);  // enable if range assignment
            int L0 = L, R0 = R;
            for (; L <= R; L >>= 1, R >>= 1) {
                if ((L & 1) == 1) {
                    apply(L++, val);
                }
                if ((R & 1) == 0) {
                    apply(R--, val);
                }
            }
            pull(L0);
            pull(R0);
        }

        T query(int L, int R) {
            if (L > R) {
                return T{};
            }
            L += base_;
            R += base_;
            push(L);
            push(R);
            T left{}, right{};
            for (; L <= R; L >>= 1, R >>= 1) {
                if ((L & 1) == 1) {
                    left = query_fn_(left, tree_[L++]);
                }
                if ((R & 1) == 0) {
                    right = query_fn_(tree_[R--], right);
                }
            }
            return query_fn_(left, right);
        }

    private:
        void apply(int x, const T val) {
            tree_[x] = update_fn_(tree_[x], (static_cast<int64_t>(val) * count_[x]) % MOD);  // modified
            if (x < base_) {
                lazy_[x] = update_fn_(lazy_[x], val);
            }
        }

        void pull(int x) {
            while (x > 1) {
                x >>= 1;
                tree_[x] = query_fn_(tree_[x << 1], tree_[(x << 1) + 1]);
                if (lazy_[x]) {
                    tree_[x] = update_fn_(tree_[x], (static_cast<int64_t>(lazy_[x]) * count_[x]) % MOD);  // modified
                }
            }
        }

        void push(int x) {
            for (int h = __lg(x) - 1; h > 0; --h) {
                int y = x >> h;
                if (lazy_[y]) {
                    apply(y << 1, lazy_[y]);
                    apply((y << 1) + 1, lazy_[y]);
                    lazy_[y] = 0;
                }
            }
        }

        int base_;
        vector<T> tree_;
        vector<T> lazy_;
        vector<T> count_;  // added
        const function<T(const T&, const T&)> query_fn_;
        const function<T(const T&, const T&)> update_fn_;
    };
};

// Time:  O(nlogr)
// Space: O(1)

// bit manipulation
class Solution {
public:
    int findKOr(vector<int>& nums, int k) {
        int result = 0; 
        const int mx = *max_element(cbegin(nums), cend(nums));
        const int l = mx != 0 ? __lg(mx) : -1;
        for (int i = 0; i <= l; ++i) {
            int cnt = 0;
            for (const auto& x : nums) {
                if ((x & (1 << i)) == 0) {
                    continue;
                }
                if (++cnt == k) {
                    result += 1 << i;
                    break;
                }
            }
        }
        return result;
    }
};

// Time:  O(n + m)
// Space: O(1)

// greedy
class Solution {
public:
    long long minSum(vector<int>& nums1, vector<int>& nums2) {
        const auto& add = [](const auto& accu, const auto& x) {
            return accu + max(x, 1);
        };

        const int64_t total1 = accumulate(cbegin(nums1), cend(nums1), 0ll, add);
        const int64_t total2 = accumulate(cbegin(nums2), cend(nums2), 0ll, add);
        if (total1 < total2) {
            return find(cbegin(nums1), cend(nums1), 0) != cend(nums1) ? total2 : -1;
        }
        if (total1 > total2) {
            return find(cbegin(nums2), cend(nums2), 0) != cend(nums2) ? total1 : -1;
        }
        return total1;
    }
};

// Time:  O(n)
// Space: O(1)

// dp
class Solution {
public:
    long long minIncrementOperations(vector<int>& nums, int k) {
        static const int W = 3;

        vector<int64_t> dp(W);
        for (int i = 0; i < size(nums); ++i) {
            int64_t mn = numeric_limits<int64_t>::max();
            for (int j = i - W; j < i; ++j) {
                mn = min(mn, dp[(j % W + W) % W]);
            }
            dp[i % W] = mn + max(k - nums[i], 0);
        }
        return *min_element(cbegin(dp), cend(dp));
    }
};

// Time:  O(nlogr), r = max(coins)
// Space: O(n)

// dfs, bitmasks, pruning
class Solution {
public:
    int maximumPoints(vector<vector<int>>& edges, vector<int>& coins, int k) {
        static const int NEG_INF = numeric_limits<int>::min();

        vector<vector<int>> adj(size(coins));
        for (const auto& e : edges) {
            adj[e[0]].emplace_back(e[1]);
            adj[e[1]].emplace_back(e[0]);
        }
        const int mx = *max_element(cbegin(coins), cend(coins));
        const int max_base = 1 << (mx != 0 ? __lg(mx) + 1 : 0);
        vector<int> lookup(size(coins));
        const function<int (int, int, int)> dfs = [&](int u, int p, int base) {
            if (base >= max_base) {
                return 0;
            }
            if (lookup[u] & base) {  // we prefer the first way to the second way, so the visited state cannot improve the current chosen ways
                return NEG_INF;
            }
            lookup[u] |= base;
            int total1 = (coins[u] / base) - k;
            for (const auto& v : adj[u]) {
                if (v == p) {
                    continue;
                }
                const auto& r = dfs(v, u, base);
                if (r == NEG_INF) {
                    total1 = r;
                    break;
                }
                total1 += r;
            }
            if ((coins[u] / base) - k >= coins[u] / (base << 1)) {  // if (coins[u]//base)-k >= coins[u]//(base*2), the first way is always better
                return total1;
            }
            int total2 = coins[u] / (base << 1);
            for (const auto& v : adj[u]) {
                if (v == p) {
                    continue;
                }
                const auto& r = dfs(v, u, base << 1);
                if (r == NEG_INF) {
                    total2 = r;
                    break;
                }
                total2 += r;
            }
            return max(total1, total2);
        };

        return dfs(0, -1, 1);
    }
};

