                assert(x != y);
                if (nodes_[curr][y & 1] != -1 && 
                    ((x > y && num <= 2 * maxs_[nodes_[curr][y & 1]]) ||
                     (x < y && mins_[nodes_[curr][y & 1]] <= 2 * num))) {
                    result |= 1;
                    curr = nodes_[curr][y & 1];
                } else {
                    curr = nodes_[curr][(y & 1) ^ 1];
                }
            }
            return result;
        }

