        for (int i = 0, j = 0; i < size(prices); ++i) {
            bst.emplace(dp[i] + prices[i], i);
            for (; j + (j + 1) < i; ++j) {
                bst.erase(pair(dp[j] + prices[j], j));
            }
            dp[i + 1] = dp[cbegin(bst)->second] + prices[cbegin(bst)->second];
        }
        return dp.back();
    }
};

