        const int n = size(grid);
        vector<int> cnt(n * n);
        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < n; ++c) {
                ++cnt[grid[r][c] - 1];
            }
        }
        vector<int> result(2);
        for (int i = 0; i < n * n; ++i) {
            if (cnt[i] == 2) {
                result[0] = i + 1;
            } else if (cnt[i] == 0) {
                result[1] = i + 1;
            }
        }
        return result;
    }
};

