        sort(begin(nums), end(nums));
        int64_t prefix = accumulate(cbegin(nums), cend(nums), 0ll);
        for (int i = size(nums) - 1; i >= 2; --i) {
            prefix -= nums[i];
            if (prefix > nums[i]) {
                return prefix + nums[i];
            }
        }
        return -1;
    }
};

