// Time:  O(max(logk, x) * (max(logk, x) / x))
// Space: O(1)
// bit manipulation, binary search, combinatorics
class Solution4 {
public:
    long long findMaximumNumber(long long k, int x) {
        const auto& binary_search_right = [](long long left, long long right, const auto& check) {
            while (left <= right) {
                const auto mid = left + (right - left) / 2;
                if (!check(mid)) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }
            return right;
        };

        const auto& count = [&](long long v) {
            long long cnt = 0;
            for (int i = 0; (1ll << (i + x - 1)) <= v; i += x) {
                const long long q = (v + 1) / (1ll << ((i + x - 1) + 1));
                const long long r = (v + 1) % (1ll << ((i + x - 1) + 1));
                cnt += q * 1 * (1ll << (i + x - 1)) + max(r - 1 * (1ll << (i + x - 1)), 0ll);
            }
            return cnt;
        };

        return binary_search_right(1, max(k << 2, 1ll << x), [&](long long v) {
            return count(v) <= k;
        });  // right bound is verified by checking all possible (k, v) values, or just set right = solution.findMaximumNumber(10**15, 8) <= 10**15
    }
};

// Time:  O(n), x = len(KMP(s, a)), y = len(KMP(s, b))
// Space: O(min(a + b + x + y, n))

// kmp, two pointers
class Solution {
public:
    vector<int> beautifulIndices(string s, string a, string b, int k) {
        const auto& KMP = [&](const string& text, const string& pattern) {
            const auto& getPrefix = [&](const string& pattern) {
                vector<int> prefix(pattern.length(), -1);
                int j = -1;
                for (int i = 1; i < pattern.length(); ++i) {
                    while (j > -1 && pattern[j + 1] != pattern[i]) {
                        j = prefix[j];
                    }
                    if (pattern[j + 1] == pattern[i]) {
                        ++j;
                    }
                    prefix[i] = j;
                }
                return prefix;
            };

            vector<int> result;
            const vector<int> prefix = getPrefix(pattern);
            int j = -1;
            for (int i = 0; i < text.length(); ++i) {
                while (j > -1 && pattern[j + 1] != text[i]) {
                    j = prefix[j];
                }
                if (pattern[j + 1] == text[i]) {
                    ++j;
                }
                if (j == pattern.length() - 1) {
                    result.emplace_back(i - j);
                    j = prefix[j];
                }
            }
            return result;
        };

        vector<int> result;
        if (!(size(a) <= size(s) && size(b) <= size(s))) {
            return result;
        }
        const auto& lookup = KMP(s, b);
        int j = 0;
        for (const auto& i : KMP(s, a)) {
            for (; j < size(lookup) && lookup[j] < i - k; ++j);
            if (j < size(lookup) && lookup[j] <= i + k) {
                result.emplace_back(i);
            }
        }
        return result;
    }
};

