bool is_prime(int n) {
    if (n % 2 == 0 || n % 3 == 0) {
        return false;
    }
    for (int i = 5; i < n; i += 6) {
        if (i * i > n) {
            break;
        }
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

