        };

        const int mn = min(n, m), mx = max(n, m);
        const auto& count = [&](int first, int last) {
            int64_t result = 0;
            int d = last > first ? 1 : (last < first ? -1 : 0);
            vector<int> cnt(mn);
            for (int j = first; j != last + d; j += d) {
                int c = 0;
                for (int i = 0; i < size(cnt); ++i) {
