class Solution {
public:
    long long sumDigitDifferences(vector<int>& nums) {
        int l = 0;
        for (int64_t base = 1; base <= nums[0]; base *= 10, ++l);
        vector<vector<int>> cnts(l, vector<int>(10));
        for (auto x : nums) {
            for (int i = 0; i < l; ++i, x /= 10) {
                ++cnts[i][x % 10];
            }
        }
        int64_t result = 0;
        for (const auto& cnt : cnts) {
            for (const auto& c : cnt) {
                result += c * (size(nums) - c);
            }
        }
        return result / 2;
    }
};

// Time:  O(logk)
// Space: O(logk)

// combinatorics
class Solution {
public:
    int waysToReachStair(int k) {
        const auto& bit_length = [](int x) {
            return (x ? std::__lg(x) : -1) + 1;
        };

        const auto& ceil_log2_x = [&](int x) {
            return bit_length(x - 1);
        };

        int l = ceil_log2_x(k);
        for (; (1ll << l) - k <= l + 1; ++l);
        vector<__int128> fact(l + 1, 1);
        for (int i = 0; i + 1 < size(fact); ++i) {
            fact[i + 1] = fact[i] * (i + 1);
        }
        const auto& nCr = [&](int n, int r) {
            if (!(0 <= r && r <= n)) {
                return static_cast<__int128>(0);
            }
            return fact[n] / fact[r] / fact[n - r];
        };

        int result = 0;
        for (int i = 0; i < l; ++i) {
            result += nCr(i + 1, (1 << i) - k);
        }
        return result;
    }
};

