class Solution {
public:
    string clearStars(string s) {
        vector<vector<int>> lookup(26);
        for (int i = 0; i < size(s); ++i) {
            if (s[i] != '*') {
                lookup[s[i] - 'a'].emplace_back(i);
                continue;
            }
            for (auto& stk : lookup) {
                if (empty(stk)) {
                    continue;
                }
                s[stk.back()] = '*';
