class Solution2 {
public:
    int minimumSum(vector<vector<int>>& grid) {
        vector<SparseTable> st_min_i, st_max_i, st_min_j, st_max_j;
        const auto& minimumArea = [&](int min_i, int max_i, int min_j, int max_j) {
