// bst
class Solution {
public:
    vector<int> shortestDistanceAfterQueries(int n, vector<vector<int>>& queries) {
        vector<int> result;
        set<int> bst;
        for (int i = 0; i < n; ++i) {
            bst.emplace(i);
        }
        for (const auto& q : queries) {
            auto jt = bst.lower_bound(q[1]);
            for (auto it = bst.upper_bound(q[0]); it != jt; it = bst.erase(it));
            result.emplace_back(size(bst) - 1);
        }
        return result;
    }
};

// Time:  O(nlogn + qlogn)
// Space: O(n)

// sorted list, freq table, bit, fenwick tree
class Solution {
private:
    class BIT {
    public:
        BIT(int n) : bit_(n + 1) {  // 0-indexed
        }

        void add(int i, int val) {
            ++i;
            for (; i < size(bit_); i += lower_bit(i)) {
                bit_[i] += val;
            }
        }

        int query(int i) const {
            ++i;
            int total = 0;
            for (; i > 0; i -= lower_bit(i)) {
                total += bit_[i];
            }
            return total;
        }

    private:
        int lower_bit(int i) const {
            return i & -i;
        }

        vector<int> bit_;
    };

public:
    vector<int> numberOfAlternatingGroups(vector<int>& colors, vector<vector<int>>& queries) {
        const int n = size(colors);
        set<int> bst;
        BIT bit1(n + 1), bit2(n + 1);
        const auto& update = [&](int i, int d) {
            if (d == +1) {
                bst.emplace(i);
                if (size(bst) == 1) {
                    bit1.add(n, +1);
                    bit2.add(n, +n);
                }
            }
            auto curr = bst.find(i);
            auto prv = prev(curr != begin(bst) ? curr : end(bst));
            auto nxt = next(curr);
            if (nxt == end(bst)) {
                nxt = begin(bst);
            }
            if (size(bst) != 1) {
                int l = ((*nxt) - (*prv) + (n - 1)) % n + 1;
                bit1.add(l, d * -1);
                bit2.add(l, d * -l);
                l = ((*curr) - (*prv) + n) % n;
                bit1.add(l, d * +1);
                bit2.add(l, d * +l);
                l = ((*nxt) - (*curr) + n) % n;
                bit1.add(l, d * +1);
                bit2.add(l, d * +l);
            }
            if (d == -1) {
                if (size(bst) == 1) {
                    bit1.add(n, -1);
                    bit2.add(n, -n);
                }
                bst.erase(curr);
            }
        };

        vector<int> result;
        for (int i = 0; i < n; ++i) {
            if (colors[i] == colors[(i + 1) % n]) {
                update(i, +1);
            }
        }
        for (const auto &q : queries) {
            if (q[0] == 1) {
                const int l = q[1];
                result.emplace_back(!empty(bst) ? (bit2.query(n) - bit2.query(l - 1)) - 
                                                  (l - 1) * (bit1.query(n) - bit1.query(l - 1)) : n);
                continue;
            }
            const int i = q[1];
            if (colors[i] == q[2]) {
                continue;
            }
            colors[i] = q[2];
            update((i - 1 + n) % n, colors[i] == colors[(i - 1 + n) % n] ? +1 : -1);
            update(i, colors[i] == colors[(i + 1) % n] ? +1 : -1);
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(1)

// combinatorics, fast exponentiation
class Solution {
public:
    int subsequenceCount(vector<int>& nums) {
        static const int MOD = 1e9 + 7;

        // 2^(odd-1)*2^even = 2^(len(nums)-1)
        return any_of(cbegin(nums), cend(nums), [](const auto& x) {
            return x % 2 == 1;
        }) ? powmod(2, size(nums) - 1, MOD) : 0;
    }

private:
    uint32_t powmod(uint32_t a, uint32_t b, uint32_t mod) {
        a %= mod;
        uint64_t result = 1;
        while (b) {
            if (b & 1) {
                result = result * a % mod;
            }
            a = uint64_t(a) * a % mod;
            b >>= 1;
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(1)
// dp
class Solution2 {
public:
    int subsequenceCount(vector<int>& nums) {
        static const int MOD = 1e9 + 7;

        vector<int> dp(2);
        for (const auto& x : nums) {
            vector<int> new_dp(2);
            for (int i = 0; i < 2; ++i) {
                new_dp[i] = (dp[i] + dp[i ^ (x % 2)] + (x % 2 == i ? 1 : 0)) % MOD;
            }
            dp = move(new_dp);
        }
        return dp[1];
    }
};

// Time:  O(c)
// Space: O(1)

// simulation
class Solution {
public:
    int finalPositionOfSnake(int n, vector<string>& commands) {
        static const unordered_map<string, pair<int, int>> lookup = {
            {"UP", {-1, 0}},
            {"RIGHT", {0, 1}},
            {"DOWN", {1, 0}},
            {"LEFT", {0, -1}}
        };

        int r = 0, c = 0;
        for (const auto& x : commands) {
            const auto& [dr, dc] = lookup.at(x);
            r += dr;
            c += dc;
        }
        return r * n + c;
    }
};

// Time:  O(n)
// Space: O(h)

// iterative dfs
class Solution {
public:
    int countGoodNodes(vector<vector<int>>& edges) {
        vector<vector<int>> adj(size(edges) + 1);
        int result = 0;
        const auto& iter_dfs = [&]() {
            int64_t result = 0;
            using RET = int;
            RET ret{};
            vector<tuple<int, int, int, int, shared_ptr<RET>, shared_ptr<int>, shared_ptr<bool>, RET *>> stk = {{1, 0, -1, -1, nullptr, nullptr, nullptr, &ret}};
            while (!empty(stk)) {
                const auto [step, u, p, i, new_ret, l, valid, ret] = stk.back(); stk.pop_back();
                if (step == 1) {
                    const auto& new_l = make_shared<int>();
                    const auto& new_valid = make_shared<bool>(true);
                    stk.emplace_back(4, -1, -1, -1, nullptr, nullptr, new_valid, ret);
                    stk.emplace_back(2, u, p, 0, nullptr, new_l, new_valid, ret);
                } else if (step == 2) {
                    if (i == size(adj[u])) {
                        continue;
                    }
                    stk.emplace_back(2, u, p, i + 1, nullptr, l, valid, ret);
                    const auto& v = adj[u][i];
                    if (v == p) {
                        continue;
                    }
                    const auto& new_ret = make_shared<RET>();
                    stk.emplace_back(3, -1, -1, -1, new_ret, l, valid, ret);
                    stk.emplace_back(1, v, u, -1, nullptr, nullptr, nullptr, new_ret.get());
                } else if (step == 3) {
                    (*ret) += (*new_ret);
                    ++(*l);
                    if ((*new_ret) * (*l) != (*ret)) {
                        (*valid) = false;
                    }
                } else if (step == 4) {
                    if (*valid) {
                        ++result;
                    }
                    ++(*ret);
                }
            }
            return result;
        };

        for (const auto& e : edges) {
            adj[e[0]].emplace_back(e[1]);
            adj[e[1]].emplace_back(e[0]);
        }
        return iter_dfs();
    }
};

// Time:  O(n)
// Space: O(h)
// dfs
class Solution2 {
public:
    int countGoodNodes(vector<vector<int>>& edges) {
        vector<vector<int>> adj(size(edges) + 1);
        int result = 0;
        const function<int (int, int)> dfs = [&](int u, int p) {
            int total = 0, l = 0;
            bool valid = true;
            for (const auto& v : adj[u]) {
                if (v == p) {
                    continue;
                }
                const int cnt = dfs(v, u);
                total += cnt;
                ++l;
                if (cnt * l != total) {
                    valid = false;
                }
            }
            if (valid) {
                ++result;
            }
            return total + 1;
        };

        for (const auto& e : edges) {
            adj[e[0]].emplace_back(e[1]);
            adj[e[1]].emplace_back(e[0]);
        }
        dfs(0, -1);
        return result;
    }
};

// Time:  O(n + r), r = max(nums)
// Space: O(n + r)

// combinatorics, stars and bars
class Solution {
public:
    int countOfPairs(vector<int>& nums) {
        // arr1 = [0+x1, arr1[0]+max(nums[1]-nums[0], 0)+x2, ..., arr[n-2]+max(nums[n-1]-nums[n-2], 0)+xn]
        // => sum(max(nums[i]-nums[i-1], 0) for i in xrange(1, len(nums)))+(x1+x2+...+xn) <= nums[-1]
        // => x1+x2+...+xn <= nums[-1]-sum(max(nums[i]-nums[i-1], 0) for i in xrange(1, len(nums))) = cnt <= min(nums)
        // => the answer is the number of solutions s.t. x1+x2+...+xn <= cnt, where cnt >= 0
        int cnt = nums.back();
        for (int i = 1; i < size(nums); ++i) {
            cnt -= max(nums[i] - nums[i - 1], 0);
        }
        return cnt >= 0 ? nHr(size(nums) + 1, cnt) : 0;
    }

private:
    int nHr(int n, int r) {
        return nCr(n + r - 1, r);
    }

    int nCr(int n, int k) {
        while (size(inv_) <= n) {  // lazy initialization
            fact_.emplace_back(mulmod(fact_.back(), size(inv_)));
            inv_.emplace_back(mulmod(inv_[MOD % size(inv_)], MOD - MOD / size(inv_)));  // https://cp-algorithms.com/algebra/module-inverse.html
            inv_fact_.emplace_back(mulmod(inv_fact_.back(), inv_.back()));
        }
        return mulmod(mulmod(fact_[n], inv_fact_[n - k]), inv_fact_[k]);
    }

    uint32_t addmod(uint32_t a, uint32_t b) {  // avoid overflow
        a %= MOD, b %= MOD;
        if (MOD - a <= b) {
            b -= MOD;  // relied on unsigned integer overflow in order to give the expected results
        }
        return a + b;
    }

    // reference: https://stackoverflow.com/questions/12168348/ways-to-do-modulo-multiplication-with-primitive-types
    uint32_t mulmod(uint32_t a, uint32_t b)  {  // avoid overflow
        a %= MOD, b %= MOD;
        uint32_t result = 0;
        if (a < b) {
            swap(a, b);
        }
        while (b > 0)  { 
            if (b & 1) {
                result = addmod(result, a);
            }
            a = addmod(a, a);
            b >>= 1;
        } 
        return result; 
    }

    static const uint32_t MOD = 1e9 + 7;
    vector<int> fact_ = {1, 1};
    vector<int> inv_ = {1, 1};
    vector<int> inv_fact_ = {1, 1};
};

// Time:  O(n * r), r = max(nums)
// Space: O(r)
// dp, prefix sum
class Solution2 {
public:
    int countOfPairs(vector<int>& nums) {
        static const int MOD = 1e9 + 7;
        vector<int> dp(ranges::max(nums) + 1);  // dp[j]: numbers of arr1, which is of length i+1 and arr1[i] is j
        for (int i = 0; i <= nums[0]; ++i) {
            dp[i] = 1;
        }
        for (int i = 1; i < size(nums); ++i) {
            // arr1[i-1] <= arr1[i]
            // => arr1[i]-arr1[i-1] >= 0 (1)
            //
            // arr2[i-1] >= arr2[i]
            // => nums[i-1]-arr1[i-1] >= nums[i]-arr1[i] 
            // => arr1[i]-arr1[i-1] >= nums[i]-nums[i-1] (2)
            //
            // (1)+(2): arr1[i]-arr1[i-1] >= max(nums[i]-nums[i-1], 0)
            vector<int> new_dp(size(dp));
            const int diff = max(nums[i] - nums[i - 1], 0);
            for (int j = diff; j <= nums[i]; ++j) {
                new_dp[j] = ((j - 1 >= 0 ? new_dp[j - 1] : 0) + dp[j - diff]) % MOD;
            }
            dp = move(new_dp);
        }
        return accumulate(cbegin(dp), cend(dp), 0, [&](const auto& accu, const auto& x) {
            return (accu + x) % MOD;
        });
    }
};

