            // => arr1[i]-arr1[i-1] >= nums[i]-nums[i-1] (2)
            //
            // (1)+(2): arr1[i]-arr1[i-1] >= max(nums[i]-nums[i-1], 0)
            vector<int> new_dp(size(dp));
