        for (int idx = 0; idx < size(vals); ++idx) {
            const auto& [x, i] = vals[idx];
            const int c = count(x, target);
            if (c <= 0) {
                break;
            }
            k -= c;
            nums2[i] *= pow(multiplier, c);
        }
        using P2 = pair<int64_t, int>;
        vector<P2> vals2;
        for (int i = 0; i < size(nums2); ++i) {
            vals2.emplace_back(nums2[i], i);
        }
        sort(begin(vals2), end(vals2));
        const int q = k / size(nums), r = k % size(nums);
        const int m = powmod(multiplier, q);
        vector<int> result(size(nums));
        for (int idx = 0; idx < size(vals2); ++idx) {
            const auto& [x, i] = vals2[idx];
            result[i] = ((x % MOD * m) % MOD * (idx < r ? multiplier : 1)) % MOD;
        }
        return result;
    }
};

// Time:  O(min(nlogr, k) * logn + nlogn) = O(nlogn * logr)
// Space: O(n)
// heap, sort, fast exponentiation
class Solution3 {
public:
    vector<int> getFinalState(vector<int>& nums, int k, int multiplier) {
        static const int MOD = 1e9 + 7;
        const auto& powmod = [&](int a, int b) {
            a %= MOD;
            int64_t result = 1;
            while (b) {
                if (b & 1) {
                    result = result * a % MOD;
                }
                a = int64_t(a) * a % MOD;
                b >>= 1;
            }
            return result;
        };

        if (multiplier == 1) {
            return nums;
        }
        using P = pair<int64_t, int>;
        vector<P> vals;
        for (int i = 0; i < size(nums); ++i) {
            vals.emplace_back(nums[i], i);
        }
        priority_queue<P, vector<P>, greater<P>> min_heap(cbegin(vals), cend(vals));
        const int mx = ranges::max(nums);
        vector<int64_t> nums2(cbegin(nums), cend(nums));
        for (; k; --k) {
            const auto [x, i] = min_heap.top(); min_heap.pop();
            if (x >= mx) {
                break;
            }
            nums2[i] *= multiplier;
            min_heap.emplace(nums2[i], i);
        }
        vector<P> vals2;
        for (int i = 0; i < size(nums2); ++i) {
            vals2.emplace_back(nums2[i], i);
        }
        sort(begin(vals2), end(vals2));
        const int q = k / size(nums), r = k % size(nums);
        const int m = powmod(multiplier, q);
        vector<int> result(size(nums));
        for (int idx = 0; idx < size(vals2); ++idx) {
            const auto& [x, i] = vals2[idx];
            result[i] = ((x % MOD * m) % MOD * (idx < r ? multiplier : 1)) % MOD;
        }
        return result;
    }
};

// Time:  O(n * l^4)
// Space: O(n * l^2 + min(n * l^4, n^2)) = O(n * l^4)

// freq table, combinatorics
class Solution {
public:
    int countPairs(vector<int>& nums) {
        static const int L = 7;
        vector<int> POW10(L);
        POW10[0] = 1;
        for (int i = 0; i + 1 < L; ++i) {
            POW10[i+1] = POW10[i] * 10;
        }
        unordered_map<int, int> cnt1;
        for (const auto& x : nums) {
            ++cnt1[x];
        }
        unordered_map<int, vector<int>> adj;
        vector<pair<int, int>> cnt;
        for (const auto& [k, v] : cnt1) {
            cnt.emplace_back(k, v);
        }
        for (int idx = 0; idx < size(cnt); ++idx) {
            adj[cnt[idx].first].emplace_back(idx);
            for (int i = 0; i < L; ++i) {
                const int a = cnt[idx].first / POW10[i] % 10;
                for (int j = i + 1; j < L; ++j) {
                    const int b = cnt[idx].first /POW10[j] % 10;
                    if (a == b) {
                        continue;
                    }
                    adj[cnt[idx].first - a * (POW10[i] - POW10[j]) + b * (POW10[i] - POW10[j])].emplace_back(idx);
                }
            }
        }
        int result = 0;
        for (const auto& [_, v] : cnt1) {
            result += v * (v - 1) / 2;
        }
        unordered_map<int, unordered_set<int>> lookup;
        for (const auto& [u, _] : adj) {
            for (int i = 0; i < size(adj[u]); ++i) {
                const int v1 = cnt[adj[u][i]].second;
                for (int j = i + 1; j < size(adj[u]); ++j) {
                    const int v2 = cnt[adj[u][j]].second;
                    if (lookup[adj[u][i]].count(adj[u][j])) {
                        continue;
                    }
                    lookup[adj[u][i]].emplace(adj[u][j]);
                    result += v1 * v2;
                }
            }
        }
        return result;
    }
};

// Time:  O(n * l^(2 * k)) = O(n * l^4)
// Space: O(n + l^(2 * k)) = O(n + l^4) = O(n)
// freq table, combinatorics, bfs
class Solution2 {
public:
    int countPairs(vector<int>& nums) {
        static const int L = 7;
        static const int K = 2;
        vector<int> POW10(L);
        POW10[0] = 1;
        for (int i = 0; i + 1 < L; ++i) {
            POW10[i+1] = POW10[i] * 10;
        }
        const auto& at_most = [&](int k, int x) {
            unordered_set<int> lookup = {x};
            vector<int> result = {x};
            for (int u = 0; k; --k) {
                for (int v = size(result); u < v; ++u) {
                    const int x = result[u];
                    for (int i = 0; i < L; ++i) {
                        const int a = x / POW10[i] % 10;
                        for (int j = i + 1; j < L; ++j) {
                            const int b = x / POW10[j] % 10;
                            if (a == b) {
                                continue;
                            }
                            const int y = x -a * (POW10[i] - POW10[j]) + b * (POW10[i] - POW10[j]);
                            if (lookup.count(y)) {
                                continue;
                            }
                            lookup.emplace(y);
                            result.emplace_back(y);
                        }
                    }
                }
            }
            return result;
        };

        int result = 0;
        unordered_map<int, int> cnt1;
        for (const auto& x : nums) {
            ++cnt1[x];
        }
        unordered_map<int, int> cnt2;
        for (const auto& [x, v] : cnt1) {
            result += cnt2[x] * v + v * (v - 1) / 2;
            for (const auto& x : at_most(K, x)) {
                if (!cnt1.count(x)) {
                    continue;
                }
                cnt2[x] += v;
            }
        }
        return result;
    }
};

// Time:  O(m * n)
// Space: O(min(m, n))

// dp
class Solution {
public:
    int minLargest(vector<int>& nums1, vector<int>& nums2) {
        static const int INF = numeric_limits<int>::max();

        if (size(nums1) < size(nums2)) {
            swap(nums1, nums2);
        }
        vector<int> dp(size(nums2) + 1, INF);
        dp[0] = 0;
        for (int i = 0; i <= size(nums1); ++i) {
            for (int j = 0; j <= size(nums2); ++j) {
                if (!i && !j) {
                    continue;
                }
                int curr = INF;
                if (i - 1 >= 0) {
                    if (dp[j] != INF) {
                        curr = min(curr, dp[j] + (dp[j] % 2 == nums1[i - 1] % 2 ? 2 : 1));
                    }
                }
                if (j - 1 >= 0) {
                    if (dp[j - 1] != INF) {
                        curr = min(curr, dp[j - 1] + (dp[j - 1] % 2 == nums2[j - 1] % 2 ? 2 : 1));
                    }
                }
                dp[j] = curr;
            }
        }
        return dp.back();
    }
};

