// dp
class Solution2 {
public:
    int beautifulSplits(vector<int>& nums) {
        vector<vector<int>> dp(size(nums), vector<int>(nums));
        for (int i = size(nums) - 1; i >= 0; --i) {
            for (int j = i + 1; j < size(nums); ++j) {
                dp[i][j] = (nums[i] == nums[j]) ? 1 + (j + 1 < size(nums) ? dp[i + 1][j + 1] : 0) : 0;
            }
        }
        int result = 0;
        for (int i = 1; i + 1 < size(nums); ++i) {
            for (int j = i + 1; j < size(nums); ++j) {
                if ((dp[0][i] >= i && (j - i >= i)) || dp[i][j] >= j - i) {
                    ++result;
                }
            }
        }
        return result;
    }
};

// Time:  O(26 * n)
// Space: O(26)

// freq table, dp
class Solution {
public:
    int makeStringGood(string s) {
        vector<int> cnt(26);
        for (const auto& x : s) {
            ++cnt[x - 'a'];
        }
        int mx = 0, mn = size(s);
        for (const auto& x : cnt) {
            mx = max(mx, x);
            mn = min(mn, x);
        }
        int result = size(s);
        for (int f = mn; f <= mx; ++f) {
            // dp1: min number of the last one of the operations is insert
            // dp2: min number of the last one of the operations is delete
            int dp1 = 0, dp2 = 0;
            for (int i = 0; i < 26; ++i) {
                if (!cnt[i]) {
                    continue;
                }
                int new_dp1 = 0, new_dp2 = 0;
                if (cnt[i] >= f) {
                    new_dp1 = size(s);
                    new_dp2 = min(dp1, dp2) + (cnt[i] - f);
                } else {
                    const int free = i - 1 >= 0 ? (cnt[i - 1] >= f ? cnt[i - 1] - f : cnt[i - 1]) : 0;
                    new_dp1 = min(min(dp1, dp2) + (f - cnt[i]), dp2 + max((f - cnt[i]) - free, 0));
                    new_dp2 = min(dp1, dp2) + cnt[i];
                }
                dp1 = new_dp1;
                dp2 = new_dp2;
            }
            result = min({result, dp1, dp2});
        }
        return result;
    }
};

// Time:  ctor:          O(1)
//        setCell:       O(logn)
//        unsetCell:     O(logn)
//        largestMatrix: O(logn)
// Space: O(n^3)

// bst
class Matrix3D {
private:
    int n_;
    unordered_map<int, unordered_map<int, unordered_set<int>>> matrix_;
    unordered_map<int, int> cnt_;
    map<int, set<int>> bst_;

public:
    Matrix3D(int n) : n_(n) {
        bst_[0].emplace(n - 1);
    }

    void setCell(int x, int y, int z) {
        if (matrix_[x][y].count(z)) {
            return;
        }
        matrix_[x][y].emplace(z);
        if (cnt_[x] || x == n_ - 1) {
            bst_[cnt_[x]].erase(x);
            if (empty(bst_[cnt_[x]])) {
                bst_.erase(cnt_[x]);
            }
        }
        ++cnt_[x];
        bst_[cnt_[x]].emplace(x);
    }

    void unsetCell(int x, int y, int z) {
        if (!matrix_.count(x) || !matrix_[x].count(y) || !matrix_[x][y].count(z)) {
            return;
        }
        matrix_[x][y].erase(z);
        if (empty(matrix_[x][y])) {
            matrix_[x].erase(y);
            if (empty(matrix_[x])) {
                matrix_.erase(x);
            }
        }
        bst_[cnt_[x]].erase(x);
        if (empty(bst_[cnt_[x]])) {
            bst_.erase(cnt_[x]);
        }
        --cnt_[x];
        if (cnt_[x] || x == n_ - 1) {
            bst_[cnt_[x]].emplace(x);
        }
    }

    int largestMatrix() {
        return *rbegin(rbegin(bst_)->second);
    }
};

// Time:  ctor:          O(1)
//        setCell:       O(logn)
//        unsetCell:     O(logn)
//        largestMatrix: O(logn) on average
// Space: O(n^3)
// heap
class Matrix3D_2 {
private:
    unordered_map<int, unordered_map<int, unordered_set<int>>> matrix_;
    unordered_map<int, int> cnt_;
    priority_queue<pair<int, int>> max_heap_;

public:
    Matrix3D_2(int n) {
        max_heap_.emplace(cnt_[n - 1], n - 1);
    }

    void setCell(int x, int y, int z) {
        if (matrix_[x][y].count(z)) {
            return;
        }
        matrix_[x][y].emplace(z);
        ++cnt_[x];
        max_heap_.emplace(cnt_[x], x);
    }

    void unsetCell(int x, int y, int z) {
        if (!matrix_.count(x) || !matrix_[x].count(y) || !matrix_[x][y].count(z)) {
            return;
        }
        matrix_[x][y].erase(z);
        if (empty(matrix_[x][y])) {
            matrix_[x].erase(y);
            if (empty(matrix_[x])) {
                matrix_.erase(x);
            }
        }
        --cnt_[x];
        max_heap_.emplace(cnt_[x], x);
    }

    int largestMatrix() {
        while (!empty(max_heap_) && max_heap_.top().first != cnt_[max_heap_.top().second]) {
            max_heap_.pop();
        }
        return max_heap_.top().second;
    }
};

