                }
                prefix.emplace_back(prefix.back() + l);
                dfs(v, u, d + 1, left);
                prefix.pop_back();
            }
            lookup[nums[u] - 1] = prev_d;
        };

        dfs(0, -1, 0, -1);
        return {-result[0], result[1]};
    }
};

