// Space: O(n)

// sort, line sweep
class Solution {
public:
    double separateSquares(vector<vector<int>>& squares) {
        vector<tuple<int, int, int>> events;
        for (const auto& s : squares) {
            events.emplace_back(s[1]       , +1, s[2]);
            events.emplace_back(s[1] + s[2], -1, s[2]);
        }
        sort(begin(events), end(events), [](const auto& a, const auto& b) {
            return get<0>(a) < get<0>(b);
        });
        double total = 0, curr = 0;
        int prev = get<0>(events[0]);
        for (const auto& [y, v, l] : events) {
            if (y != prev) {
                total += (y - prev) * curr;
                prev = y;
            }
            curr += l * v;
        }
        const double expect = total / 2.0;
        total = 0, curr = 0;
        prev = get<0>(events[0]);
        for (const auto& [y, v, l] : events) {
            if (y != prev) {
                if (total + (y - prev) * curr >= expect) {
                    break;
                }
                total += (y - prev) * curr;
                prev = y;
            }
            curr += l * v;
        }
        return prev + (expect - total) / curr; 
    }
};

// Time:  O(nlogr)
// Space: O(1)
// binary search
class Solution2 {
public:
    double separateSquares(vector<vector<int>>& squares) {
        const auto& binary_search = [&](double left, double right, const auto& check) {
            static const double EPS = 1e-5;
            while (right - left > EPS) {
                const auto mid = left + (right - left) / 2;
                if (check(mid)) {
                    right = mid;
                } else {
                    left = mid;
                }
            }
            return left;
        };

        const auto& check = [&](double k) {
            double result = 0;
            for (const auto& s : squares) {
                if (s[1] >= k) {
                    result += static_cast<double>(s[2]) * s[2];
                } else if (s[1] + s[2] <= k) {
                    result -= static_cast<double>(s[2]) * s[2];
                } else {
                    result += static_cast<double>(s[2]) * (((s[1] + s[2]) - k) - (k - s[1]));
                }
            }
            return result <= 0;
        };

        double left = numeric_limits<double>::max();
        double right = numeric_limits<double>::min();
        for (const auto& s : squares) {
            left = min(left, static_cast<double>(s[1]));
            right = max(right, static_cast<double>(s[1] + s[2]));
        }
        return binary_search(left, right, check);
    }
};

// Time:  O(nlogn)
// Space: O(n)

// sort, line sweep, segment tree
class Solution {
public:
    double separateSquares(vector<vector<int>>& squares) {
        vector<tuple<int, int, int, int>> events;
        unordered_set<int> x_set;
        for (const auto& s : squares) {
            events.emplace_back(s[1], +1, s[0], s[0] + s[2]);
            events.emplace_back(s[1] + s[2], -1, s[0], s[0] + s[2]);
            x_set.emplace(s[0]);
            x_set.emplace(s[0] + s[2]);
        }
        sort(begin(events), end(events), [](const auto& a, const auto& b) {
            return get<0>(a) < get<0>(b);
        });
        vector<int> sorted_x(cbegin(x_set), cend(x_set));
        sort(begin(sorted_x), end(sorted_x));
        unordered_map<int, int> x_to_idx;
        for (int i = 0; i < size(sorted_x); ++i) {  // coordinate compression
            x_to_idx[sorted_x[i]] = i;
        }
        auto st = SegmentTreeRecu(sorted_x);
        int prev = get<0>(events[0]);
        vector<tuple<int, int, double>> intervals;
        for (const auto& [y, v, x1, x2] : events) {
            if (y != prev) {
                intervals.emplace_back(prev, y, st.tree[1]);
                prev = y;
            }
            st.update(x_to_idx[x1], x_to_idx[x2], v, 0, size(sorted_x) - 1, 1);
        }
        double expect = 0;
        for (const auto& [y1, y2, curr] : intervals) {
            expect += (y2 - y1) * curr;
        }
        expect /= 2;
        double total = 0;
        for (const auto& [y1, y2, curr] : intervals) {
            if (total + (y2 - y1) * curr >= expect) {
                return y1 + (expect - total) / curr;
            }
            total += (y2 - y1) * curr;
        }
        return -1;
    }

private:
    class SegmentTreeRecu {
    public:
        SegmentTreeRecu(const vector<int>& sorted_x) : sorted_x(sorted_x) {
            const int n = size(sorted_x) - 1;
            const int l = n > 1 ? 1 << (__lg(n - 1) + 2) : 2;
            tree.assign(l, 0);
            cnt.assign(l, 0);
        }

        void update(int ql, int qr, int v, int l, int r, int i) {  // update [ql, qr) by v, interval [l, r) in sorted_x is covered by i
            if (ql >= r || qr <= l) {
                return;
            }
            if (ql <= l && r <= qr) {
                cnt[i] += v;
            } else {
                const auto m = l + (r - l) / 2;
                update(ql, qr, v, l, m, 2 * i);
                update(ql, qr, v, m, r, 2 * i + 1);
            }
            if (cnt[i] > 0) {
                tree[i] = sorted_x[r] - sorted_x[l];
            } else {
                if (r - l == 1) {
                    tree[i] = 0;
                } else {
                    tree[i] = tree[2 * i] + tree[2 * i + 1];
                }
            }
        }

    public:
        vector<int> sorted_x;
        vector<int> tree;
        vector<int> cnt;
    };
};

// Time:  O(n + m)
// Space: O(n + m)

// kmp, two pointers (three pointers)
class Solution {
public:
    int shortestMatchingSubstring(string s, string p) {
        static const int INF = numeric_limits<int>::max();

        const auto& KMP = [](const auto& text, const auto& pattern) {
            const auto& getPrefix = [](const auto& pattern) {
                vector<int> prefix(size(pattern), -1);
                int j = -1;
                for (int i = 1; i < size(pattern); ++i) {
                    while (j != -1 && pattern[j + 1] != pattern[i]) {
                        j = prefix[j];
                    }
                    if (pattern[j + 1] == pattern[i]) {
                        ++j;
                    }
                    prefix[i] = j;
                }
                return prefix;
            };

            vector<int> result;
            if (empty(pattern)) {
                result.resize(size(text) + 1);
                iota(begin(result), end(result), 0);
                return result;
            }
            const vector<int> prefix = getPrefix(pattern);
            int j = -1;
            for (int i = 0; i < size(text); ++i) {
                while (j > -1 && pattern[j + 1] != text[i]) {
                    j = prefix[j];
                }
                if (pattern[j + 1] == text[i]) {
                    ++j;
                }
                if (j == size(pattern) - 1) {
                    result.emplace_back(i - j);
                    j = prefix[j];
                }
            }
            return result;
        };

        const int i = p.find('*');
        const auto& a = p.substr(0, i);
        const int j = p.find('*', i + 1);
        const auto& b = p.substr(i + 1, j - (i + 1));
        const auto& c = p.substr(j + 1);
        const int n = size(s), la = size(a), lb = size(b), lc = size(c);
        int result = INF;
        const auto& idxs1 = KMP(s, b);
        const auto& idxs2 = KMP(s, c);
        int x = 0, y = 0;
        for (const auto& i : KMP(s, a)) {
            for (; x < size(idxs1) && idxs1[x] < i + la; ++x);
            if (x == size(idxs1)) {
                break;
            }
            for (; y < size(idxs2) && idxs2[y] < idxs1[x] + lb; ++y);
            if (y == size(idxs2)) {
                break;
            }
            result = min(result, (idxs2[y] + lc) - i);
        }
        return result != INF ? result : -1;
    }
};

