// lucas's theorem
class Solution2 {
public:
    bool hasSameDigits(string s) {
        const auto& nCr = [&](int n, int r) {
            if (n - r < r) {
                r = n - r;
            }
            if (LOOKUP[n][r] == -1) {
                int c = 1;
                for (int k = 1; k <= r; ++k) {
                    c *= n - k + 1;
                    c /= k;
                }
                LOOKUP[n][r] = c;
            }
            return LOOKUP[n][r];
        };

        // https://en.wikipedia.org/wiki/Lucas%27s_theorem
        const auto& nCr_mod = [&](int n, int r, int mod) {
            int result = 1;
            while (n > 0 || r > 0) {
                const int ni = n % mod;
                n /= mod;
                const int ri = r % mod;
                r /= mod;
                if (ni < ri) {
                    return 0;
                }
                result = (result * nCr(ni, ri)) % mod;
            }
            return result;
        };

        vector<vector<int>> lookup(2, vector<int>(5));
        for (int i = 0; i < 10; ++i) {
            lookup[i % 2][i % 5] = i;
        }
        const auto& nC10 = [&](int n, int k) {
            return lookup[nCr_mod(n, k, 2)][nCr_mod(n, k, 5)];
        };

        int total = 0;
        for (int i = 0; i <= size(s) - 2; ++i) {
            total = (total + nC10(size(s) - 2, i) * (((s[i] - s[i + 1]) % 10 + 10) % 10)) % 10;
        }
        return total == 0;
    }
};

