// Space: O(n)

#include <ext/pb_ds/assoc_container.hpp>
#include <ext/pb_ds/tree_policy.hpp>
using namespace __gnu_pbds;

// queue, ordered set
class Router {
public:
    Router(int memoryLimit) : size_(memoryLimit) {
    }

    bool addPacket(int src, int dest, int timestamp) {
        if (!lookup_[dest].insert({timestamp, src}).second) {
            return false;
        }
        if (size(q_) == size_){
            const auto [s, d, t] = q_.front(); q_.pop();
            lookup_[d].erase({t, s});
        }
        q_.emplace(src, dest, timestamp);
        return true;
    }

    vector<int> forwardPacket() {
        if (empty(q_)) {
            return {};
        }
        const auto [s, d, t] = q_.front(); q_.pop();
        lookup_[d].erase({t, s});
        return {s, d, t};
    }

    int getCount(int dest, int startTime, int endTime) {
        return lookup_[dest].order_of_key({endTime + 1, 0}) -
               lookup_[dest].order_of_key({startTime, 0});
    }

private:
    using ordered_set = tree<pair<int, int>, null_type, less<pair<int, int>>, rb_tree_tag, tree_order_statistics_node_update>;
    queue<tuple<int, int, int>> q_;
    unordered_map<int, ordered_set> lookup_;
    int size_;
};

// Time:  O(n * k * l), l = limits
// Space: O(n * k * l)

// dp
class Solution {
public:
    int maxProduct(vector<int>& nums, int k, int limit) {
        const int total = accumulate(cbegin(nums), cend(nums), 0);
        if (k > total || k < -total) {  // optimized to speed up
            return -1;
        }
        unordered_map<int, unordered_map<int, unordered_set<int>>> dp;
        for (const auto& x : nums) {
            unordered_map<int, unordered_map<int, unordered_set<int>>> new_dp;
            for (const auto& [p, total_products] : dp) {
                for (const auto& [total, products] : total_products) {
                    new_dp[p][total] = products;
                }
            }
            new_dp[1][x].emplace(min(x, limit + 1));
            for (const auto& [p, total_products] : dp) {
                const int new_p = p ^ 1;
                const int v = p == 0 ? x : -x;
                for (const auto& [total, products] : total_products) {
                    const int new_total = total + v;
                    for (const auto& v : products) {
                        new_dp[new_p][new_total].emplace(min(v * x, limit + 1));
                    }
                }
            }
            dp = move(new_dp);
        }
        int result = -1;
        for (const auto& [p, total_products] : dp) {
            for (const auto& [total, products] : total_products) {
                if (total != k) {
                    continue;
                }
                for (const auto& v : products) {
                    if (v <= limit) {
                        result = max(result, v);
                    }
                }
            }
        }
        return result;
    }
};

