// segment tree
class Solution {
public:
    vector<int> resultArray(vector<int>& nums, int k, vector<vector<int>>& queries) {
        const auto& build = [&](int i) {
            const int x = nums[i] % k;
            vector<int> cnt(k + 1);
            ++cnt[x];
            cnt.back() = x;
            return cnt;
        };

        const auto& update = [&](const auto& c) {
            const int x = c % k;
            vector<int> cnt(k + 1);
            ++cnt[x];
            cnt.back() = x;
            return cnt;
        };

        const auto& query = [&](const auto& x, const auto& y) {
            if (empty(x)) {
                return y;
            }
            if (empty(y)) {
                return x;
            }
            vector<int> cnt(x);
            for (int i = 0; i < k; ++i) {
                cnt[x.back() * i % k] += y[i];
            }
            cnt.back() = x.back() * y.back() % k;
            return cnt;
        };

        SegmentTree<vector<int>> st(size(nums), build, update, query);
        vector<int> result(size(queries));
        for (int idx = 0; idx < size(queries); ++idx) {
            const int i = queries[idx][0];
            const int v = queries[idx][1];
            const int s = queries[idx][2];
            const int x = queries[idx][3];
            st.update(i, v);
            result[idx] = st.query(s, size(nums) - 1)[x];
        }
        return result;
    }

private:
    // Template:
    // https://github.com/kamyu104/LeetCode-Solutions/blob/master/C++/booking-concert-tickets-in-groups.cpp
    template <typename T>
    class SegmentTree {
     public:
        explicit SegmentTree(
            int N,
            const function<T(const int&)>& build_fn,
            const function<T(const int&)>& update_fn,
            const function<T(const T&, const T&)>& query_fn)
          : tree(N > 1 ? 1 << (__lg(N - 1) + 2) : 2),
            base(N > 1 ? 1 << (__lg(N - 1) + 1) : 1),
            build_fn_(build_fn),
            query_fn_(query_fn),
            update_fn_(update_fn) {

            for (int i = base; i < base + N; ++i) {
                tree[i] = build_fn_(i - base);
            }
            for (int i = base - 1; i >= 1; --i) {
                tree[i] = query_fn_(tree[i << 1], tree[(i << 1) + 1]);
            }
        }

        void update(int i, int h) {
            int x = base + i;
            tree[x] = update_fn_(h);
            while (x > 1) {
                x >>= 1;
                tree[x] = query_fn_(tree[x << 1], tree[(x << 1) + 1]);
            }
        }

        T query(int L, int R) {
            L += base;
            R += base;
            T left, right;
            for (; L <= R; L >>= 1, R >>= 1) {
                if (L & 1) {
                    left = query_fn_(left, tree[L]);
                    ++L;
                }
                if ((R & 1) == 0) {
                    right = query_fn_(tree[R], right);
                    --R;
                }
            }
            return query_fn_(left, right);
        }

        vector<T> tree;
        int base;

    private:
        const function<T(const int&)> build_fn_;
        const function<T(const int&)> update_fn_;
        const function<T(const T&, const T&)> query_fn_;
    };
};

// Time:  O(n + qlogn)
// Space: O(n)

// template from: https://cp-algorithms.com/data_structures/treap.html
using pTreapNode = struct TreapNode *;

struct TreapNode {
    int prior, value, cnt;
    int xor_sum;  // added
    bool rev;
    pTreapNode l, r;

    TreapNode (int v) : value(v), prior(rand()), cnt(1), xor_sum(v), rev(false), l(nullptr), r(nullptr) {}  // added
};

int cnt(pTreapNode t) {
    return t ? t->cnt : 0;
}

int xor_sum(pTreapNode t) {  // added
    return t ? t->xor_sum : 0;
}

void upd_cnt(pTreapNode t) {
    if (t) {
        t->cnt = cnt(t->l) + cnt(t->r) + 1;
        t->xor_sum = t->value ^ xor_sum(t->l) ^ xor_sum(t->r);  // added
    }
}

void push(pTreapNode t) {
    if (t && t->rev) {
        t->rev = false;
        swap(t->l, t->r);
        if (t->l) t->l->rev ^= true;
        if (t->r) t->r->rev ^= true;
    }
}

void merge(pTreapNode& t, pTreapNode l, pTreapNode r) {
    push(l);
    push(r);
    if (!l || !r)
        t = l ? l : r;
    else if (l->prior > r->prior)
        merge(l->r, l->r, r), t = l;
    else
        merge(r->l, l, r->l), t = r;
    upd_cnt(t);
}

void split(pTreapNode t, pTreapNode& l, pTreapNode& r, int key, int add = 0) {
    if (!t)
        return void(l = r = 0);
    push(t);
    int cur_key = add + cnt(t->l);
    if (key <= cur_key)
        split(t->l, l, t->l, key, add), r = t;
    else
        split(t->r, t->r, r, key, add + 1 + cnt(t->l)), l = t;
    upd_cnt(t);
}

void reverse(pTreapNode t, int l, int r) {
    pTreapNode t1, t2, t3;
    split(t, t1, t2, l);
    split(t2, t2, t3, r - l + 1);
    t2->rev ^= true;
    merge(t, t1, t2);
    merge(t, t, t3);
}

void heapify(pTreapNode t) {
    if (!t) return;
    pTreapNode max = t;
    if (t->l && t->l->prior > max->prior)
        max = t->l;
    if (t->r && t->r->prior > max->prior)
        max = t->r;
    if (max != t) {
        swap(t->prior, max->prior);
        heapify(max);
    }
}

pTreapNode build(const vector<int>& a, int i, int n) {
    if (n == 0) return nullptr;
    int mid = n / 2;
    auto t = new TreapNode(a[i + mid]);
    t->l = build(a, i, mid);
    t->r = build(a, i + mid + 1, n - mid - 1);
    heapify(t);
    upd_cnt(t);
    return t;
}

// treap
class Solution {
public:
    vector<int> getResults(vector<int>& nums, vector<vector<int>>& queries) {
        pTreapNode root = build(nums, 0, size(nums));
        const auto& update = [&](int index, int value) {
            pTreapNode left, mid, right;
            split(root, left, mid, index);
            split(mid, mid, right, 1);
            mid->value = value;
            upd_cnt(mid);
            merge(root, left, mid);
            merge(root, root, right);
        };

        const auto& query = [&](int left, int right) {
            pTreapNode t1, t2, t3;
            split(root, t1, t2, left);
            split(t2, t2, t3, right - left + 1);
            int result = xor_sum(t2);
            merge(root, t1, t2);
            merge(root, root, t3);
            return result;
        };

        vector<int> result;
        for (const auto& q : queries) {
            if (q[0] == 1) {
                update(q[1], q[2]);
            } else if (q[0] == 2) {
                result.emplace_back(query(q[1], q[2]));
            } else if (q[0] == 3) {
                reverse(root, q[1], q[2]);
            }
        }
        return result;
    }
};

