class Solution {
public:
    vector<int> baseUnitConversions(vector<vector<int>>& conversions) {
        static const int MOD = 1e9 + 7;

        vector<vector<pair<int, int>>> adj(size(conversions) + 1);
        for (const auto& c : conversions) {
            adj[c[0]].emplace_back(c[1], c[2]);
        }
        vector<int> result(size(adj));
        result[0] = 1;
        vector<int> q = {0};
        while (!empty(q)) {
            vector<int> new_q;
            for (const auto& u : q) {
                for (const auto& [v, w] : adj[u]) {
                    result[v] = (static_cast<int64_t>(result[u]) * w) % MOD;
                    new_q.emplace_back(v);
                }
            }
            q = move(new_q);
        }
        return result;
    }
};

// Time:  O(n * m)
// Space: O(n * m)

// z-function
class Solution {
public:
    int countCells(vector<vector<char>>& grid, const string& pattern) {
        // Template: https://cp-algorithms.com/string/z-function.html
        const auto& z_function = [](const string& s) {  // Time: O(n), Space: O(n)
            vector<int> z(size(s));
            for (int i = 1, l = 0, r = 0; i < size(z); ++i) {
                if (i <= r) {
                    z[i] = min(r - i + 1, z[i - l]);
                }
                while (i + z[i] < size(z) && s[z[i]] == s[i + z[i]]) {
                    ++z[i];
                }
                if (i + z[i] - 1 > r) {
                    l = i, r = i + z[i] - 1;
                }
            }
            return z;
        };

        const auto& check = [&](bool is_horizontal) {
            int n = size(grid), m = size(grid[0]);
            if (!is_horizontal) {
                swap(n, m);
            }
            const int p = size(pattern);
            string s = pattern;
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    s.push_back(is_horizontal ? grid[i][j] : grid[j][i]);
                }
            }
            vector<vector<bool>> lookup(n, vector<bool>(m));
            vector<int> z = z_function(s);
            for (int i = p, curr = 0 - p; i < size(s); ++i) {
                if (z[i] < p) {
                    continue;
                }
                curr = max(curr, i - p);
                for (; curr <= (i - p) + p - 1; ++curr) {
                    lookup[curr / m][curr % m] = true;
                }
            }
            return lookup;
        };

        const auto& lookup1 = check(true);
        const auto& lookup2 = check(false);
        int result = 0;
        for (int i = 0; i < size(grid); ++i) {
            for (int j = 0; j < size(grid[0]); ++j) {
                if (lookup1[i][j] && lookup2[j][i]) {
                    ++result;
                }
            }
        }
        return result;
    }
};

// Time:  O(n * 2^n)
// Space: O(2^n)

// dp, bitmasks
class Solution {
public:
    int maxProfit(int n, vector<vector<int>>& edges, vector<int>& score) {
        vector<int> adj(n);
        for (const auto& e : edges) {
            adj[e[1]] |= 1 << e[0];
        }
        vector<int> dp(1 << n, -1);
        dp[0] = 0;
        for (int mask = 0; mask < size(dp); ++mask) {
            if (dp[mask] == -1) {
                continue;
            }
            const int l = __builtin_popcount(mask) + 1;
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) {
                    continue;
                }
                if ((mask & adj[i]) == adj[i]) {
                    dp[mask | (1 << i)] = max(dp[mask | (1 << i)], dp[mask] + l * score[i]);
                }
            }
        }
        return dp.back();
    }
};

