// Time:  O(nlogr + k * n * 2^n)
// Space: O(logr + k * 2^n)

// dp, backtracing
class Solution {
public:
    vector<int> concatenatedDivisibility(vector<int>& nums, int k) {
        const auto& length = [](int x) {
            int l = 0;
            for (; x > 0; x /= 10) {
                ++l;
            }
            return max(l, 1);
        };

        vector<int> lookup(size(nums));
        for (int i = 0; i < size(nums); ++i) {
            lookup[i] = length(nums[i]);
        }
        const int mx = ranges::max(lookup);
        vector<int> pow10(mx + 1);
        pow10[0] = 1 % k;
        for (int i = 0; i + 1 < size(pow10); ++i) {
            pow10[i + 1] = (pow10[i] * 10) % k;
        }
        vector<vector<bool>> dp(1 << size(nums), vector<bool>(k));
        dp.back()[0] = true;
        for (int mask = (size(dp) - 1) - 1; mask >= 0; --mask) {
            for (int r = 0; r < k; ++r) {
                for (int i = 0; i < size(nums); ++i) {
                    if (mask & (1 << i)) {
                        continue;
                    }
                    if (dp[mask | (1 << i)][(r * pow10[lookup[i]] + nums[i]) % k]) {
                        dp[mask][r] = true;
                        break;
                    }
                }
            }
        }
        vector<int> result;
        if (!dp[0][0]) {
            return result;
        }
        vector<pair<int,int>> order;
        for (int i = 0; i < size(nums); ++i) {
            order.emplace_back(nums[i], i);
        }
        sort(begin(order), end(order));
        for (int _ = 0, mask = 0, r = 0; _ < size(nums); ++_) {
            for (const auto& [_, i] : order) {
                if (mask & (1 << i)) {
                    continue;
                }
                if (dp[mask | (1 << i)][(r * pow10[lookup[i]] + nums[i]) % k]) {
                    result.emplace_back(nums[i]);
                    mask |= (1 << i);
                    r = (r * pow10[lookup[i]] + nums[i]) % k;
                    break;
                }
            }
        }
        return result;
    }
};

// Time:  O((n + q) * logn)
// Space: O(nlogn)

// prefix sum, greedy, binary lifting
class Solution {
public:
    vector<int> pathExistenceQueries(int n, vector<int>& nums, int maxDiff, vector<vector<int>>& queries) {
        const auto& bit_length = [](int x) {
            return (x ? std::__lg(x) : -1) + 1;
        };

        const auto& ceil_log2_x = [&](int x) {
            return bit_length(x - 1);
        };

        vector<int> sorted_i(n);
        iota(begin(sorted_i), end(sorted_i), 0);
        sort(begin(sorted_i), end(sorted_i), [&](int i, int j) {
            return nums[i] < nums[j];
        });
        vector<int> i_to_idx(n);
        for (int idx = 0; idx < n; ++idx) {
            i_to_idx[sorted_i[idx]] = idx;
        }
        vector<int> prefix(n);
        for (int i = 0; i < n - 1; ++i) {
            prefix[i + 1] = prefix[i] + (nums[sorted_i[i + 1]] - nums[sorted_i[i]] <= maxDiff ? 0 : 1);
        }
        vector<vector<int>> P(ceil_log2_x(n - 1) + 1, vector<int>(n, n - 1));
        for (int right = 0, left = 0; right < n; ++right) {
            for (; nums[sorted_i[right]] - nums[sorted_i[left]] > maxDiff; ++left) {
                P[0][left] = right - 1;
            }
        }
        for (int i = 0; i + 1 < size(P); ++i) {
            for (int j = 0; j < n; ++j) {
                P[i + 1][j] = P[i][P[i][j]];
            }
        }
        vector<int> result(size(queries), -1);
        for (int idx = 0; idx < size(queries); ++idx) {
            int i = queries[idx][0], j = queries[idx][1];
            if (i == j) {
                result[idx] = 0;
                continue;
            }
            if (prefix[i_to_idx[i]] != prefix[i_to_idx[j]]) {
                continue;
            }
            if (i_to_idx[i] > i_to_idx[j]) {
                swap(i, j);
            }
            int curr = i_to_idx[i], l = 0;
            for (int k = size(P) - 1; k >= 0; --k) {
                if (P[k][curr] < i_to_idx[j]) {
                    curr = P[k][curr];
                    l += 1 << k;
                }
            }
            result[idx] = l + 1;
        }
        return result;
    }
};

// Time:  O(n + qlogm)
// Space: O(n)

// bfs, fast exponentiation
class Solution {
public:
    vector<int> queryConversions(vector<vector<int>>& conversions, vector<vector<int>>& queries) {
        static const int MOD = 1e9 + 7;

        const auto& powmod = [&](int a, int b) {
            a %= MOD;
            int64_t result = 1;
            while (b) {
                if (b & 1) {
                    result = result * a % MOD;
                }
                a = int64_t(a) * a % MOD;
                b >>= 1;
            }
            return result;
        };

        const auto& divmod = [&](int a, int b) {
            return (a * powmod(b, MOD - 2)) % MOD;
        };

        const auto& unit = [&]() {
            vector<vector<pair<int, int>>> adj(size(conversions) + 1);
            for (const auto& c : conversions) {
                adj[c[0]].emplace_back(c[1], c[2]);
            }
            vector<int> result(size(adj));
            result[0] = 1;
            vector<int> q = {0};
            while (!empty(q)) {
                vector<int> new_q;
                for (const auto& u : q) {
                    for (const auto& [v, w] : adj[u]) {
                        result[v] = (static_cast<int64_t>(result[u]) * w) % MOD;
                        new_q.emplace_back(v);
                    }
                }
                q = move(new_q);
            }
            return result;
        };

        const auto& lookup = unit();
        vector<int> result(size(queries));
        for (int i = 0; i < size(queries); ++i) {
            result[i] = divmod(lookup[queries[i][1]], lookup[queries[i][0]]);
        }
        return result;
    }
};

// Time:  O(d + 10)
// Space: O(10)

// freq table, greedy
class Solution {
public:
    int maxProduct(int n) {
        static const int MAX_COUNT = 2;
        const auto& count = [](int n) {
            vector<int> cnt(10);
            for (; n; n /= 10) {
                ++cnt[n % 10];
            }
            return cnt;
        };

        auto cnt = count(n);
        int result = 1;
        for (int d = 9, c = MAX_COUNT; d >= 0; --d) {
            if (c == 0) {
                break;
            }
            for (; cnt[d]; --cnt[d]) {
                if (c == 0) {
                    break;
                }
                --c;
                result *= d;
            }
        }
        return result;
    }
};

