// array, hash table
class Solution {
public:
    bool canPartitionGrid(vector<vector<int>>& grid) {
        const int64_t total = accumulate(cbegin(grid), cend(grid), static_cast<int64_t>(0), [](const auto& accu, const auto& x) {
            return accumulate(cbegin(x), cend(x), accu);
        });
        const auto& check = [&](int begin1, int end1, int begin2, int end2, const auto& get) {
            int64_t curr = 0;
            const int d = begin1 < end1 ? 1 : -1;
            unordered_set<int64_t> lookup;
            for (int i = begin1; i != end1; i += d) {
                for (int j = begin2; j != end2; ++j) {
                    curr += get(i, j);
                    lookup.emplace(get(i, j));
                }
                const int64_t diff = curr - (total - curr);
                if (diff == 0) {
                    return true;
                }
                if (i != begin1 && end2 - begin2 != 1) {
                    if (lookup.count(diff)) {
                        return true;
                    }
                } else if (i == begin1) {
                    if (get(begin1, begin2) == diff || get(begin1, end2 - 1) == diff) {
                        return true;
                    }
                } else {
                    if (get(begin1, 0) == diff || get(i, 0) == diff) {
                        return true;
                    }
                }
            }
            return false;
        };

        return check(0, size(grid), 0, size(grid[0]), [&](int i, int j) { return grid[i][j]; }) ||
               check(size(grid) - 1, -1, 0, size(grid[0]), [&](int i, int j) { return grid[i][j]; }) ||
               check(0, size(grid[0]), 0, size(grid), [&](int i, int j) { return grid[j][i]; }) ||
               check(size(grid[0]) - 1, -1, 0, size(grid), [&](int i, int j) { return grid[j][i]; });
    }
};

// Time:  O((n + m) * log(n + m))
// Space: O(n + m)

const double PI = acos(-1.0);

void fft(vector<complex<double>>& a, bool invert) {
    const int n = size(a);
    if (n <= 1) {
      return;
    }

    // bit-reversal permutation
    for (int i = 1, j = 0; i < n; ++i) {
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) {
            j ^= bit;
        }
        j ^= bit;
        if (i < j) {
            swap(a[i], a[j]);
        }
    }

    // Cooley-Tukey fft
    for (int len = 2; len <= n; len <<= 1) {
        double angle = 2 * PI / len * (invert ? -1 : 1);
        complex<double> wlen(cos(angle), sin(angle));
        for (int i = 0; i < n; i += len) {
            complex<double> w(1);
            for (int j = 0; j < len / 2; ++j) {
                complex<double> u = a[i + j];
                complex<double> v = a[i + j + len / 2] * w;
                a[i + j] = u + v;
                a[i + j + len / 2] = u - v;
                w *= wlen;
            }
        }
    }

    // if inverse fft, divide by n
    if (invert) {
        for (complex<double>& x : a) {
            x /= n;
        }
    }
}

vector<long long> conv(const auto& poly1, const auto& poly2) {
    const int n = size(poly1), m = size(poly2);
    int sz = 1, tot = n + m - 1;
    while (sz < tot) {
        sz <<= 1;
    }
    vector<complex<double>> a(sz), b(sz);
    for (int i = 0; i < n; ++i) {
        a[i] = poly1[i];
    }
    for (int i = 0; i < m; ++i) {
        b[i] = poly2[i];
    }
    fft(a, false);
    fft(b, false);
    for (int i = 0; i < sz; ++i) {
        a[i] *= b[i];
    }
    fft(a, true);
    vector<long long> result(tot);
    for (int i = 0; i < size(result); ++i) {
        result[i] = static_cast<long long>(round(a[i].real()));
    }
    return result;
}

// fft
class Solution {
public:
    vector<long long> multiply(vector<int>& poly1, vector<int>& poly2) {
        return conv(poly1, poly2);
    }
};

