const int MAX_N = 100;
const auto& SPF = linear_sieve_of_eratosthenes(MAX_N);
class Solution {
public:
    bool checkPrimeFrequency(vector<int>& nums) {
        unordered_map<int, int> cnt;
        for (const auto& x : nums) {
            ++cnt[x];
        }
        return any_of(cbegin(cnt), cend(cnt), [](const auto& x) {
            return SPF[x.second] == x.second;
        });
    }
};

// Time:  O(n^2)
// Space: O(1)

// dp
class Solution {
public:
    vector<int> findCoins(vector<int>& numWays) {
        vector<int> result;
        for (int i = 1; i <= size(numWays); ++i) {
            if (numWays[i - 1] == 1) {
                result.emplace_back(i);
                for (int j = size(numWays); j >= i; --j) {
                    numWays[j - 1] -= (j - i) - 1 >= 0 ? numWays[(j - i) - 1] : 1;
                }
            }
            if (numWays[i - 1]) {
                return {};
            }
        }
        return result;
    }
};

// Time:  O(n^2)
// Space: O(n)
// dp
class Solution2 {
public:
    vector<int> findCoins(vector<int>& numWays) {
        vector<int> result;
        vector<int> dp(size(numWays) + 1);
        dp[0] = 1;
        for (int i = 1; i <= size(numWays); ++i) {
            if (numWays[i - 1] - dp[i] == 1) {
                result.emplace_back(i);
                for (int j = i; j <= size(numWays); ++j) {
                    dp[j] += dp[j - i];
                }
            }
            if (numWays[i - 1] - dp[i]) {
                return {};
            }
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(n)

// iterative dfs
class Solution {
public:
    int minIncrease(int n, vector<vector<int>>& edges, vector<int>& cost) {
        vector<vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].emplace_back(e[1]);
            adj[e[1]].emplace_back(e[0]);
        }
        const auto& iter_dfs = [&]() {
            int result = n - 1;
            vector<int64_t> mx(n);
            vector<tuple<int, int, int>> stk = {{1, 0, -1}};
            while (!empty(stk)) {
                const auto [step, u, p] = stk.back(); stk.pop_back();
                if (step == 1) {
                    stk.emplace_back(2, u, p);
                    for (const auto& v : adj[u]) {
                        if (v == p) {
                            continue;
                        }
                        stk.emplace_back(1, v, u);
                    }
                } else if (step == 2) {
                    int cnt = 0;
                    for (const auto& v : adj[u]) {
                        if (v == p || mx[v] < mx[u]) {
                            continue;
                        }
                        if (mx[v] > mx[u]) {
                            mx[u] = mx[v];
                            cnt = 0;
                        }
                        ++cnt;
                    }
                    result -= cnt;
                    mx[u] += cost[u];
                }
            }
            return result;
        };

        return iter_dfs();
    }
};

// Time:  O(n)
// Space: O(n)
// dfs
class Solution2 {
public:
    int minIncrease(int n, vector<vector<int>>& edges, vector<int>& cost) {
        vector<vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].emplace_back(e[1]);
            adj[e[1]].emplace_back(e[0]);
        }
        int result = n - 1;
        const function<int64_t (int, int)> dfs = [&](int u, int p) {
            int64_t mx = 0;
            int cnt = 0;
            for (const auto& v : adj[u]) {
                if (v == p) {
                    continue;
                }
                const auto& c = dfs(v, u);
                if (c < mx) {
                    continue;
                }
                if (c > mx) {
                    mx = c;
                    cnt = 0;
                }
                ++cnt;
            }
            result -= cnt;
            return mx + cost[u];
        };

        dfs(0, -1);
        return result;
    }
};

// Time:  O((n * m * 2^n + m * 3^n) * log(n * m * 2^n + m * 3^n)) = O(m * 3^n * log(m * 3^n))
// Space: O(n * m * 2^n + m * 3^n) = O(m * 3^n)

// dijkstra's algorithm, submask enumeration
class Solution {
public:
    double minTime(int n, int k, int m, vector<int>& time, vector<double>& mul) {
        static const auto INF = numeric_limits<double>::max();

        vector<int> lookup(1 << n);
        for (int mask = 1; mask < 1 << n; ++mask) {  // Time: O(n * 2^n)
            for (int i = 0; i < n; ++i) {
                if (!(mask & (1 <<i))) {
                    continue;
                }
                lookup[mask] = max(lookup[mask], time[i]);
            }
        }

        vector<vector<vector<double>>> dist(2, vector<vector<double>>(m, vector<double>(1 << n, INF)));
        dist[0][0][(1 << n) - 1] = 0.0;
        using D = tuple<double, int, int, int>;
        priority_queue<D, vector<D>, greater<D>> min_heap;
        min_heap.emplace(0.0, 0, 0, (1 << n) - 1);
        const auto& update = [&](double d, int r, int s, int mask, int submask) {
            const auto& t = lookup[submask] * mul[s];
            const auto& nr = r ^ 1;
            const auto& ns = (s + static_cast<int>(t)) % m;
            const auto& new_mask = mask ^ submask;
            const auto& nd = d + t;
            if (dist[nr][ns][new_mask] > nd) {
                dist[nr][ns][new_mask] = nd;
                min_heap.emplace(nd, nr, ns, new_mask);
            }
        };

        while (!empty(min_heap)) {
            const auto [d, r, s, mask] = min_heap.top(); min_heap.pop();  // Total Time: O((n * m * 2^n + m * 3^n) * log(n * m * 2^n + m * 3^n))
            if (d != dist[r][s][mask]) {
                continue;
            }
            if (mask == 0) {
                assert(r == 1);
                return d;
            }
            if (r == 0) {
                for (int submask = mask; submask; submask = (submask - 1) & mask) {  // Total Time: O(m * 3^n)
                    if (__builtin_popcount(submask) > k) {
                        continue;
                    }
                    update(d, r, s, mask, submask);
                }
            } else {
                for (int i = 0; i < n; ++i) {  // Total Time: O(n * m * 2^n)
                    if (mask & (1 << i)) {
                        continue;
                    }
                    update(d, r, s, mask, 1 << i);
                }
            }
        }
        return -1.0;
    }
};

