// prefix sum
class Solution {
public:
    vector<int> longestCommonPrefix(vector<string>& words) {
        const auto& lcp = [&](int i, int j) {
            if (i < 0 || j >= size(words)) {
                return 0;
            }
            const auto& s1 = words[i], &s2 = words[j];
            const int l = min(size(s1), size(s2));
            for (int k = 0; k < l; ++k) {
                if (s1[k] != s2[k]) {
                    return k;
                }
            }
            return l;
        };

        vector<int> lcps(size(words) - 1);
        for (int i = 0; i < size(lcps); ++i) {
            lcps[i] = lcp(i, i + 1);
        }
        vector<int> right(size(lcps) + 2);
        for (int i = size(lcps) - 1; i >= 0; --i) {
            right[i] = max(right[i + 1], lcps[i]);
        }
        vector<int> result(size(words));
        for (int i = 0, left = 0; i < size(words); ++i) {
            if (i - 2 >= 0) {
                left = max(left, lcps[i - 2]);
            }
            result[i] = max({left, right[i + 1], lcp(i - 1, i + 1)});
        }
        return result;
    }
};

// Time:  O(n^2 * k)
// Space: O(n)

// dp, prefix sum
class Solution {
public:
    int minXor(vector<int>& nums, int k) {
        static const int INF = numeric_limits<int>::max();

        vector<int> prefix(size(nums) + 1);
        for (int i = 0; i < size(nums); ++i) {
            prefix[i + 1] = prefix[i] ^ nums[i];
        }
        vector<int> dp(prefix);
        dp[0] = INF;
        for (int l = 2; l <= k; ++l){
            for (int i = size(nums); i >= l - 1; --i) {
                int mn = INF;
                for (int j = l - 1; j < i; ++j) {
                    const auto& v = prefix[i] ^ prefix[j];
                    const auto& mx = dp[j] > v ? dp[j] : v;
                    if (mx < mn) {
                        mn = mx;
                    }
                }
                dp[i] = mn;
            }
        }
        return dp[size(nums)];
    }
};

