// backward simulation
class Solution {
public:
    char processStr(string s, long long k) {
        int64_t l = 0;
        for (const auto& x : s) {
            if (x == '*') {
                l = max(l - 1, static_cast<int64_t>(0));
            } else if (x == '#') {
                l <<= 1;
            } else if (x == '%') {
                continue;
            } else {
                ++l;
            }
        }
        if (k >= l) {
            return '.';
        }
        for (int i = size(s) - 1; i >= 0; --i) {
            const auto& x = s[i];
            if (x == '*') {
                ++l;
            } else if (x == '#') {
                l >>= 1;
                if (k >= l) {
                    k -= l;
                }
            } else if (x == '%') {
                k = (l - 1) - k;
            } else {
                if (--l == k) {
                    return x;
                }
            }
        }
        return 'x';
    }
};

// Time:  O(n^4 * 2^n)
// Space: O(n + e)

// bitmasks, dp, freq table
class Solution {
public:
    int maxLen(int n, vector<vector<int>>& edges, string label) {
        if (size(edges) == n * (n - 1) / 2) {  // to improve performance
            vector<int> cnt(26);
            for (const auto& x : label) {
                ++cnt[x - 'a'];
            }
            int result = 0;
            for (const auto& c : cnt) {
                result += (c / 2) * 2;
                if (c % 2 && result % 2 == 0) {
                    ++result;
                }
            }
            return result;
        }
        vector<vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].emplace_back(e[1]);
            adj[e[1]].emplace_back(e[0]);
        }
        vector<vector<vector<bool>>> dp(1 << n, vector<vector<bool>>(n, vector<bool>(n)));
        for (int u = 0; u < n; ++u) {
            dp[1 << u][u][u] = true;
        }
        for (const auto& e : edges) {
            if (label[e[0]] == label[e[1]]) {
                dp[(1 << e[0]) | (1 << e[1])][min(e[0], e[1])][max(e[0], e[1])] = true;
            }
        }
        int result = 0;
        for (int mask = 1; mask < (1 << n); ++mask) {
            for (int u = 0; u < n; ++u) {
                for (int v = u; v < n; ++v) {
                    if (!dp[mask][u][v]) {
                        continue;
                    }
                    result = max(result, __builtin_popcount(mask));
                    for (const auto& nu : adj[u]) {
                        if (mask & (1 << nu)) {
                            continue;
                        }
                        for (const auto& nv : adj[v]) {
                            if (mask & (1 << nv)) {
                                continue;
                            }
                            if (nu == nv) {
                                continue;
                            }
                            if (label[nu] == label[nv]) {
                                dp[mask | (1 << nu) | (1 << nv)][min(nu, nv)][max(nu, nv)] = true;
                            }
                        }
                    }
                }
            }
        }
        return result;
    }
};

