// fenwick tree
class BIT {
public:
    BIT(int n) : bit_(n + 1) {  // 0-indexed
    }

    void add(int i, int val) {
        ++i;
        for (; i < size(bit_); i += lower_bit(i)) {
            bit_[i] += val;
        }
    }

    int query(int i) const {
        ++i;
        int total = 0;
        for (; i > 0; i -= lower_bit(i)) {
            total += bit_[i];
        }
        return total;
    }

private:
    int lower_bit(int i) const {
        return i & -i;
    }

    vector<int> bit_;
};

int bit_length(int64_t x) {
    return (x ? std::__lg(x) : -1) + 1;
}

int ceil_log2(int64_t x) {
    return std::__lg(x - 1) + 1;
};

pair<vector<int>, int> init() {
    int64_t MAX_N = 1e15;
    static const int MAX_BIT_LEN = bit_length(MAX_N);
    vector<int> D(MAX_BIT_LEN + 1, 0);
    for (int i = 2; i < size(D); ++i) {
        D[i] = D[__builtin_popcount(i)] + 1;
    }
    int MAX_K = 0;
    for (; MAX_N != 1; ++MAX_K) {  // O(log*(MAX_N)) times
        MAX_N = ceil_log2(MAX_N);
    }
    return {D, MAX_K};
}

const auto& [D, MAX_K] = init();
class Solution {
public:
    vector<int> popcountDepth(vector<long long>& nums, vector<vector<long long>>& queries) {
        const auto& count = [](int64_t x) {
            return x != 1 ? D[__builtin_popcountll(x)] + 1 : 0;
        };

        vector<BIT> bit(MAX_K + 1, BIT(size(nums)));
        for (int i = 0; i < size(nums); ++i) {
            bit[count(nums[i])].add(i, +1);
        }
        vector<int> result;
        for (const auto& q : queries) {
            if (q[0] == 1) {
                const int l = q[1], r = q[2], k = q[3];
                assert(k < size(bit));
                result.emplace_back(bit[k].query(r) - bit[k].query(l - 1));
            } else {
                const auto& i = q[1], &x = q[2];
                const auto& old_d = count(nums[i]);
                const auto& new_d = count(x);
                if (new_d != old_d) {
                    bit[old_d].add(i, -1);
                    bit[new_d].add(i, +1);
                }
                nums[i] = x;
            }
        }
        return result;
    }
};

// Time:  O(n^2 * logr), r = max(max(abs(x), abs(y)) for x, y in points)
// Space: O(n^2)

// freq table, combinatorics
class Solution {
private:
    struct TupleHash {
        template <typename... T>
        std::size_t operator()(const std::tuple<T...>& t) const {
            return apply([](const auto&... args) {
                std::size_t seed = 0;
                ((seed ^= std::hash<std::decay_t<decltype(args)>>{}(args) + 
                        0x9e3779b9 + (seed << 6) + (seed >> 2)), ...);
                return seed;
            }, t);
        }
    };

public:
    int countTrapezoids(vector<vector<int>>& points) {
        unordered_map<tuple<int, int>, int, TupleHash> lookup_slope;
        unordered_map<tuple<int, int, int>, int, TupleHash> lookup_line;
        unordered_map<tuple<int, int, int>, int, TupleHash> lookup_slope_length;
        unordered_map<tuple<int, int, int, int>, int, TupleHash> lookup_line_length;
        int result = 0, same = 0;
        for (int i = 0; i < size(points); ++i) {
            const int x1 = points[i][0], y1 = points[i][1];
            for (int j = 0; j < i; ++j) {
                const int x2 = points[j][0], y2 = points[j][1];
                const int dx = x2 - x1, dy = y2 - y1;
                const auto& g = gcd(dx, dy);
                int a = dx / g, b = dy / g;
                if (a < 0 || (a == 0 && b < 0)) {
                    a = -a, b = -b;
                }
                const int c = b * x1 - a * y1;
                result += lookup_slope[tuple(a, b)]++ - lookup_line[tuple(a, b, c)]++;
                const int l = dx * dx + dy * dy;
                same += lookup_slope_length[tuple(a, b, l)]++ - lookup_line_length[tuple(a, b, c, l)]++;
            }
        }
        return result - same / 2;
    }
};

