// number theory, bfs
vector<int> linear_sieve_of_eratosthenes(int n) {  // Time: O(n), Space: O(n)
    vector<int> spf(n + 1, -1);
    vector<int> primes;
    for (int i = 2; i <= n; ++i) {
        if (spf[i] == -1) {
            spf[i] = i;
            primes.emplace_back(i);
        }
        for (const auto& p : primes) {
            if (i * p > n || p > spf[i]) {
                break;
            }
            spf[i * p] = p;
        }
    }
    return spf;
};

const int MAX_NUM = 1e6;
const auto& SPF = linear_sieve_of_eratosthenes(MAX_NUM);
class Solution {
public:
    int minJumps(vector<int>& nums) {
        unordered_map<int, vector<int>> adj;
        for (int i = 0; i < size(nums); ++i) {
            int x = nums[i];
            while (x != 1) {
                const auto& p = SPF[x];
                while (x % p == 0) {
                    x /= p;
                }
                adj[p].emplace_back(i);
            }
        }
        vector<int> dist(size(nums), -1);
        dist[0] = 0;
        vector<int> q = {0};
        while (!empty(q)) {
            vector<int> new_q;
            for (const auto& i : q) {
                if (i == size(nums) - 1) {
                    return dist.back();
                }
                for (const auto& di : {-1, +1}) {
                    const int ni = i + di;
                    if (0 <= ni && ni < size(nums) && dist[ni] == -1) {
                        dist[ni] = dist[i] + 1;
                        new_q.emplace_back(ni);
                    }
                }
                const int p = nums[i];
                if (SPF[p] != p || !adj.count(p)) {
                    continue;
                }
                for (const auto& ni : adj[p]) {
                    if (dist[ni] != -1) {
                        continue;
                    }
                    dist[ni] = dist[i] + 1;
                    new_q.emplace_back(ni);
                }
                adj.erase(p);
            }
            q = move(new_q);
        }
        return -1;
    }
};

// Time:  O(nlogr * 2^n)
// Space: O(2^n)

// bitmasks, greedy
class Solution {
public:
    long long maximizeXorAndXor(vector<int>& nums) {
        const auto& bit_length = [](int x) {
            return (x ? std::__lg(x) : -1) + 1;
        };

        const int l = bit_length(ranges::max(nums));
        const int n = size(nums);
        const int full_mask = (1 << n) - 1;
        vector<int> and_arr(1 << n);
        vector<int> xor_arr(1 << n);
        for (int mask = 1; mask < (1 << n); ++mask) {
            const auto& lb = mask & -mask;
            const auto& i = __builtin_ctz(lb);
            and_arr[mask] = (mask ^ lb) ? (and_arr[mask ^ lb] & nums[i]) : nums[i];
            xor_arr[mask] = xor_arr[mask ^ lb] ^ nums[i];
        }
        int64_t result = 0;
        vector<int> base(l);  // to improve performance
        for (int mask = 1; mask < (1 << n); ++mask) {
            const auto& total_and = and_arr[mask];
            const auto& total_xor = xor_arr[full_mask ^ mask];
            base.assign(l, 0);
            for (int remain = full_mask ^ mask; remain; remain &= remain - 1) {
                const int i = __builtin_ctz(remain);
                int x = nums[i] & ~total_xor;
                for (int i = l - 1; i >= 0; --i) {
                    if (!(x & (1 << i))) {
                        continue;
                    }
                    if (base[i] == 0) {
                        base[i] = x;
                        break;
                    }
                    x ^= base[i];
                }
            }
            int max_xor = 0;
            for (int i = l - 1; i >= 0; --i) {
                if ((max_xor ^ base[i]) > max_xor) {
                    max_xor ^= base[i];
                }
            }
            result = max(result, total_and + total_xor + static_cast<int64_t>(2) * max_xor);
        }
        return result;
    }
};

