// sort, two pointers
class Solution {
public:
    int minRemoval(vector<int>& nums, int k) {
        sort(begin(nums), end(nums));
        int left = 0;
        for (int right = 0; right < size(nums); ++right) {
            if (static_cast<int64_t>(nums[left]) * k < nums[right]) {
                ++left;
            }
        }
        return left;
    }
};

