// two pointers, greedy
class Solution {
public:
    long long maxSumTrionic(vector<int>& nums) {
        int64_t result = numeric_limits<int64_t>::min();
        for (int64_t right = 1, left = 0, p = 0, q = 0, prefix = nums[0]; right < size(nums); ++right) {
            prefix += nums[right];
            if (nums[right - 1] > nums[right]) {
                if (right - 2 >= 0 && nums[right - 2] < nums[right - 1]) {
                    p = right - 1;
                    while (left < q || (nums[left] < 0 && left + 1 < p)) {
                        prefix -= nums[left++];
                    }
                }
            } else if (nums[right - 1] < nums[right]) {
                if (right - 2 >= 0 && nums[right - 2] > nums[right - 1]) {
                    q = right - 1;
                }
                if (left != p) {
                    result = max(result, prefix);
                }
            } else {
                left = p = q = right;
                prefix = nums[right];
            }
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(n)

// freq table, two pointers
class Solution {
public:
    int longestSubarray(vector<int>& nums, int k) {
        unordered_map<int, int> cnt;
        int left = 0;
        for (int right = 0, repeat = 0; right < size(nums); ++right) {
            if (++cnt[nums[right]] == 2) {
                ++repeat;
            }
            if (repeat > k) {
                if (cnt[nums[left]]-- == 2) {
                    --repeat;
                }
                if (!cnt[nums[left]]) {
                    cnt.erase(nums[left]);
                }
                ++left;
            }
        }
        return size(nums) - left;
    }
};

